import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Currency {
  code: string;
  name: string;
  flag: string; // Emoji flag or image url
  locale: string; // e.g., 'vi-VN', 'en-US'
}

export interface ConversionResult {
  convertedAmount: number;
  exchangeRate: number;
  textSource: string; // Text representation in source language
  textTarget: string; // Text representation in target language
}

export enum LoadingState {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { ConversionResult } from '../types';

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const convertCurrencyWithGemini = async (
  amount: number,
  fromCurrency: string,
  toCurrency: string
): Promise<ConversionResult> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  const model = "gemini-3-flash-preview";

  const prompt = `
    Convert ${amount} ${fromCurrency} to ${toCurrency}.
    Use the latest available exchange rates.
    Provide the result in JSON format containing:
    1. convertedAmount: The numeric result of the conversion.
    2. exchangeRate: The rate used for 1 ${fromCurrency} to ${toCurrency}.
    3. textSource: The amount in words in the native language of ${fromCurrency} (e.g. if VND, in Vietnamese).
    4. textTarget: The converted amount in words in the native language of ${toCurrency} (e.g. if USD, in English).

    Ensure the text descriptions are natural and grammatically correct for currency reading in their respective languages.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            convertedAmount: { type: Type.NUMBER },
            exchangeRate: { type: Type.NUMBER },
            textSource: { type: Type.STRING },
            textTarget: { type: Type.STRING },
          },
          required: ["convertedAmount", "exchangeRate", "textSource", "textTarget"],
        },
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from Gemini.");
    }

    const result = JSON.parse(text) as ConversionResult;
    return result;
  } catch (error) {
    console.error("Gemini conversion error:", error);
    throw new Error("Failed to convert currency. Please try again.");
  }
};

import React from 'react';
