import React, { useState, useCallback } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { convertCurrencyWithGemini } from './services/geminiService';
import { POPULAR_CURRENCIES, DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from './constants';
import { ConversionResult, LoadingState, Currency } from './types';

const App: React.FC = () => {
  const [amount, setAmount] = useState<string>('100000');
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);

  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');

  const handleConvert = useCallback(async () => {
    const numAmount = parseFloat(amount);
    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }

    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');
    setResult(null);

    try {
      const data = await convertCurrencyWithGemini(numAmount, fromCurrency.code, toCurrency.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);
    } catch (err) {
      setErrorMsg("Có lỗi xảy ra khi chuyển đổi. Vui lòng kiểm tra kết nối hoặc API Key.");
      setLoadingState(LoadingState.ERROR);
    }
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = () => {
    setFromCurrency(toCurrency);
    setToCurrency(fromCurrency);
    setResult(null); // Clear result on swap to avoid confusion
    setLoadingState(LoadingState.IDLE);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: currencyCode,
      maximumFractionDigits: 2
    }).format(val);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
      <div className="w-full max-w-2xl bg-white/90 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/50 overflow-hidden">

        {/* Header */}
        <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-8 text-center relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-full opacity-10">
                 <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
                    <path d="M0 100 C 20 0 50 0 100 100 Z" fill="white" />
                 </svg>
            </div>
          <h1 className="text-3xl font-bold text-white relative z-10 mb-2">VinaChange</h1>
          <p className="text-blue-100 text-sm relative z-10">Chuyển đổi tiền tệ nhanh chóng & Chính xác</p>
        </div>

        {/* Main Content */}
        <div className="p-6 sm:p-8 space-y-8">

          {/* Inputs Section */}
          <div className="space-y-6 relative">
            <CurrencyRow
              label="Số tiền cần đổi"
              amount={amount}
              currency={fromCurrency}
              onAmountChange={setAmount}
              onCurrencyChange={setFromCurrency}
            />

            {/* Swap Button */}
            <div className="absolute left-1/2 top-[50%] -translate-x-1/2 -translate-y-[20%] sm:-translate-y-[20%] z-10">
              <button
                onClick={handleSwap}
                className="bg-white p-3 rounded-full shadow-lg border border-slate-100 text-blue-600 hover:text-blue-700 hover:scale-110 transition-transform focus:outline-none focus:ring-4 focus:ring-blue-100 active:scale-95"
                title="Hoán đổi tiền tệ"
              >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3 7.5L7.5 3m0 0L12 7.5M7.5 3v13.5m13.5 0L16.5 21m0 0L12 16.5m4.5 4.5V7.5" />
                </svg>
              </button>
            </div>

            <CurrencyRow
              label="Được chuyển đổi sang"
              amount={result ? result.convertedAmount : ''}
              currency={toCurrency}
              onCurrencyChange={setToCurrency}
              readOnly={true}
            />
          </div>

          {/* Action Button */}
          <button
            onClick={handleConvert}
            disabled={loadingState === LoadingState.LOADING}
            className={`w-full py-4 rounded-xl text-white font-bold text-lg shadow-lg transition-all 
              ${loadingState === LoadingState.LOADING 
                ? 'bg-slate-400 cursor-not-allowed' 
                : 'bg-gradient-to-r from-blue-600 to-indigo-600 hover:shadow-blue-500/30 hover:scale-[1.01] active:scale-[0.99]'
              }`}
          >
            {loadingState === LoadingState.LOADING ? (
              <span className="flex items-center justify-center gap-2">
                <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Đang xử lý...
              </span>
            ) : (
              'Chuyển đổi ngay'
            )}
          </button>

          {/* Error Message */}
          {errorMsg && (
            <div className="p-4 bg-red-50 text-red-600 rounded-xl border border-red-100 text-center animate-pulse">
              {errorMsg}
            </div>
          )}

          {/* Result Section */}
          {result && loadingState === LoadingState.SUCCESS && (
            <div className="animate-fade-in-up space-y-6">
              <div className="h-px bg-slate-200 w-full" />

              <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                <div className="flex justify-between items-center mb-4">
                  <span className="text-slate-500 text-sm font-medium">Tỷ giá áp dụng</span>
                  <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold">
                    1 {fromCurrency.code} = {result.exchangeRate.toFixed(6)} {toCurrency.code}
                  </span>
                </div>

                <div className="space-y-4">
                  {/* Source */}
                  <div className="group">
                    <p className="text-2xl sm:text-3xl font-bold text-slate-800 break-words">
                      {formatCurrency(parseFloat(amount), fromCurrency.locale, fromCurrency.code)}
                    </p>
                    <p className="text-slate-500 italic mt-1 text-sm sm:text-base border-l-4 border-blue-400 pl-3 py-1">
                      "{result.textSource}"
                    </p>
                  </div>

                  <div className="flex items-center gap-2 text-slate-300">
                     <div className="h-px bg-slate-200 flex-1"></div>
                     <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 13.5L12 21m0 0l-7.5-7.5M12 21V3" />
                     </svg>
                     <div className="h-px bg-slate-200 flex-1"></div>
                  </div>

                  {/* Target */}
                  <div className="group">
                     <p className="text-3xl sm:text-4xl font-extrabold text-blue-600 break-words">
                      {formatCurrency(result.convertedAmount, toCurrency.locale, toCurrency.code)}
                    </p>
                    <p className="text-slate-500 italic mt-1 text-sm sm:text-base border-l-4 border-indigo-500 pl-3 py-1">
                      "{result.textTarget}"
                    </p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Footer Info */}
      <div className="fixed bottom-4 text-center w-full pointer-events-none">
          <p className="text-slate-400 text-xs font-medium opacity-60">Powered by Gemini AI • Tỷ giá mang tính chất tham khảo</p>
      </div>
    </div>
  );
};

export default App;

