import { GoogleGenAI, Type } from "@google/genai";
import { ConversionResult } from '../types';

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const convertCurrencyWithGemini = async (
  amount: number,
  fromCurrency: string,
  toCurrency: string
): Promise<ConversionResult> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  const model = "gemini-3-flash-preview";
  const currentDate = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  const prompt = `
    Context: You are a professional financial currency converter API. Today is ${currentDate}.

    Task: Convert ${amount} ${fromCurrency} to ${toCurrency}.

    Requirements:
    1. **Exchange Rate**: Use the most current real-time market exchange rate available to you for today (${currentDate}).
    2. **Accuracy**: The numeric conversion must be precise.
    3. **Text Representation (Reading in words)**:
       - 'textSource': Read the source amount (${amount} ${fromCurrency}) in the native language of ${fromCurrency} (e.g., Vietnamese for VND, English for USD).
       - 'textTarget': Read the converted amount in the native language of ${toCurrency}.
       - **Crucial for Vietnamese (VND)**: Read naturally as a native Vietnamese speaker would for currency (e.g., "Một trăm nghìn đồng" instead of "Một trăm ngàn dong"). Include "đồng" at the end. If the amount is round, adding "chẵn" is optional but good.
       - **Crucial for English (USD, EUR, etc.)**: Use standard format (e.g., "One hundred dollars" or "Fifty euros and ten cents").

    Output Format: Provide the result strictly in JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            convertedAmount: { type: Type.NUMBER },
            exchangeRate: { type: Type.NUMBER },
            textSource: { type: Type.STRING },
            textTarget: { type: Type.STRING },
          },
          required: ["convertedAmount", "exchangeRate", "textSource", "textTarget"],
        },
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from Gemini.");
    }

    const result = JSON.parse(text) as ConversionResult;
    return result;
  } catch (error) {
    console.error("Gemini conversion error:", error);
    throw new Error("Failed to convert currency. Please try again.");
  }
};

