import React, { useState, useRef, useEffect } from 'react';
import { POPULAR_CURRENCIES as CURRENCY_LIST } from '../constants';
import { Currency } from '../types';

interface CurrencyRowProps {
  label: string;
  amount: number | string;
  currency: Currency;
  onAmountChange?: (value: string) => void;
  onCurrencyChange: (currency: Currency) => void;
  readOnly?: boolean;
}

export const CurrencyRow: React.FC<CurrencyRowProps> = ({
  label,
  amount,
  currency,
  onAmountChange,
  onCurrencyChange,
  readOnly = false,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Handle clicking outside to close dropdown
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  return (
    <div className="flex flex-col gap-2">
      <label className="text-xs sm:text-sm font-semibold text-slate-500 uppercase tracking-wide ml-1">{label}</label>
      <div className="flex gap-3 relative z-10"> {/* z-10 mostly for the dropdown context */}

        {/* Input Field */}
        <div className="relative flex-1 group">
          <input
            type="number"
            min="0"
            value={amount}
            onChange={(e) => onAmountChange && onAmountChange(e.target.value)}
            readOnly={readOnly}
            className={`w-full p-4 rounded-xl border ${
              readOnly 
                ? 'bg-slate-50 text-slate-500 border-slate-200 cursor-default' 
                : 'bg-white text-slate-800 border-slate-200 group-hover:border-blue-300 focus:ring-4 focus:ring-blue-100 focus:border-blue-500'
            } outline-none transition-all duration-300 text-xl font-bold shadow-sm placeholder-slate-300`}
            placeholder="0"
          />
        </div>

        {/* Custom Currency Dropdown */}
        <div className="relative w-36 sm:w-44" ref={dropdownRef}>
          <button
            onClick={() => setIsOpen(!isOpen)}
            className={`w-full h-full bg-white border rounded-xl px-4 py-3 flex items-center justify-between outline-none transition-all duration-300 shadow-sm
              ${isOpen ? 'border-blue-500 ring-4 ring-blue-50' : 'border-slate-200 hover:border-blue-300 hover:shadow-md'}
            `}
          >
            <div className="flex items-center gap-2 overflow-hidden">
               <span className="text-2xl flex-shrink-0 leading-none">{currency.flag}</span>
               <span className="font-bold text-slate-700 text-lg">{currency.code}</span>
            </div>
            <svg 
              xmlns="http://www.w3.org/2000/svg" 
              fill="none" 
              viewBox="0 0 24 24" 
              strokeWidth={2.5} 
              stroke="currentColor" 
              className={`w-4 h-4 text-slate-400 transition-transform duration-300 ${isOpen ? 'rotate-180 text-blue-500' : ''}`}
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" />
            </svg>
          </button>

          {/* Animated Dropdown Menu */}
          <div 
            className={`absolute right-0 top-full mt-2 w-64 bg-white rounded-2xl shadow-2xl border border-slate-100 z-[100] overflow-hidden transition-all duration-200 origin-top-right
              ${isOpen ? 'opacity-100 scale-100 translate-y-0 visible' : 'opacity-0 scale-95 -translate-y-2 invisible pointer-events-none'}
            `}
          >
             <div className="max-h-72 overflow-y-auto custom-scrollbar p-2 space-y-1">
                <div className="px-3 py-2 text-xs font-bold text-slate-400 uppercase tracking-wider">Chọn tiền tệ</div>
                {CURRENCY_LIST.map((c) => (
                  <div
                    key={c.code}
                    onClick={() => { onCurrencyChange(c); setIsOpen(false); }}
                    className={`flex items-center gap-3 px-3 py-3 rounded-xl cursor-pointer transition-colors duration-200
                      ${c.code === currency.code ? 'bg-blue-50 border border-blue-100' : 'hover:bg-slate-50 border border-transparent'}
                    `}
                  >
                     <span className="text-2xl">{c.flag}</span>
                     <div className="flex flex-col flex-1">
                        <div className="flex justify-between items-center">
                            <span className={`font-bold text-sm ${c.code === currency.code ? 'text-blue-700' : 'text-slate-700'}`}>{c.code}</span>
                            {c.code === currency.code && (
                              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4 text-blue-600">
                                <path fillRule="evenodd" d="M16.704 4.153a.75.75 0 01.143 1.052l-8 10.5a.75.75 0 01-1.127.075l-4.5-4.5a.75.75 0 011.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 011.05-.143z" clipRule="evenodd" />
                              </svg>
                            )}
                        </div>
                        <span className={`text-xs truncate ${c.code === currency.code ? 'text-blue-500' : 'text-slate-400'}`}>{c.name}</span>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

