import { GoogleGenAI, Type } from "@google/genai";
import { ConversionResult } from '../types';

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const convertCurrencyWithGemini = async (
  amount: number,
  fromCurrency: string,
  toCurrency: string
): Promise<ConversionResult> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  // Use Gemini 2.5 Flash as it supports Search Grounding well with JSON output
  const model = "gemini-2.5-flash";
  const currentDate = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  const prompt = `
    Context: You are a financial currency converter API. Today is ${currentDate}.

    Task: Convert ${amount} ${fromCurrency} to ${toCurrency}.

    CRITICAL REQUIREMENT:
    1. **REAL-TIME RATE**: Use the Google Search tool to find the EXACT current market exchange rate for ${fromCurrency} to ${toCurrency} RIGHT NOW. Do not use training data rates.
    2. **ACCURACY**: Use the rate found to calculate the conversion precisely.
    3. **Text Representation**:
       - 'textSource': Read source amount in its native language.
       - 'textTarget': Read converted amount in its native language.
       - Vietnamese (VND): Must read naturally (e.g., "Một trăm nghìn đồng").
       - English/Others: Standard financial reading.

    Output Format:
    Return strictly a JSON object matching the schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }], // Enable grounding for real-time rates
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            convertedAmount: { type: Type.NUMBER },
            exchangeRate: { type: Type.NUMBER },
            textSource: { type: Type.STRING },
            textTarget: { type: Type.STRING },
          },
          required: ["convertedAmount", "exchangeRate", "textSource", "textTarget"],
        },
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from Gemini.");
    }

    // Grounding might add some metadata, but with responseSchema it usually adheres to JSON.
    // If it fails, the error catch will handle it.
    const result = JSON.parse(text) as ConversionResult;
    return result;
  } catch (error) {
    console.error("Gemini conversion error:", error);
    throw new Error("Failed to convert currency. Please try again.");
  }
};

