        </div>

        {/* Main Content */}
        <div className="p-6 sm:p-8 space-y-8 relative">

          {/* Inputs Section */}
          <div className="grid gap-6 relative p-2">
            <div className="bg-white rounded-2xl relative z-20"> 
                <CurrencyRow
                label="Số tiền cần đổi"
                amount={amount}
                currency={fromCurrency}
                onAmountChange={setAmount}
                onCurrencyChange={setFromCurrency}
                dropdownPlacement="bottom"
                />
            </div>

            {/* Swap Button Area */}
            <div className="relative h-2 flex items-center justify-center z-10">
               {/* Decorative line */}
               <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-slate-100"></div>
               </div>

               <button
                onClick={handleSwap}
                className={`bg-white p-3 rounded-full shadow-lg border border-slate-200 text-blue-600 hover:text-blue-700 hover:bg-blue-50 focus:outline-none focus:ring-4 focus:ring-blue-100 transition-all duration-500 ${isSwapping ? 'rotate-180 scale-110' : 'hover:scale-105'}`}
                title="Hoán đổi vị trí"
              >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3 7.5L7.5 3m0 0L12 7.5M7.5 3v13.5m13.5 0L16.5 21m0 0L12 16.5m4.5 4.5V7.5" />
                </svg>
              </button>
            </div>

            <div className="bg-white rounded-2xl relative z-10">
                <CurrencyRow
                label="Quy đổi sang"
                amount={result ? result.convertedAmount : ''}
                currency={toCurrency}
                onCurrencyChange={setToCurrency}
                readOnly={true}
                dropdownPlacement="top" 
