                    className={`flex items-center gap-4 px-4 py-3 rounded-xl cursor-pointer transition-all duration-200
                      ${c.code === currency.code ? 'bg-blue-50 border border-blue-100 shadow-sm' : 'hover:bg-slate-50 border border-transparent'}
                    `}
                  >
                     <img 
                       src={c.flag} 
                       alt={c.code} 
                       className="w-10 h-7 object-cover rounded shadow-sm border border-slate-100"
                     />
                     <div className="flex flex-col flex-1">
                        <div className="flex justify-between items-center">
                            <span className={`font-bold text-base ${c.code === currency.code ? 'text-blue-700' : 'text-slate-800'}`}>{c.code}</span>
