import React, { useState, useCallback } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { convertCurrencyWithGemini } from './services/geminiService';
import { POPULAR_CURRENCIES, DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from './constants';
import { ConversionResult, LoadingState, Currency } from './types';

const App: React.FC = () => {
  const [amount, setAmount] = useState<string>('100000');
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);

  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');

  // Manage which dropdown is currently active to handle z-index stacking
  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);

  // Animation state for swap button
  const [isSwapping, setIsSwapping] = useState(false);

  const handleConvert = useCallback(async () => {
    const numAmount = parseFloat(amount);
    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }

    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');
    setResult(null);

    try {
      const data = await convertCurrencyWithGemini(numAmount, fromCurrency.code, toCurrency.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);
    } catch (err) {
      console.error(err);
      setErrorMsg("Có lỗi xảy ra khi lấy tỷ giá. Vui lòng thử lại.");
      setLoadingState(LoadingState.ERROR);
    }
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = () => {
    setIsSwapping(true);
    setTimeout(() => setIsSwapping(false), 500); // Reset animation class after 500ms

    setFromCurrency(toCurrency);
    setToCurrency(fromCurrency);
    // Clear result on swap to force user to re-convert with new context
    setResult(null); 
    setLoadingState(LoadingState.IDLE);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        return new Intl.NumberFormat(locale, {
        style: 'currency',
        currency: currencyCode,
        maximumFractionDigits: 2
        }).format(val);
    } catch (e) {
        return `${val} ${currencyCode}`;
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4 font-sans text-slate-800">
      {/* Removed overflow-hidden from main container to let dropdowns fly out */}
      <div className="w-full max-w-3xl bg-white rounded-3xl shadow-2xl shadow-slate-200 border border-white transition-all duration-500 relative">

        {/* Header */}
        <div className="bg-gradient-to-r from-blue-600 via-blue-700 to-indigo-700 p-8 text-center relative overflow-hidden rounded-t-3xl">
          <div className="absolute top-0 left-0 w-full h-full opacity-10">
             <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
                 <circle cx="0" cy="0" r="40" fill="white" />
                 <circle cx="100" cy="100" r="60" fill="white" />
             </svg>
          </div>

          <div className="relative z-10">
            <h1 className="text-3xl sm:text-4xl font-extrabold text-white mb-2 tracking-tight drop-shadow-sm">VinaChange</h1>
            <p className="text-blue-100 text-sm font-medium bg-white/20 inline-block px-4 py-1 rounded-full backdrop-blur-sm">
                Tỷ giá chuẩn Google
            </p>
          </div>
        </div>

        {/* Main Content */}
        <div className="p-6 sm:p-8 space-y-8 relative">

          {/* Inputs Section */}
          <div className="grid gap-6 relative p-2">
            {/* Source Currency Row */}
            <div className={`bg-white rounded-2xl relative transition-all duration-200 ${activeDropdown === 'FROM' ? 'z-30' : 'z-20'}`}> 
                <CurrencyRow
                    label="Số tiền cần đổi"
                    amount={amount}
                    currency={fromCurrency}
                    onAmountChange={setAmount}
                    onCurrencyChange={setFromCurrency}
                    dropdownPlacement="bottom"
                    isActive={activeDropdown === 'FROM'}
                    onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                    onCloseDropdown={() => setActiveDropdown(null)}
                />
            </div>

            {/* Swap Button Area */}
            <div className="relative h-2 flex items-center justify-center z-10">
               {/* Decorative line */}
               <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-slate-100"></div>
               </div>

               <button
                onClick={handleSwap}
                className={`bg-white p-3 rounded-full shadow-lg border border-slate-200 text-blue-600 hover:text-blue-700 hover:bg-blue-50 focus:outline-none focus:ring-4 focus:ring-blue-100 transition-all duration-500 ${isSwapping ? 'rotate-180 scale-110' : 'hover:scale-105'}`}
                title="Hoán đổi vị trí"
              >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3 7.5L7.5 3m0 0L12 7.5M7.5 3v13.5m13.5 0L16.5 21m0 0L12 16.5m4.5 4.5V7.5" />
                </svg>
              </button>
            </div>

            {/* Target Currency Row */}
            <div className={`bg-white rounded-2xl relative transition-all duration-200 ${activeDropdown === 'TO' ? 'z-30' : 'z-10'}`}>
                <CurrencyRow
                    label="Quy đổi sang"
                    amount={result ? result.convertedAmount : ''}
                    currency={toCurrency}
                    onCurrencyChange={setToCurrency}
                    readOnly={true}
                    dropdownPlacement="top" 
                    isActive={activeDropdown === 'TO'}
                    onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                    onCloseDropdown={() => setActiveDropdown(null)}
                />
            </div>
          </div>

          {/* Action Button */}
          <button
            onClick={handleConvert}
            disabled={loadingState === LoadingState.LOADING}
            className={`w-full py-4 rounded-xl text-white font-bold text-lg shadow-xl shadow-blue-500/20 transition-all duration-300 transform relative z-0
              ${loadingState === LoadingState.LOADING 
                ? 'bg-slate-400 cursor-not-allowed scale-[0.99]' 
                : 'bg-gradient-to-r from-blue-600 to-indigo-600 hover:shadow-blue-600/40 hover:-translate-y-1 active:scale-[0.98]'
              }`}
          >
            {loadingState === LoadingState.LOADING ? (
              <span className="flex items-center justify-center gap-2">
