interface CurrencyRowProps {
  label: string;
  amount: number | string;
  currency: Currency;
  onAmountChange?: (value: string) => void;
  onCurrencyChange: (currency: Currency) => void;
  readOnly?: boolean;
  dropdownPlacement?: 'top' | 'bottom';
  isActive?: boolean;
  onToggleDropdown?: () => void;
  onCloseDropdown?: () => void;
}

export const CurrencyRow: React.FC<CurrencyRowProps> = ({
  label,
  amount,
  currency,
  onAmountChange,
  onCurrencyChange,
  readOnly = false,
  dropdownPlacement = 'bottom',
  isActive = false,
  onToggleDropdown,
  onCloseDropdown,
}) => {
  const dropdownRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Handle clicking outside to close dropdown
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        if (isActive && onCloseDropdown) {
          onCloseDropdown();
        }
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isActive, onCloseDropdown]);

  // Focus search input when dropdown opens and reset search when closed
  useEffect(() => {
    if (isActive) {
      // Small delay to ensure the animation/render cycle is ready
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 50);
    } else {
      // Reset search query when closed (after animation)
      const timeout = setTimeout(() => setSearchQuery(''), 300);
      return () => clearTimeout(timeout);
    }
  }, [isActive]);

  const dropdownPositionClass = dropdownPlacement === 'top' 
    ? 'bottom-full mb-3 origin-bottom-right' 
    : 'top-full mt-3 origin-top-right';

  // Filter currencies based on search query
  const filteredCurrencies = CURRENCY_LIST.filter((c) => 
    c.code.toLowerCase().includes(searchQuery.toLowerCase()) || 
    c.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="flex flex-col gap-2">
      <label className="text-xs sm:text-sm font-semibold text-slate-500 uppercase tracking-wide ml-1">{label}</label>
      <div className="flex gap-3 relative z-10">

        {/* Input Field */}
        <div className="relative flex-1 group">
          <input
            type="number"
            min="0"
            value={amount}
            onChange={(e) => onAmountChange && onAmountChange(e.target.value)}
            readOnly={readOnly}
            className={`w-full p-4 rounded-xl border ${
              readOnly 
                ? 'bg-slate-50 text-slate-500 border-slate-200 cursor-default' 
                : 'bg-white text-slate-800 border-slate-200 group-hover:border-blue-300 focus:ring-4 focus:ring-blue-100 focus:border-blue-500'
            } outline-none transition-all duration-300 text-xl font-bold shadow-sm placeholder-slate-300`}
            placeholder="0"
          />
        </div>

        {/* Custom Currency Dropdown */}
        <div className="relative w-36 sm:w-44" ref={dropdownRef}>
          <button
            onClick={onToggleDropdown}
            className={`w-full h-full bg-white border rounded-xl px-4 py-3 flex items-center justify-between outline-none transition-all duration-300 shadow-sm
              ${isActive ? 'border-blue-500 ring-4 ring-blue-50' : 'border-slate-200 hover:border-blue-300 hover:shadow-md'}
            `}
          >
            <div className="flex items-center gap-3 overflow-hidden">
               <img 
                 src={currency.flag} 
                 alt={currency.code} 
                 className="w-8 h-6 object-cover rounded shadow-sm flex-shrink-0"
               />
               <span className="font-bold text-slate-700 text-lg">{currency.code}</span>
            </div>
            <svg 
              xmlns="http://www.w3.org/2000/svg" 
              fill="none" 
              viewBox="0 0 24 24" 
              strokeWidth={2.5} 
              stroke="currentColor" 
              className={`w-4 h-4 text-slate-400 transition-transform duration-300 ${isActive ? 'rotate-180 text-blue-500' : ''}`}
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" />
            </svg>
          </button>

          {/* Animated Dropdown Menu */}
          <div 
            className={`absolute right-0 w-80 bg-white rounded-2xl shadow-2xl border border-slate-100 z-[100] overflow-hidden transition-all duration-200 flex flex-col
              ${dropdownPositionClass}
              ${isActive ? 'opacity-100 scale-100 translate-y-0 visible' : 'opacity-0 scale-95 invisible pointer-events-none'}
            `}
          >
             {/* Search Bar Header */}
             <div className="p-3 bg-white border-b border-slate-100 sticky top-0 z-20">
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
