// Hàm đọc số thành chữ tiếng Việt
const readNumberVietnamese = (number: number): string => {
  const Suffixs = ["", "nghìn", "triệu", "tỷ", "nghìn tỷ", "triệu tỷ"];
  const Digits = ["không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín"];

  const readGroup = (group: string) => {
    const readDigit = [
      " không", " một", " hai", " ba", " bốn", " năm", " sáu", " bảy", " tám", " chín"
    ];
    let temp = "";
    if (group == "000") return "";

    // Hàng trăm
    temp += readDigit[parseInt(group.substring(0, 1))] + " trăm";

    // Hàng chục
    if (group.substring(1, 2) == "0") {
      if (group.substring(2, 3) == "0") return temp;
      temp += " linh" + readDigit[parseInt(group.substring(2, 3))];
    } else {
      if (group.substring(1, 2) == "1") temp += " mười";
      else temp += readDigit[parseInt(group.substring(1, 2))] + " mươi";

      if (group.substring(2, 3) == "5") temp += " lăm";
      else if (group.substring(2, 3) != "0") {
         if (group.substring(1, 2) != "1" && group.substring(2, 3) == "1") temp += " mốt";
         else temp += readDigit[parseInt(group.substring(2, 3))];
      }
    }
    return temp;
  };

  if (number === 0) return "Không";

  let s = Math.round(number).toString();
  // Padding zeros to groups of 3
  while (s.length % 3 !== 0) s = "0" + s;

  let result = "";
  let groupCount = s.length / 3;

  for (let i = 0; i < groupCount; i++) {
    let group = s.substring(i * 3, i * 3 + 3);
    let prefix = readGroup(group);

    if (prefix !== "") {
      result += prefix + " " + Suffixs[groupCount - i - 1];
    }
  }

  result = result.trim();
  // Capitalize first letter
  return result.charAt(0).toUpperCase() + result.slice(1);
};

// Hàm đọc số thành chữ tiếng Anh (Simplified)
const readNumberEnglish = (number: number): string => {
    const a = ['','one ','two ','three ','four ','five ','six ','seven ','eight ','nine ','ten ','eleven ','twelve ','thirteen ','fourteen ','fifteen ','sixteen ','seventeen ','eighteen ','nineteen '];
    const b = ['', '', 'twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];

    const numToWords = (n: number): string => {
        if ((n = n.toString() as any).length > 9) return 'overflow';
        const n_arr: any[] = ('000000000' + n).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/) || [];
        if (!n_arr) return ""; 
        let str = '';
        str += (n_arr[1] != 0) ? (a[Number(n_arr[1])] || b[n_arr[1][0]] + ' ' + a[n_arr[1][1]]) + 'crore ' : '';
        str += (n_arr[2] != 0) ? (a[Number(n_arr[2])] || b[n_arr[2][0]] + ' ' + a[n_arr[2][1]]) + 'lakh ' : '';
        str += (n_arr[3] != 0) ? (a[Number(n_arr[3])] || b[n_arr[3][0]] + ' ' + a[n_arr[3][1]]) + 'thousand ' : '';
        str += (n_arr[4] != 0) ? (a[Number(n_arr[4])] || b[n_arr[4][0]] + ' ' + a[n_arr[4][1]]) + 'hundred ' : '';
        str += (n_arr[5] != 0) ? ((str != '') ? 'and ' : '') + (a[Number(n_arr[5])] || b[n_arr[5][0]] + ' ' + a[n_arr[5][1]]) : '';
        return str.trim();
    };

    // Fallback simple standard implementation
    if (number === 0) return "Zero";

    const units = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
    const tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
    const thousands = ["", "Thousand", "Million", "Billion"];

    let words = "";
    let i = 0;

    const numStr = Math.round(number).toString();

    // Very simple fallback for large numbers or specific implementation
    // Using Intl for robust English formatting if needed, but here is a simple recursion logic container
    // For this demo, let's use a cleaner recursive approach:

    function helper(n: number): string {
        if (n < 20) return units[n];
        if (n < 100) return tens[Math.floor(n / 10)] + (n % 10 !== 0 ? " " + units[n % 10] : "");
        if (n < 1000) return units[Math.floor(n / 100)] + " Hundred" + (n % 100 !== 0 ? " and " + helper(n % 100) : "");
        for (let j = 0; j < thousands.length; j++) {
            const unitVal = Math.pow(1000, j);
            const nextUnitVal = Math.pow(1000, j + 1);
            if (n < nextUnitVal) {
                return helper(Math.floor(n / unitVal)) + " " + thousands[j] + (n % unitVal !== 0 ? " " + helper(n % unitVal) : "");
            }
        }
        return numStr; // Fallback
    }

    return helper(Math.round(number));
};


export const convertCurrencyWithGemini = async (
  amount: number,
  fromCurrency: string,
  toCurrency: string
): Promise<ConversionResult> => {
  try {
    // 1. Fetch real-time exchange rate
    const response = await fetch(`https://open.er-api.com/v6/latest/${fromCurrency}`);
    if (!response.ok) {
        throw new Error('Network response was not ok');
    }
    const data = await response.json();
    const rate = data.rates[toCurrency];

    if (!rate) {
        throw new Error(`Exchange rate not found for ${toCurrency}`);
    }

    // 2. Calculate conversion
    const convertedAmount = amount * rate;

    // 3. Generate text description
    let textSource = "";
    let textTarget = "";

    // Source Text
    if (fromCurrency === 'VND') {
        textSource = readNumberVietnamese(amount) + " đồng";
    } else {
        // Default to English for other source currencies for simplicity
        textSource = readNumberEnglish(amount) + ` ${fromCurrency}`;
    }

    // Target Text
    if (toCurrency === 'VND') {
        textTarget = readNumberVietnamese(convertedAmount) + " đồng";
    } else {
        // Default to English for other target currencies
        // NOTE: Implementing native number readers for JP, KR, CN, etc. locally is complex.
        // We use English as the international standard fallback for non-Vietnamese targets.
        textTarget = readNumberEnglish(convertedAmount) + ` ${toCurrency}`;
    }

    return {
      convertedAmount,
      exchangeRate: rate,
      textSource,
      textTarget
    };

  } catch (error) {
    console.error("Currency API error:", error);
    throw new Error("Failed to convert currency. Please try again.");
  }
};

import React, { useState, useCallback } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { convertCurrencyWithGemini } from './services/geminiService';
import { POPULAR_CURRENCIES, DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from './constants';
