/**
 * XỬ LÝ LÀM TRÒN SỐ
 */
const getDecimals = (currencyCode: string): number => {
  // Các đồng tiền thường không dùng số thập phân
  if (['VND', 'JPY', 'KRW', 'TWD'].includes(currencyCode)) {
    return 0;
  }
  return 2;
};

const formatNumberStandard = (num: number, currencyCode: string): string => {
  const decimals = getDecimals(currencyCode);
  return num.toFixed(decimals);
};

/**
 * LOGIC ĐỌC SỐ TIẾNG VIỆT
 */
const readGroupVietnamese = (group: string): string => {
  const digits = ["không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín"];
  let temp = "";

  if (group === "000") return "";

  const a = parseInt(group.substring(0, 1)); // Trăm
  const b = parseInt(group.substring(1, 2)); // Chục
  const c = parseInt(group.substring(2, 3)); // Đơn vị

  // Hàng Trăm
  temp += digits[a] + " trăm";

  // Hàng Chục
  if (b === 0) {
    if (c === 0) return temp; // x00 -> x trăm
    temp += " linh " + digits[c]; // x05 -> x trăm linh năm
  } else if (b === 1) {
    temp += " mười";
    if (c === 1) temp += " một";
    else if (c === 5) temp += " lăm";
    else if (c !== 0) temp += " " + digits[c];
  } else {
    temp += " " + digits[b] + " mươi";
    if (c === 1) temp += " mốt"; // >20 thì 1 đọc là mốt
    else if (c === 4) temp += " tư"; // >20 thì 4 thường đọc là tư
    else if (c === 5) temp += " lăm"; // >20 thì 5 đọc là lăm
    else if (c !== 0) temp += " " + digits[c];
  }

  return temp;
};

const readNumberVietnamese = (number: number, currencyName: string): string => {
  if (number === 0) return "Không " + currencyName;

  const strNum = Math.abs(number).toString();
  const parts = strNum.split('.');

  // Phần nguyên
  let integerPart = parts[0];
  let decimalPart = parts.length > 1 ? parts[1] : "";

  // Xử lý phần nguyên
  while (integerPart.length % 3 !== 0) integerPart = "0" + integerPart;

  const groups = [];
  for (let i = 0; i < integerPart.length; i += 3) {
    groups.push(integerPart.substring(i, i + 3));
  }

  const suffixes = ["", "nghìn", "triệu", "tỷ", "nghìn tỷ", "triệu tỷ"];
  let result = "";
  let totalGroups = groups.length;

  for (let i = 0; i < totalGroups; i++) {
    const group = groups[i];
    const groupValue = parseInt(group);
    const suffix = suffixes[totalGroups - 1 - i];

    // Đọc nhóm số
    let read = readGroupVietnamese(group);

    // Fix lỗi "không trăm" ở nhóm đầu tiên nếu số nhỏ hơn 1000 nhưng được padding 0
    if (i === 0 && totalGroups === 1) {
        // Bỏ qua xử lý phức tạp, hàm readGroup đã lo
        // Chỉ cần clean up logic "linh" nếu số đầu là 0
        read = read.replace(/^không trăm linh/, "linh").replace(/^không trăm/, "");
        if (read.startsWith(" linh")) read = read.replace(" linh", ""); // Số chục
        if (read === "") read = "không"; // Trường hợp 0
    }

    if (groupValue > 0) {
       // Nếu không phải nhóm đầu tiên, và nhóm trước đó có giá trị, mà nhóm này < 100 -> thêm "không trăm" để nghe hợp lý
       // Tuy nhiên thuật toán readGroup đã luôn đọc "x trăm" nên ok.
       result += " " + read + " " + suffix;
    }
  }

  // Xử lý clean text
  result = result.trim().replace(/\s+/g, ' ');

  // Phần thập phân
  let decimalText = "";
  if (decimalPart && parseInt(decimalPart) > 0) {
      // Đọc từng số hoặc đọc gộp. Với tiền tệ thường đọc kiểu "phẩy năm mươi"
      // Để đơn giản và chuẩn, đọc tách số nếu dài, hoặc đọc như số thường.
      // Cách tốt nhất cho tiền tệ là đọc số thường.
      // Padding lại decimal cho đúng logic nhóm 3 nếu cần, nhưng thường decimal chỉ có 2 số.
      if (decimalPart.length === 1) decimalPart += "0"; // .5 -> .50

      // Reuse logic đọc nhóm cho decimal (thường < 100)
      let dVal = parseInt(decimalPart);
      let dRead = "";

      const digits = ["không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín"];
      if (dVal < 10) dRead = "linh " + digits[dVal];
      else {
          const chuc = Math.floor(dVal / 10);
          const donvi = dVal % 10;
          if (chuc === 1) dRead = "mười";
          else dRead = digits[chuc] + " mươi";

          if (donvi === 1 && chuc > 1) dRead += " mốt";
          else if (donvi === 5 && chuc > 0) dRead += " lăm";
          else if (donvi !== 0) dRead += " " + digits[donvi];
      }

      decimalText = " phẩy " + dRead;
  }

  // Ghép chuỗi
  let finalString = result + decimalText + " " + currencyName;

  // Capitalize
  finalString = finalString.trim();
  return finalString.charAt(0).toUpperCase() + finalString.slice(1);
};


/**
 * LOGIC ĐỌC SỐ TIẾNG ANH
 */
const readNumberEnglish = (number: number, currencyName: string): string => {
  const ones = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
  const tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
  const scales = ['', 'thousand', 'million', 'billion', 'trillion', 'quadrillion'];

  if (number === 0) return `Zero ${currencyName}`;

  const numStr = Math.abs(number).toString();
  const parts = numStr.split('.');
  let integerPart = parseInt(parts[0]);
  let decimalPart = parts.length > 1 ? parts[1] : null;

  let words = [];

  if (integerPart === 0) {
      words.push("zero");
  } else {
      let scaleIndex = 0;
      while (integerPart > 0) {
        const chunk = integerPart % 1000;
        if (chunk > 0) {
          const chunkStr = [];
          const hundreds = Math.floor(chunk / 100);
          const remainder = chunk % 100;

          if (hundreds > 0) {
            chunkStr.push(ones[hundreds]);
            chunkStr.push('hundred');
          }

          if (remainder > 0) {
             // Logic "and" nếu cần thiết, tiếng Anh Mỹ thường bỏ "and" giữa trăm và chục
             if (remainder < 20) {
               chunkStr.push(ones[remainder]);
             } else {
               const tenUnit = Math.floor(remainder / 10);
               const oneUnit = remainder % 10;
               chunkStr.push(tens[tenUnit]);
               if (oneUnit > 0) chunkStr.push(ones[oneUnit]);
             }
          }

          if (scales[scaleIndex]) {
             chunkStr.push(scales[scaleIndex]);
          }

          // Thêm vào đầu mảng words
          words.unshift(...chunkStr);
        }
        integerPart = Math.floor(integerPart / 1000);
        scaleIndex++;
      }
  }

  let result = words.join(' ');

  // Xử lý Decimal (Point XX)
  if (decimalPart) {
      if (decimalPart.length === 1) decimalPart += "0"; // .5 -> .50
      const dVal = parseInt(decimalPart.substring(0, 2)); // Lấy 2 số đầu
      if (dVal > 0) {
          result += " point";
          // Đọc từng số cho phần thập phân (theo chuẩn khoa học) hoặc đọc nhóm (tiền tệ).
          // Tiền tệ thường đọc: "Ten dollars and fifty cents".
          // Nhưng để tổng quát: "Ten point fifty Dollars".

          if (dVal < 20) {
             result += " " + ones[dVal];
          } else {
             const tenUnit = Math.floor(dVal / 10);
             const oneUnit = dVal % 10;
             result += " " + tens[tenUnit];
             if (oneUnit > 0) result += " " + ones[oneUnit];
          }
      }
  }

  // Capitalize
  result = result + " " + currencyName;
  return result.charAt(0).toUpperCase() + result.slice(1);
};


/**
 * HÀM CHUYỂN ĐỔI CHÍNH
 */
export const convertCurrencyApi = async (
  amount: number,
  fromCurrency: string,
  toCurrency: string
): Promise<ConversionResult> => {
  try {
    // 1. Fetch real-time exchange rate (bypass cache)
    const response = await fetch(`https://open.er-api.com/v6/latest/${fromCurrency}?t=${Date.now()}`);

    if (!response.ok) {
        throw new Error('Network response was not ok');
    }
    const data = await response.json();
    const rate = data.rates[toCurrency];

    if (!rate) {
        throw new Error(`Exchange rate not found for ${toCurrency}`);
    }

    // 2. Tính toán & Làm tròn
    const rawConverted = amount * rate;

    // Làm tròn số input để đọc cho đúng (nếu input người dùng nhập nhiều số lẻ)
    const sourceDecimals = getDecimals(fromCurrency);
    const roundedInput = parseFloat(amount.toFixed(sourceDecimals));

    // Làm tròn số output để hiển thị và đọc
    const targetDecimals = getDecimals(toCurrency);
    const roundedConverted = parseFloat(rawConverted.toFixed(targetDecimals));

    // 3. Tạo Text
    let textSource = "";
    let textTarget = "";

    // -- Text Nguồn (Luôn ưu tiên Tiếng Việt nếu là VND, ngược lại Tiếng Anh hoặc format chung) --
    // Theo yêu cầu: "mệnh giá viết bằng chữ theo tiếng Việt và ngôn ngữ của nước có mệnh giá tiền được đổi"
    // Source Text: Nếu là VND -> Tiếng Việt. Nếu nước ngoài -> Tiếng Anh (Lingua Franca)
    if (fromCurrency === 'VND') {
        textSource = readNumberVietnamese(roundedInput, "Đồng");
    } else {
        textSource = readNumberEnglish(roundedInput, fromCurrency);
    }

    // -- Text Đích --
    if (toCurrency === 'VND') {
        textTarget = readNumberVietnamese(roundedConverted, "Đồng");
    } else {
        textTarget = readNumberEnglish(roundedConverted, toCurrency);
    }

    return {
      convertedAmount: roundedConverted, // Trả về số đã làm tròn để UI hiển thị khớp với Text
      exchangeRate: rate,
      textSource,
      textTarget
    };

  } catch (error) {
    console.error("Currency API error:", error);
    throw new Error("Failed to convert currency. Please try again.");
  }
};

