/**
 * 3. JAPANESE (Tiếng Nhật - JPY) & CHINESE (Tiếng Trung - CNY) & KOREAN (Tiếng Hàn - KRW)
 * Logic chung: Chia nhóm 4 số (Vạn/Man/Man)
 */

const readCJK = (
    number: number, 
    currencyName: string, 
    chars: { digits: string[], units: string[], groups: string[] },
    lang: 'JP' | 'CN' | 'KR'
): string => {
    if (number === 0) return `${chars.digits[0]}${currencyName}`;

    let num = Math.floor(number); // JPY/KRW usually no decimals
    let result = "";
    let groupIndex = 0;

    while (num > 0) {
        const part = num % 10000;
        if (part > 0) {
            let partStr = "";
            let p = part;
            let unitIndex = 0;
            let zeroFlag = false; // Handle zeros in Chinese

            // Process digits in group of 4 (units, tens, hundreds, thousands)
            // Example: 1234 -> 1000 200 30 4
            const digitsInPart = [];
            for (let i = 0; i < 4; i++) {
                digitsInPart.push(p % 10);
                p = Math.floor(p / 10);
            }

            for(let i=0; i<4; i++) {
                const digit = digitsInPart[i];
                if (digit > 0) {
                    // Logic for 10 (Juu/Shi/Sip): 
                    // JP: 10 is "Juu", not "Ichi Juu". 
                    // KR: 10 is "Sip", not "Il Sip".
                    // CN: 10 is "Shi", but 110 is "Yi Bai Yi Shi".

                    let prefix = chars.digits[digit];
                    if (i === 1 && digit === 1 && (lang === 'JP' || lang === 'KR')) {
                        prefix = ""; // Skip "One" for tens in JP/KR
                    }

                    partStr = prefix + (i > 0 ? chars.units[i-1] : "") + partStr;
                    zeroFlag = false;
                } else if (lang === 'CN' && !zeroFlag && i < 3 && partStr.length > 0) {
                     // Chinese Zero logic (simplified)
                     // partStr = chars.digits[0] + partStr; 
                     // zeroFlag = true;
                }
            }

            result = partStr + (groupIndex > 0 ? chars.groups[groupIndex - 1] : "") + result;
        }
        num = Math.floor(num / 10000);
        groupIndex++;
    }

    return result + currencyName;
};

