                      ${isDarkMode ? 'bg-slate-700 border-slate-800 text-white hover:bg-slate-600' : 'bg-white border-slate-100 hover:bg-slate-50'}
                      ${isSwapping ? 'rotate-180 scale-110' : 'hover:rotate-180 hover:scale-110'}
