            </div>

            {/* Row 2: Target Currency Selector */}
            {/* Added 'mt-2' to give just enough space for the button to breathe without a large gap */}
            <div className={`relative transition-all duration-200 mt-2 ${activeDropdown === 'TO' ? 'z-50' : 'z-10'}`}>
                <CurrencyRow
                    label="Sang đơn vị"
                    amount=""
