import React, { useRef, useEffect, useState, useMemo } from 'react';
import { POPULAR_CURRENCIES as CURRENCY_LIST } from '../constants';
import { Currency } from '../types';

interface CurrencyRowProps {
  label: string;
  amount: number | string;
  currency: Currency;
  onAmountChange?: (value: string) => void;
  onCurrencyChange: (currency: Currency) => void;
  readOnly?: boolean;
  isActive?: boolean;
  onToggleDropdown?: () => void;
  onCloseDropdown?: () => void;
  hideInput?: boolean; // New prop to hide the input field
}

export const CurrencyRow: React.FC<CurrencyRowProps> = ({
  label,
  amount,
  currency,
  onAmountChange,
  onCurrencyChange,
  readOnly = false,
  isActive = false,
  onToggleDropdown,
  onCloseDropdown,
  hideInput = false,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Handle clicking outside to close dropdown
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        if (isActive && onCloseDropdown) {
          onCloseDropdown();
        }
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isActive, onCloseDropdown]);

  // Focus search input when dropdown opens
  useEffect(() => {
    if (isActive) {
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 50);
    } else {
      const timeout = setTimeout(() => setSearchQuery(''), 300);
      return () => clearTimeout(timeout);
    }
  }, [isActive]);

  const filteredCurrencies = CURRENCY_LIST.filter((c) => 
    c.code.toLowerCase().includes(searchQuery.toLowerCase()) || 
    c.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // --- FORMATTING LOGIC START ---
  const { groupSeparator, decimalSeparator } = useMemo(() => {
    try {
      const parts = new Intl.NumberFormat(currency.locale).formatToParts(1000.1);
      return {
        groupSeparator: parts.find(p => p.type === 'group')?.value || ',',
        decimalSeparator: parts.find(p => p.type === 'decimal')?.value || '.'
      };
    } catch (e) {
      return { groupSeparator: ',', decimalSeparator: '.' };
    }
  }, [currency.locale]);

  const displayValue = useMemo(() => {
    if (amount === '' || amount === undefined || amount === null) return '';
    if (isNaN(Number(amount)) && !amount.toString().endsWith('.')) return amount.toString();

    const strAmount = amount.toString();
    const parts = strAmount.split('.');
    const integerPart = parts[0];
    const decimalPart = parts.length > 1 ? parts[1] : null;

    const integerFormatted = integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, groupSeparator);

    if (decimalPart !== null) {
      return `${integerFormatted}${decimalSeparator}${decimalPart}`;
    }
    return integerFormatted;
  }, [amount, groupSeparator, decimalSeparator]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!onAmountChange) return;
    let value = e.target.value;
    if (value === '') {
      onAmountChange('');
      return;
    }
    const escapedGroupSep = groupSeparator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const escapedDecimalSep = decimalSeparator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const rawNoGroups = value.replace(new RegExp(escapedGroupSep, 'g'), '');
    const normalized = rawNoGroups.replace(new RegExp(escapedDecimalSep), '.');

    if (/^\d*\.?\d*$/.test(normalized)) {
      onAmountChange(normalized);
    }
  };

  return (
    <div className="flex flex-col gap-1.5" ref={containerRef}>
      <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wide ml-1">{label}</label>

      {/* Unified Container */}
      {/* Logic: Light mode is now bg-white (was bg-slate-50). Dark mode remains bg-slate-800. */}
      <div 
        className={`relative flex items-center border rounded-2xl transition-all duration-300
          ${isActive 
            ? 'border-blue-500 ring-2 ring-blue-100 dark:ring-blue-900/40 bg-white dark:bg-slate-800 z-50' 
            : 'border-slate-200 dark:border-slate-700 hover:border-blue-300 dark:hover:border-blue-500 bg-white dark:bg-slate-800'}
          ${readOnly ? 'opacity-90' : ''}
        `}
      >

        {/* Input Area (Left) - Hidden if hideInput is true */}
        {!hideInput && (
          <>
            <div className="flex-1 p-2">
              <input
                type="text"
                inputMode="decimal"
                value={displayValue}
                onChange={handleInputChange}
                readOnly={readOnly}
                className={`w-full h-12 px-2 bg-transparent border-none outline-none text-3xl font-bold placeholder-slate-300
                  ${readOnly ? 'text-slate-600 dark:text-slate-400 cursor-default' : 'text-slate-800 dark:text-white'}
                `}
                placeholder="0"
                autoComplete="off"
              />
            </div>
            {/* Divider */}
            <div className="w-px h-10 bg-slate-200 dark:bg-slate-600 mx-1"></div>
          </>
        )}

        {/* Currency Selector Trigger */}
        <button
          onClick={onToggleDropdown}
          className={`flex items-center gap-2 px-4 py-4 m-1 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors group outline-none focus:bg-slate-100 dark:focus:bg-slate-700
             ${hideInput ? 'w-full justify-between' : ''}
          `}
        >
          <div className="flex items-center gap-3">
             <img 
              src={currency.flag} 
              alt={currency.code} 
              className="w-8 h-6 object-cover rounded shadow-sm border border-slate-100 dark:border-slate-600 group-hover:scale-110 transition-transform"
            />
            <div className="flex flex-col items-start">
               <span className="text-xl font-bold text-slate-700 dark:text-slate-100">{currency.code}</span>
               {hideInput && <span className="text-xs text-slate-400 dark:text-slate-500 font-medium">{currency.name}</span>}
            </div>
          </div>

          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            fill="none" 
            viewBox="0 0 24 24" 
            strokeWidth={3} 
            stroke="currentColor" 
            className={`w-4 h-4 text-slate-400 transition-transform duration-300 ${isActive ? 'rotate-180 text-blue-500' : ''}`}
          >
            <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" />
          </svg>
        </button>

        {/* Dropdown Menu */}
        <div 
          className={`absolute right-0 top-[calc(100%+8px)] w-full sm:w-80 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-slate-100 dark:border-slate-700 overflow-hidden transition-all duration-200 flex flex-col z-[100]
            ${isActive ? 'opacity-100 scale-100 translate-y-0 visible' : 'opacity-0 scale-95 -translate-y-2 invisible pointer-events-none'}
            ${hideInput ? 'left-0 sm:left-auto' : ''}
          `}
        >
            {/* Sticky Search Header */}
            <div className="p-3 bg-white dark:bg-slate-800 border-b border-slate-100 dark:border-slate-700">
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                </div>
                <input
                  ref={searchInputRef}
                  type="text"
                  className="block w-full pl-10 pr-3 py-2.5 border border-slate-200 dark:border-slate-600 rounded-xl bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-200 placeholder-slate-400 focus:outline-none focus:bg-white dark:focus:bg-slate-600 focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 sm:text-sm transition-all"
                  placeholder="Tìm kiếm tiền tệ..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
            </div>

            {/* Scrollable List */}
            <div className="max-h-64 overflow-y-auto custom-scrollbar p-1.5 space-y-1">
              {filteredCurrencies.length > 0 ? (
                filteredCurrencies.map((c) => (
                  <div
                    key={c.code}
                    onClick={() => { 
                        onCurrencyChange(c); 
                        if (onCloseDropdown) onCloseDropdown(); 
                    }}
                    className={`flex items-center gap-3 px-3 py-3 rounded-xl cursor-pointer transition-all duration-200
                      ${c.code === currency.code ? 'bg-blue-50 dark:bg-blue-900/30 border border-blue-100 dark:border-blue-800' : 'hover:bg-slate-50 dark:hover:bg-slate-700 border border-transparent'}
                    `}
                  >
                      <img 
                        src={c.flag} 
                        alt={c.code} 
                        className="w-8 h-6 object-cover rounded shadow-sm border border-slate-100 dark:border-slate-600"
                      />
                      <div className="flex flex-col flex-1 min-w-0">
                        <div className="flex justify-between items-center">
                            <span className={`font-bold text-base ${c.code === currency.code ? 'text-blue-700 dark:text-blue-400' : 'text-slate-700 dark:text-slate-200'}`}>{c.code}</span>
                            {c.code === currency.code && (
                              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5 text-blue-600 dark:text-blue-400">
                                <path fillRule="evenodd" d="M16.704 4.153a.75.75 0 01.143 1.052l-8 10.5a.75.75 0 01-1.127.075l-4.5-4.5a.75.75 0 011.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 011.05-.143z" clipRule="evenodd" />
                              </svg>
                            )}
                        </div>
                        <span className="text-xs font-medium text-slate-500 dark:text-slate-400 truncate">{c.name}</span>
                      </div>
                  </div>
                ))
              ) : (
                <div className="py-8 text-center">
                  <p className="text-slate-400 text-sm">Không tìm thấy "{searchQuery}"</p>
                </div>
              )}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { convertCurrencyApi } from './services/geminiService';
import { POPULAR_CURRENCIES, DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from './constants';
import { ConversionResult, LoadingState, Currency } from './types';

const App: React.FC = () => {
  const [amount, setAmount] = useState<string>('100000');
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);

  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');

  // UI State
  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [isSwapping, setIsSwapping] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [accentColor, setAccentColor] = useState('#2563eb'); // Blue-600 (Original color)

  // Apply dark mode to document
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  // Core logic
  const executeConversion = async (currentAmount: number, source: Currency, target: Currency) => {
    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');
    setResult(null);

    try {
      const data = await convertCurrencyApi(currentAmount, source.code, target.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);
    } catch (err) {
      console.error(err);
      setErrorMsg("Có lỗi xảy ra khi lấy tỷ giá. Vui lòng thử lại.");
      setLoadingState(LoadingState.ERROR);
    }
  };

  const handleConvert = useCallback(() => {
    const numAmount = parseFloat(amount);
    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }
    executeConversion(numAmount, fromCurrency, toCurrency);
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = () => {
    setIsSwapping(true);
    setTimeout(() => setIsSwapping(false), 500); 

    // Swap currencies
    const newFrom = toCurrency;
    const newTo = fromCurrency;

    setFromCurrency(newFrom);
    setToCurrency(newTo);

    // Auto-trigger if we have valid input
    const numAmount = parseFloat(amount);
    if (!isNaN(numAmount) && numAmount > 0) {
        executeConversion(numAmount, newFrom, newTo);
    }
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        return new Intl.NumberFormat(locale, {
        style: 'currency',
        currency: currencyCode,
        maximumFractionDigits: 0,
        minimumFractionDigits: 0
        }).format(val);
    } catch (e) {
        return `${val} ${currencyCode}`;
    }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  // Styles based on accent color
  const primaryBgStyle = { backgroundColor: accentColor };
  const primaryTextStyle = { color: accentColor };
  // Gradient mimicking original aesthetic
  const gradientStyle = { background: `linear-gradient(135deg, ${accentColor}, ${adjustColorBrightness(accentColor, -40)})` };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${isDarkMode ? 'bg-slate-900 text-slate-100' : 'bg-slate-100 text-slate-800'} flex items-center justify-center p-4 font-sans`}>

      {/* Settings Bar (Fixed Top Right) */}
      <div className="fixed top-4 right-4 z-[100] flex items-center gap-3 bg-white/10 backdrop-blur-md p-2 rounded-full border border-white/20 shadow-lg">

          {/* Color Picker */}
          <div className="relative group cursor-pointer" title="Chọn màu chủ đạo">
              <div className="w-8 h-8 rounded-full border-2 border-white shadow-sm overflow-hidden" style={primaryBgStyle}>
                <input 
                  type="color" 
                  value={accentColor}
                  onChange={(e) => setAccentColor(e.target.value)}
                  className="opacity-0 w-full h-full cursor-pointer absolute inset-0" 
                />
