import React, { useRef, useEffect, useState, useMemo } from 'react';
import { POPULAR_CURRENCIES as CURRENCY_LIST } from '../constants';
import { Currency } from '../types';

interface CurrencyRowProps {
  label: string;
  amount: number | string;
  currency: Currency;
  onAmountChange?: (value: string) => void;
  onCurrencyChange: (currency: Currency) => void;
  readOnly?: boolean;
  isActive?: boolean;
  onToggleDropdown?: () => void;
  onCloseDropdown?: () => void;
  inputPlacement?: 'left' | 'right' | 'hidden'; // Control layout
}

export const CurrencyRow: React.FC<CurrencyRowProps> = ({
  label,
  amount,
  currency,
  onAmountChange,
  onCurrencyChange,
  readOnly = false,
  isActive = false,
  onToggleDropdown,
  onCloseDropdown,
  inputPlacement = 'left',
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const amountInputRef = useRef<HTMLInputElement>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Handle clicking outside to close dropdown
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        if (isActive && onCloseDropdown) {
          onCloseDropdown();
        }
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isActive, onCloseDropdown]);

  // Focus search input when dropdown opens
  useEffect(() => {
    if (isActive) {
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 50);
    } else {
      const timeout = setTimeout(() => setSearchQuery(''), 300);
      return () => clearTimeout(timeout);
    }
  }, [isActive]);

  const filteredCurrencies = CURRENCY_LIST.filter((c) => 
    c.code.toLowerCase().includes(searchQuery.toLowerCase()) || 
    c.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // --- FORMATTING LOGIC ---
  const { groupSeparator, decimalSeparator } = useMemo(() => {
    try {
      const parts = new Intl.NumberFormat(currency.locale).formatToParts(1000.1);
      return {
        groupSeparator: parts.find(p => p.type === 'group')?.value || ',',
        decimalSeparator: parts.find(p => p.type === 'decimal')?.value || '.'
      };
    } catch (e) {
      return { groupSeparator: ',', decimalSeparator: '.' };
    }
  }, [currency.locale]);

  const displayValue = useMemo(() => {
    if (amount === '' || amount === undefined || amount === null) return '';

    const strAmount = amount.toString();
    const parts = strAmount.split('.');
    const integerPart = parts[0];
    const decimalPart = parts.length > 1 ? parts[1] : null;

    // Apply thousands separator to the integer part
    const integerFormatted = integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, groupSeparator);

    if (decimalPart !== null) {
      return `${integerFormatted}${decimalSeparator}${decimalPart}`;
    }
    return integerFormatted;
  }, [amount, groupSeparator, decimalSeparator]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!onAmountChange) return;
    let value = e.target.value;

    if (value === '') {
      onAmountChange('');
      return;
    }

    // Helper to escape regex special characters
    const escapeRegex = (string: string) => string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    // UX Improvement: If the locale uses ',' as decimal separator (like Vietnam),
    // but the user types '.', assume they mean the decimal separator.
    if (decimalSeparator === ',' && value.endsWith('.')) {
         value = value.slice(0, -1) + ',';
    }

    // 1. Remove all group separators
    const groupSepRegex = new RegExp(escapeRegex(groupSeparator), 'g');
    let cleanValue = value.replace(groupSepRegex, '');

    // 2. Replace localized decimal separator with standard dot '.'
    const decimalSepRegex = new RegExp(escapeRegex(decimalSeparator), 'g');
    cleanValue = cleanValue.replace(decimalSepRegex, '.');

    // 3. Remove any non-numeric characters (except the single dot)
    cleanValue = cleanValue.replace(/[^0-9.]/g, '');

    // 4. Ensure only one dot exists
    const parts = cleanValue.split('.');
    if (parts.length > 2) {
      cleanValue = parts[0] + '.' + parts.slice(1).join('');
    }

    onAmountChange(cleanValue);
  };

  // --- RENDER HELPERS (JSX Logic moved inside return to avoid re-mounting bugs) ---

  const renderSelectorButton = () => (
    <button
      onClick={(e) => {
        e.stopPropagation(); // Prevent focusing input when clicking button
        if (onToggleDropdown) onToggleDropdown();
      }}
      className={`flex items-center gap-2 px-2 py-3 sm:px-3 sm:py-4 hover:bg-slate-50 transition-colors group outline-none shrink-0
        ${inputPlacement === 'hidden' ? 'w-full justify-between rounded-2xl' : ''}
        ${inputPlacement === 'left' ? 'rounded-r-2xl border-l border-slate-100' : ''}
        ${inputPlacement === 'right' ? 'rounded-l-2xl border-r border-slate-100' : ''}
      `}
    >
      <div className="flex items-center gap-2">
        <img 
          src={currency.flag} 
          alt={currency.code} 
          className="w-6 h-4 sm:w-7 sm:h-5 object-cover rounded shadow-sm border border-slate-100 group-hover:scale-110 transition-transform"
        />
        <div className="flex flex-col items-start">
            <span className="text-base sm:text-lg font-bold text-slate-700 leading-none">{currency.code}</span>
        </div>
      </div>

      <svg 
        xmlns="http://www.w3.org/2000/svg" 
        fill="none" 
        viewBox="0 0 24 24" 
        strokeWidth={3} 
        stroke="currentColor" 
        className={`w-3 h-3 sm:w-3.5 sm:h-3.5 text-slate-400 transition-transform duration-300 ${isActive ? 'rotate-180 text-blue-500' : ''}`}
      >
        <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" />
      </svg>
    </button>
  );

  const renderInput = () => (
    <div className="flex-1 p-2 w-full h-full">
      <input
        ref={amountInputRef}
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={handleInputChange}
        readOnly={readOnly}
        className={`w-full h-full px-2 bg-transparent border-none outline-none text-xl sm:text-2xl font-bold placeholder-slate-300 text-slate-800
           ${readOnly ? 'cursor-default' : ''}
           text-left
        `}
        placeholder="0"
        autoComplete="off"
      />
    </div>
  );

  return (
    <div className="flex flex-col gap-1.5 w-full" ref={containerRef}>
      <label className="text-[10px] sm:text-xs font-bold text-slate-500 uppercase tracking-wide ml-1">{label}</label>

      {/* Container - Click to focus input */}
      <div 
        onClick={() => {
            if (!readOnly && !isActive) {
                amountInputRef.current?.focus();
            }
        }}
        className={`relative flex items-center bg-white border rounded-2xl transition-all duration-300 h-[60px] sm:h-[66px] cursor-text
          ${isActive 
            ? 'border-blue-500 ring-2 ring-blue-100 z-50' 
            : 'border-slate-200 hover:border-blue-300'}
          ${readOnly ? 'opacity-90 cursor-default' : ''}
        `}
      >
        {/* Render Order based on Placement */}
        {inputPlacement === 'left' && <>{renderInput()}{renderSelectorButton()}</>}
        {inputPlacement === 'right' && <>{renderSelectorButton()}{renderInput()}</>}
        {inputPlacement === 'hidden' && renderSelectorButton()}

        {/* Dropdown Menu */}
        <div 
          className={`absolute top-[calc(100%+8px)] w-full sm:w-72 bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden transition-all duration-200 flex flex-col z-[100]
            ${isActive ? 'opacity-100 scale-100 translate-y-0 visible' : 'opacity-0 scale-95 -translate-y-2 invisible pointer-events-none'}
            ${inputPlacement === 'right' ? 'left-0' : 'right-0'}
          `}
        >
            {/* Search */}
            <div className="p-3 bg-white border-b border-slate-100">
              <input
                ref={searchInputRef}
                type="text"
                className="block w-full px-3 py-2 border border-slate-200 rounded-lg bg-slate-50 text-slate-700 placeholder-slate-400 focus:outline-none focus:bg-white focus:border-blue-500 text-sm"
                placeholder="Tìm kiếm..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onClick={(e) => e.stopPropagation()} 
              />
            </div>

            {/* List */}
            <div className="max-h-64 overflow-y-auto custom-scrollbar p-1">
              {filteredCurrencies.length > 0 ? (
                filteredCurrencies.map((c) => (
                  <div
                    key={c.code}
                    onClick={(e) => { 
                        e.stopPropagation();
                        onCurrencyChange(c); 
                        if (onCloseDropdown) onCloseDropdown(); 
                    }}
                    className={`flex items-center gap-3 px-3 py-2.5 rounded-lg cursor-pointer transition-colors
                      ${c.code === currency.code ? 'bg-blue-50 text-blue-700' : 'hover:bg-slate-50 text-slate-700'}
                    `}
                  >
                      <img src={c.flag} alt={c.code} className="w-6 h-4 object-cover rounded shadow-sm" />
                      <div className="flex flex-col">
                        <span className="text-sm font-bold">{c.code}</span>
                        <span className="text-xs opacity-70 truncate max-w-[150px]">{c.name}</span>
                      </div>
                  </div>
                ))
              ) : (
                <div className="py-4 text-center text-slate-400 text-xs">Không tìm thấy</div>
              )}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { convertCurrencyApi } from './services/geminiService';
import { DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from './constants';
import { ConversionResult, LoadingState, Currency } from './types';

const App: React.FC = () => {
  const [amount, setAmount] = useState<string>('100000');
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);

  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');

  // UI State
  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [isSwapping, setIsSwapping] = useState(false);

  // Core logic
  const executeConversion = async (currentAmount: number, source: Currency, target: Currency) => {
    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');
    setResult(null);

    try {
      const data = await convertCurrencyApi(currentAmount, source.code, target.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);
    } catch (err) {
      console.error(err);
      setErrorMsg("Có lỗi xảy ra khi lấy tỷ giá. Vui lòng thử lại.");
      setLoadingState(LoadingState.ERROR);
    }
  };

  const handleConvert = useCallback(() => {
    const numAmount = parseFloat(amount);
    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }
    executeConversion(numAmount, fromCurrency, toCurrency);
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = () => {
    setIsSwapping(true);
    setTimeout(() => setIsSwapping(false), 500); 

    // Swap currencies
    const newFrom = toCurrency;
    const newTo = fromCurrency;

    setFromCurrency(newFrom);
    setToCurrency(newTo);

    // Auto-trigger if we have valid input
    const numAmount = parseFloat(amount);
    if (!isNaN(numAmount) && numAmount > 0) {
        executeConversion(numAmount, newFrom, newTo);
    }
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        return new Intl.NumberFormat(locale, {
        style: 'currency',
        currency: currencyCode,
        maximumFractionDigits: 0,
        minimumFractionDigits: 0
        }).format(val);
    } catch (e) {
        return `${val} ${currencyCode}`;
    }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-3 sm:p-4 font-sans text-slate-800">

      <div className="w-full max-w-5xl bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-white/50 relative flex flex-col my-2 sm:my-0">

        {/* Header */}
        <div className="bg-gradient-to-r from-blue-600 via-blue-700 to-indigo-700 p-6 sm:p-8 text-center relative overflow-hidden rounded-t-3xl">
          <div className="absolute top-0 left-0 w-full h-full opacity-10">
             <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
                 <circle cx="0" cy="0" r="40" fill="white" />
                 <circle cx="100" cy="100" r="60" fill="white" />
             </svg>
          </div>

          <div className="relative z-10">
            <h1 className="text-2xl sm:text-3xl font-extrabold text-white mb-2 tracking-tight drop-shadow-sm">Máy Đổi Tiền Của Gia Hân♎️</h1>
            <div className="inline-flex items-center gap-2 text-white/90 text-xs sm:text-sm font-medium bg-white/20 px-3 py-1 rounded-full backdrop-blur-md">
               <span className="w-2 h-2 rounded-full bg-green-400 animate-pulse"></span>
               Tỷ giá cập nhật liên tục
            </div>
          </div>
        </div>

        {/* Main Content */}
        <div className="p-4 sm:p-8 space-y-6 relative flex-1">

          {/* 
              Main Input Row 
              Changed layout strategy:
              - Mobile: Vertical stack with NO GAP. The button sits in between with negative Y margin.
              - Desktop: Horizontal row with NO GAP. The button sits in between with negative X margin.
          */}
          <div className="flex flex-col md:flex-row items-stretch md:items-center relative z-20">

            {/* Left: Amount Input & Source Currency */}
            <div className={`relative w-full md:flex-[3] transition-all duration-200 ${activeDropdown === 'FROM' ? 'z-50' : 'z-20'}`}> 
                <CurrencyRow
                    label="Nhập số tiền cần đổi"
                    amount={amount}
                    currency={fromCurrency}
                    onAmountChange={setAmount}
                    onCurrencyChange={setFromCurrency}
                    inputPlacement="left"
                    isActive={activeDropdown === 'FROM'}
                    onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                    onCloseDropdown={() => setActiveDropdown(null)}
                />
            </div>

            {/* Middle: Swap Button Wrapper */}
            {/* 
                -my-4 (Mobile): Pulls top and bottom elements closer, button floats on top.
                md:-mx-5 (Desktop): Pulls left and right elements closer, button floats in middle.
                md:my-0: Reset vertical margin on desktop.
            */}
            <div className="relative z-30 flex items-center justify-center -my-4 md:-my-0 md:-mx-5 pointer-events-none">
                <button
                    onClick={handleSwap}
                    className={`
                        pointer-events-auto
                        flex-shrink-0 w-12 h-12 rounded-full shadow-lg 
                        bg-white text-blue-600 
                        border-[5px] border-white
                        hover:bg-blue-50 hover:text-blue-700 hover:border-blue-50
                        transition-all duration-300 transform flex items-center justify-center
                        ${isSwapping ? 'animate-swap-spin bg-blue-50' : 'hover:scale-110 hover:shadow-blue-200/50'}
                        focus:outline-none focus:ring-2 focus:ring-blue-500/30
                    `}
                    title="Hoán đổi vị trí"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5 sm:w-6 sm:h-6 transform rotate-90 md:rotate-0 transition-transform duration-300">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M7.5 21 3 16.5m0 0L7.5 12M3 16.5h13.5m0-13.5L21 7.5m0 0L16.5 12M21 7.5H7.5" />
                    </svg>
                </button>
            </div>

            {/* Right: Target Currency */}
            <div className={`relative w-full md:flex-[2] transition-all duration-200 ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                <CurrencyRow
                    label="Quy đổi sang"
                    amount=""
                    currency={toCurrency}
                    onCurrencyChange={setToCurrency}
                    inputPlacement="hidden" // Selector Only
                    isActive={activeDropdown === 'TO'}
                    onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                    onCloseDropdown={() => setActiveDropdown(null)}
                />
            </div>
          </div>

          {/* Action Button */}
          <button
            onClick={handleConvert}
            disabled={loadingState === LoadingState.LOADING}
            className={`w-full py-3.5 sm:py-4 rounded-2xl text-white font-bold text-base sm:text-lg shadow-xl shadow-blue-500/20 transition-all duration-300 transform relative overflow-hidden mt-4
              ${loadingState === LoadingState.LOADING 
                ? 'bg-slate-400 cursor-not-allowed opacity-80' 
                : 'bg-gradient-to-r from-blue-600 to-indigo-600 hover:-translate-y-1 active:scale-[0.98]'
              }`}
          >
             <div className="absolute inset-0 bg-white/10 hover:bg-transparent transition-colors"></div>
             <span className="relative z-10 flex items-center justify-center gap-2">
                {loadingState === LoadingState.LOADING ? (
                  <>
                    <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Đang xử lý...
                  </>
                ) : (
                  'Chuyển đổi ngay'
                )}
             </span>
          </button>

