import React, { useRef, useEffect, useState, useMemo } from 'react';
import { POPULAR_CURRENCIES as CURRENCY_LIST } from '../constants';
import { Currency } from '../types';

interface CurrencyRowProps {
  label: string;
  amount: number | string;
  currency: Currency;
  onAmountChange?: (value: string) => void;
  onCurrencyChange: (currency: Currency) => void;
  readOnly?: boolean;
  isActive?: boolean;
  onToggleDropdown?: () => void;
  onCloseDropdown?: () => void;
  inputPlacement?: 'left' | 'right' | 'hidden';
  autoFocus?: boolean;
}

export const CurrencyRow: React.FC<CurrencyRowProps> = ({
  label, amount, currency, onAmountChange, onCurrencyChange,
  readOnly = false, isActive = false, onToggleDropdown, onCloseDropdown,
  inputPlacement = 'left', autoFocus = false
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const amountInputRef = useRef<HTMLInputElement>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    if (autoFocus && amountInputRef.current) {
      amountInputRef.current.focus();
    }
  }, [autoFocus]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        if (isActive && onCloseDropdown) onCloseDropdown();
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [isActive, onCloseDropdown]);

  useEffect(() => {
    if (isActive) setTimeout(() => searchInputRef.current?.focus(), 50);
    else setSearchQuery('');
  }, [isActive]);

  const filteredCurrencies = CURRENCY_LIST.filter((c) => 
    c.code.toLowerCase().includes(searchQuery.toLowerCase()) || 
    c.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const { groupSeparator, decimalSeparator } = useMemo(() => {
    try {
      const parts = new Intl.NumberFormat(currency.locale).formatToParts(1000.1);
      return {
        groupSeparator: parts.find(p => p.type === 'group')?.value || ',',
        decimalSeparator: parts.find(p => p.type === 'decimal')?.value || '.'
      };
    } catch (e) { return { groupSeparator: ',', decimalSeparator: '.' }; }
  }, [currency.locale]);

  const displayValue = useMemo(() => {
    if (amount === '' || amount === undefined || amount === null) return '';
    const parts = amount.toString().split('.');
    const integerFormatted = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, groupSeparator);
    return parts.length > 1 ? `${integerFormatted}${decimalSeparator}${parts[1]}` : integerFormatted;
  }, [amount, groupSeparator, decimalSeparator]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!onAmountChange) return;
    let value = e.target.value;
    if (value === '') { onAmountChange(''); return; }
    if (decimalSeparator === ',' && value.endsWith('.')) value = value.slice(0, -1) + ',';
    const groupSepRegex = new RegExp(groupSeparator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
    let cleanValue = value.replace(groupSepRegex, '').replace(new RegExp(decimalSeparator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'), '.').replace(/[^0-9.]/g, '');
    const parts = cleanValue.split('.');
    if (parts.length > 2) cleanValue = parts[0] + '.' + parts.slice(1).join('');
    onAmountChange(cleanValue);
  };

  const renderSelectorButton = () => (
    <button
      onClick={(e) => { e.stopPropagation(); if (onToggleDropdown) onToggleDropdown(); }}
      className={`flex items-center gap-2 px-2 py-3 sm:px-3 sm:py-4 hover:bg-slate-50 transition-colors group outline-none shrink-0
        ${inputPlacement === 'hidden' ? 'w-full justify-between rounded-2xl' : ''}
        ${inputPlacement === 'left' ? 'rounded-r-2xl border-l border-slate-100' : ''}
        ${inputPlacement === 'right' ? 'rounded-l-2xl border-r border-slate-100' : ''}
      `}
    >
      <div className="flex items-center gap-2">
        <img src={currency.flag} alt={currency.code} className="w-6 h-4 sm:w-7 sm:h-5 object-cover rounded shadow-sm border border-slate-100" />
        <span className="text-base sm:text-lg font-bold text-slate-700 leading-none">{currency.code}</span>
      </div>
      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className={`w-3 h-3 sm:w-3.5 sm:h-3.5 text-slate-400 transition-transform ${isActive ? 'rotate-180 text-blue-500' : ''}`}><path strokeLinecap="round" strokeLinejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" /></svg>
    </button>
  );

  const renderInput = () => (
    <div className="flex-1 p-2 w-full h-full">
      <input
        ref={amountInputRef}
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={handleInputChange}
        readOnly={readOnly}
        className="w-full h-full px-2 bg-transparent border-none outline-none text-xl sm:text-2xl font-bold placeholder-slate-300 text-slate-800"
        placeholder="0"
        autoComplete="off"
      />
    </div>
  );

  return (
    <div className="flex flex-col gap-1.5 w-full" ref={containerRef}>
      <label className="text-[10px] sm:text-xs font-bold text-slate-500 uppercase tracking-wide ml-1">{label}</label>
      <div onClick={() => !readOnly && !isActive && amountInputRef.current?.focus()}
        className={`relative flex items-center bg-white border rounded-2xl transition-all h-[60px] sm:h-[66px] cursor-text ${isActive ? 'border-blue-500 ring-2 ring-blue-100 z-50' : 'border-slate-200 hover:border-blue-300'}`}>
        {inputPlacement === 'left' && <>{renderInput()}{renderSelectorButton()}</>}
        {inputPlacement === 'right' && <>{renderSelectorButton()}{renderInput()}</>}
        {inputPlacement === 'hidden' && renderSelectorButton()}

        <div className={`absolute top-[calc(100%+8px)] w-full sm:w-72 bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden transition-all z-[100] ${isActive ? 'opacity-100 scale-100 visible' : 'opacity-0 scale-95 invisible'}`}>
            <div className="p-3 border-b border-slate-100"><input ref={searchInputRef} type="text" className="w-full px-3 py-2 border rounded-lg bg-slate-50 text-sm outline-none focus:border-blue-500" placeholder="Tìm kiếm..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onClick={(e) => e.stopPropagation()} /></div>
            <div className="max-h-64 overflow-y-auto p-1">
              {filteredCurrencies.map((c) => (
                <div key={c.code} onClick={(e) => { e.stopPropagation(); onCurrencyChange(c); onCloseDropdown?.(); }} className={`flex items-center gap-3 px-3 py-2.5 rounded-lg cursor-pointer ${c.code === currency.code ? 'bg-blue-50 text-blue-700' : 'hover:bg-slate-50'}`}>
                  <img src={c.flag} className="w-6 h-4 object-cover rounded" /><div className="flex flex-col"><span className="text-sm font-bold">{c.code}</span><span className="text-xs opacity-70 truncate max-w-[150px]">{c.name}</span></div>
                </div>
              ))}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState } from './types';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-3 sm:p-4 font-sans text-slate-800">
      <div className="w-full max-w-5xl bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-white/50 relative flex flex-col my-2">

        <Header />

        <div className="p-4 sm:p-8 space-y-6 relative flex-1">
          <div className="flex flex-col md:flex-row items-stretch md:items-center relative z-20">
            <div className={`relative w-full md:flex-[3] transition-all ${activeDropdown === 'FROM' ? 'z-50' : 'z-20'}`}> 
                <CurrencyRow
                    label="Nhập số tiền cần đổi"
                    amount={amount}
                    currency={fromCurrency}
                    onAmountChange={setAmount}
                    onCurrencyChange={setFromCurrency}
                    inputPlacement="left"
                    autoFocus={true}
                    isActive={activeDropdown === 'FROM'}
                    onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                    onCloseDropdown={() => setActiveDropdown(null)}
                />
            </div>

            <SwapButton onClick={handleSwap} isSwapping={isSwapping} />

            <div className={`relative w-full md:flex-[2] transition-all ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                <CurrencyRow
                    label="Quy đổi sang"
                    amount=""
                    currency={toCurrency}
                    onCurrencyChange={setToCurrency}
                    inputPlacement="hidden"
                    isActive={activeDropdown === 'TO'}
                    onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                    onCloseDropdown={() => setActiveDropdown(null)}
                />
            </div>
          </div>

          <button
            onClick={handleConvert}
            disabled={loadingState === LoadingState.LOADING}
            className={`w-full py-3.5 sm:py-4 rounded-2xl text-white font-bold text-base sm:text-lg shadow-xl transition-all transform mt-4
              ${loadingState === LoadingState.LOADING 
                ? 'bg-slate-400 cursor-not-allowed opacity-80' 
                : 'bg-gradient-to-r from-blue-600 to-indigo-600 hover:-translate-y-1 active:scale-[0.98]'
              }`}
          >
             <span className="flex items-center justify-center gap-2">
                {loadingState === LoadingState.LOADING ? 'Đang xử lý...' : 'Chuyển đổi ngay'}
             </span>
          </button>

           {result && loadingState === LoadingState.SUCCESS && (
              <div className="flex justify-center -mt-2 animate-fade-in-up">
                 <div className="text-xs sm:text-sm font-medium px-4 py-1.5 rounded-full border border-slate-200 bg-white text-slate-500 shadow-sm flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                    {formatExchangeRate(result.exchangeRate, fromCurrency.code, toCurrency.code)}
                 </div>
              </div>
           )}

          {errorMsg && <div className="p-4 bg-red-50 text-red-600 rounded-xl border border-red-100 text-center text-sm font-semibold">{errorMsg}</div>}

          {result && loadingState === LoadingState.SUCCESS && (
             <ResultSection 
                result={result} 
                fromCurrency={fromCurrency} 
                toCurrency={toCurrency} 
                inputAmount={amount}
                formatCurrency={formatCurrency}
             />
          )}
        </div>
      </div>

      <div className="fixed bottom-4 text-center w-full pointer-events-none hidden sm:block text-slate-400 opacity-50 text-xs">
          Powered by VinaChange
      </div>
    </div>
  );
};

