          const isSelected = currentAmount === valStr;
          return (
            <button
              key={val}
              onClick={() => onSelect(valStr)}
              className={`
                flex-shrink-0 px-4 py-2 rounded-xl text-sm font-bold transition-all border
                ${isSelected 
                  ? 'bg-blue-600 border-blue-600 text-white shadow-md shadow-blue-200 scale-105' 
                  : 'bg-white border-slate-200 text-slate-600 hover:border-blue-300 hover:text-blue-600 hover:bg-blue-50/50'}
