import { ConversionResult } from '../types';
import { getReadFunction } from '../utils/currencyTextFormatter';

const CACHE_KEY_PREFIX = 'curr_rate_';
const CACHE_TTL = 3600 * 1000; // 1 hour

interface CacheData {
  timestamp: number;
  rates: Record<string, number>;
}

// In-memory cache for current session speed
const memoryCache: Record<string, CacheData> = {};

const getDecimals = (currencyCode: string): number => {
  if (['VND', 'JPY', 'KRW', 'TWD', 'HUF'].includes(currencyCode)) {
    return 0;
  }
  return 2;
};

const getRates = async (baseCurrency: string): Promise<Record<string, number>> => {
  const now = Date.now();

  // 1. Check Memory Cache
  if (memoryCache[baseCurrency] && (now - memoryCache[baseCurrency].timestamp < CACHE_TTL)) {
    return memoryCache[baseCurrency].rates;
  }

  // 2. Check Local Storage
  try {
    const stored = localStorage.getItem(CACHE_KEY_PREFIX + baseCurrency);
    if (stored) {
      const parsed: CacheData = JSON.parse(stored);
      if (now - parsed.timestamp < CACHE_TTL) {
        // Hydrate memory cache
        memoryCache[baseCurrency] = parsed;
        return parsed.rates;
      }
    }
  } catch (e) {
    console.warn("Local storage access failed", e);
  }

  // 3. Fetch from API
  const response = await fetch(`https://open.er-api.com/v6/latest/${baseCurrency}`);
  if (!response.ok) throw new Error('Network response was not ok');
  const data = await response.json();

  if (!data || !data.rates) throw new Error('Invalid API response');

  const cacheData: CacheData = {
    timestamp: now,
    rates: data.rates
  };

  // 4. Save to caches
  memoryCache[baseCurrency] = cacheData;
  try {
    localStorage.setItem(CACHE_KEY_PREFIX + baseCurrency, JSON.stringify(cacheData));
  } catch (e) {
    console.warn("Local storage write failed", e);
  }

  return data.rates;
};

export const convertCurrencyApi = async (
  amount: number,
  fromCurrency: string,
  toCurrency: string
): Promise<ConversionResult> => {
  try {
    let rate: number;

    // Hardcoded overrides for specific street rates if needed, otherwise use API
    if (fromCurrency === 'CNY' && toCurrency === 'VND') {
        // Specific manual override example, can be removed if dynamic is preferred
        rate = 3450; 
    } else if (fromCurrency === 'VND' && toCurrency === 'CNY') {
        rate = 1 / 3450;
    } else {
        const rates = await getRates(fromCurrency);
        rate = rates[toCurrency];
        if (!rate) throw new Error(`Exchange rate not found for ${toCurrency}`);
    }

    const rawConverted = amount * rate;
    // Use Math.round instead of ceil for better accuracy on general currencies, 
    // but keep logic consistent with user preference if previously defined.
    // Switching to round for standard financial accuracy.
    const roundedConverted = Math.round(rawConverted); 

    const sourceDecimals = getDecimals(fromCurrency);
    // Fix floating point issues for input
    const roundedInput = parseFloat(amount.toFixed(sourceDecimals));

    return {
      convertedAmount: roundedConverted,
      exchangeRate: rate,
      textSource: getReadFunction(fromCurrency, roundedInput),
      textTarget: getReadFunction(toCurrency, roundedConverted)
    };
  } catch (error) {
    console.error("Currency API error:", error);
    throw new Error("Failed to convert currency. Please try again.");
  }
};
// Add a method to warm up cache
export const prefetchRates = (currency: string) => {
    getRates(currency).catch(err => console.log('Prefetch failed silently', err));
};

/**
 * UTILS: Number to Text Converters
 * Optimized: Static arrays moved outside functions to prevent reallocation on every call.
 */

const VI_DIGITS = ["không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín"];
const VI_SUFFIXES = ["", "nghìn", "triệu", "tỷ", "nghìn tỷ", "triệu tỷ"];

const readGroupVietnamese = (group: string): string => {
  let temp = "";
  if (group === "000") return "";

  const a = parseInt(group.substring(0, 1));
  const b = parseInt(group.substring(1, 2));
  const c = parseInt(group.substring(2, 3));

  temp += VI_DIGITS[a] + " trăm";

  if (b === 0) {
    if (c === 0) return temp;
    temp += " linh " + VI_DIGITS[c];
  } else if (b === 1) {
    temp += " mười";
    if (c === 1) temp += " một";
    else if (c === 5) temp += " lăm";
    else if (c !== 0) temp += " " + VI_DIGITS[c];
  } else {
    temp += " " + VI_DIGITS[b] + " mươi";
    if (c === 1) temp += " mốt";
    else if (c === 4) temp += " tư";
    else if (c === 5) temp += " lăm";
    else if (c !== 0) temp += " " + VI_DIGITS[c];
  }
  return temp;
};

const readNumberVietnamese = (number: number, currencyName: string): string => {
  if (number === 0) return "Không " + currencyName;
  const strNum = Math.abs(number).toString();
  const parts = strNum.split('.');
  let integerPart = parts[0];
  let decimalPart = parts.length > 1 ? parts[1] : "";

  while (integerPart.length % 3 !== 0) integerPart = "0" + integerPart;

  const groups = [];
  for (let i = 0; i < integerPart.length; i += 3) groups.push(integerPart.substring(i, i + 3));

  let result = "";

  for (let i = 0; i < groups.length; i++) {
    const group = groups[i];
    const groupValue = parseInt(group);
    const suffix = VI_SUFFIXES[groups.length - 1 - i];
    let read = readGroupVietnamese(group);

    if (i === 0) {
        read = read.replace(/^không trăm linh /, "").replace(/^không trăm /, "");
        if (read.startsWith("linh ")) read = read.replace("linh ", "");
    }
    if (groupValue > 0) result += " " + read + " " + suffix;
  }

  result = result.trim().replace(/\s+/g, ' ');

  if (decimalPart && parseInt(decimalPart) > 0) {
      if (decimalPart.length === 1) decimalPart += "0";
      const val = parseInt(decimalPart.substring(0, 2));
      let decimalText = "";
      if (val < 10) decimalText = "linh " + VI_DIGITS[val];
      else {
          const chuc = Math.floor(val / 10);
          const donvi = val % 10;
          if (chuc === 1) decimalText = "mười";
          else decimalText = VI_DIGITS[chuc] + " mươi";
          if (donvi === 1 && chuc > 1) decimalText += " mốt";
          else if (donvi === 5 && chuc > 0) decimalText += " lăm";
          else if (donvi !== 0) decimalText += " " + VI_DIGITS[donvi];
      }
      result += ` phẩy ${decimalText}`;
  }

  const final = result + " " + currencyName;
  return final.charAt(0).toUpperCase() + final.slice(1);
};

const EN_ONES = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
const EN_TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
const EN_SCALES = ['', 'thousand', 'million', 'billion', 'trillion'];
const EN_CURRENCY_NAMES: Record<string, string> = {
    'USD': 'Dollars', 'EUR': 'Euros', 'GBP': 'Pounds', 
    'AUD': 'Australian Dollars', 'CAD': 'Canadian Dollars', 'SGD': 'Singapore Dollars'
};

const readNumberEnglish = (number: number, currencyCode: string): string => {
  if (number === 0) return `Zero ${currencyCode}`;

  const numStr = Math.abs(number).toString();
  const parts = numStr.split('.');
  let integerPart = parseInt(parts[0]);
  let decimalPart = parts.length > 1 ? parts[1] : null;

  let words = [];
  if (integerPart === 0) words.push("zero");
  else {
      let scaleIndex = 0;
      while (integerPart > 0) {
        const chunk = integerPart % 1000;
        if (chunk > 0) {
          const chunkStr = [];
          const hundreds = Math.floor(chunk / 100);
          const remainder = chunk % 100;
          if (hundreds > 0) { chunkStr.push(EN_ONES[hundreds]); chunkStr.push('hundred'); }
          if (remainder > 0) {
             if (remainder < 20) chunkStr.push(EN_ONES[remainder]);
             else {
               chunkStr.push(EN_TENS[Math.floor(remainder / 10)]);
               if (remainder % 10 > 0) chunkStr.push(EN_ONES[remainder % 10]);
             }
          }
          if (EN_SCALES[scaleIndex]) chunkStr.push(EN_SCALES[scaleIndex]);
          words.unshift(...chunkStr);
        }
        integerPart = Math.floor(integerPart / 1000);
        scaleIndex++;
      }
  }

  let result = words.join(' ');
  if (decimalPart) {
      if (decimalPart.length === 1) decimalPart += "0";
      const val = parseInt(decimalPart.substring(0, 2));
      if (val > 0) {
           result += ` point`;
           if (val < 20) result += " " + EN_ONES[val];
           else {
               result += " " + EN_TENS[Math.floor(val/10)];
               if (val%10 > 0) result += " " + EN_ONES[val%10];
           }
      }
  }

  const name = EN_CURRENCY_NAMES[currencyCode] || currencyCode;
  result = result + " " + name;
  return result.charAt(0).toUpperCase() + result.slice(1);
};

interface CJKChars { digits: string[], units: string[], groups: string[] }

const readCJK = (number: number, currencyName: string, chars: CJKChars, lang: 'JP' | 'CN' | 'KR'): string => {
    if (number === 0) return `${chars.digits[0]}${currencyName}`;
    let num = Math.floor(number); 
    let result = "";
    let groupIndex = 0;
    while (num > 0) {
        const part = num % 10000;
        if (part > 0) {
            let partStr = "";
            let p = part;
            const digitsInPart = [];
            for (let i = 0; i < 4; i++) { digitsInPart.push(p % 10); p = Math.floor(p / 10); }
            for(let i=0; i<4; i++) {
                const digit = digitsInPart[i];
                if (digit > 0) {
                    let prefix = chars.digits[digit];
                    if (i === 1 && digit === 1 && (lang === 'JP' || lang === 'KR')) prefix = ""; 
                    partStr = prefix + (i > 0 ? chars.units[i-1] : "") + partStr;
                }
            }
            result = partStr + (groupIndex > 0 ? chars.groups[groupIndex - 1] : "") + result;
        }
        num = Math.floor(num / 10000);
        groupIndex++;
    }
    return result + currencyName;
};

// Static Definitions for CJK
const JP_CHARS: CJKChars = { digits: ['零', '一', '二', '三', '四', '五', '六', '七', '八', '九'], units: ['十', '百', '千'], groups: ['万', '億', '兆'] };
const KR_CHARS: CJKChars = { digits: ['영', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구'], units: ['십', '백', '천'], groups: ['만', '억', '조'] };
const CN_CHARS: CJKChars = { digits: ['零', '一', '二', '三', '四', '五', '六', '七', '八', '九'], units: ['十', '百', '千'], groups: ['万', '亿', '兆'] };

export const getReadFunction = (currencyCode: string, amount: number): string => {
    switch (currencyCode) {
        case 'VND': return readNumberVietnamese(amount, 'Đồng');
        case 'JPY': return readCJK(amount, '円 (Yen)', JP_CHARS, 'JP');
        case 'KRW': return readCJK(amount, '원 (Won)', KR_CHARS, 'KR');
        case 'CNY': return readCJK(amount, '元', CN_CHARS, 'CN');
        case 'TWD': return readCJK(amount, '圓', CN_CHARS, 'CN');
        case 'USD': case 'EUR': case 'GBP': case 'AUD': case 'CAD': case 'SGD':
        default: return readNumberEnglish(amount, currencyCode);
    }
};

