import React, { useRef, useEffect, useState, useMemo, ReactNode } from 'react';
import { POPULAR_CURRENCIES as CURRENCY_LIST } from '../constants';
import { Currency, ThemeColor } from '../types';

interface CurrencyRowProps {
  label: string;
  amount: number | string;
  currency: Currency;
  onAmountChange?: (value: string) => void;
  onCurrencyChange: (currency: Currency) => void;
  readOnly?: boolean;
  isActive?: boolean;
  onToggleDropdown?: () => void;
  onCloseDropdown?: () => void;
  inputPlacement?: 'left' | 'right' | 'hidden';
  autoFocus?: boolean;
  theme: ThemeColor;
  headerAction?: ReactNode;
}

export const CurrencyRow: React.FC<CurrencyRowProps> = ({
  label, amount, currency, onAmountChange, onCurrencyChange,
  readOnly = false, isActive = false, onToggleDropdown, onCloseDropdown,
  inputPlacement = 'left', autoFocus = false, headerAction
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const amountInputRef = useRef<HTMLInputElement>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    if (autoFocus && amountInputRef.current) {
      amountInputRef.current.focus();
    }
  }, [autoFocus]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        if (isActive && onCloseDropdown) onCloseDropdown();
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [isActive, onCloseDropdown]);

  useEffect(() => {
    if (isActive) {
      const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) || window.innerWidth < 768;

      if (!isMobile) {
        setTimeout(() => searchInputRef.current?.focus(), 50);
      }
    } else {
      setSearchQuery('');
    }
  }, [isActive]);

  const displayCurrencies = useMemo(() => {
    let list = [...CURRENCY_LIST];
    const currentIndex = list.findIndex(c => c.code === currency.code);
    if (currentIndex > -1) {
      const [selected] = list.splice(currentIndex, 1);
      list.unshift(selected);
    }
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      return list.filter((c) => 
        c.code.toLowerCase().includes(query) || 
        c.name.toLowerCase().includes(query)
      );
    }
    return list;
  }, [currency.code, searchQuery]);

  const { groupSeparator, decimalSeparator } = useMemo(() => {
    try {
      const parts = new Intl.NumberFormat(currency.locale).formatToParts(1000.1);
      return {
        groupSeparator: parts.find(p => p.type === 'group')?.value || ',',
        decimalSeparator: parts.find(p => p.type === 'decimal')?.value || '.'
      };
    } catch (e) { return { groupSeparator: ',', decimalSeparator: '.' }; }
  }, [currency.locale]);

  const displayValue = useMemo(() => {
    if (amount === '' || amount === undefined || amount === null) return '';
    const parts = amount.toString().split('.');
    const integerFormatted = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, groupSeparator);
    return parts.length > 1 ? `${integerFormatted}${decimalSeparator}${parts[1]}` : integerFormatted;
  }, [amount, groupSeparator, decimalSeparator]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!onAmountChange) return;
    let value = e.target.value;
    if (value === '') { onAmountChange(''); return; }
    if (decimalSeparator === ',' && value.endsWith('.')) value = value.slice(0, -1) + ',';
    const groupSepRegex = new RegExp(groupSeparator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
    let cleanValue = value.replace(groupSepRegex, '').replace(new RegExp(decimalSeparator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'), '.').replace(/[^0-9.]/g, '');
    const parts = cleanValue.split('.');
    if (parts.length > 2) cleanValue = parts[0] + '.' + parts.slice(1).join('');
    onAmountChange(cleanValue);
  };

  const renderSelectorButton = () => (
    <button
      onClick={(e) => { e.stopPropagation(); if (onToggleDropdown) onToggleDropdown(); }}
      className={`flex items-center gap-2 px-2 py-3 sm:px-3 sm:py-4 hover:bg-slate-50 transition-colors group outline-none shrink-0
        ${inputPlacement === 'hidden' ? 'w-full justify-between rounded-2xl' : ''}
        ${inputPlacement === 'left' ? 'rounded-r-2xl border-l border-slate-100' : ''}
        ${inputPlacement === 'right' ? 'rounded-l-2xl border-r border-slate-100' : ''}
      `}
    >
      <div className="flex items-center gap-2">
        <img src={currency.flag} alt={currency.code} className="w-6 h-4 sm:w-7 sm:h-5 object-cover rounded shadow-sm border border-slate-100" />
        <span className="text-base sm:text-lg font-bold text-slate-700 leading-none">{currency.code}</span>
      </div>
      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className={`w-3 h-3 sm:w-3.5 sm:h-3.5 text-slate-400 transition-transform ${isActive ? `rotate-180 text-primary-500` : ''}`}><path strokeLinecap="round" strokeLinejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" /></svg>
    </button>
  );

  const renderInput = () => (
    <div className="flex-1 p-2 w-full h-full">
      <input
        ref={amountInputRef}
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={handleInputChange}
        onFocus={(e) => e.target.select()}
        readOnly={readOnly}
        className="w-full h-full px-2 bg-transparent border-none outline-none text-xl sm:text-2xl font-bold placeholder-slate-300 text-slate-800"
        placeholder="0"
        autoComplete="off"
      />
    </div>
  );

  return (
    <div className="flex flex-col gap-1.5 w-full" ref={containerRef}>
      {/* Fixed height (h-8 = 32px) ensures alignment regardless of button presence */}
      <div className="flex items-center justify-between ml-1 h-8">
        <label className="text-[10px] sm:text-xs font-bold text-slate-500 uppercase tracking-wide">{label}</label>
        {headerAction && <div>{headerAction}</div>}
      </div>
      <div onClick={() => !readOnly && !isActive && amountInputRef.current?.focus()}
        className={`relative flex items-center bg-white border rounded-2xl transition-all h-[60px] sm:h-[66px] cursor-text ${isActive ? `border-primary-500 ring-2 ring-primary-100 z-50` : `border-slate-200 hover:border-primary-300`}`}>
        {inputPlacement === 'left' && <>{renderInput()}{renderSelectorButton()}</>}
        {inputPlacement === 'right' && <>{renderSelectorButton()}{renderInput()}</>}
        {inputPlacement === 'hidden' && renderSelectorButton()}

        <div className={`absolute top-[calc(100%+8px)] w-full sm:w-72 bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden transition-all z-[100] 
            ${inputPlacement === 'right' ? 'left-0 origin-top-left' : 'right-0 origin-top-right'}
            ${isActive ? 'opacity-100 scale-100 visible' : 'opacity-0 scale-95 invisible'}`}>
            <div className="p-3 border-b border-slate-100"><input ref={searchInputRef} type="text" className={`w-full px-3 py-2 border rounded-lg bg-slate-50 text-sm outline-none focus:border-primary-500`} placeholder="Tìm kiếm..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onClick={(e) => e.stopPropagation()} /></div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {displayCurrencies.map((c) => (
                <div key={c.code} onClick={(e) => { e.stopPropagation(); onCurrencyChange(c); onCloseDropdown?.(); }} className={`flex items-center gap-3 px-3 py-2.5 rounded-lg cursor-pointer ${c.code === currency.code ? `bg-primary-50 text-primary-700` : 'hover:bg-slate-50'}`}>
                  <img src={c.flag} className="w-6 h-4 object-cover rounded" /><div className="flex flex-col"><span className="text-sm font-bold">{c.code}</span><span className="text-xs opacity-70 truncate max-w-[150px]">{c.name}</span></div>
                  {c.code === currency.code && <div className="ml-auto"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="m4.5 12.75 6 6 9-13.5" /></svg></div>}
                </div>
              ))}
              {displayCurrencies.length === 0 && <div className="p-4 text-center text-sm text-slate-400 italic">Không tìm thấy kết quả</div>}
            </div>
        </div>
      </div>
    </div>
  );
};

import { useState, useCallback, useEffect } from 'react';
import { Currency, ConversionResult, LoadingState, ConversionHistoryItem } from '../types';
import { DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from '../constants';
import { convertCurrencyApi } from '../services/geminiService';

export const useCurrencyConverter = () => {
  const [amount, setAmount] = useState<string>(''); // Default to empty string to require user input
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');
  const [isSwapping, setIsSwapping] = useState(false);
  const [history, setHistory] = useState<ConversionHistoryItem[]>([]);

  // Load history from local storage on mount
  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('conversion_history');
      if (savedHistory) {
        setHistory(JSON.parse(savedHistory));
      }
    } catch (e) {
      console.error("Failed to load history", e);
    }
  }, []);

  const saveHistory = (newHistory: ConversionHistoryItem[]) => {
    setHistory(newHistory);
    localStorage.setItem('conversion_history', JSON.stringify(newHistory));
  };

  const addToHistory = (currentAmount: number, source: Currency, target: Currency, converted: number) => {
    const newItem: ConversionHistoryItem = {
      id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      inputAmount: currentAmount,
      fromCurrency: source,
      toCurrency: target,
      convertedAmount: converted
    };

    // Avoid duplicates: if the latest item is identical, don't add
    if (history.length > 0) {
        const latest = history[0];
        if (latest.inputAmount === newItem.inputAmount && 
            latest.fromCurrency.code === newItem.fromCurrency.code && 
            latest.toCurrency.code === newItem.toCurrency.code) {
            return;
        }
    }

    const updatedHistory = [newItem, ...history].slice(0, 20); // Limit to 20 items
    saveHistory(updatedHistory);
  };

  const clearHistory = () => {
    saveHistory([]);
  };

  const selectHistoryItem = (item: ConversionHistoryItem) => {
    setAmount(item.inputAmount.toString());
    setFromCurrency(item.fromCurrency);
    setToCurrency(item.toCurrency);
    // Automatically trigger conversion when history item is selected
    executeConversion(item.inputAmount, item.fromCurrency, item.toCurrency);
  };

  const executeConversion = async (currentAmount: number, source: Currency, target: Currency) => {
    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');

    try {
      const data = await convertCurrencyApi(currentAmount, source.code, target.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);

      // Add to history on success
      addToHistory(currentAmount, source, target, data.convertedAmount);
    } catch (err) {
      setErrorMsg("Có lỗi xảy ra khi lấy tỷ giá. Vui lòng thử lại.");
      setLoadingState(LoadingState.ERROR);
      setResult(null); 
    }
  };

  // Allow passing an override amount for immediate actions (like chips)
  const handleConvert = useCallback((amountOverride?: string) => {
    const valueToCheck = amountOverride !== undefined ? amountOverride : amount;
    const numAmount = parseFloat(valueToCheck);

    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }
    executeConversion(numAmount, fromCurrency, toCurrency);
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = () => {
    setIsSwapping(true);
    setTimeout(() => setIsSwapping(false), 500); 

    const newFrom = toCurrency;
    const newTo = fromCurrency;

    setFromCurrency(newFrom);
    setToCurrency(newTo);

    const numAmount = parseFloat(amount);

    // Only convert if there is a valid amount
    if (!isNaN(numAmount) && numAmount > 0) {
        executeConversion(numAmount, newFrom, newTo);
    } else {
        // If no amount, just swap currencies and clear previous result
        setResult(null);
        setErrorMsg('');
    }
  };

  return {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, selectHistoryItem
  };
};

import React, { useState, useEffect } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { DenominationSelector } from './components/DenominationSelector';
import { HistorySection } from './components/HistorySection';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState, ThemeColor } from './types';
import { Tooltip } from './components/Tooltip';
import { THEME_COLORS } from './constants';
import { generatePalette } from './utils/themeUtils';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, selectHistoryItem
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [theme, setTheme] = useState<ThemeColor>('blue');
  const [showHistory, setShowHistory] = useState(false);

  // Apply theme palette to CSS variables
  useEffect(() => {
    const applyTheme = (colorIdOrHex: string) => {
      let hex = colorIdOrHex;
      // If it's a preset ID (e.g. 'blue'), find the hex
      const preset = THEME_COLORS.find(t => t.id === colorIdOrHex);
      if (preset) {
        hex = preset.hex;
      }

      // Generate shades
      const palette = generatePalette(hex);
      const root = document.documentElement;

      Object.entries(palette).forEach(([shade, value]) => {
        root.style.setProperty(`--color-primary-${shade}`, value);
      });
    };

    const savedTheme = localStorage.getItem('app_theme');
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      applyTheme('blue');
    }
  }, []);

  const handleThemeChange = (newTheme: ThemeColor) => {
    setTheme(newTheme);
    localStorage.setItem('app_theme', newTheme);

    // Apply immediately
    let hex = newTheme;
    const preset = THEME_COLORS.find(t => t.id === newTheme);
    if (preset) hex = preset.hex;

    const palette = generatePalette(hex);
    Object.entries(palette).forEach(([shade, value]) => {
      document.documentElement.style.setProperty(`--color-primary-${shade}`, value);
    });
  };

  // Auto-convert when amount changes from denomination buttons
  const handleDenominationSelect = (newAmount: string) => {
    setAmount(newAmount);
    // Explicitly trigger conversion with the new amount
    handleConvert(newAmount);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  const handleHistorySelect = (item: any) => {
    selectHistoryItem(item);
    setShowHistory(false);
  };

  // Render the history icon button to be placed in the CurrencyRow
  const renderHistoryButton = (
    <Tooltip content="Xem lịch sử chuyển đổi" position="bottom">
      <button 
          onClick={() => setShowHistory(true)}
          className={`flex items-center gap-1.5 text-xs font-bold text-primary-600 hover:text-primary-700 bg-primary-50 hover:bg-primary-100 px-2 py-1 rounded-md transition-all`}
      >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
          </svg>
          Lịch sử
      </button>
    </Tooltip>
  );

  return (
    <div className={`min-h-screen bg-slate-100 flex items-center justify-center p-3 sm:p-4 font-sans text-slate-800 selection:bg-primary-200`}>

      <div className="w-full max-w-5xl bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-white/50 relative flex flex-col my-2">

        <Header theme={theme} onThemeChange={handleThemeChange} onShowHistory={() => {}} />

        <div className="p-4 sm:p-8 space-y-6 relative flex-1">

          <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
            <DenominationSelector 
              currency={fromCurrency} 
              onSelect={handleDenominationSelect} 
              currentAmount={amount}
              theme={theme}
            />
          </div>

          {/* 
             PC Layout Logic: 
             - items-start: Align top to handle variable height.
             - gap-4: Keep spacing clean.
             - md:flex-row: Horizontal on PC.
          */}
          <div className="flex flex-col md:flex-row items-center md:items-start relative z-20 gap-3 md:gap-4">
            <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'FROM' ? 'z-50' : 'z-20'}`}> 
                <CurrencyRow
                    label="Nhập số tiền cần đổi"
                    amount={amount}
                    currency={fromCurrency}
                    onAmountChange={setAmount}
                    onCurrencyChange={setFromCurrency}
                    inputPlacement="left"
                    autoFocus={true}
                    isActive={activeDropdown === 'FROM'}
                    onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                    onCloseDropdown={() => setActiveDropdown(null)}
                    theme={theme}
                    headerAction={renderHistoryButton}
                />
            </div>

            {/* 
              Swap Button Alignment:
              - md:mt-12: Pushes the button down ~48px on PC. 
              Calculation: Header (32px) + Gap (6px) + InputHalf (33px) = 71px center.
              ButtonHalf = 24px. Margin = 47px. mt-12 is 48px.
            */}
            <div className="md:mt-12 z-30 shrink-0">
               <SwapButton onClick={handleSwap} isSwapping={isSwapping} theme={theme} />
            </div>

            <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                <CurrencyRow
                    label="Quy đổi sang"
                    amount=""
                    currency={toCurrency}
                    onCurrencyChange={setToCurrency}
                    inputPlacement="hidden"
                    isActive={activeDropdown === 'TO'}
                    onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                    onCloseDropdown={() => setActiveDropdown(null)}
                    theme={theme}
                />
