import React, { useState, useRef, useEffect } from 'react';
import { ThemeColor } from '../types';
import { THEME_COLORS } from '../constants';
import { Tooltip } from './Tooltip';

interface ThemeSelectorProps {
  currentTheme: ThemeColor;
  onThemeChange: (theme: ThemeColor) => void;
}

export const ThemeSelector: React.FC<ThemeSelectorProps> = ({ currentTheme, onThemeChange }) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleCustomColor = (e: React.ChangeEvent<HTMLInputElement>) => {
    onThemeChange(e.target.value);
  };

  const isPreset = THEME_COLORS.some(t => t.id === currentTheme);

  return (
    <div className="relative" ref={containerRef}>
      <Tooltip content="Đổi màu chủ đề" position="left">
        <button
          onClick={() => setIsOpen(!isOpen)}
          className="w-12 h-12 rounded-full bg-white text-slate-600 shadow-lg hover:shadow-xl hover:scale-105 transition-all flex items-center justify-center border border-slate-100 group"
        >
          <div className="w-6 h-6 rounded-full border border-slate-200" style={{ backgroundColor: isPreset ? 'transparent' : currentTheme, color: currentTheme }}>
             {isPreset ? (
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-full h-full p-0.5">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M9.53 16.122a3 3 0 0 0-5.78 1.128 2.25 2.25 0 0 1-2.4 2.245 4.5 4.5 0 0 0 8.4-2.245c0-.399-.078-.78-.22-1.128Zm0 0a15.998 15.998 0 0 0 3.38-3.81m-9 3.81c5.26 0 9.43-6.38 9.43-11.233 0-1.847-1.428-2.618-2.585-1.928-1.157.69-2.015 2.15-2.015 3.35 0 .237-.038.468-.11.685a16.036 16.036 0 0 1-3.722 3.882c-1.257 1.056-2.023 2.189-2.023 3.35 0 1.203.774 2.25 1.95 2.915Z" />
               </svg>
             ) : (
                <div className="w-full h-full rounded-full ring-2 ring-white" style={{ backgroundColor: currentTheme }} />
             )}
          </div>
        </button>
      </Tooltip>

      {isOpen && (
        <div className="absolute right-0 top-[calc(100%+12px)] bg-white rounded-2xl shadow-2xl border border-slate-100 p-4 min-w-[240px] z-[100] animate-fade-in-up origin-top-right">
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 px-1">Màu có sẵn</p>
          <div className="grid grid-cols-4 gap-3 mb-4">
            {THEME_COLORS.map((theme) => (
              <button
                key={theme.id}
                onClick={() => {
                  onThemeChange(theme.id);
                  setIsOpen(false);
                }}
                className={`w-10 h-10 rounded-full flex items-center justify-center transition-transform hover:scale-110 ring-2 ring-offset-2 ${
                  currentTheme === theme.id ? 'ring-slate-400 scale-110' : 'ring-transparent'
                }`}
                style={{ backgroundColor: theme.hex }}
                title={theme.name}
              >
                {currentTheme === theme.id && (
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-5 h-5 text-white">
                    <path strokeLinecap="round" strokeLinejoin="round" d="m4.5 12.75 6 6 9-13.5" />
                  </svg>
                )}
              </button>
            ))}
          </div>

          <div className="pt-3 border-t border-slate-100">
             <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 px-1">Tự chọn màu</p>
             <div className="relative w-full h-12 rounded-xl overflow-hidden border border-slate-200 cursor-pointer hover:border-primary-400 transition-colors shadow-sm group bg-slate-50">
                {/* Visual Background */}
                <div className="absolute inset-0 flex items-center px-3 gap-3 group-hover:bg-white transition-colors">
                   <div className="w-8 h-8 rounded-full border border-slate-200 shadow-sm" style={{ backgroundColor: isPreset ? '#2563eb' : currentTheme }}></div>
                   <span className="text-xs font-bold text-slate-600 group-hover:text-primary-600">Nhấn để chọn màu...</span>
                </div>
                {/* The actual input */}
                <input 
                    type="color" 
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    value={isPreset ? '#2563eb' : currentTheme}
                    onChange={handleCustomColor}
                />
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { DenominationSelector } from './components/DenominationSelector';
import { HistorySection } from './components/HistorySection';
import { ThemeSelector } from './components/ThemeSelector';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState, ThemeColor, Currency } from './types';
import { Tooltip } from './components/Tooltip';
import { THEME_COLORS } from './constants';
import { generatePalette } from './utils/themeUtils';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, selectHistoryItem, resetResult
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [theme, setTheme] = useState<ThemeColor>('blue');
  const [showHistory, setShowHistory] = useState(false);

  // Apply theme palette to CSS variables
  useEffect(() => {
    const applyTheme = (colorIdOrHex: string) => {
      let hex = colorIdOrHex;
      // If it's a preset ID (e.g. 'blue'), find the hex
      const preset = THEME_COLORS.find(t => t.id === colorIdOrHex);
      if (preset) {
        hex = preset.hex;
      }

      // Generate shades
      const palette = generatePalette(hex);
      const root = document.documentElement;

      Object.entries(palette).forEach(([shade, value]) => {
        root.style.setProperty(`--color-primary-${shade}`, value);
      });
    };

    const savedTheme = localStorage.getItem('app_theme');
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      applyTheme('blue');
    }
  }, []);

  const handleThemeChange = (newTheme: ThemeColor) => {
    setTheme(newTheme);
    localStorage.setItem('app_theme', newTheme);

    // Apply immediately
    let hex = newTheme;
    const preset = THEME_COLORS.find(t => t.id === newTheme);
    if (preset) hex = preset.hex;

    const palette = generatePalette(hex);
    Object.entries(palette).forEach(([shade, value]) => {
      document.documentElement.style.setProperty(`--color-primary-${shade}`, value);
    });
  };

  // Wrapper to reset result when amount changes manually
  const handleAmountChange = (val: string) => {
    setAmount(val);
    resetResult(); // Hide result on input change
  };

  // Wrapper to reset result when currency changes
  const handleFromChange = (currency: Currency) => {
    setFromCurrency(currency);
    resetResult();
  };

  const handleToChange = (currency: Currency) => {
    setToCurrency(currency);
    resetResult();
  };

  // Just set amount, do NOT convert immediately
  const handleDenominationSelect = (newAmount: string) => {
    handleAmountChange(newAmount);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        if (isNaN(val)) return `0 ${currencyCode}`;
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  const handleHistorySelect = (item: any) => {
    selectHistoryItem(item);
    setShowHistory(false);
  };

  // Render the history icon button to be placed in the CurrencyRow
  const renderHistoryButton = (
    <Tooltip content="Xem lịch sử chuyển đổi" position="bottom">
      <button 
          onClick={() => setShowHistory(true)}
          className={`flex items-center gap-1.5 text-xs font-bold text-primary-600 hover:text-primary-700 bg-primary-50 hover:bg-primary-100 px-2 py-1 rounded-md transition-all`}
      >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
          </svg>
          Lịch sử
      </button>
    </Tooltip>
  );

  return (
    <div className={`min-h-screen bg-slate-100 font-sans text-slate-800 selection:bg-primary-200 flex flex-col relative overflow-hidden`}>

      {/* Floating Theme Selector - Fixed Top Right */}
      <div className="fixed top-4 right-4 z-[100] animate-fade-in-up">
        <ThemeSelector currentTheme={theme} onThemeChange={handleThemeChange} />
      </div>

      <div className="flex-1 flex items-center justify-center p-3 sm:p-4 relative z-10 mb-20 sm:mb-24">
        <div className="w-full max-w-5xl bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-white/50 relative flex flex-col my-2">

          <Header theme={theme} onShowHistory={() => {}} />

          <div className="p-4 sm:p-8 space-y-6 relative flex-1">

            <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
              <DenominationSelector 
                currency={fromCurrency} 
                onSelect={handleDenominationSelect} 
                currentAmount={amount}
                theme={theme}
              />
            </div>

            <div className="flex flex-col md:flex-row items-center md:items-start relative z-20 gap-3 md:gap-4">
              <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'FROM' ? 'z-50' : 'z-20'}`}> 
                  <CurrencyRow
                      label="Nhập số tiền cần đổi"
                      amount={amount}
                      currency={fromCurrency}
                      onAmountChange={handleAmountChange}
                      onCurrencyChange={handleFromChange}
                      inputPlacement="left"
                      autoFocus={true}
                      isActive={activeDropdown === 'FROM'}
                      onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                      onCloseDropdown={() => setActiveDropdown(null)}
                      theme={theme}
                      headerAction={renderHistoryButton}
                  />
              </div>

              <div className="md:mt-12 z-30 shrink-0">
                 <SwapButton onClick={handleSwap} isSwapping={isSwapping} theme={theme} />
              </div>

              <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                  <CurrencyRow
                      label="Quy đổi sang"
                      amount=""
                      currency={toCurrency}
                      onCurrencyChange={handleToChange}
                      inputPlacement="hidden"
                      isActive={activeDropdown === 'TO'}
                      onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                      onCloseDropdown={() => setActiveDropdown(null)}
                      theme={theme}
                  />
              </div>
            </div>

            <Tooltip content="Cập nhật tỷ giá mới nhất và tính toán" position="bottom">
                <button
                  onClick={() => handleConvert()}
                  disabled={loadingState === LoadingState.LOADING}
                  className={`w-full py-3.5 sm:py-4 rounded-2xl text-white font-bold text-base sm:text-lg shadow-xl transition-all transform mt-4
                    ${loadingState === LoadingState.LOADING 
                      ? 'bg-slate-400 cursor-not-allowed opacity-80' 
                      : `bg-gradient-to-r from-primary-600 to-primary-800 hover:-translate-y-1 active:scale-[0.98]`
                    }`}
                >
                  <span className="flex items-center justify-center gap-2">
                      {loadingState === LoadingState.LOADING ? (
                        <>
                          <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                          </svg>
                          Đang xử lý...
                        </>
                      ) : 'Chuyển đổi ngay'}
                  </span>
                </button>
            </Tooltip>

             {result && loadingState === LoadingState.SUCCESS && (
                <div className="flex justify-center -mt-2 animate-fade-in-up">
                   <div className="text-xs sm:text-sm font-medium px-4 py-1.5 rounded-full border border-slate-200 bg-white text-slate-500 shadow-sm flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                      {formatExchangeRate(result.exchangeRate, fromCurrency.code, toCurrency.code)}
                   </div>
                </div>
             )}

            {errorMsg && <div className="p-4 bg-red-50 text-red-600 rounded-xl border border-red-100 text-center text-sm font-semibold">{errorMsg}</div>}

            {result && loadingState === LoadingState.SUCCESS && (
               <ResultSection 
                  result={result} 
                  fromCurrency={fromCurrency} 
                  toCurrency={toCurrency} 
                  inputAmount={amount}
                  formatCurrency={formatCurrency}
                  theme={theme}
               />
            )}
          </div>
        </div>
      </div>

      {/* Animated Footer */}
      <footer className="absolute bottom-0 left-0 w-full z-0 overflow-hidden pointer-events-none">
        <svg
          className="relative block w-[calc(100%+1.3px)] h-[100px] sm:h-[150px] text-primary-200/40"
          data-name="Layer 1"
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 1200 120"
          preserveAspectRatio="none"
        >
          <path
            d="M321.39,56.44c58-10.79,114.16-30.13,172-41.86,82.39-16.72,168.19-17.73,250.45-.39C823.78,31,906.67,72,985.66,92.83c70.05,18.48,146.53,26.09,214.34,3V0H0V27.35A600.21,600.21,0,0,0,321.39,56.44Z"
            fill="currentColor"
            className="animate-wave-slow"
          ></path>
          <path
             d="M985.66,92.83c-81.47-23.45-156.8-58.12-234.33-66.21-82.5-8.62-166.44,11.23-247.69,38.29-62.44,20.8-121.28,34-181.71,32.33-54.67-1.48-107.59-13.88-158.46-32.89L0,27.35V120H1200V95.8C1130.29,118.28,1055.71,111.31,985.66,92.83Z"
             fill="currentColor"
             className="opacity-50 animate-wave-fast"
          ></path>
        </svg>
        <div className="bg-primary-200/40 h-10 w-full flex items-center justify-center -mt-1 pb-4">
             <div className="flex flex-col items-center gap-1 opacity-70">
                <div className="flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-primary-600"></div>
                  <span className="text-xs font-bold text-primary-900 tracking-wider uppercase">Powered by VinaChange</span>
                  <div className="w-1.5 h-1.5 rounded-full bg-primary-600"></div>
                </div>
                <div className="text-[10px] text-primary-800 font-medium">
                  © {new Date().getFullYear()} All Rights Reserved
                </div>
             </div>
        </div>
      </footer>

      {showHistory && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
             <div className="absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity animate-fade-in-up" onClick={() => setShowHistory(false)} style={{animationDuration: '0.2s'}} />
             <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md relative z-10 overflow-hidden animate-fade-in-up flex flex-col max-h-[80vh]">
                <div className="p-4 flex-1 overflow-hidden flex flex-col">
                   <HistorySection 
                        history={history} 
                        onSelect={handleHistorySelect} 
                        onClear={clearHistory}
                        formatCurrency={formatCurrency}
                        onClose={() => setShowHistory(false)}
                   />
                </div>
             </div>
        </div>
      )}

      {/* Animation Styles */}
      <style>{`
         @keyframes wave {
            0% { transform: translateX(0) translateZ(0) scaleY(1); }
            50% { transform: translateX(-25%) translateZ(0) scaleY(0.85); }
            100% { transform: translateX(-50%) translateZ(0) scaleY(1); }
         }
         .animate-wave-slow {
            animation: wave 15s cubic-bezier(0.36, 0.45, 0.63, 0.53) infinite alternate;
            transform-origin: center bottom;
         }
         .animate-wave-fast {
            animation: wave 10s cubic-bezier(0.36, 0.45, 0.63, 0.53) infinite alternate-reverse;
            transform-origin: center bottom;
         }
      `}</style>
    </div>
  );
};

export default App;

