const CopyButton: React.FC<{ text: string; colorClass?: string }> = ({ text, colorClass = "text-slate-400 hover:text-slate-600 hover:bg-slate-100" }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent triggering parent clicks
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <button
      onClick={handleCopy}
      className={`p-1.5 rounded-lg transition-all active:scale-95 ${copied ? 'bg-green-100 text-green-600' : colorClass}`}
      title="Sao chép"
