import { useState, useCallback, useEffect } from 'react';
import { Currency, ConversionResult, LoadingState, ConversionHistoryItem } from '../types';
import { DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from '../constants';
import { convertCurrencyApi } from '../services/geminiService';

export const useCurrencyConverter = () => {
  const [amount, setAmount] = useState<string>('100000');
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');
  const [isSwapping, setIsSwapping] = useState(false);
  const [history, setHistory] = useState<ConversionHistoryItem[]>([]);

  // Load history from local storage on mount
  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('conversion_history');
      if (savedHistory) {
        setHistory(JSON.parse(savedHistory));
      }
    } catch (e) {
      console.error("Failed to load history", e);
    }
  }, []);

  const saveHistory = (newHistory: ConversionHistoryItem[]) => {
    setHistory(newHistory);
    localStorage.setItem('conversion_history', JSON.stringify(newHistory));
  };

  const addToHistory = (currentAmount: number, source: Currency, target: Currency, converted: number) => {
    const newItem: ConversionHistoryItem = {
      id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      inputAmount: currentAmount,
      fromCurrency: source,
      toCurrency: target,
      convertedAmount: converted
    };

    // Check if an identical conversion exists (Same Input Amount, Source Code, and Target Code)
    const existingIndex = history.findIndex(item => 
        item.inputAmount === newItem.inputAmount && 
        item.fromCurrency.code === newItem.fromCurrency.code && 
        item.toCurrency.code === newItem.toCurrency.code
    );

    let updatedHistory = [...history];

    if (existingIndex > -1) {
        // Remove the existing item so the new one can go to the top
        updatedHistory.splice(existingIndex, 1);
    }

    // Add new item to the beginning
    updatedHistory.unshift(newItem);

    // Limit to 20 items
    updatedHistory = updatedHistory.slice(0, 20); 

    saveHistory(updatedHistory);
  };

  const clearHistory = () => {
    saveHistory([]);
  };

  const deleteHistoryItems = (ids: string[]) => {
    const updatedHistory = history.filter(item => !ids.includes(item.id));
    saveHistory(updatedHistory);
  };

  const selectHistoryItem = (item: ConversionHistoryItem) => {
    setAmount(item.inputAmount.toString());
    setFromCurrency(item.fromCurrency);
    setToCurrency(item.toCurrency);
    executeConversion(item.inputAmount, item.fromCurrency, item.toCurrency);
  };

  const resetResult = useCallback(() => {
    setResult(null);
    setErrorMsg('');
    setLoadingState(LoadingState.IDLE);
  }, []);

  const executeConversion = async (currentAmount: number, source: Currency, target: Currency) => {
    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');

    try {
      const data = await convertCurrencyApi(currentAmount, source.code, target.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);

      // Add to history on success
      addToHistory(currentAmount, source, target, data.convertedAmount);
    } catch (err) {
      setErrorMsg("Có lỗi xảy ra khi lấy tỷ giá. Vui lòng thử lại.");
      setLoadingState(LoadingState.ERROR);
      setResult(null); 
    }
  };

  const handleConvert = useCallback((amountOverride?: string) => {
    const valueToCheck = amountOverride !== undefined ? amountOverride : amount;
    const numAmount = parseFloat(valueToCheck);

    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }
    executeConversion(numAmount, fromCurrency, toCurrency);
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = () => {
    setIsSwapping(true);
    setTimeout(() => setIsSwapping(false), 500); 

    const newFrom = toCurrency;
    const newTo = fromCurrency;

    setFromCurrency(newFrom);
    setToCurrency(newTo);

    // If we have a result visible, we want to recalculate immediately to show the swapped result
    // But if there is no result (user was typing), we just swap positions without calculating.
    if (result) {
        const numAmount = parseFloat(amount);
        if (!isNaN(numAmount) && numAmount > 0) {
            executeConversion(numAmount, newFrom, newTo);
        } else {
            setResult(null);
        }
    } else {
        // Just swap, do not convert yet as per requirement "only convert when button is pressed"
        // unless a result was already there.
        setResult(null); 
    }
  };

  return {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult
  };
};

import React, { useState } from 'react';
import { ConversionHistoryItem } from '../types';

interface HistorySectionProps {
  history: ConversionHistoryItem[];
  onSelect: (item: ConversionHistoryItem) => void;
  onClear: () => void;
  onDeleteItems: (ids: string[]) => void;
  formatCurrency: (val: number, locale: string, currencyCode: string) => string;
  onClose?: () => void;
}

export const HistorySection: React.FC<HistorySectionProps> = ({ history, onSelect, onClear, onDeleteItems, formatCurrency, onClose }) => {
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [confirmDelete, setConfirmDelete] = useState<{ isOpen: boolean, idsToDelete: string[], isAll: boolean }>({ 
    isOpen: false, idsToDelete: [], isAll: false 
  });

  const toggleSelectionMode = () => {
    setIsSelectionMode(!isSelectionMode);
    setSelectedIds(new Set());
  };

  const handleCheckboxChange = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const handleDeleteSelected = () => {
    if (selectedIds.size === 0) return;
    setConfirmDelete({
        isOpen: true,
        idsToDelete: Array.from(selectedIds),
        isAll: false
    });
  };

  const handleDeleteSingle = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setConfirmDelete({
        isOpen: true,
        idsToDelete: [id],
        isAll: false
    });
  };

  const handleClearAll = () => {
    setConfirmDelete({
        isOpen: true,
        idsToDelete: [],
        isAll: true
    });
  };

  const performDelete = () => {
    if (confirmDelete.isAll) {
        onClear();
        setIsSelectionMode(false);
    } else {
        onDeleteItems(confirmDelete.idsToDelete);
        // Remove deleted IDs from selection
        const newSelected = new Set(selectedIds);
        confirmDelete.idsToDelete.forEach(id => newSelected.delete(id));
        setSelectedIds(newSelected);

        if (isSelectionMode && newSelected.size === 0 && history.length === confirmDelete.idsToDelete.length) {
             setIsSelectionMode(false);
        }
    }
    setConfirmDelete({ isOpen: false, idsToDelete: [], isAll: false });
  };

  return (
    <div className="w-full flex flex-col h-full relative">
      {/* Header */}
      <div className="flex items-center justify-between mb-4 px-1 pb-2 border-b border-slate-100 min-h-[40px]">
        {isSelectionMode ? (
            <div className="flex items-center gap-2">
                <button onClick={toggleSelectionMode} className="text-slate-500 font-bold hover:text-slate-700">Hủy</button>
                <span className="text-sm text-slate-400">Đã chọn {selectedIds.size}</span>
            </div>
        ) : (
             <h3 className="text-lg font-bold text-slate-700 flex items-center gap-2">
                Lịch sử
            </h3>
        )}

        <div className="flex items-center gap-2">
            {!isSelectionMode && history.length > 0 && (
                <button 
                    onClick={toggleSelectionMode}
                    className="text-xs font-bold text-primary-600 bg-primary-50 hover:bg-primary-100 px-3 py-1.5 rounded-lg transition-colors"
                >
                    Chọn
                </button>
            )}
            {!isSelectionMode && history.length > 0 && (
                <button 
                onClick={handleClearAll} 
                className="text-xs text-red-500 hover:text-red-600 font-bold hover:bg-red-50 px-3 py-1.5 rounded-lg transition-colors"
                title="Xóa tất cả"
                >
                    Xóa hết
                </button>
            )}

            <button onClick={onClose} className="p-1 rounded-full hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors ml-1">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18 18 6M6 6l12 12" />
                </svg>
            </button>
        </div>
      </div>

      {/* List */}
      {history.length === 0 ? (
          <div className="flex-1 flex flex-col items-center justify-center py-10 text-slate-400 gap-3">
              <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-8 h-8 text-slate-300">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
                </svg>
              </div>
              <span className="text-sm italic">Chưa có lịch sử chuyển đổi nào.</span>
          </div>
      ) : (
        <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 space-y-2 max-h-[50vh] pb-16">
            {history.map(item => (
                <div key={item.id} 
                     onClick={() => {
                        if (isSelectionMode) {
                            handleCheckboxChange(item.id);
                        } else {
                            onSelect(item); 
                            if(onClose) onClose();
                        }
                     }} 
                     className={`
                        bg-white p-3 sm:p-4 rounded-xl border shadow-sm transition-all flex items-center justify-between group relative cursor-pointer
                        ${isSelectionMode && selectedIds.has(item.id) ? 'border-primary-500 bg-primary-50 ring-1 ring-primary-500' : 'border-slate-100 hover:border-primary-300 hover:bg-primary-50 hover:shadow-md'}
                     `}
                >
                    {isSelectionMode && (
                        <div className="mr-3 flex items-center justify-center">
                            <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${selectedIds.has(item.id) ? 'bg-primary-600 border-primary-600' : 'border-slate-300 bg-white'}`}>
                                {selectedIds.has(item.id) && (
                                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3.5 h-3.5 text-white">
                                        <path fillRule="evenodd" d="M16.704 4.153a.75.75 0 0 1 .143 1.052l-8 10.5a.75.75 0 0 1-1.127.075l-4.5-4.5a.75.75 0 0 1 1.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 0 1 1.05-.143Z" clipRule="evenodd" />
                                    </svg>
                                )}
                            </div>
                        </div>
                    )}

                    <div className="flex flex-col w-full gap-1 min-w-0">
                        <div className="flex items-center gap-2 text-sm sm:text-base font-bold text-slate-700 flex-wrap">
                            <div className="flex items-center gap-1.5 min-w-0">
                                <img src={item.fromCurrency.flag} alt="" className="w-5 h-3.5 rounded shadow-sm object-cover" />
                                <span className="truncate">{formatCurrency(item.inputAmount, item.fromCurrency.locale, item.fromCurrency.code)}</span>
                            </div>
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-4 h-4 text-slate-300 shrink-0">
                                <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3" />
                            </svg>
                            <div className="flex items-center gap-1.5 min-w-0">
                                <img src={item.toCurrency.flag} alt="" className="w-5 h-3.5 rounded shadow-sm object-cover" />
                                <span className="text-primary-600 truncate">{formatCurrency(item.convertedAmount, item.toCurrency.locale, item.toCurrency.code)}</span>
                            </div>
                        </div>
                        <div className="text-xs text-slate-400">
                            {new Date(item.timestamp).toLocaleString('vi-VN', { hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit', year: 'numeric' })}
                        </div>
                    </div>

                    {!isSelectionMode && (
                        <button
                            onClick={(e) => handleDeleteSingle(item.id, e)}
                            className="p-2 ml-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-full transition-all shrink-0"
                            title="Xóa"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                                <path strokeLinecap="round" strokeLinejoin="round" d="m14.74 9-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 0 1-2.244 2.077H8.084a2.25 2.25 0 0 1-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 0 0-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 0 1 3.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 0 0-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 0 0-7.5 0" />
                            </svg>
                        </button>
                    )}
                </div>
            ))}
        </div>
      )}

      {/* Floating Action Button for Selection Mode */}
      {isSelectionMode && (
          <div className="absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-white via-white to-transparent pt-6">
              <button
                onClick={handleDeleteSelected}
                disabled={selectedIds.size === 0}
                className={`w-full py-3 rounded-xl font-bold text-white shadow-lg transition-all ${
                    selectedIds.size > 0 
                    ? 'bg-red-500 hover:bg-red-600 active:scale-[0.98]' 
                    : 'bg-slate-300 cursor-not-allowed'
                }`}
              >
                  Xóa {selectedIds.size} mục đã chọn
              </button>
          </div>
      )}

      {/* Confirmation Modal */}
      {confirmDelete.isOpen && (
          <div className="absolute inset-0 z-[60] flex items-center justify-center p-4">
              <div className="absolute inset-0 bg-white/80 backdrop-blur-[2px]" onClick={() => setConfirmDelete({ ...confirmDelete, isOpen: false })}></div>
              <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 p-6 w-full max-w-sm relative z-10 animate-pulse-soft" style={{animationDuration: '0.3s', animationIterationCount: 1}}>
                  <div className="text-center mb-4">
                      <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-3 text-red-500">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z" />
                        </svg>
                      </div>
                      <h4 className="text-lg font-bold text-slate-800">Xác nhận xóa?</h4>
                      <p className="text-sm text-slate-500 mt-1">
                          {confirmDelete.isAll 
                            ? "Bạn có chắc chắn muốn xóa toàn bộ lịch sử?" 
                            : `Bạn có chắc chắn muốn xóa ${confirmDelete.idsToDelete.length} mục đã chọn?`}
                          <br/>Hành động này không thể hoàn tác.
                      </p>
                  </div>
                  <div className="flex gap-3">
                      <button 
                        onClick={() => setConfirmDelete({ ...confirmDelete, isOpen: false })}
                        className="flex-1 py-2 rounded-xl font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors"
                      >
                          Hủy bỏ
                      </button>
                      <button 
                        onClick={performDelete}
                        className="flex-1 py-2 rounded-xl font-bold text-white bg-red-500 hover:bg-red-600 transition-colors shadow-md shadow-red-200"
                      >
                          Đồng ý xóa
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { DenominationSelector } from './components/DenominationSelector';
import { HistorySection } from './components/HistorySection';
import { ThemeSelector } from './components/ThemeSelector';
import { TabSelector } from './components/TabSelector';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState, ThemeColor, Currency } from './types';
import { Tooltip } from './components/Tooltip';
import { THEME_COLORS } from './constants';
import { generatePalette } from './utils/themeUtils';
import { getReadFunction } from './utils/currencyTextFormatter';
import { CopyButton } from './components/CopyButton';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [theme, setTheme] = useState<ThemeColor>('blue');
  const [showHistory, setShowHistory] = useState(false);

  // New States for Calculation Mode
  const [activeTab, setActiveTab] = useState<'convert' | 'calculate'>('convert');
  const [salaryAmount, setSalaryAmount] = useState<string>('');
  const [calcType, setCalcType] = useState<'probation' | 'official'>('official');

  // Apply theme palette to CSS variables
  useEffect(() => {
    const applyTheme = (colorIdOrHex: string) => {
      let hex = colorIdOrHex;
      const preset = THEME_COLORS.find(t => t.id === colorIdOrHex);
      if (preset) hex = preset.hex;

      const palette = generatePalette(hex);
      const root = document.documentElement;
      Object.entries(palette).forEach(([shade, value]) => {
        root.style.setProperty(`--color-primary-${shade}`, value);
      });
    };

    const savedTheme = localStorage.getItem('app_theme');
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      applyTheme('blue');
    }
  }, []);

  const handleThemeChange = (newTheme: ThemeColor) => {
    setTheme(newTheme);
    localStorage.setItem('app_theme', newTheme);

    let hex = newTheme;
    const preset = THEME_COLORS.find(t => t.id === newTheme);
    if (preset) hex = preset.hex;

    const palette = generatePalette(hex);
    Object.entries(palette).forEach(([shade, value]) => {
      document.documentElement.style.setProperty(`--color-primary-${shade}`, value);
    });
  };

  const handleAmountChange = (val: string) => {
    if (activeTab === 'calculate') {
        setSalaryAmount(val);
    } else {
        setAmount(val);
    }
    resetResult();
  };

  const handleFromChange = (currency: Currency) => {
    setFromCurrency(currency);
    resetResult();
  };

  const handleToChange = (currency: Currency) => {
    setToCurrency(currency);
    resetResult();
  };

  const handleDenominationSelect = (newAmount: string) => {
    handleAmountChange(newAmount);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        if (isNaN(val)) return `0 ${currencyCode}`;
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  const handleHistorySelect = (item: any) => {
    setActiveTab('convert'); // Force switch to convert tab when selecting history
    selectHistoryItem(item);
    setShowHistory(false);
  };

  // Wrapper for calculation logic
  const onCalculateAndConvert = () => {
    if (activeTab === 'calculate') {
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
            // Let the hook handle the error display or set manual error
            handleConvert('0'); 
            return;
        }
        const multiplier = calcType === 'probation' ? 0.75 : 0.60;
        const fee = Math.floor(salary * multiplier);
        setAmount(fee.toString()); // Sync state
        handleConvert(fee.toString()); // Trigger conversion with calculated fee
    } else {
        handleConvert();
    }
  };

  const renderHistoryButton = (
    <Tooltip content="Xem lịch sử chuyển đổi" position="bottom">
      <button 
          onClick={() => setShowHistory(true)}
          className={`flex items-center gap-1.5 text-xs font-bold text-primary-600 hover:text-primary-700 bg-primary-50 hover:bg-primary-100 px-2 py-1 rounded-md transition-all`}
      >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
          </svg>
          Lịch sử
      </button>
    </Tooltip>
  );

  // Calculate Stage Fee Values (only available when result is present)
  const stageFeeData = useMemo(() => {
    if (activeTab !== 'calculate' || !result || !amount) return null;

    const totalFeeSource = parseFloat(amount);
    if (isNaN(totalFeeSource)) return null;

    const stageSource = Math.floor(totalFeeSource / 2);
    // Calculate target using the same rate logic
    const stageTarget = Math.ceil(stageSource * result.exchangeRate);

    const formattedSource = formatCurrency(stageSource, fromCurrency.locale, fromCurrency.code);
    const formattedTarget = formatCurrency(stageTarget, toCurrency.locale, toCurrency.code);

    return {
        source: stageSource,
        target: stageTarget,
        formattedSource,
        formattedTarget,
        textSource: getReadFunction(fromCurrency.code, stageSource),
        textTarget: getReadFunction(toCurrency.code, stageTarget)
    };
  }, [activeTab, result, amount, fromCurrency, toCurrency]);

  return (
    <div className={`min-h-screen bg-slate-100 font-sans text-slate-800 selection:bg-primary-200 flex flex-col relative`}>

      <div className="fixed top-3 right-3 sm:top-5 sm:right-5 z-[100] animate-fade-in-up">
        <ThemeSelector currentTheme={theme} onThemeChange={handleThemeChange} />
      </div>

      <div className="flex-1 flex items-center justify-center p-3 sm:p-4 relative z-10">
        <div className="w-full max-w-5xl bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-white/50 relative flex flex-col my-2 mb-8">

          <Header theme={theme} onShowHistory={() => {}} />

          <div className="p-4 sm:p-8 space-y-6 relative flex-1">

            <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                <TabSelector activeTab={activeTab} onTabChange={(tab) => { setActiveTab(tab); resetResult(); setAmount(''); setSalaryAmount(''); }} theme={theme} />
            </div>

            {activeTab === 'convert' && (
                <div className="animate-fade-in-up" style={{ animationDelay: '150ms' }}>
                <DenominationSelector 
                    currency={fromCurrency} 
                    onSelect={handleDenominationSelect} 
                    currentAmount={amount}
                    theme={theme}
                />
                </div>
            )}

            <div className="flex flex-col md:flex-row items-center md:items-start relative z-20 gap-3 md:gap-4">
              <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'FROM' ? 'z-50' : 'z-20'}`}> 
                  <CurrencyRow
                      key={activeTab} // Force remount and auto-focus when tab changes
                      label={activeTab === 'calculate' ? "Nhập mức lương" : "Nhập số tiền cần đổi"}
                      amount={activeTab === 'calculate' ? salaryAmount : amount}
                      currency={fromCurrency}
                      onAmountChange={handleAmountChange}
                      onCurrencyChange={handleFromChange}
                      inputPlacement="left"
                      autoFocus={true}
                      isActive={activeDropdown === 'FROM'}
                      onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                      onCloseDropdown={() => setActiveDropdown(null)}
                      theme={theme}
                      headerAction={renderHistoryButton}
                      error={errorMsg}
                      onEnter={onCalculateAndConvert}
                  />

                  {/* Calculation Options */}
                  {activeTab === 'calculate' && (
                      <div className="mt-3 flex gap-3 animate-fade-in-up">
                          {/* Official Salary (Default) on Left */}
                          <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border cursor-pointer transition-all ${calcType === 'official' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="calcType" value="official" checked={calcType === 'official'} onChange={() => setCalcType('official')} className="hidden" />
                              <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'official' ? 'border-primary-500' : 'border-slate-300'}`}>
                                  {calcType === 'official' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                              </div>
                              <span>Chính thức (60%)</span>
                          </label>

                           {/* Probation Salary on Right */}
                          <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border cursor-pointer transition-all ${calcType === 'probation' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="calcType" value="probation" checked={calcType === 'probation'} onChange={() => setCalcType('probation')} className="hidden" />
                              <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'probation' ? 'border-primary-500' : 'border-slate-300'}`}>
                                  {calcType === 'probation' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                              </div>
                              <span>Thử việc (75%)</span>
                          </label>
                      </div>
                  )}
              </div>

              {activeTab === 'convert' && (
                <div className="md:mt-12 z-30 shrink-0">
                    <SwapButton onClick={handleSwap} isSwapping={isSwapping} theme={theme} />
                </div>
              )}

              <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                  <CurrencyRow
                      label={activeTab === 'calculate' ? "Quy đổi phí sang" : "Quy đổi sang"}
                      amount=""
                      currency={toCurrency}
                      onCurrencyChange={handleToChange}
                      inputPlacement="hidden"
                      isActive={activeDropdown === 'TO'}
                      onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                      onCloseDropdown={() => setActiveDropdown(null)}
                      theme={theme}
                  />
              </div>
            </div>

            <Tooltip content="Cập nhật tỷ giá mới nhất và tính toán" position="bottom">
                <button
                  onClick={onCalculateAndConvert}
                  disabled={loadingState === LoadingState.LOADING}
                  className={`w-full py-3.5 sm:py-4 rounded-2xl text-white font-bold text-base sm:text-lg shadow-xl transition-all transform mt-4
                    ${loadingState === LoadingState.LOADING 
                      ? 'bg-slate-400 cursor-not-allowed opacity-80' 
                      : `bg-gradient-to-r from-primary-600 to-primary-800 hover:-translate-y-1 active:scale-[0.98]`
                    }`}
                >
                  <span className="flex items-center justify-center gap-2">
                      {loadingState === LoadingState.LOADING ? (
                        <>
                          <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                          </svg>
                          Đang xử lý...
                        </>
                      ) : (activeTab === 'calculate' ? 'Tính toán & Quy đổi' : 'Chuyển đổi ngay')}
                  </span>
                </button>
            </Tooltip>

             {result && loadingState === LoadingState.SUCCESS && (
                <div className="flex justify-center -mt-2 animate-fade-in-up">
                   <div className="text-xs sm:text-sm font-medium px-4 py-1.5 rounded-full border border-slate-200 bg-white text-slate-500 shadow-sm flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                      {formatExchangeRate(result.exchangeRate, fromCurrency.code, toCurrency.code)}
                   </div>
                </div>
             )}

            {/* Total Fee Section */}
            {result && loadingState === LoadingState.SUCCESS && (
                <>
                   {activeTab === 'calculate' && (
                        <div className="flex items-center gap-2 animate-fade-in-up mt-2">
                             <div className="h-px bg-slate-200 flex-1"></div>
                             <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Phí dịch vụ tổng</span>
                             <div className="h-px bg-slate-200 flex-1"></div>
                        </div>
                   )}
                   <ResultSection 
                      result={result} 
                      fromCurrency={fromCurrency} 
                      toCurrency={toCurrency} 
                      inputAmount={amount}
                      formatCurrency={formatCurrency}
                      theme={theme}
                   />
                </>
            )}

            {/* Detailed Stage Fee Breakdown */}
            {activeTab === 'calculate' && stageFeeData && loadingState === LoadingState.SUCCESS && (
                <div className="animate-fade-in-up pt-2">
                    <div className="flex items-center gap-2 mb-4">
