            <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                <TabSelector activeTab={activeTab} onTabChange={(tab) => { setActiveTab(tab); resetResult(); setAmount(''); setSalaryAmount(''); }} theme={theme} />
