/**
 * UTILS: Number to Text Converters
 */

const readGroupVietnamese = (group: string): string => {
  const digits = ["không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín"];
  let temp = "";
  if (group === "000") return "";

  const a = parseInt(group.substring(0, 1));
  const b = parseInt(group.substring(1, 2));
  const c = parseInt(group.substring(2, 3));

  temp += digits[a] + " trăm";

  if (b === 0) {
    if (c === 0) return temp;
    temp += " linh " + digits[c];
  } else if (b === 1) {
    temp += " mười";
    if (c === 1) temp += " một";
    else if (c === 5) temp += " lăm";
    else if (c !== 0) temp += " " + digits[c];
  } else {
    temp += " " + digits[b] + " mươi";
    if (c === 1) temp += " mốt";
    else if (c === 4) temp += " tư";
    else if (c === 5) temp += " lăm";
    else if (c !== 0) temp += " " + digits[c];
  }
  return temp;
};

const readNumberVietnamese = (number: number, currencyName: string): string => {
  if (number === 0) return "Không " + currencyName;
  const strNum = Math.abs(number).toString();
  const parts = strNum.split('.');
  let integerPart = parts[0];
  let decimalPart = parts.length > 1 ? parts[1] : "";

  while (integerPart.length % 3 !== 0) integerPart = "0" + integerPart;

  const groups = [];
  for (let i = 0; i < integerPart.length; i += 3) groups.push(integerPart.substring(i, i + 3));

  const suffixes = ["", "nghìn", "triệu", "tỷ", "nghìn tỷ", "triệu tỷ"];
  let result = "";

  for (let i = 0; i < groups.length; i++) {
    const group = groups[i];
    const groupValue = parseInt(group);
    const suffix = suffixes[groups.length - 1 - i];
    let read = readGroupVietnamese(group);

    if (i === 0) {
        read = read.replace(/^không trăm linh /, "").replace(/^không trăm /, "");
        if (read.startsWith("linh ")) read = read.replace("linh ", "");
    }
    if (groupValue > 0) result += " " + read + " " + suffix;
  }

  result = result.trim().replace(/\s+/g, ' ');

  if (decimalPart && parseInt(decimalPart) > 0) {
      if (decimalPart.length === 1) decimalPart += "0";
      const val = parseInt(decimalPart.substring(0, 2));
      let decimalText = "";
      if (val < 10) decimalText = "linh " + ["không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín"][val];
      else {
          const chuc = Math.floor(val / 10);
          const donvi = val % 10;
          const digits = ["không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín"];
          if (chuc === 1) decimalText = "mười";
          else decimalText = digits[chuc] + " mươi";
          if (donvi === 1 && chuc > 1) decimalText += " mốt";
          else if (donvi === 5 && chuc > 0) decimalText += " lăm";
          else if (donvi !== 0) decimalText += " " + digits[donvi];
      }
      result += ` phẩy ${decimalText}`;
  }

  const final = result + " " + currencyName;
  return final.charAt(0).toUpperCase() + final.slice(1);
};

const readNumberEnglish = (number: number, currencyCode: string): string => {
  const ones = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
  const tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
  const scales = ['', 'thousand', 'million', 'billion', 'trillion'];
  if (number === 0) return `Zero ${currencyCode}`;

  const numStr = Math.abs(number).toString();
  const parts = numStr.split('.');
  let integerPart = parseInt(parts[0]);
  let decimalPart = parts.length > 1 ? parts[1] : null;

  let words = [];
  if (integerPart === 0) words.push("zero");
  else {
      let scaleIndex = 0;
      while (integerPart > 0) {
        const chunk = integerPart % 1000;
        if (chunk > 0) {
          const chunkStr = [];
          const hundreds = Math.floor(chunk / 100);
          const remainder = chunk % 100;
          if (hundreds > 0) { chunkStr.push(ones[hundreds]); chunkStr.push('hundred'); }
          if (remainder > 0) {
             if (remainder < 20) chunkStr.push(ones[remainder]);
             else {
               chunkStr.push(tens[Math.floor(remainder / 10)]);
               if (remainder % 10 > 0) chunkStr.push(ones[remainder % 10]);
             }
          }
          if (scales[scaleIndex]) chunkStr.push(scales[scaleIndex]);
          words.unshift(...chunkStr);
        }
        integerPart = Math.floor(integerPart / 1000);
        scaleIndex++;
      }
  }

  let result = words.join(' ');
  if (decimalPart) {
      if (decimalPart.length === 1) decimalPart += "0";
      const val = parseInt(decimalPart.substring(0, 2));
      if (val > 0) {
           result += ` point`;
           if (val < 20) result += " " + ones[val];
           else {
               result += " " + tens[Math.floor(val/10)];
               if (val%10 > 0) result += " " + ones[val%10];
           }
      }
  }

  const currencyNames: Record<string, string> = {
      'USD': 'Dollars', 'EUR': 'Euros', 'GBP': 'Pounds', 
      'AUD': 'Australian Dollars', 'CAD': 'Canadian Dollars', 'SGD': 'Singapore Dollars'
  };
  const name = currencyNames[currencyCode] || currencyCode;
  result = result + " " + name;
  return result.charAt(0).toUpperCase() + result.slice(1);
};

const readCJK = (number: number, currencyName: string, chars: { digits: string[], units: string[], groups: string[] }, lang: 'JP' | 'CN' | 'KR'): string => {
    // If integer and CN lang, append '整'
    const isInteger = Math.abs(number % 1) < 0.001;
    const suffix = (lang === 'CN' && isInteger) ? "整" : "";

    if (number === 0) return `${chars.digits[0]}${currencyName}${suffix}`;

    let num = Math.floor(number); 
    let result = "";
    let groupIndex = 0;
    while (num > 0) {
        const part = num % 10000;
        if (part > 0) {
            let partStr = "";
            let p = part;
            const digitsInPart = [];
            for (let i = 0; i < 4; i++) { digitsInPart.push(p % 10); p = Math.floor(p / 10); }
            for(let i=0; i<4; i++) {
                const digit = digitsInPart[i];
                if (digit > 0) {
                    let prefix = chars.digits[digit];
                    if (i === 1 && digit === 1 && (lang === 'JP' || lang === 'KR')) prefix = ""; 
                    partStr = prefix + (i > 0 ? chars.units[i-1] : "") + partStr;
                }
            }
            result = partStr + (groupIndex > 0 ? chars.groups[groupIndex - 1] : "") + result;
        }
        num = Math.floor(num / 10000);
        groupIndex++;
    }
    return result + currencyName + suffix;
};

export const getReadFunction = (currencyCode: string, amount: number): string => {
    switch (currencyCode) {
        case 'VND': 
            // For VND: If amount has non-zero remainder when divided by 1000 (lẻ 3 chữ số), use 'đồng'.
            // Otherwise (round thousands/millions), use 'Việt Nam Đồng'.
            const suffix = (amount % 1000 !== 0) ? 'đồng' : 'Việt Nam Đồng';
            return readNumberVietnamese(amount, suffix);
        case 'JPY': return readCJK(amount, '円 (Yen)', { digits: ['零', '一', '二', '三', '四', '五', '六', '七', '八', '九'], units: ['十', '百', '千'], groups: ['万', '億', '兆'] }, 'JP');
        case 'KRW': return readCJK(amount, '원 (Won)', { digits: ['영', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구'], units: ['십', '백', '천'], groups: ['만', '억', '조'] }, 'KR');
        case 'CNY': return readCJK(amount, '圆', { 
            // Simplified Chinese Financial Numerals (Daxie)
            digits: ['零', '壹', '贰', '叁', '肆', '伍', '陆', '柒', '捌', '玖'], 
            units: ['拾', '佰', '仟'], 
            groups: ['万', '亿', '兆'] 
        }, 'CN');
        case 'TWD': return readCJK(amount, '圓', { 
            // Traditional Chinese Financial Numerals
            digits: ['零', '壹', '貳', '參', '肆', '伍', '陸', '柒', '捌', '玖'], 
            units: ['拾', '佰', '仟'], 
            groups: ['萬', '億', '兆'] 
        }, 'CN');
        case 'USD': case 'EUR': case 'GBP': case 'AUD': case 'CAD': case 'SGD':
        default: return readNumberEnglish(amount, currencyCode);
    }
};

import React from 'react';
import { ThemeColor } from '../types';

interface TabSelectorProps {
  activeTab: 'convert' | 'calculate' | 'revenue';
  onTabChange: (tab: 'convert' | 'calculate' | 'revenue') => void;
  theme: ThemeColor;
}

export const TabSelector: React.FC<TabSelectorProps> = ({ activeTab, onTabChange, theme }) => {
  const getLeftPosition = () => {
    switch (activeTab) {
      case 'convert': return '0.375rem';
      case 'calculate': return 'calc(33.33% + 0.1875rem)';
      case 'revenue': return 'calc(66.66% + 0.1875rem)'; // adjusted for 3 tabs
      default: return '0.375rem';
    }
  };

  return (
    <div className="flex p-1.5 bg-slate-100 rounded-xl mb-6 relative">
      <div 
        className="absolute top-1.5 bottom-1.5 rounded-lg bg-white shadow-sm transition-all duration-300 ease-in-out"
        style={{
            left: getLeftPosition(),
            width: 'calc(33.33% - 0.5rem)'
        }}
      />
      <button
        onClick={() => onTabChange('convert')}
        className={`flex-1 relative z-10 py-2.5 text-xs sm:text-sm md:text-base font-bold text-center rounded-lg transition-colors ${
            activeTab === 'convert' ? 'text-slate-800' : 'text-slate-500 hover:text-slate-700'
        }`}
      >
        Chuyển đổi
      </button>
      <button
        onClick={() => onTabChange('calculate')}
        className={`flex-1 relative z-10 py-2.5 text-xs sm:text-sm md:text-base font-bold text-center rounded-lg transition-colors ${
            activeTab === 'calculate' ? 'text-slate-800' : 'text-slate-500 hover:text-slate-700'
        }`}
      >
        Tính phí
      </button>
       <button
        onClick={() => onTabChange('revenue')}
        className={`flex-1 relative z-10 py-2.5 text-xs sm:text-sm md:text-base font-bold text-center rounded-lg transition-colors ${
            activeTab === 'revenue' ? 'text-slate-800' : 'text-slate-500 hover:text-slate-700'
        }`}
      >
        Tính doanh thu
      </button>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { DenominationSelector } from './components/DenominationSelector';
import { HistorySection } from './components/HistorySection';
import { ThemeSelector } from './components/ThemeSelector';
import { TabSelector } from './components/TabSelector';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState, ThemeColor, Currency, ConversionHistoryItem } from './types';
import { THEME_COLORS } from './constants';
import { generatePalette } from './utils/themeUtils';
import { getReadFunction } from './utils/currencyTextFormatter';
import { CopyButton } from './components/CopyButton';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [theme, setTheme] = useState<ThemeColor>('blue');
  const [showHistory, setShowHistory] = useState(false);

  // States for Calculation & Revenue Mode
  const [activeTab, setActiveTab] = useState<'convert' | 'calculate' | 'revenue'>('convert');
  const [salaryAmount, setSalaryAmount] = useState<string>('');
  const [calcType, setCalcType] = useState<'probation' | 'official'>('official');

  // New State for Revenue Options
  const [revenueShare, setRevenueShare] = useState<'all' | 'cv' | 'job'>('all');
  const [revenueResult, setRevenueResult] = useState<{
      totalRevenue: number;
      stageRevenue: number;
      netIncome: number;
  } | null>(null);

  // Filter history based on active tab (Revenue currently doesn't share history with others to avoid type complexity)
  const filteredHistory = useMemo(() => {
    return history.filter(item => item.type === activeTab);
  }, [history, activeTab]);

  // Apply theme palette to CSS variables
  useEffect(() => {
    const applyTheme = (colorIdOrHex: string) => {
      let hex = colorIdOrHex;
      const preset = THEME_COLORS.find(t => t.id === colorIdOrHex);
      if (preset) hex = preset.hex;

      const palette = generatePalette(hex);
      const root = document.documentElement;
      Object.entries(palette).forEach(([shade, value]) => {
        root.style.setProperty(`--color-primary-${shade}`, value);
      });
    };

    const savedTheme = localStorage.getItem('app_theme');
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      applyTheme('blue');
    }
  }, []);

  const handleThemeChange = (newTheme: ThemeColor) => {
    setTheme(newTheme);
    localStorage.setItem('app_theme', newTheme);

    let hex = newTheme;
    const preset = THEME_COLORS.find(t => t.id === newTheme);
    if (preset) hex = preset.hex;

    const palette = generatePalette(hex);
    Object.entries(palette).forEach(([shade, value]) => {
      document.documentElement.style.setProperty(`--color-primary-${shade}`, value);
    });
  };

  const handleAmountChange = (val: string) => {
    if (activeTab === 'calculate' || activeTab === 'revenue') {
        setSalaryAmount(val);
    } else {
        setAmount(val);
    }
    resetResult();
    setRevenueResult(null); // Reset revenue result on input change
  };

  const handleFromChange = (currency: Currency) => {
    setFromCurrency(currency);
    resetResult();
  };

  const handleToChange = (currency: Currency) => {
    setToCurrency(currency);
    resetResult();
  };

  const handleDenominationSelect = (newAmount: string) => {
    handleAmountChange(newAmount);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        if (isNaN(val)) return `0 ${currencyCode}`;
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  const handleHistorySelect = (item: ConversionHistoryItem) => {
    // Since we filter history, we know the item belongs to the active tab
    selectHistoryItem(item);

    if (item.type === 'calculate' && item.originalSalary) {
        setSalaryAmount(item.originalSalary.toString());
        // Trigger conversion with the fee (inputAmount) and pass salary
        handleConvert(item.inputAmount.toString(), activeTab, item.originalSalary);
    } else {
        handleConvert(item.inputAmount.toString(), activeTab);
    }

    setShowHistory(false);
  };

  const handleSwapClick = () => {
    handleSwap(activeTab as 'convert' | 'calculate');
  };

  // Main Calculation Logic
  const onCalculateAndConvert = () => {
    if (activeTab === 'revenue') {
        // Revenue Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
             setRevenueResult(null);
             return;
        }

        // 1. Calculate Base Fee (Revenue) from Salary
        const feeMultiplier = calcType === 'probation' ? 0.75 : 0.60;
        const baseRevenue = Math.floor(salary * feeMultiplier);

        // 2. Apply Revenue Share Option
        let shareMultiplier = 1;
        if (revenueShare === 'cv') shareMultiplier = 0.7;
        else if (revenueShare === 'job') shareMultiplier = 0.3;

        const totalRevenue = Math.floor(baseRevenue * shareMultiplier);

        // 3. Calculate Derived Values
        const stageRevenue = Math.floor(totalRevenue / 2);
        const netIncome = Math.floor(totalRevenue * 0.49);

        setRevenueResult({
            totalRevenue,
            stageRevenue,
            netIncome
        });

    } else if (activeTab === 'calculate') {
        // Calculate Fee Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
            handleConvert('0', activeTab); 
            return;
        }
        const multiplier = calcType === 'probation' ? 0.75 : 0.60;
        const fee = Math.floor(salary * multiplier);
        setAmount(fee.toString()); // Sync state
        handleConvert(fee.toString(), activeTab, salary); // Trigger conversion
    } else {
        // Standard Convert Logic
        handleConvert(amount, activeTab);
    }
  };

  const renderHistoryButton = (
    activeTab !== 'revenue' ? (
        <button 
            onClick={() => setShowHistory(true)}
            className={`flex items-center gap-1.5 text-xs font-bold text-primary-600 hover:text-primary-700 bg-primary-50 hover:bg-primary-100 px-2 py-1 rounded-md transition-all`}
        >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
            </svg>
            Lịch sử
        </button>
    ) : null
  );

  // Calculate Stage Fee Values (only available when result is present)
  const stageFeeData = useMemo(() => {
    if (activeTab !== 'calculate' || !result || !amount) return null;

    const totalFeeSource = parseFloat(amount);
    if (isNaN(totalFeeSource)) return null;

    const stageSource = Math.floor(totalFeeSource / 2);
    // Calculate target using the same rate logic
    const stageTarget = Math.ceil(stageSource * result.exchangeRate);

    const formattedSource = formatCurrency(stageSource, fromCurrency.locale, fromCurrency.code);
    const formattedTarget = formatCurrency(stageTarget, toCurrency.locale, toCurrency.code);

    return {
        source: stageSource,
        target: stageTarget,
        formattedSource,
        formattedTarget,
        textSource: getReadFunction(fromCurrency.code, stageSource),
        textTarget: getReadFunction(toCurrency.code, stageTarget)
    };
  }, [activeTab, result, amount, fromCurrency, toCurrency]);

  return (
    <div className={`min-h-screen bg-slate-100 font-sans text-slate-800 selection:bg-primary-200 flex flex-col relative`}>

      <div className="fixed top-3 right-3 sm:top-5 sm:right-5 z-[100] animate-fade-in-up">
        <ThemeSelector currentTheme={theme} onThemeChange={handleThemeChange} />
      </div>

      <div className="flex-1 flex items-center justify-center p-3 sm:p-4 relative z-10">
        <div className="w-full max-w-5xl bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-white/50 relative flex flex-col my-2 mb-8">

          <Header theme={theme} onShowHistory={() => {}} />

          <div className="p-4 sm:p-8 space-y-6 relative flex-1">

            <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                <TabSelector 
                    activeTab={activeTab} 
                    onTabChange={(tab) => { setActiveTab(tab); resetResult(); setAmount(''); setSalaryAmount(''); setRevenueResult(null); }} 
                    theme={theme} 
                />
            </div>

            {activeTab === 'convert' && (
                <div className="animate-fade-in-up" style={{ animationDelay: '150ms' }}>
                <DenominationSelector 
                    currency={fromCurrency} 
                    onSelect={handleDenominationSelect} 
                    currentAmount={amount}
                    theme={theme}
                />
                </div>
            )}

            <div className="flex flex-col md:flex-row items-center md:items-start relative z-20 gap-3 md:gap-4">
              <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'FROM' ? 'z-50' : 'z-20'}`}> 
                  <CurrencyRow
                      key={activeTab} // Force remount and auto-focus when tab changes
                      label={activeTab === 'convert' ? "Nhập số tiền cần đổi" : "Nhập mức lương"}
                      amount={activeTab === 'convert' ? amount : salaryAmount}
                      currency={fromCurrency}
                      onAmountChange={handleAmountChange}
                      onCurrencyChange={handleFromChange}
                      inputPlacement="left"
                      autoFocus={true}
                      isActive={activeDropdown === 'FROM'}
                      onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                      onCloseDropdown={() => setActiveDropdown(null)}
                      theme={theme}
                      headerAction={renderHistoryButton}
                      error={errorMsg}
                      onEnter={onCalculateAndConvert}
                  />

                  {/* Calculation Options (Shared by Calculate and Revenue tabs) */}
                  {(activeTab === 'calculate' || activeTab === 'revenue') && (
                      <div className="mt-3 flex gap-3 animate-fade-in-up">
                          {/* Official Salary (Default) */}
                          <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border cursor-pointer transition-all ${calcType === 'official' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="calcType" value="official" checked={calcType === 'official'} onChange={() => setCalcType('official')} className="hidden" />
                              <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'official' ? 'border-primary-500' : 'border-slate-300'}`}>
                                  {calcType === 'official' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                              </div>
                              <span>Chính thức (60%)</span>
                          </label>

                           {/* Probation Salary */}
                          <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border cursor-pointer transition-all ${calcType === 'probation' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="calcType" value="probation" checked={calcType === 'probation'} onChange={() => setCalcType('probation')} className="hidden" />
                              <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'probation' ? 'border-primary-500' : 'border-slate-300'}`}>
                                  {calcType === 'probation' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                              </div>
                              <span>Thử việc (75%)</span>
                          </label>
                      </div>
                  )}

                  {/* Revenue Specific Options */}
                  {activeTab === 'revenue' && (
                      <div className="mt-3 grid grid-cols-3 gap-3 animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                          <label className={`flex items-center justify-center gap-1.5 p-2.5 rounded-xl border cursor-pointer transition-all ${revenueShare === 'all' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="revenueShare" value="all" checked={revenueShare === 'all'} onChange={() => setRevenueShare('all')} className="hidden" />
                              <span className="text-sm">Tất cả (100%)</span>
                          </label>
                          <label className={`flex items-center justify-center gap-1.5 p-2.5 rounded-xl border cursor-pointer transition-all ${revenueShare === 'cv' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="revenueShare" value="cv" checked={revenueShare === 'cv'} onChange={() => setRevenueShare('cv')} className="hidden" />
                              <span className="text-sm">Có CV (70%)</span>
                          </label>
                          <label className={`flex items-center justify-center gap-1.5 p-2.5 rounded-xl border cursor-pointer transition-all ${revenueShare === 'job' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="revenueShare" value="job" checked={revenueShare === 'job'} onChange={() => setRevenueShare('job')} className="hidden" />
                              <span className="text-sm">Nắm Job (30%)</span>
                          </label>
                      </div>
                  )}
              </div>

              {activeTab === 'convert' && (
                <div className="md:mt-12 z-30 shrink-0">
                    <SwapButton onClick={handleSwapClick} isSwapping={isSwapping} theme={theme} />
                </div>
              )}

              {/* Target Currency Input (Hidden for Revenue) */}
              {activeTab !== 'revenue' && (
                  <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                      <CurrencyRow
                          label={activeTab === 'calculate' ? "Quy đổi phí sang" : "Quy đổi sang"}
                          amount=""
                          currency={toCurrency}
                          onCurrencyChange={handleToChange}
                          inputPlacement="hidden"
                          isActive={activeDropdown === 'TO'}
                          onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                          onCloseDropdown={() => setActiveDropdown(null)}
                          theme={theme}
                      />
                  </div>
              )}
            </div>

            <button
                onClick={onCalculateAndConvert}
                disabled={loadingState === LoadingState.LOADING}
                className={`w-full py-3.5 sm:py-4 rounded-2xl text-white font-bold text-base sm:text-lg shadow-xl transition-all transform mt-4
                ${loadingState === LoadingState.LOADING 
                    ? 'bg-slate-400 cursor-not-allowed opacity-80' 
                    : `bg-gradient-to-r from-primary-600 to-primary-800 hover:-translate-y-1 active:scale-[0.98]`
                }`}
            >
                <span className="flex items-center justify-center gap-2">
                    {loadingState === LoadingState.LOADING ? (
                    <>
                        <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Đang xử lý...
                    </>
                    ) : (
                        activeTab === 'revenue' ? 'Tính doanh thu' :
                        activeTab === 'calculate' ? 'Tính toán & Quy đổi' : 'Chuyển đổi ngay'
                    )}
                </span>
            </button>

             {/* Exchange Rate Badge (Convert/Calculate Only) */}
             {activeTab !== 'revenue' && result && loadingState === LoadingState.SUCCESS && (
                <div className="flex justify-center -mt-2 animate-fade-in-up">
                   <div className="text-xs sm:text-sm font-medium px-4 py-1.5 rounded-full border border-slate-200 bg-white text-slate-500 shadow-sm flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                      {formatExchangeRate(result.exchangeRate, fromCurrency.code, toCurrency.code)}
                   </div>
                </div>
             )}

            {/* --- RESULTS SECTIONS --- */}

            {/* 1. Standard Result (Convert & Calculate Total Fee) */}
            {activeTab !== 'revenue' && result && loadingState === LoadingState.SUCCESS && (
                <>
                   {activeTab === 'calculate' && (
                        <div className="flex items-center gap-2 animate-fade-in-up mt-2">
                             <div className="h-px bg-slate-200 flex-1"></div>
                             <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Phí dịch vụ tổng</span>
                             <div className="h-px bg-slate-200 flex-1"></div>
                        </div>
                   )}
                   <ResultSection 
                      result={result} 
                      fromCurrency={fromCurrency} 
                      toCurrency={toCurrency} 
                      inputAmount={amount}
                      formatCurrency={formatCurrency}
                      theme={theme}
                   />
                </>
            )}

            {/* 2. Calculate Stage Breakdown */}
            {activeTab === 'calculate' && stageFeeData && loadingState === LoadingState.SUCCESS && (
                <div className="animate-fade-in-up pt-2">
                    <div className="flex items-center gap-2 mb-4">
                        <div className="h-px bg-slate-200 flex-1"></div>
                        <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Phí mỗi giai đoạn (50%)</span>
                        <div className="h-px bg-slate-200 flex-1"></div>
                    </div>

                    <div className="grid md:grid-cols-2 gap-4">
                        {/* Stage Fee - Source */}
                        <div className="p-4 rounded-2xl border border-slate-200 bg-slate-50/50 flex flex-col justify-between">
                            <div>
                                <div className="flex items-center gap-2 mb-2 opacity-70">
                                    <img src={fromCurrency.flag} alt={fromCurrency.code} className="w-6 h-4 rounded shadow-sm object-cover" />
                                    <span className="text-xs font-bold uppercase text-slate-500">{fromCurrency.code}</span>
                                </div>
                                <div className="flex items-start justify-between gap-3">
                                    <div className="text-xl sm:text-2xl font-bold text-slate-700">
                                        {stageFeeData.formattedSource}
                                    </div>
                                    <CopyButton text={stageFeeData.formattedSource} />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-slate-200">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold uppercase text-slate-400">Bằng chữ</span>
                                    <CopyButton 
                                        text={stageFeeData.textSource} 
                                        className="bg-white border-slate-200 text-slate-400 hover:text-slate-600 hover:border-slate-300"
                                    />
                                </div>
                                <p className="text-sm italic font-medium text-slate-600 leading-relaxed">{stageFeeData.textSource}</p>
                            </div>
                        </div>

                        {/* Stage Fee - Target */}
                        <div className="p-4 rounded-2xl border border-primary-100 bg-primary-50/30 flex flex-col justify-between">
                            <div>
                                <div className="flex items-center gap-2 mb-2">
                                    <img src={toCurrency.flag} alt={toCurrency.code} className="w-6 h-4 rounded shadow-sm object-cover" />
                                    <span className="text-xs font-bold uppercase text-primary-500">{toCurrency.code}</span>
                                </div>
                                <div className="flex items-start justify-between gap-3">
                                    <div className="text-xl sm:text-2xl font-bold text-primary-700">
                                        {stageFeeData.formattedTarget}
                                    </div>
                                    <CopyButton 
                                        text={stageFeeData.formattedTarget} 
                                        className="bg-white border-primary-200 text-primary-500 hover:text-primary-700 hover:border-primary-300"
                                    />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-primary-200/50">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold uppercase text-primary-400">Bằng chữ</span>
                                    <CopyButton 
                                        text={stageFeeData.textTarget} 
                                        className="bg-white border-primary-200 text-primary-500 hover:text-primary-700 hover:border-primary-300"
                                    />
                                </div>
                                <p className="text-sm italic font-medium text-primary-800 leading-relaxed">{stageFeeData.textTarget}</p>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* 3. REVENUE RESULT DISPLAY */}
            {activeTab === 'revenue' && revenueResult && (
                <div className="animate-fade-in-up space-y-4 pt-2">
                     <div className="flex items-center gap-2 mt-2 mb-4">
                        <div className="h-px bg-slate-200 flex-1"></div>
                        <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Kết quả tính doanh thu</span>
                        <div className="h-px bg-slate-200 flex-1"></div>
                    </div>

                    {/* Total & Stage Revenue */}
                    <div className="grid md:grid-cols-2 gap-4">
                        {/* Total Revenue */}
                        <div className="p-4 rounded-2xl border border-slate-200 bg-white flex flex-col justify-between">
                            <div>
                                <span className="text-xs font-bold uppercase text-slate-500 mb-2 block">Doanh thu tổng ({revenueShare === 'all' ? '100%' : revenueShare === 'cv' ? '70%' : '30%'})</span>
                                <div className="flex items-start justify-between gap-2">
                                    <span className="text-2xl font-bold text-slate-800">
                                        {formatCurrency(revenueResult.totalRevenue, 'vi-VN', 'VND')}
                                    </span>
                                    <CopyButton text={formatCurrency(revenueResult.totalRevenue, 'vi-VN', 'VND')} />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-slate-100">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold text-slate-400 uppercase">Bằng chữ</span>
                                    <CopyButton 
                                        text={getReadFunction('VND', revenueResult.totalRevenue)} 
                                        className="bg-white border-slate-100 text-slate-400 hover:text-slate-600 w-8 h-8"
                                        iconSize="w-4 h-4"
                                    />
                                </div>
                                <p className="text-xs italic text-slate-500">{getReadFunction('VND', revenueResult.totalRevenue)}</p>
                            </div>
                        </div>

                         {/* Stage Revenue */}
                         <div className="p-4 rounded-2xl border border-slate-200 bg-white flex flex-col justify-between">
                            <div>
                                <span className="text-xs font-bold uppercase text-slate-500 mb-2 block">Doanh thu mỗi giai đoạn (50%)</span>
                                <div className="flex items-start justify-between gap-2">
                                    <span className="text-2xl font-bold text-slate-800">
                                        {formatCurrency(revenueResult.stageRevenue, 'vi-VN', 'VND')}
                                    </span>
                                    <CopyButton text={formatCurrency(revenueResult.stageRevenue, 'vi-VN', 'VND')} />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-slate-100">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold text-slate-400 uppercase">Bằng chữ</span>
                                    <CopyButton 
                                        text={getReadFunction('VND', revenueResult.stageRevenue)} 
                                        className="bg-white border-slate-100 text-slate-400 hover:text-slate-600 w-8 h-8"
                                        iconSize="w-4 h-4"
                                    />
                                </div>
                                <p className="text-xs italic text-slate-500">{getReadFunction('VND', revenueResult.stageRevenue)}</p>
                            </div>
                        </div>
                    </div>

                    {/* Net Income (Highlighted) */}
                    <div className="p-5 rounded-2xl border border-primary-200 bg-gradient-to-r from-primary-50 to-white shadow-sm relative overflow-hidden">
                        <div className="relative z-10">
                            <span className="text-sm font-extrabold uppercase text-primary-600 mb-2 block tracking-wide">Thu nhập thực nhận (49%)</span>
                            <div className="flex items-start justify-between gap-3">
                                <span className="text-3xl sm:text-4xl font-extrabold text-primary-700">
                                    {formatCurrency(revenueResult.netIncome, 'vi-VN', 'VND')}
                                </span>
                                <CopyButton 
                                    text={formatCurrency(revenueResult.netIncome, 'vi-VN', 'VND')} 
                                    className="bg-white border-primary-200 text-primary-600 hover:text-primary-800"
                                />
                            </div>
                            <div className="mt-4 pt-4 border-t border-primary-100">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold text-primary-400 uppercase">Bằng chữ</span>
                                    <CopyButton 
                                        text={getReadFunction('VND', revenueResult.netIncome)} 
                                        className="bg-white border-primary-100 text-primary-400 hover:text-primary-600 w-8 h-8"
                                        iconSize="w-4 h-4"
                                    />
                                </div>
                                <p className="text-sm italic font-bold text-primary-800">{getReadFunction('VND', revenueResult.netIncome)}</p>
                            </div>
                        </div>
                    </div>
                </div>
            )}
          </div>
        </div>
      </div>

      {/* Simple Dark Footer */}
      <footer className="w-full bg-slate-900 text-slate-400 py-6 mt-auto">
        <div className="container mx-auto px-4 text-center">
            <p className="font-semibold text-slate-300 mb-1 tracking-wide text-sm">Powered by ZiQi</p>
            <p className="text-xs opacity-60">Lasted update: {new Date().toLocaleDateString('vi-VN')} </p>
        </div>
      </footer>

      {showHistory && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
             <div className="absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity animate-fade-in-up" onClick={() => setShowHistory(false)} style={{animationDuration: '0.2s'}} />
             <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl relative z-10 overflow-hidden animate-fade-in-up flex flex-col max-h-[85vh]">
                <div className="p-0 flex-1 overflow-hidden flex flex-col">
                   <HistorySection 
                        history={filteredHistory} 
                        onSelect={handleHistorySelect} 
                        onClear={clearHistory}
                        onDeleteItems={deleteHistoryItems}
                        formatCurrency={formatCurrency}
                        onClose={() => setShowHistory(false)}
                   />
                </div>
             </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { DenominationSelector } from './components/DenominationSelector';
import { HistorySection } from './components/HistorySection';
import { ThemeSelector } from './components/ThemeSelector';
import { TabSelector } from './components/TabSelector';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState, ThemeColor, Currency, ConversionHistoryItem } from './types';
import { THEME_COLORS } from './constants';
import { generatePalette } from './utils/themeUtils';
import { getReadFunction } from './utils/currencyTextFormatter';
import { CopyButton } from './components/CopyButton';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [theme, setTheme] = useState<ThemeColor>('blue');
  const [showHistory, setShowHistory] = useState(false);

  // States for Calculation & Revenue Mode
  const [activeTab, setActiveTab] = useState<'convert' | 'calculate' | 'revenue'>('convert');
  const [salaryAmount, setSalaryAmount] = useState<string>('');
  const [calcType, setCalcType] = useState<'probation' | 'official'>('official');

  // New State for Revenue Options
  const [revenueShare, setRevenueShare] = useState<'all' | 'cv' | 'job'>('all');
  const [revenueResult, setRevenueResult] = useState<{
      totalRevenue: number;
      stageRevenue: number;
      netIncome: number;
  } | null>(null);

  // Filter history based on active tab (Revenue currently doesn't share history with others to avoid type complexity)
  const filteredHistory = useMemo(() => {
    return history.filter(item => item.type === activeTab);
  }, [history, activeTab]);

  // Apply theme palette to CSS variables
  useEffect(() => {
    const applyTheme = (colorIdOrHex: string) => {
      let hex = colorIdOrHex;
      const preset = THEME_COLORS.find(t => t.id === colorIdOrHex);
      if (preset) hex = preset.hex;

      const palette = generatePalette(hex);
      const root = document.documentElement;
      Object.entries(palette).forEach(([shade, value]) => {
        root.style.setProperty(`--color-primary-${shade}`, value);
      });
    };

    const savedTheme = localStorage.getItem('app_theme');
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      applyTheme('blue');
    }
  }, []);

  const handleThemeChange = (newTheme: ThemeColor) => {
    setTheme(newTheme);
    localStorage.setItem('app_theme', newTheme);

    let hex = newTheme;
    const preset = THEME_COLORS.find(t => t.id === newTheme);
    if (preset) hex = preset.hex;

    const palette = generatePalette(hex);
    Object.entries(palette).forEach(([shade, value]) => {
      document.documentElement.style.setProperty(`--color-primary-${shade}`, value);
    });
  };

  const handleAmountChange = (val: string) => {
    if (activeTab === 'calculate' || activeTab === 'revenue') {
        setSalaryAmount(val);
    } else {
        setAmount(val);
    }
    resetResult();
    setRevenueResult(null); // Reset revenue result on input change
  };

  const handleFromChange = (currency: Currency) => {
    setFromCurrency(currency);
    resetResult();
  };

  const handleToChange = (currency: Currency) => {
    setToCurrency(currency);
    resetResult();
  };

  const handleDenominationSelect = (newAmount: string) => {
    handleAmountChange(newAmount);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        if (isNaN(val)) return `0 ${currencyCode}`;
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  const handleHistorySelect = (item: ConversionHistoryItem) => {
    // Since we filter history, we know the item belongs to the active tab
    selectHistoryItem(item);

    if (item.type === 'calculate' && item.originalSalary) {
        setSalaryAmount(item.originalSalary.toString());
        // Trigger conversion with the fee (inputAmount) and pass salary
        handleConvert(item.inputAmount.toString(), activeTab, item.originalSalary);
    } else {
        handleConvert(item.inputAmount.toString(), activeTab);
    }

    setShowHistory(false);
  };

  const handleSwapClick = () => {
    handleSwap(activeTab as 'convert' | 'calculate');
  };

  // Main Calculation Logic
  const onCalculateAndConvert = () => {
    if (activeTab === 'revenue') {
        // Revenue Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
             setRevenueResult(null);
             return;
        }

        // 1. Calculate Base Fee (Revenue) from Salary
        const feeMultiplier = calcType === 'probation' ? 0.75 : 0.60;
        const baseRevenue = Math.floor(salary * feeMultiplier);

        // 2. Apply Revenue Share Option
        let shareMultiplier = 1;
        if (revenueShare === 'cv') shareMultiplier = 0.7;
        else if (revenueShare === 'job') shareMultiplier = 0.3;

        const totalRevenue = Math.floor(baseRevenue * shareMultiplier);

        // 3. Calculate Derived Values
        const stageRevenue = Math.floor(totalRevenue / 2);
        const netIncome = Math.floor(totalRevenue * 0.49);

        setRevenueResult({
            totalRevenue,
            stageRevenue,
            netIncome
        });

    } else if (activeTab === 'calculate') {
        // Calculate Fee Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
            handleConvert('0', activeTab); 
            return;
        }
        const multiplier = calcType === 'probation' ? 0.75 : 0.60;
        const fee = Math.floor(salary * multiplier);
        setAmount(fee.toString()); // Sync state
        handleConvert(fee.toString(), activeTab, salary); // Trigger conversion
    } else {
        // Standard Convert Logic
        handleConvert(amount, activeTab);
    }
  };

  const renderHistoryButton = (
    activeTab !== 'revenue' ? (
        <button 
            onClick={() => setShowHistory(true)}
            className={`flex items-center gap-1.5 text-xs font-bold text-primary-600 hover:text-primary-700 bg-primary-50 hover:bg-primary-100 px-2 py-1 rounded-md transition-all`}
        >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
            </svg>
            Lịch sử
        </button>
    ) : null
  );

  // Calculate Stage Fee Values (only available when result is present)
  const stageFeeData = useMemo(() => {
    if (activeTab !== 'calculate' || !result || !amount) return null;

    const totalFeeSource = parseFloat(amount);
    if (isNaN(totalFeeSource)) return null;

    const stageSource = Math.floor(totalFeeSource / 2);
    // Calculate target using the same rate logic
    const stageTarget = Math.ceil(stageSource * result.exchangeRate);

    const formattedSource = formatCurrency(stageSource, fromCurrency.locale, fromCurrency.code);
    const formattedTarget = formatCurrency(stageTarget, toCurrency.locale, toCurrency.code);

    return {
        source: stageSource,
        target: stageTarget,
        formattedSource,
        formattedTarget,
        textSource: getReadFunction(fromCurrency.code, stageSource),
        textTarget: getReadFunction(toCurrency.code, stageTarget)
    };
  }, [activeTab, result, amount, fromCurrency, toCurrency]);

  const vietNamFlagUrl = "https://flagcdn.com/w80/vn.png";

  return (
    <div className={`min-h-screen bg-slate-100 font-sans text-slate-800 selection:bg-primary-200 flex flex-col relative`}>

      <div className="fixed top-3 right-3 sm:top-5 sm:right-5 z-[100] animate-fade-in-up">
        <ThemeSelector currentTheme={theme} onThemeChange={handleThemeChange} />
      </div>

      <div className="flex-1 flex items-center justify-center p-3 sm:p-4 relative z-10">
        <div className="w-full max-w-5xl bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-white/50 relative flex flex-col my-2 mb-8">

          <Header theme={theme} onShowHistory={() => {}} />

          <div className="p-4 sm:p-8 space-y-6 relative flex-1">

            <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                <TabSelector 
                    activeTab={activeTab} 
                    onTabChange={(tab) => { setActiveTab(tab); resetResult(); setAmount(''); setSalaryAmount(''); setRevenueResult(null); }} 
                    theme={theme} 
                />
            </div>

            {activeTab === 'convert' && (
                <div className="animate-fade-in-up" style={{ animationDelay: '150ms' }}>
                <DenominationSelector 
                    currency={fromCurrency} 
                    onSelect={handleDenominationSelect} 
                    currentAmount={amount}
                    theme={theme}
                />
                </div>
            )}

            <div className="flex flex-col md:flex-row items-center md:items-start relative z-20 gap-3 md:gap-4">
              <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'FROM' ? 'z-50' : 'z-20'}`}> 
                  <CurrencyRow
                      key={activeTab} // Force remount and auto-focus when tab changes
                      label={activeTab === 'convert' ? "Nhập số tiền cần đổi" : "Nhập mức lương"}
                      amount={activeTab === 'convert' ? amount : salaryAmount}
                      currency={fromCurrency}
                      onAmountChange={handleAmountChange}
                      onCurrencyChange={handleFromChange}
                      inputPlacement="left"
                      autoFocus={true}
                      isActive={activeDropdown === 'FROM'}
                      onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                      onCloseDropdown={() => setActiveDropdown(null)}
                      theme={theme}
                      headerAction={renderHistoryButton}
                      error={errorMsg}
                      onEnter={onCalculateAndConvert}
                  />

                  {/* Calculation Options (Shared by Calculate and Revenue tabs) */}
                  {(activeTab === 'calculate' || activeTab === 'revenue') && (
                      <div className="mt-3 flex gap-3 animate-fade-in-up">
                          {/* Official Salary (Default) */}
                          <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border cursor-pointer transition-all ${calcType === 'official' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="calcType" value="official" checked={calcType === 'official'} onChange={() => setCalcType('official')} className="hidden" />
                              <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'official' ? 'border-primary-500' : 'border-slate-300'}`}>
                                  {calcType === 'official' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                              </div>
                              <span>Chính thức (60%)</span>
                          </label>

                           {/* Probation Salary */}
                          <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border cursor-pointer transition-all ${calcType === 'probation' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="calcType" value="probation" checked={calcType === 'probation'} onChange={() => setCalcType('probation')} className="hidden" />
                              <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'probation' ? 'border-primary-500' : 'border-slate-300'}`}>
                                  {calcType === 'probation' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                              </div>
                              <span>Thử việc (75%)</span>
                          </label>
                      </div>
                  )}

                  {/* Revenue Specific Options - CHANGED TO SELECT */}
                  {activeTab === 'revenue' && (
                      <div className="mt-3 animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                        <div className="relative">
                            <select
                                value={revenueShare}
                                onChange={(e) => setRevenueShare(e.target.value as 'all' | 'cv' | 'job')}
                                className="w-full appearance-none bg-white border border-slate-200 text-slate-700 font-bold py-3.5 px-4 pr-10 rounded-xl leading-tight focus:outline-none focus:border-primary-500 focus:ring-2 focus:ring-primary-100 transition-all cursor-pointer shadow-sm hover:border-primary-300"
                            >
                                <option value="all">Tất cả (100%)</option>
                                <option value="cv">Có CV (70%)</option>
                                <option value="job">Nắm Job (30%)</option>
                            </select>
                            <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500">
                                <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                            </div>
                        </div>
                      </div>
                  )}
              </div>

              {activeTab === 'convert' && (
                <div className="md:mt-12 z-30 shrink-0">
                    <SwapButton onClick={handleSwapClick} isSwapping={isSwapping} theme={theme} />
                </div>
              )}

              {/* Target Currency Input (Hidden for Revenue) */}
              {activeTab !== 'revenue' && (
                  <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                      <CurrencyRow
                          label={activeTab === 'calculate' ? "Quy đổi phí sang" : "Quy đổi sang"}
                          amount=""
                          currency={toCurrency}
                          onCurrencyChange={handleToChange}
                          inputPlacement="hidden"
                          isActive={activeDropdown === 'TO'}
                          onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                          onCloseDropdown={() => setActiveDropdown(null)}
                          theme={theme}
                      />
                  </div>
              )}
            </div>

            <button
                onClick={onCalculateAndConvert}
                disabled={loadingState === LoadingState.LOADING}
                className={`w-full py-3.5 sm:py-4 rounded-2xl text-white font-bold text-base sm:text-lg shadow-xl transition-all transform mt-4
                ${loadingState === LoadingState.LOADING 
                    ? 'bg-slate-400 cursor-not-allowed opacity-80' 
                    : `bg-gradient-to-r from-primary-600 to-primary-800 hover:-translate-y-1 active:scale-[0.98]`
                }`}
            >
                <span className="flex items-center justify-center gap-2">
                    {loadingState === LoadingState.LOADING ? (
                    <>
                        <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Đang xử lý...
                    </>
                    ) : (
                        activeTab === 'revenue' ? 'Tính doanh thu' :
                        activeTab === 'calculate' ? 'Tính toán & Quy đổi' : 'Chuyển đổi ngay'
                    )}
                </span>
            </button>

             {/* Exchange Rate Badge (Convert/Calculate Only) */}
             {activeTab !== 'revenue' && result && loadingState === LoadingState.SUCCESS && (
                <div className="flex justify-center -mt-2 animate-fade-in-up">
                   <div className="text-xs sm:text-sm font-medium px-4 py-1.5 rounded-full border border-slate-200 bg-white text-slate-500 shadow-sm flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                      {formatExchangeRate(result.exchangeRate, fromCurrency.code, toCurrency.code)}
                   </div>
                </div>
             )}

            {/* --- RESULTS SECTIONS --- */}

            {/* 1. Standard Result (Convert & Calculate Total Fee) */}
            {activeTab !== 'revenue' && result && loadingState === LoadingState.SUCCESS && (
                <>
                   {activeTab === 'calculate' && (
                        <div className="flex items-center gap-2 animate-fade-in-up mt-2">
                             <div className="h-px bg-slate-200 flex-1"></div>
                             <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Phí dịch vụ tổng</span>
                             <div className="h-px bg-slate-200 flex-1"></div>
                        </div>
                   )}
                   <ResultSection 
                      result={result} 
                      fromCurrency={fromCurrency} 
                      toCurrency={toCurrency} 
                      inputAmount={amount}
                      formatCurrency={formatCurrency}
                      theme={theme}
                   />
                </>
            )}

            {/* 2. Calculate Stage Breakdown */}
            {activeTab === 'calculate' && stageFeeData && loadingState === LoadingState.SUCCESS && (
                <div className="animate-fade-in-up pt-2">
                    <div className="flex items-center gap-2 mb-4">
                        <div className="h-px bg-slate-200 flex-1"></div>
                        <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Phí mỗi giai đoạn (50%)</span>
                        <div className="h-px bg-slate-200 flex-1"></div>
                    </div>

                    <div className="grid md:grid-cols-2 gap-4">
                        {/* Stage Fee - Source */}
                        <div className="p-4 rounded-2xl border border-slate-200 bg-slate-50/50 flex flex-col justify-between">
                            <div>
                                <div className="flex items-center gap-2 mb-2 opacity-70">
                                    <img src={fromCurrency.flag} alt={fromCurrency.code} className="w-6 h-4 rounded shadow-sm object-cover" />
                                    <span className="text-xs font-bold uppercase text-slate-500">{fromCurrency.code}</span>
                                </div>
                                <div className="flex items-start justify-between gap-3">
                                    <div className="text-xl sm:text-2xl font-bold text-slate-700">
                                        {stageFeeData.formattedSource}
                                    </div>
                                    <CopyButton text={stageFeeData.formattedSource} />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-slate-200">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold uppercase text-slate-400">Bằng chữ</span>
                                    <CopyButton 
                                        text={stageFeeData.textSource} 
                                        className="bg-white border-slate-200 text-slate-400 hover:text-slate-600 hover:border-slate-300"
                                    />
                                </div>
                                <p className="text-sm italic font-medium text-slate-600 leading-relaxed">{stageFeeData.textSource}</p>
                            </div>
                        </div>

                        {/* Stage Fee - Target */}
                        <div className="p-4 rounded-2xl border border-primary-100 bg-primary-50/30 flex flex-col justify-between">
                            <div>
                                <div className="flex items-center gap-2 mb-2">
                                    <img src={toCurrency.flag} alt={toCurrency.code} className="w-6 h-4 rounded shadow-sm object-cover" />
                                    <span className="text-xs font-bold uppercase text-primary-500">{toCurrency.code}</span>
                                </div>
                                <div className="flex items-start justify-between gap-3">
                                    <div className="text-xl sm:text-2xl font-bold text-primary-700">
                                        {stageFeeData.formattedTarget}
                                    </div>
                                    <CopyButton 
                                        text={stageFeeData.formattedTarget} 
                                        className="bg-white border-primary-200 text-primary-500 hover:text-primary-700 hover:border-primary-300"
                                    />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-primary-200/50">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold uppercase text-primary-400">Bằng chữ</span>
                                    <CopyButton 
                                        text={stageFeeData.textTarget} 
                                        className="bg-white border-primary-200 text-primary-500 hover:text-primary-700 hover:border-primary-300"
                                    />
                                </div>
                                <p className="text-sm italic font-medium text-primary-800 leading-relaxed">{stageFeeData.textTarget}</p>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* 3. REVENUE RESULT DISPLAY */}
            {activeTab === 'revenue' && revenueResult && (
                <div className="animate-fade-in-up space-y-4 pt-2">
                     <div className="flex items-center gap-2 mt-2 mb-4">
                        <div className="h-px bg-slate-200 flex-1"></div>
                        <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Kết quả tính doanh thu</span>
                        <div className="h-px bg-slate-200 flex-1"></div>
                    </div>

                    {/* Total & Stage Revenue */}
                    <div className="grid md:grid-cols-2 gap-4">
                        {/* Total Revenue */}
                        <div className="p-4 rounded-2xl border border-slate-200 bg-white flex flex-col justify-between">
                            <div>
                                <div className="flex items-center gap-2 mb-2">
                                    <img src={vietNamFlagUrl} alt="VND" className="w-6 h-4 rounded shadow-sm object-cover" />
                                    <span className="text-xs font-bold uppercase text-slate-500">Doanh thu tổng ({revenueShare === 'all' ? '100%' : revenueShare === 'cv' ? '70%' : '30%'})</span>
                                </div>
                                <div className="flex items-start justify-between gap-2">
                                    <span className="text-2xl font-bold text-slate-800">
                                        {formatCurrency(revenueResult.totalRevenue, 'vi-VN', 'VND')}
                                    </span>
                                    <CopyButton text={formatCurrency(revenueResult.totalRevenue, 'vi-VN', 'VND')} />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-slate-100">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold text-slate-400 uppercase">Bằng chữ</span>
                                    <CopyButton 
                                        text={getReadFunction('VND', revenueResult.totalRevenue)} 
                                        className="bg-white border-slate-100 text-slate-400 hover:text-slate-600 w-8 h-8"
                                        iconSize="w-4 h-4"
                                    />
                                </div>
                                <p className="text-xs italic text-slate-500">{getReadFunction('VND', revenueResult.totalRevenue)}</p>
                            </div>
                        </div>

                         {/* Stage Revenue */}
                         <div className="p-4 rounded-2xl border border-slate-200 bg-white flex flex-col justify-between">
                            <div>
                                <div className="flex items-center gap-2 mb-2">
                                    <img src={vietNamFlagUrl} alt="VND" className="w-6 h-4 rounded shadow-sm object-cover" />
                                    <span className="text-xs font-bold uppercase text-slate-500">Doanh thu mỗi giai đoạn (50%)</span>
                                </div>
                                <div className="flex items-start justify-between gap-2">
                                    <span className="text-2xl font-bold text-slate-800">
                                        {formatCurrency(revenueResult.stageRevenue, 'vi-VN', 'VND')}
                                    </span>
                                    <CopyButton text={formatCurrency(revenueResult.stageRevenue, 'vi-VN', 'VND')} />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-slate-100">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold text-slate-400 uppercase">Bằng chữ</span>
                                    <CopyButton 
                                        text={getReadFunction('VND', revenueResult.stageRevenue)} 
                                        className="bg-white border-slate-100 text-slate-400 hover:text-slate-600 w-8 h-8"
                                        iconSize="w-4 h-4"
                                    />
                                </div>
                                <p className="text-xs italic text-slate-500">{getReadFunction('VND', revenueResult.stageRevenue)}</p>
                            </div>
                        </div>
                    </div>

                    {/* Net Income (Highlighted) */}
                    <div className="p-5 rounded-2xl border border-primary-200 bg-gradient-to-r from-primary-50 to-white shadow-sm relative overflow-hidden">
                        <div className="relative z-10">
                            <div className="flex items-center gap-2 mb-2">
                                <img src={vietNamFlagUrl} alt="VND" className="w-6 h-4 rounded shadow-sm object-cover" />
                                <span className="text-sm font-extrabold uppercase text-primary-600 tracking-wide">Thu nhập thực nhận (49%)</span>
                            </div>
                            <div className="flex items-start justify-between gap-3">
                                <span className="text-3xl sm:text-4xl font-extrabold text-primary-700">
                                    {formatCurrency(revenueResult.netIncome, 'vi-VN', 'VND')}
                                </span>
                                <CopyButton 
                                    text={formatCurrency(revenueResult.netIncome, 'vi-VN', 'VND')} 
                                    className="bg-white border-primary-200 text-primary-600 hover:text-primary-800"
                                />
                            </div>
                            <div className="mt-4 pt-4 border-t border-primary-100">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold text-primary-400 uppercase">Bằng chữ</span>
                                    <CopyButton 
                                        text={getReadFunction('VND', revenueResult.netIncome)} 
                                        className="bg-white border-primary-100 text-primary-400 hover:text-primary-600 w-8 h-8"
                                        iconSize="w-4 h-4"
                                    />
                                </div>
                                <p className="text-sm italic font-bold text-primary-800">{getReadFunction('VND', revenueResult.netIncome)}</p>
                            </div>
                        </div>
                    </div>
                </div>
            )}
          </div>
        </div>
      </div>

      {/* Simple Dark Footer */}
      <footer className="w-full bg-slate-900 text-slate-400 py-6 mt-auto">
        <div className="container mx-auto px-4 text-center">
            <p className="font-semibold text-slate-300 mb-1 tracking-wide text-sm">Powered by ZiQi</p>
            <p className="text-xs opacity-60">Lasted update: {new Date().toLocaleDateString('vi-VN')} </p>
        </div>
      </footer>

      {showHistory && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
             <div className="absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity animate-fade-in-up" onClick={() => setShowHistory(false)} style={{animationDuration: '0.2s'}} />
             <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl relative z-10 overflow-hidden animate-fade-in-up flex flex-col max-h-[85vh]">
                <div className="p-0 flex-1 overflow-hidden flex flex-col">
                   <HistorySection 
                        history={filteredHistory} 
                        onSelect={handleHistorySelect} 
                        onClear={clearHistory}
                        onDeleteItems={deleteHistoryItems}
                        formatCurrency={formatCurrency}
                        onClose={() => setShowHistory(false)}
                   />
                </div>
             </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { DenominationSelector } from './components/DenominationSelector';
import { HistorySection } from './components/HistorySection';
import { ThemeSelector } from './components/ThemeSelector';
import { TabSelector } from './components/TabSelector';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState, ThemeColor, Currency, ConversionHistoryItem } from './types';
import { THEME_COLORS } from './constants';
import { generatePalette } from './utils/themeUtils';
import { getReadFunction } from './utils/currencyTextFormatter';
import { CopyButton } from './components/CopyButton';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [theme, setTheme] = useState<ThemeColor>('blue');
  const [showHistory, setShowHistory] = useState(false);

  // States for Calculation & Revenue Mode
  const [activeTab, setActiveTab] = useState<'convert' | 'calculate' | 'revenue'>('convert');
  const [salaryAmount, setSalaryAmount] = useState<string>('');
  const [calcType, setCalcType] = useState<'probation' | 'official'>('official');

  // New State for Revenue Options
  const [revenueShare, setRevenueShare] = useState<'all' | 'cv' | 'job'>('all');
  const [revenueResult, setRevenueResult] = useState<{
      totalRevenue: number;
      stageRevenue: number;
      netIncome: number;
  } | null>(null);

  // Filter history based on active tab (Revenue currently doesn't share history with others to avoid type complexity)
  const filteredHistory = useMemo(() => {
    return history.filter(item => item.type === activeTab);
  }, [history, activeTab]);

  // Apply theme palette to CSS variables
  useEffect(() => {
    const applyTheme = (colorIdOrHex: string) => {
      let hex = colorIdOrHex;
      const preset = THEME_COLORS.find(t => t.id === colorIdOrHex);
      if (preset) hex = preset.hex;

      const palette = generatePalette(hex);
      const root = document.documentElement;
      Object.entries(palette).forEach(([shade, value]) => {
        root.style.setProperty(`--color-primary-${shade}`, value);
      });
    };

    const savedTheme = localStorage.getItem('app_theme');
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      applyTheme('blue');
    }
  }, []);

  const handleThemeChange = (newTheme: ThemeColor) => {
    setTheme(newTheme);
    localStorage.setItem('app_theme', newTheme);

    let hex = newTheme;
    const preset = THEME_COLORS.find(t => t.id === newTheme);
    if (preset) hex = preset.hex;

    const palette = generatePalette(hex);
    Object.entries(palette).forEach(([shade, value]) => {
      document.documentElement.style.setProperty(`--color-primary-${shade}`, value);
    });
  };

  const handleAmountChange = (val: string) => {
    if (activeTab === 'calculate' || activeTab === 'revenue') {
        setSalaryAmount(val);
    } else {
        setAmount(val);
    }
    resetResult();
    setRevenueResult(null); // Reset revenue result on input change
  };

  const handleFromChange = (currency: Currency) => {
    setFromCurrency(currency);
    resetResult();
  };

  const handleToChange = (currency: Currency) => {
    setToCurrency(currency);
    resetResult();
  };

  const handleDenominationSelect = (newAmount: string) => {
    handleAmountChange(newAmount);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        if (isNaN(val)) return `0 ${currencyCode}`;
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  const handleHistorySelect = (item: ConversionHistoryItem) => {
    // Since we filter history, we know the item belongs to the active tab
    selectHistoryItem(item);

    if (item.type === 'calculate' && item.originalSalary) {
        setSalaryAmount(item.originalSalary.toString());
        // Trigger conversion with the fee (inputAmount) and pass salary
        handleConvert(item.inputAmount.toString(), activeTab, item.originalSalary);
    } else {
        handleConvert(item.inputAmount.toString(), activeTab);
    }

    setShowHistory(false);
  };

  const handleSwapClick = () => {
    handleSwap(activeTab as 'convert' | 'calculate');
  };

  // Main Calculation Logic
  const onCalculateAndConvert = () => {
    if (activeTab === 'revenue') {
        // Revenue Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
             setRevenueResult(null);
             return;
        }

        // 1. Calculate Base Fee (Revenue) from Salary
        const feeMultiplier = calcType === 'probation' ? 0.75 : 0.60;
        const baseRevenue = Math.floor(salary * feeMultiplier);

        // 2. Apply Revenue Share Option
        let shareMultiplier = 1;
        if (revenueShare === 'cv') shareMultiplier = 0.7;
        else if (revenueShare === 'job') shareMultiplier = 0.3;

        const totalRevenue = Math.floor(baseRevenue * shareMultiplier);

        // 3. Calculate Derived Values
        const stageRevenue = Math.floor(totalRevenue / 2);
        const netIncome = Math.floor(totalRevenue * 0.49);

        setRevenueResult({
            totalRevenue,
            stageRevenue,
            netIncome
        });

    } else if (activeTab === 'calculate') {
        // Calculate Fee Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
            handleConvert('0', activeTab); 
            return;
        }
        const multiplier = calcType === 'probation' ? 0.75 : 0.60;
        const fee = Math.floor(salary * multiplier);
        setAmount(fee.toString()); // Sync state
        handleConvert(fee.toString(), activeTab, salary); // Trigger conversion
    } else {
        // Standard Convert Logic
        handleConvert(amount, activeTab);
    }
  };

  const renderHistoryButton = (
    activeTab !== 'revenue' ? (
        <button 
            onClick={() => setShowHistory(true)}
            className={`flex items-center gap-1.5 text-xs font-bold text-primary-600 hover:text-primary-700 bg-primary-50 hover:bg-primary-100 px-2 py-1 rounded-md transition-all`}
        >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
            </svg>
            Lịch sử
        </button>
    ) : null
  );

  // Calculate Stage Fee Values (only available when result is present)
  const stageFeeData = useMemo(() => {
    if (activeTab !== 'calculate' || !result || !amount) return null;

    const totalFeeSource = parseFloat(amount);
    if (isNaN(totalFeeSource)) return null;

    const stageSource = Math.floor(totalFeeSource / 2);
    // Calculate target using the same rate logic
    const stageTarget = Math.ceil(stageSource * result.exchangeRate);

    const formattedSource = formatCurrency(stageSource, fromCurrency.locale, fromCurrency.code);
    const formattedTarget = formatCurrency(stageTarget, toCurrency.locale, toCurrency.code);

    return {
        source: stageSource,
        target: stageTarget,
        formattedSource,
        formattedTarget,
        textSource: getReadFunction(fromCurrency.code, stageSource),
        textTarget: getReadFunction(toCurrency.code, stageTarget)
    };
  }, [activeTab, result, amount, fromCurrency, toCurrency]);

  const vietNamFlagUrl = "https://flagcdn.com/w80/vn.png";

  return (
    <div className={`min-h-screen bg-slate-100 font-sans text-slate-800 selection:bg-primary-200 flex flex-col relative`}>

      <div className="fixed top-3 right-3 sm:top-5 sm:right-5 z-[100] animate-fade-in-up">
        <ThemeSelector currentTheme={theme} onThemeChange={handleThemeChange} />
      </div>

      <div className="flex-1 flex items-center justify-center p-3 sm:p-4 relative z-10">
        <div className="w-full max-w-5xl bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-white/50 relative flex flex-col my-2 mb-8">

          <Header theme={theme} onShowHistory={() => {}} />

          <div className="p-4 sm:p-8 space-y-6 relative flex-1">

            <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                <TabSelector 
                    activeTab={activeTab} 
                    onTabChange={(tab) => { setActiveTab(tab); resetResult(); setAmount(''); setSalaryAmount(''); setRevenueResult(null); }} 
                    theme={theme} 
                />
            </div>

            {activeTab === 'convert' && (
                <div className="animate-fade-in-up" style={{ animationDelay: '150ms' }}>
                <DenominationSelector 
                    currency={fromCurrency} 
                    onSelect={handleDenominationSelect} 
                    currentAmount={amount}
                    theme={theme}
                />
                </div>
            )}

            <div className="flex flex-col md:flex-row items-center md:items-start relative z-20 gap-3 md:gap-4">
              <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'FROM' ? 'z-50' : 'z-20'}`}> 
                  <CurrencyRow
                      key={activeTab} // Force remount and auto-focus when tab changes
                      label={activeTab === 'convert' ? "Nhập số tiền cần đổi" : "Nhập mức lương"}
                      amount={activeTab === 'convert' ? amount : salaryAmount}
                      currency={fromCurrency}
                      onAmountChange={handleAmountChange}
                      onCurrencyChange={handleFromChange}
                      inputPlacement="left"
                      autoFocus={true}
                      isActive={activeDropdown === 'FROM'}
                      onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                      onCloseDropdown={() => setActiveDropdown(null)}
                      theme={theme}
                      headerAction={renderHistoryButton}
                      error={errorMsg}
                      onEnter={onCalculateAndConvert}
                  />

                  {/* Calculation Options (Shared by Calculate and Revenue tabs) */}
                  {(activeTab === 'calculate' || activeTab === 'revenue') && (
                      <div className="mt-3 flex gap-3 animate-fade-in-up">
                          {/* Official Salary (Default) */}
                          <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border cursor-pointer transition-all ${calcType === 'official' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="calcType" value="official" checked={calcType === 'official'} onChange={() => setCalcType('official')} className="hidden" />
                              <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'official' ? 'border-primary-500' : 'border-slate-300'}`}>
                                  {calcType === 'official' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                              </div>
                              <span>Chính thức (60%)</span>
                          </label>

                           {/* Probation Salary */}
                          <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border cursor-pointer transition-all ${calcType === 'probation' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                              <input type="radio" name="calcType" value="probation" checked={calcType === 'probation'} onChange={() => setCalcType('probation')} className="hidden" />
                              <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'probation' ? 'border-primary-500' : 'border-slate-300'}`}>
                                  {calcType === 'probation' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                              </div>
                              <span>Thử việc (75%)</span>
                          </label>
                      </div>
                  )}

                  {/* Revenue Specific Options - STYLED LIKE CURRENCY ROW */}
                  {activeTab === 'revenue' && (
                      <div className="mt-4 animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                        <div className="flex flex-col gap-1.5 w-full">
                             <label className="text-[10px] sm:text-xs font-bold uppercase tracking-wide text-slate-500 ml-1">
                                Tùy chọn tỷ lệ
                             </label>
                             <div className="relative group">
                                <select
                                    value={revenueShare}
                                    onChange={(e) => setRevenueShare(e.target.value as 'all' | 'cv' | 'job')}
                                    className="w-full appearance-none bg-white border border-slate-200 text-slate-800 text-base sm:text-lg font-bold py-4 px-4 pr-12 rounded-2xl leading-tight focus:outline-none focus:border-primary-500 focus:ring-2 focus:ring-primary-100 transition-all cursor-pointer hover:border-primary-300 shadow-sm h-[60px] sm:h-[66px]"
                                >
                                    <option value="all">Tất cả (100%)</option>
                                    <option value="cv">Có CV (70%)</option>
                                    <option value="job">Nắm Job (30%)</option>
                                </select>
                                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-400 group-hover:text-primary-500 transition-colors">
                                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-4 h-4">
                                        <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
                                    </svg>
                                </div>
                            </div>
                        </div>
                      </div>
                  )}
              </div>

              {activeTab === 'convert' && (
                <div className="md:mt-12 z-30 shrink-0">
                    <SwapButton onClick={handleSwapClick} isSwapping={isSwapping} theme={theme} />
                </div>
              )}

              {/* Target Currency Input (Hidden for Revenue) */}
              {activeTab !== 'revenue' && (
                  <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                      <CurrencyRow
                          label={activeTab === 'calculate' ? "Quy đổi phí sang" : "Quy đổi sang"}
                          amount=""
                          currency={toCurrency}
                          onCurrencyChange={handleToChange}
                          inputPlacement="hidden"
                          isActive={activeDropdown === 'TO'}
                          onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                          onCloseDropdown={() => setActiveDropdown(null)}
                          theme={theme}
                      />
                  </div>
              )}
            </div>

            <button
                onClick={onCalculateAndConvert}
                disabled={loadingState === LoadingState.LOADING}
                className={`w-full py-3.5 sm:py-4 rounded-2xl text-white font-bold text-base sm:text-lg shadow-xl transition-all transform mt-4
                ${loadingState === LoadingState.LOADING 
                    ? 'bg-slate-400 cursor-not-allowed opacity-80' 
                    : `bg-gradient-to-r from-primary-600 to-primary-800 hover:-translate-y-1 active:scale-[0.98]`
                }`}
            >
                <span className="flex items-center justify-center gap-2">
                    {loadingState === LoadingState.LOADING ? (
                    <>
                        <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Đang xử lý...
                    </>
                    ) : (
                        activeTab === 'revenue' ? 'Tính doanh thu' :
                        activeTab === 'calculate' ? 'Tính toán & Quy đổi' : 'Chuyển đổi ngay'
                    )}
                </span>
            </button>

             {/* Exchange Rate Badge (Convert/Calculate Only) */}
             {activeTab !== 'revenue' && result && loadingState === LoadingState.SUCCESS && (
                <div className="flex justify-center -mt-2 animate-fade-in-up">
                   <div className="text-xs sm:text-sm font-medium px-4 py-1.5 rounded-full border border-slate-200 bg-white text-slate-500 shadow-sm flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                      {formatExchangeRate(result.exchangeRate, fromCurrency.code, toCurrency.code)}
                   </div>
                </div>
             )}

            {/* --- RESULTS SECTIONS --- */}

            {/* 1. Standard Result (Convert & Calculate Total Fee) */}
            {activeTab !== 'revenue' && result && loadingState === LoadingState.SUCCESS && (
                <>
                   {activeTab === 'calculate' && (
                        <div className="flex items-center gap-2 animate-fade-in-up mt-2">
                             <div className="h-px bg-slate-200 flex-1"></div>
                             <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Phí dịch vụ tổng</span>
                             <div className="h-px bg-slate-200 flex-1"></div>
                        </div>
                   )}
                   <ResultSection 
                      result={result} 
                      fromCurrency={fromCurrency} 
                      toCurrency={toCurrency} 
                      inputAmount={amount}
                      formatCurrency={formatCurrency}
                      theme={theme}
                   />
                </>
            )}

            {/* 2. Calculate Stage Breakdown */}
            {activeTab === 'calculate' && stageFeeData && loadingState === LoadingState.SUCCESS && (
                <div className="animate-fade-in-up pt-2">
                    <div className="flex items-center gap-2 mb-4">
                        <div className="h-px bg-slate-200 flex-1"></div>
                        <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Phí mỗi giai đoạn (50%)</span>
                        <div className="h-px bg-slate-200 flex-1"></div>
                    </div>

                    <div className="grid md:grid-cols-2 gap-4">
                        {/* Stage Fee - Source */}
                        <div className="p-4 rounded-2xl border border-slate-200 bg-slate-50/50 flex flex-col justify-between">
                            <div>
                                <div className="flex items-center gap-2 mb-2 opacity-70">
                                    <img src={fromCurrency.flag} alt={fromCurrency.code} className="w-6 h-4 rounded shadow-sm object-cover" />
                                    <span className="text-xs font-bold uppercase text-slate-500">{fromCurrency.code}</span>
                                </div>
                                <div className="flex items-start justify-between gap-3">
                                    <div className="text-xl sm:text-2xl font-bold text-slate-700">
                                        {stageFeeData.formattedSource}
                                    </div>
                                    <CopyButton text={stageFeeData.formattedSource} />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-slate-200">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold uppercase text-slate-400">Bằng chữ</span>
                                    <CopyButton 
                                        text={stageFeeData.textSource} 
                                        className="bg-white border-slate-200 text-slate-400 hover:text-slate-600 hover:border-slate-300"
                                    />
                                </div>
                                <p className="text-sm italic font-medium text-slate-600 leading-relaxed">{stageFeeData.textSource}</p>
                            </div>
                        </div>

                        {/* Stage Fee - Target */}
                        <div className="p-4 rounded-2xl border border-primary-100 bg-primary-50/30 flex flex-col justify-between">
                            <div>
                                <div className="flex items-center gap-2 mb-2">
                                    <img src={toCurrency.flag} alt={toCurrency.code} className="w-6 h-4 rounded shadow-sm object-cover" />
                                    <span className="text-xs font-bold uppercase text-primary-500">{toCurrency.code}</span>
                                </div>
                                <div className="flex items-start justify-between gap-3">
                                    <div className="text-xl sm:text-2xl font-bold text-primary-700">
                                        {stageFeeData.formattedTarget}
                                    </div>
                                    <CopyButton 
                                        text={stageFeeData.formattedTarget} 
                                        className="bg-white border-primary-200 text-primary-500 hover:text-primary-700 hover:border-primary-300"
                                    />
                                </div>
                            </div>
                            <div className="mt-3 pt-3 border-t border-primary-200/50">
                                <div className="flex items-center justify-between mb-1">
                                    <span className="text-[10px] font-bold uppercase text-primary-400">Bằng chữ</span>
                                    <CopyButton 
                                        text={stageFeeData.textTarget} 
                                        className="bg-white border-primary-200 text-primary-500 hover:text-primary-700 hover:border-primary-300"
                                    />
                                </div>
                                <p className="text-sm italic font-medium text-primary-800 leading-relaxed">{stageFeeData.textTarget}</p>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* 3. REVENUE RESULT DISPLAY */}
            {activeTab === 'revenue' && revenueResult && (
                <div className="animate-fade-in-up space-y-4 pt-2">
                     <div className="flex items-center gap-2 mt-2 mb-4">
                        <div className="h-px bg-slate-200 flex-1"></div>
                        <span className="text-sm font-extrabold text-slate-400 uppercase tracking-widest">Kết quả tính doanh thu</span>
                        <div className="h-px bg-slate-200 flex-1"></div>
                    </div>

                    {/* Total & Stage Revenue - MERGED CARD */}
                    <div className="p-5 rounded-3xl border border-slate-200 bg-white shadow-sm flex flex-col gap-6">

                        {/* Total Revenue Item */}
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-slate-50 rounded-lg border border-slate-100">
                                     <img src={vietNamFlagUrl} alt="VND" className="w-6 h-4 rounded shadow-sm object-cover" />
                                </div>
                                <div>
                                    <span className="text-xs font-bold uppercase text-slate-400 block mb-0.5">Doanh thu tổng</span>
                                    <span className="text-[10px] font-semibold text-primary-600 bg-primary-50 px-2 py-0.5 rounded-full">
                                        {revenueShare === 'all' ? '100%' : revenueShare === 'cv' ? '70%' : '30%'}
                                    </span>
                                </div>
                            </div>
                            <div className="flex flex-col items-end gap-1">
                                 <span className="text-xl sm:text-2xl font-bold text-slate-800">
                                    {formatCurrency(revenueResult.totalRevenue, 'vi-VN', 'VND')}
                                </span>
                                <CopyButton 
                                    text={formatCurrency(revenueResult.totalRevenue, 'vi-VN', 'VND')} 
                                    className="bg-slate-50 border-slate-100 text-slate-400 hover:text-slate-600 w-7 h-7"
                                    iconSize="w-3.5 h-3.5"
                                />
                            </div>
                        </div>

                        {/* Separator */}
                        <div className="w-full h-px bg-slate-100"></div>

                        {/* Stage Revenue Item */}
                        <div className="flex items-center justify-between">
                             <div className="flex items-center gap-3">
                                <div className="p-2 bg-slate-50 rounded-lg border border-slate-100">
                                     <img src={vietNamFlagUrl} alt="VND" className="w-6 h-4 rounded shadow-sm object-cover" />
                                </div>
                                <div>
                                    <span className="text-xs font-bold uppercase text-slate-400 block mb-0.5">Doanh thu mỗi giai đoạn</span>
                                    <span className="text-[10px] font-semibold text-primary-600 bg-primary-50 px-2 py-0.5 rounded-full">
                                        50%
                                    </span>
                                </div>
                            </div>
                             <div className="flex flex-col items-end gap-1">
                                 <span className="text-xl sm:text-2xl font-bold text-slate-800">
                                    {formatCurrency(revenueResult.stageRevenue, 'vi-VN', 'VND')}
                                </span>
                                <CopyButton 
                                    text={formatCurrency(revenueResult.stageRevenue, 'vi-VN', 'VND')} 
                                    className="bg-slate-50 border-slate-100 text-slate-400 hover:text-slate-600 w-7 h-7"
                                    iconSize="w-3.5 h-3.5"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Net Income (Highlighted) - REDESIGNED */}
                    <div className="p-6 rounded-3xl bg-gradient-to-br from-primary-600 to-primary-800 shadow-lg shadow-primary-200 relative overflow-hidden group transform hover:scale-[1.01] transition-transform duration-300">
                        {/* Background Decoration */}
                        <div className="absolute top-0 right-0 p-4 opacity-10">
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-24 h-24 text-white">
                                <path d="M12 7.5a2.25 2.25 0 1 0 0 4.5 2.25 2.25 0 0 0 0-4.5Z" />
                                <path fillRule="evenodd" d="M1.5 4.875C1.5 3.839 2.34 3 3.375 3h17.25c1.035 0 1.875.84 1.875 1.875v9.75c0 1.036-.84 1.875-1.875 1.875H3.375A1.875 1.875 0 0 1 1.5 14.625v-9.75ZM8.25 9.75a3.75 3.75 0 1 1 7.5 0 3.75 3.75 0 0 1-7.5 0ZM18.75 9a.75.75 0 0 0-.75.75v.008c0 .414.336.75.75.75h.008a.75.75 0 0 0 .75-.75V9.75a.75.75 0 0 0-.75-.75h-.008ZM4.5 9.75A.75.75 0 0 1 5.25 9h.008a.75.75 0 0 1 .75.75v.008a.75.75 0 0 1-.75.75H5.25a.75.75 0 0 1-.75-.75V9.75Z" clipRule="evenodd" />
                                <path d="M2.25 18a.75.75 0 0 0 0 1.5c5.4 0 10.63.722 15.6 2.075 1.19.324 2.4-.558 2.4-1.82V18.75a.75.75 0 0 0-.75-.75H2.25Z" />
                            </svg>
                        </div>

                        <div className="relative z-10 flex flex-col items-center text-center">
                            <div className="flex items-center gap-2 mb-2 bg-white/10 px-3 py-1 rounded-full backdrop-blur-sm">
                                <img src={vietNamFlagUrl} alt="VND" className="w-5 h-3.5 rounded shadow-sm object-cover" />
                                <span className="text-xs font-bold uppercase text-white/90 tracking-widest">Thu nhập thực nhận (49%)</span>
                            </div>

                            <div className="my-2">
                                <span className="text-3xl sm:text-4xl md:text-5xl font-extrabold text-white tracking-tight">
                                    {formatCurrency(revenueResult.netIncome, 'vi-VN', 'VND')}
                                </span>
                            </div>

                             <CopyButton 
                                text={formatCurrency(revenueResult.netIncome, 'vi-VN', 'VND')} 
                                className="bg-white/20 border-white/10 text-white hover:bg-white hover:text-primary-700 w-10 h-10 mt-2"
                                iconSize="w-5 h-5"
                            />
                        </div>
                    </div>
                </div>
            )}
          </div>
        </div>
      </div>

      {/* Simple Dark Footer */}
      <footer className="w-full bg-slate-900 text-slate-400 py-6 mt-auto">
        <div className="container mx-auto px-4 text-center">
            <p className="font-semibold text-slate-300 mb-1 tracking-wide text-sm">Powered by ZiQi</p>
            <p className="text-xs opacity-60">Lasted update: {new Date().toLocaleDateString('vi-VN')} </p>
        </div>
      </footer>

      {showHistory && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
             <div className="absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity animate-fade-in-up" onClick={() => setShowHistory(false)} style={{animationDuration: '0.2s'}} />
             <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl relative z-10 overflow-hidden animate-fade-in-up flex flex-col max-h-[85vh]">
                <div className="p-0 flex-1 overflow-hidden flex flex-col">
                   <HistorySection 
                        history={filteredHistory} 
                        onSelect={handleHistorySelect} 
                        onClear={clearHistory}
                        onDeleteItems={deleteHistoryItems}
                        formatCurrency={formatCurrency}
                        onClose={() => setShowHistory(false)}
                   />
                </div>
             </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { DenominationSelector } from './components/DenominationSelector';
import { HistorySection } from './components/HistorySection';
import { ThemeSelector } from './components/ThemeSelector';
import { TabSelector } from './components/TabSelector';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState, ThemeColor, Currency, ConversionHistoryItem } from './types';
import { THEME_COLORS } from './constants';
import { generatePalette } from './utils/themeUtils';
import { getReadFunction } from './utils/currencyTextFormatter';
import { CopyButton } from './components/CopyButton';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [theme, setTheme] = useState<ThemeColor>('blue');
  const [showHistory, setShowHistory] = useState(false);

  // States for Calculation & Revenue Mode
  const [activeTab, setActiveTab] = useState<'convert' | 'calculate' | 'revenue'>('convert');
  const [salaryAmount, setSalaryAmount] = useState<string>('');
  const [calcType, setCalcType] = useState<'probation' | 'official'>('official');

  // New State for Revenue Options
  const [revenueShare, setRevenueShare] = useState<'all' | 'cv' | 'job'>('all');
  const [isRevenueDropdownOpen, setIsRevenueDropdownOpen] = useState(false);
  const revenueDropdownRef = useRef<HTMLDivElement>(null);

  const [revenueResult, setRevenueResult] = useState<{
      totalRevenue: number;
      stageRevenue: number;
      netIncome: number;
  } | null>(null);

  const revenueOptions = [
    { value: 'all', label: 'Tất cả (100%)' },
    { value: 'cv', label: 'Có CV (70%)' },
    { value: 'job', label: 'Nắm Job (30%)' }
  ];

  // Filter history based on active tab (Revenue currently doesn't share history with others to avoid type complexity)
  const filteredHistory = useMemo(() => {
    return history.filter(item => item.type === activeTab);
  }, [history, activeTab]);

  // Apply theme palette to CSS variables
  useEffect(() => {
    const applyTheme = (colorIdOrHex: string) => {
      let hex = colorIdOrHex;
      const preset = THEME_COLORS.find(t => t.id === colorIdOrHex);
      if (preset) hex = preset.hex;

      const palette = generatePalette(hex);
      const root = document.documentElement;
      Object.entries(palette).forEach(([shade, value]) => {
        root.style.setProperty(`--color-primary-${shade}`, value);
      });
    };

    const savedTheme = localStorage.getItem('app_theme');
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      applyTheme('blue');
    }
  }, []);

  // Handle click outside for Revenue Dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (revenueDropdownRef.current && !revenueDropdownRef.current.contains(event.target as Node)) {
            setIsRevenueDropdownOpen(false);
        }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleThemeChange = (newTheme: ThemeColor) => {
    setTheme(newTheme);
    localStorage.setItem('app_theme', newTheme);

    let hex = newTheme;
    const preset = THEME_COLORS.find(t => t.id === newTheme);
    if (preset) hex = preset.hex;

    const palette = generatePalette(hex);
    Object.entries(palette).forEach(([shade, value]) => {
      document.documentElement.style.setProperty(`--color-primary-${shade}`, value);
    });
  };

  const handleAmountChange = (val: string) => {
    if (activeTab === 'calculate' || activeTab === 'revenue') {
        setSalaryAmount(val);
    } else {
        setAmount(val);
    }
    resetResult();
    setRevenueResult(null); // Reset revenue result on input change
  };

  const handleFromChange = (currency: Currency) => {
    setFromCurrency(currency);
    resetResult();
  };

  const handleToChange = (currency: Currency) => {
    setToCurrency(currency);
    resetResult();
  };

  const handleDenominationSelect = (newAmount: string) => {
    handleAmountChange(newAmount);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        if (isNaN(val)) return `0 ${currencyCode}`;
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  const handleHistorySelect = (item: ConversionHistoryItem) => {
    // Since we filter history, we know the item belongs to the active tab
    selectHistoryItem(item);

    if (item.type === 'calculate' && item.originalSalary) {
        setSalaryAmount(item.originalSalary.toString());
        // Trigger conversion with the fee (inputAmount) and pass salary
        handleConvert(item.inputAmount.toString(), activeTab, item.originalSalary);
    } else {
        handleConvert(item.inputAmount.toString(), activeTab);
    }

    setShowHistory(false);
  };

  const handleSwapClick = () => {
    handleSwap(activeTab as 'convert' | 'calculate');
  };

  // Main Calculation Logic
  const onCalculateAndConvert = () => {
    if (activeTab === 'revenue') {
        // Revenue Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
             setRevenueResult(null);
             return;
        }

        // 1. Calculate Base Fee (Revenue) from Salary
        const feeMultiplier = calcType === 'probation' ? 0.75 : 0.60;
        const baseRevenue = Math.floor(salary * feeMultiplier);

        // 2. Apply Revenue Share Option
        let shareMultiplier = 1;
        if (revenueShare === 'cv') shareMultiplier = 0.7;
        else if (revenueShare === 'job') shareMultiplier = 0.3;

        const totalRevenue = Math.floor(baseRevenue * shareMultiplier);

        // 3. Calculate Derived Values
        const stageRevenue = Math.floor(totalRevenue / 2);
        const netIncome = Math.floor(totalRevenue * 0.49);

        setRevenueResult({
            totalRevenue,
            stageRevenue,
            netIncome
        });

    } else if (activeTab === 'calculate') {
        // Calculate Fee Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
            handleConvert('0', activeTab); 
            return;
        }
        const multiplier = calcType === 'probation' ? 0.75 : 0.60;
        const fee = Math.floor(salary * multiplier);
        setAmount(fee.toString()); // Sync state
        handleConvert(fee.toString(), activeTab, salary); // Trigger conversion
    } else {
        // Standard Convert Logic
        handleConvert(amount, activeTab);
    }
  };

  const renderHistoryButton = (
    activeTab !== 'revenue' ? (
        <button 
            onClick={() => setShowHistory(true)}
            className={`flex items-center gap-1.5 text-xs font-bold text-primary-600 hover:text-primary-700 bg-primary-50 hover:bg-primary-100 px-2 py-1 rounded-md transition-all`}
        >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
            </svg>
            Lịch sử
        </button>
    ) : null
  );

  // Calculate Stage Fee Values (only available when result is present)
  const stageFeeData = useMemo(() => {
    if (activeTab !== 'calculate' || !result || !amount) return null;

    const totalFeeSource = parseFloat(amount);
    if (isNaN(totalFeeSource)) return null;

    const stageSource = Math.floor(totalFeeSource / 2);
    // Calculate target using the same rate logic
    const stageTarget = Math.ceil(stageSource * result.exchangeRate);

    const formattedSource = formatCurrency(stageSource, fromCurrency.locale, fromCurrency.code);
    const formattedTarget = formatCurrency(stageTarget, toCurrency.locale, toCurrency.code);

    return {
        source: stageSource,
        target: stageTarget,
        formattedSource,
        formattedTarget,
        textSource: getReadFunction(fromCurrency.code, stageSource),
        textTarget: getReadFunction(toCurrency.code, stageTarget)
    };
  }, [activeTab, result, amount, fromCurrency, toCurrency]);

  const vietNamFlagUrl = "https://flagcdn.com/w80/vn.png";

  return (
    <div className={`min-h-screen bg-slate-100 font-sans text-slate-800 selection:bg-primary-200 flex flex-col relative`}>

      <div className="fixed top-3 right-3 sm:top-5 sm:right-5 z-[100] animate-fade-in-up">
        <ThemeSelector currentTheme={theme} onThemeChange={handleThemeChange} />
      </div>

      <div className="flex-1 flex items-center justify-center p-3 sm:p-4 relative z-10">
        <div className="w-full max-w-5xl bg-white rounded-3xl shadow-xl shadow-slate-200/60 border border-white/50 relative flex flex-col my-2 mb-8">

          <Header theme={theme} onShowHistory={() => {}} />

          <div className="p-4 sm:p-8 space-y-6 relative flex-1">

            <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                <TabSelector 
                    activeTab={activeTab} 
                    onTabChange={(tab) => { setActiveTab(tab); resetResult(); setAmount(''); setSalaryAmount(''); setRevenueResult(null); }} 
                    theme={theme} 
                />
            </div>

            {activeTab === 'convert' && (
                <div className="animate-fade-in-up" style={{ animationDelay: '150ms' }}>
                <DenominationSelector 
                    currency={fromCurrency} 
                    onSelect={handleDenominationSelect} 
                    currentAmount={amount}
                    theme={theme}
                />
                </div>
            )}

            <div className="flex flex-col md:flex-row items-center md:items-start relative z-20 gap-3 md:gap-4">
              <div className={`w-full md:flex-1 transition-all ${activeDropdown === 'FROM' ? 'z-50' : 'z-20'}`}> 
                  <CurrencyRow
                      key={activeTab} // Force remount and auto-focus when tab changes
                      label={activeTab === 'convert' ? "Nhập số tiền cần đổi" : "Nhập mức lương"}
                      amount={activeTab === 'convert' ? amount : salaryAmount}
                      currency={fromCurrency}
                      onAmountChange={handleAmountChange}
                      onCurrencyChange={handleFromChange}
                      inputPlacement="left"
                      autoFocus={true}
                      isActive={activeDropdown === 'FROM'}
                      onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                      onCloseDropdown={() => setActiveDropdown(null)}
                      theme={theme}
                      headerAction={renderHistoryButton}
                      error={errorMsg}
                      onEnter={onCalculateAndConvert}
                  />

                  {/* Calculation Options (Shared by Calculate and Revenue tabs) */}
                  {(activeTab === 'calculate' || activeTab === 'revenue') && (
                      <div className="mt-3 flex gap-3 animate-fade-in-up">
                          {/* Official Salary (Default) */}
                          <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border cursor-pointer transition-all ${calcType === 'official' ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
