export interface Currency {
  code: string;
  name: string;
  flag: string; // Emoji flag or image url
  locale: string; // e.g., 'vi-VN', 'en-US'
}

export interface ConversionResult {
  convertedAmount: number;
  exchangeRate: number;
  textSource: string; // Text representation in source language
  textTarget: string; // Text representation in target language
}

export interface ConversionHistoryItem {
  id: string;
  timestamp: number;
  inputAmount: number; // This is Fee/Salary depending on type
  fromCurrency: Currency;
  toCurrency: Currency;
  convertedAmount: number; // This is Result/Net Income
  type: 'convert' | 'calculate' | 'revenue'; 
  originalSalary?: number; // Only for 'calculate' type
  revenueDetails?: {
      shareType: 'all' | 'cv' | 'job';
      stageRevenue: number;
      totalRevenue: number;
  };
}

export enum LoadingState {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export type ThemeColor = string;

export const hexToRgb = (hex: string) => {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16),
    g: parseInt(result[2], 16),
    b: parseInt(result[3], 16)
  } : { r: 0, g: 0, b: 0 };
};

// Mix color with white (tint) or black (shade)
const mix = (color: {r: number, g: number, b: number}, mixColor: {r: number, g: number, b: number}, weight: number) => {
  return {
    r: Math.round(color.r * (1 - weight) + mixColor.r * weight),
    g: Math.round(color.g * (1 - weight) + mixColor.g * weight),
    b: Math.round(color.b * (1 - weight) + mixColor.b * weight)
  };
};

const rgbToHex = (rgb: {r: number, g: number, b: number}) => {
  return "#" + ((1 << 24) + (rgb.r << 16) + (rgb.g << 8) + rgb.b).toString(16).slice(1);
};

export const generatePalette = (baseHex: string) => {
  const rgb = hexToRgb(baseHex);
  const white = { r: 255, g: 255, b: 255 };
  const black = { r: 0, g: 0, b: 0 };

  return {
    50: rgbToHex(mix(rgb, white, 0.95)),
    100: rgbToHex(mix(rgb, white, 0.9)),
    200: rgbToHex(mix(rgb, white, 0.75)),
    300: rgbToHex(mix(rgb, white, 0.6)),
    400: rgbToHex(mix(rgb, white, 0.3)),
    500: baseHex, // Base color is usually 500 or 600. Let's assume input is the primary brand color (approx 600)
    600: baseHex, // We'll use the input as 600 for strong contrast
    700: rgbToHex(mix(rgb, black, 0.1)),
    800: rgbToHex(mix(rgb, black, 0.2)),
    900: rgbToHex(mix(rgb, black, 0.3)),
  };
};

export const extractDominantColor = (imageSrc: string): Promise<string> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.src = imageSrc;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                resolve('#2563eb'); // Default fallback
                return;
            }

            // Resize to 1x1 to get average color
            canvas.width = 1;
            canvas.height = 1;
            ctx.drawImage(img, 0, 0, 1, 1);

            const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data;
            resolve(rgbToHex({ r, g, b }));
        };
        img.onerror = () => reject('#2563eb');
    });
};

import { useState, useCallback, useEffect } from 'react';
import { Currency, ConversionResult, LoadingState, ConversionHistoryItem } from '../types';
import { DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from '../constants';
import { convertCurrencyApi } from '../services/geminiService';

export const useCurrencyConverter = () => {
  const [amount, setAmount] = useState<string>('100000');
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');
  const [isSwapping, setIsSwapping] = useState(false);
  const [history, setHistory] = useState<ConversionHistoryItem[]>([]);

  // Load history from local storage on mount
  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('conversion_history');
      if (savedHistory) {
        const parsed = JSON.parse(savedHistory);
        // Migration support for old data without 'type'
        const migrated = parsed.map((item: any) => ({
            ...item,
            type: item.type || 'convert'
        }));
        setHistory(migrated);
      }
    } catch (e) {
      console.error("Failed to load history", e);
    }
  }, []);

  const saveHistory = (newHistory: ConversionHistoryItem[]) => {
    setHistory(newHistory);
    localStorage.setItem('conversion_history', JSON.stringify(newHistory));
  };

  const addToHistory = (
      currentAmount: number, 
      source: Currency, 
      target: Currency, 
      converted: number, 
      type: 'convert' | 'calculate' | 'revenue', 
      originalSalary?: number,
      revenueDetails?: { shareType: 'all' | 'cv' | 'job', stageRevenue: number, totalRevenue: number }
  ) => {
    const newItem: ConversionHistoryItem = {
      id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      inputAmount: currentAmount,
      fromCurrency: source,
      toCurrency: target,
      convertedAmount: converted,
      type: type,
      originalSalary: originalSalary,
      revenueDetails: revenueDetails
    };

    // Check if an identical conversion exists
    const existingIndex = history.findIndex(item => 
        item.inputAmount === newItem.inputAmount && 
        item.fromCurrency.code === newItem.fromCurrency.code && 
        item.toCurrency.code === newItem.toCurrency.code &&
        item.type === newItem.type &&
        item.originalSalary === newItem.originalSalary &&
        item.revenueDetails?.shareType === newItem.revenueDetails?.shareType
    );

    let updatedHistory = [...history];

    if (existingIndex > -1) {
        // Remove the existing item so the new one can go to the top
        updatedHistory.splice(existingIndex, 1);
    }

    // Add new item to the beginning
    updatedHistory.unshift(newItem);

    // Limit to 50 items total
    updatedHistory = updatedHistory.slice(0, 50); 

    saveHistory(updatedHistory);
  };

  const clearHistory = () => {
    saveHistory([]);
  };

  const deleteHistoryItems = (ids: string[]) => {
    const updatedHistory = history.filter(item => !ids.includes(item.id));
    saveHistory(updatedHistory);
  };

  const selectHistoryItem = (item: ConversionHistoryItem) => {
    setAmount(item.inputAmount.toString());
    setFromCurrency(item.fromCurrency);
    setToCurrency(item.toCurrency);
  };

  const resetResult = useCallback(() => {
    setResult(null);
    setErrorMsg('');
    setLoadingState(LoadingState.IDLE);
  }, []);

  const executeConversion = async (currentAmount: number, source: Currency, target: Currency, type: 'convert' | 'calculate', originalSalary?: number) => {
    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');

    try {
      const data = await convertCurrencyApi(currentAmount, source.code, target.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);

      // Add to history on success
      addToHistory(currentAmount, source, target, data.convertedAmount, type, originalSalary);
    } catch (err) {
      setErrorMsg("Có lỗi xảy ra khi lấy tỷ giá. Vui lòng thử lại.");
      setLoadingState(LoadingState.ERROR);
      setResult(null); 
    }
  };

  const handleConvert = useCallback((amountOverride?: string, type: 'convert' | 'calculate' = 'convert', originalSalary?: number) => {
    const valueToCheck = amountOverride !== undefined ? amountOverride : amount;
    const numAmount = parseFloat(valueToCheck);

    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }
    executeConversion(numAmount, fromCurrency, toCurrency, type, originalSalary);
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = (currentType: 'convert' | 'calculate' = 'convert') => {
    setIsSwapping(true);
    setTimeout(() => setIsSwapping(false), 500); 

    const newFrom = toCurrency;
    const newTo = fromCurrency;

    setFromCurrency(newFrom);
    setToCurrency(newTo);

    if (result) {
        const numAmount = parseFloat(amount);
        if (!isNaN(numAmount) && numAmount > 0) {
            executeConversion(numAmount, newFrom, newTo, currentType);
        } else {
            setResult(null);
        }
    } else {
        setResult(null); 
    }
  };

  return {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult, addToHistory
  };
};

import React, { useState } from 'react';
import { ConversionHistoryItem } from '../types';

interface HistorySectionProps {
  history: ConversionHistoryItem[];
  onSelect: (item: ConversionHistoryItem) => void;
  onClear: () => void;
  onDeleteItems: (ids: string[]) => void;
  formatCurrency: (val: number, locale: string, currencyCode: string) => string;
  onClose?: () => void;
}

export const HistorySection: React.FC<HistorySectionProps> = ({ history, onSelect, onClear, onDeleteItems, formatCurrency, onClose }) => {
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [confirmDelete, setConfirmDelete] = useState<{ isOpen: boolean, idsToDelete: string[], isAll: boolean }>({ 
    isOpen: false, idsToDelete: [], isAll: false 
  });

  const toggleSelectionMode = () => {
    setIsSelectionMode(!isSelectionMode);
    setSelectedIds(new Set());
  };

  const handleCheckboxChange = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const handleDeleteSelected = () => {
    if (selectedIds.size === 0) return;
    setConfirmDelete({
        isOpen: true,
        idsToDelete: Array.from(selectedIds),
        isAll: false
    });
  };

  const handleDeleteSingle = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setConfirmDelete({
        isOpen: true,
        idsToDelete: [id],
        isAll: false
    });
  };

  const handleClearAll = () => {
    setConfirmDelete({
        isOpen: true,
        idsToDelete: [],
        isAll: true
    });
  };

  const performDelete = () => {
    if (confirmDelete.isAll) {
        // Only clear visible items (filtered by filteredHistory from parent)
        const ids = history.map(h => h.id);
        onDeleteItems(ids);
        setIsSelectionMode(false);
    } else {
        onDeleteItems(confirmDelete.idsToDelete);
        const newSelected = new Set(selectedIds);
        confirmDelete.idsToDelete.forEach(id => newSelected.delete(id));
        setSelectedIds(newSelected);

        if (isSelectionMode && newSelected.size === 0 && history.length === confirmDelete.idsToDelete.length) {
             setIsSelectionMode(false);
        }
    }
    setConfirmDelete({ isOpen: false, idsToDelete: [], isAll: false });
  };

  const formatDate = (timestamp: number) => {
      return new Date(timestamp).toLocaleString('vi-VN', { hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit' });
  };

  const getShareLabel = (shareType?: 'all' | 'cv' | 'job') => {
      if (shareType === 'cv') return 'Có CV (70%)';
      if (shareType === 'job') return 'Nắm Job (30%)';
      return 'Tất cả (100%)';
  };

  return (
    <div className="w-full flex flex-col h-full relative bg-slate-50">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-slate-200 bg-white sticky top-0 z-20 shadow-sm">
        {isSelectionMode ? (
            <div className="flex items-center gap-3">
                <button onClick={toggleSelectionMode} className="text-slate-600 font-bold hover:text-slate-900 bg-slate-100 px-3 py-1 rounded-lg">Hủy</button>
                <span className="text-sm font-medium text-slate-500">Đã chọn <span className="text-slate-900 font-bold">{selectedIds.size}</span></span>
            </div>
        ) : (
             <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                Lịch sử
                <span className="text-xs font-normal text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full">{history.length}</span>
            </h3>
        )}

        <div className="flex items-center gap-2">
            {!isSelectionMode && history.length > 0 && (
                <button 
                    onClick={toggleSelectionMode}
                    className="text-primary-600 bg-primary-50 hover:bg-primary-100 p-2 sm:px-3 sm:py-2 rounded-lg transition-colors border border-primary-100 flex items-center gap-1.5"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75 11.25 15 15 9.75M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
                    </svg>
                    <span className="hidden sm:inline text-xs font-bold">Chọn nhiều</span>
                </button>
            )}
            {!isSelectionMode && history.length > 0 && (
                <button 
                onClick={handleClearAll} 
                className="text-xs text-red-500 hover:text-red-600 font-bold hover:bg-red-50 px-3 py-2 rounded-lg transition-colors border border-transparent hover:border-red-100"
                >
                    Xóa hết
                </button>
            )}

            <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors ml-1">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18 18 6M6 6l12 12" />
