      totalRevenue: number;
  };
}

export enum LoadingState {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export type ThemeColor = string;

// --- NOTES SYSTEM TYPES ---

export type NoteStatus = 'incomplete' | 'completed' | 'attention' | 'skipped';

export interface NoteTag {
  id: string;
  name: string;
  color: string; // hex string
}

export interface Note {
  id: string;
  content: string;
  timestamp: number;
  status: NoteStatus;
  tagId: string | null; // One tag per note for simplicity in filtering
}

import { useState, useEffect } from 'react';
import { Note, NoteTag, NoteStatus } from '../types';

const DEFAULT_TAGS: NoteTag[] = [
  { id: 'personal', name: 'Cá nhân', color: '#3b82f6' }, // Blue
  { id: 'work', name: 'Công việc', color: '#10b981' },   // Emerald
  { id: 'idea', name: 'Ý tưởng', color: '#f59e0b' },     // Amber
];

export const useNotes = () => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [tags, setTags] = useState<NoteTag[]>(DEFAULT_TAGS);

  // Load data
  useEffect(() => {
    try {
      const savedNotes = localStorage.getItem('app_notes');
      const savedTags = localStorage.getItem('app_note_tags');

      if (savedNotes) setNotes(JSON.parse(savedNotes));
      if (savedTags) setTags(JSON.parse(savedTags));
      else setTags(DEFAULT_TAGS);
    } catch (e) {
      console.error("Failed to load notes", e);
    }
  }, []);

  // Save data helpers
  const saveNotes = (newNotes: Note[]) => {
    setNotes(newNotes);
    localStorage.setItem('app_notes', JSON.stringify(newNotes));
  };

  const saveTags = (newTags: NoteTag[]) => {
    setTags(newTags);
    localStorage.setItem('app_note_tags', JSON.stringify(newTags));
  };

  // Note Actions
  const addNote = (content: string, tagId: string | null) => {
    const newNote: Note = {
      id: Date.now().toString(),
      content,
      timestamp: Date.now(),
      status: 'incomplete',
      tagId
    };
    saveNotes([newNote, ...notes]);
  };

  const updateNoteStatus = (id: string, status: NoteStatus) => {
    const updated = notes.map(n => n.id === id ? { ...n, status } : n);
    saveNotes(updated);
  };

  const deleteNote = (id: string) => {
    saveNotes(notes.filter(n => n.id !== id));
  };

  // Tag Actions
  const addTag = (name: string, color: string) => {
    const newTag: NoteTag = {
      id: Date.now().toString(),
      name,
      color
    };
    saveTags([...tags, newTag]);
  };

  const deleteTag = (id: string) => {
    saveTags(tags.filter(t => t.id !== id));
    // Optional: Remove tag from notes that had it? Or keep them untagged?
    // For now, let's keep them (they will just have an invalid tagId which we handle in UI)
  };

  return {
    notes,
    tags,
    addNote,
    updateNoteStatus,
    deleteNote,
    addTag,
    deleteTag
  };
};

