               <path strokeLinecap="round" strokeLinejoin="round" d="m16.862 4.487 1.687-1.688a1.875 1.875 0 1 1 2.652 2.652L10.582 16.07a4.5 4.5 0 0 1-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 0 1 1.13-1.897l8.932-8.931Zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0 1 15.75 21H5.25A2.25 2.25 0 0 1 3 18.75V8.25A2.25 2.25 0 0 1 5.25 6H10" />
            </svg>
          )}
        </button>
      </div>

      {/* Popup Panel 
          Fix mobile layout: Use flex col, max-height with dvh units, proper spacing.
      */}
      <div 
        className={`fixed bottom-[90px] left-4 sm:left-6 z-[60] w-[calc(100vw-32px)] sm:w-[380px] bg-white/95 backdrop-blur-xl border border-white/60 shadow-2xl rounded-3xl overflow-hidden flex flex-col transition-all duration-300 origin-bottom-left
          ${isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-10 pointer-events-none'}
        `}
        style={{
            maxHeight: 'min(500px, 80dvh)'
        }}
      >
        {renderHeader()}

        {/* --- VIEW: ADD TAG --- */}
        {viewMode === 'add-tag' && (
             <div className="p-5 flex flex-col gap-4 animate-fade-in-up flex-1 overflow-y-auto">
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Tên thẻ mới</label>
                    <input 
                        type="text" 
                        placeholder="Ví dụ: Mua sắm, Deadline..." 
                        className="w-full text-sm px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:border-indigo-500 bg-slate-50 focus:bg-white transition-all"
                        value={newTagName}
                        onChange={(e) => setNewTagName(e.target.value)}
                        autoFocus
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Chọn màu nhận diện</label>
                    <div className="flex items-center gap-3">
                        <input 
                            type="color" 
                            className="w-12 h-12 rounded-xl cursor-pointer border-2 border-white shadow-sm"
                            value={newTagColor}
                            onChange={(e) => setNewTagColor(e.target.value)}
                        />
                        <span className="text-xs font-mono bg-slate-100 px-2 py-1 rounded text-slate-600">{newTagColor}</span>
                    </div>
                </div>
                <div className="mt-auto pt-4 flex gap-3 pb-2">
                     <button 
                        onClick={() => setViewMode('list')}
                        className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-600 text-sm font-bold rounded-xl transition-colors"
                    >
                        Hủy
                    </button>
                    <button 
                        onClick={handleCreateTag}
                        className="flex-1 py-3 bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold rounded-xl transition-colors shadow-lg shadow-indigo-200"
                    >
                        Tạo thẻ
                    </button>
                </div>
             </div>
        )}

        {/* --- VIEW: ADD NOTE --- */}
        {viewMode === 'add-note' && (
            <div className="p-5 flex flex-col gap-4 flex-1 h-full animate-fade-in-up overflow-hidden">
                <div className="flex-1 flex flex-col min-h-0">
                     <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5 shrink-0">Nội dung ghi chú</label>
                     <textarea 
                        className="w-full flex-1 bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm focus:outline-none focus:border-indigo-500 focus:bg-white transition-all resize-none min-h-[120px]"
                        placeholder="Nhập nội dung ghi chú của bạn..."
                        value={newNoteContent}
                        onChange={(e) => setNewNoteContent(e.target.value)}
                        autoFocus
                    />
                </div>

                {/* Custom Tag Dropdown */}
                <div className="relative shrink-0" ref={tagDropdownRef}>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Phân loại thẻ</label>
                    <button
                        onClick={() => setIsTagDropdownOpen(!isTagDropdownOpen)}
                        className={`w-full flex items-center justify-between px-4 py-3 rounded-xl border bg-white transition-all ${isTagDropdownOpen ? 'border-indigo-500 ring-2 ring-indigo-50' : 'border-slate-200 hover:border-slate-300'}`}
                    >
                        {selectedTagForNewNote ? (
                             <div className="flex items-center gap-2">
                                <span className="w-3 h-3 rounded-full" style={{ backgroundColor: getTag(selectedTagForNewNote)?.color }}></span>
                                <span className="text-sm font-semibold text-slate-700">{getTag(selectedTagForNewNote)?.name}</span>
                             </div>
                        ) : (
                            <span className="text-sm text-slate-400">Chọn thẻ...</span>
                        )}
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4 text-slate-400">
                            <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
                        </svg>
                    </button>

                    {isTagDropdownOpen && (
                        <div className="absolute bottom-full left-0 w-full mb-2 bg-white rounded-xl shadow-xl border border-slate-100 overflow-hidden z-20 animate-fade-in-up">
                            <div className="max-h-40 overflow-y-auto custom-scrollbar p-1">
                                <button
                                    onClick={() => { setSelectedTagForNewNote(''); setIsTagDropdownOpen(false); }}
                                    className="w-full text-left px-3 py-2 text-sm text-slate-600 hover:bg-slate-50 rounded-lg font-medium"
                                >
                                    Mặc định (Không thẻ)
                                </button>
                                {tags.map(tag => (
                                    <button
                                        key={tag.id}
                                        onClick={() => { setSelectedTagForNewNote(tag.id); setIsTagDropdownOpen(false); }}
                                        className="w-full flex items-center gap-2 px-3 py-2 hover:bg-slate-50 rounded-lg transition-colors"
                                    >
                                        <span className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: tag.color }}></span>
                                        <span className="text-sm font-semibold text-slate-700">{tag.name}</span>
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                <div className="flex gap-3 mt-auto shrink-0 pb-1">
                    <button 
                        onClick={() => setViewMode('list')}
                        className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-600 text-sm font-bold rounded-xl transition-colors"
                    >
                        Hủy
                    </button>
                    <button 
                        onClick={handleAddNote}
                        disabled={!newNoteContent.trim()}
                        className={`flex-1 py-3 text-white text-sm font-bold rounded-xl transition-colors shadow-lg
                            ${newNoteContent.trim() ? 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200' : 'bg-slate-300 cursor-not-allowed'}
                        `}
                    >
                        Lưu ghi chú
                    </button>
                </div>
            </div>
        )}

        {/* --- VIEW: LIST --- */}
        {viewMode === 'list' && (
            <>
                {/* Filter Tabs */}
                <div className="px-2 py-2 flex gap-2 overflow-x-auto custom-scrollbar no-scrollbar-on-mobile border-b border-slate-100/50 bg-slate-50/30 shrink-0">
                    <button
                        onClick={() => setActiveTab('all')}
                        className={`px-3 py-1.5 rounded-lg text-xs font-bold whitespace-nowrap transition-all ${activeTab === 'all' ? 'bg-slate-800 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-100 border border-transparent hover:border-slate-200'}`}
                    >
                        Tất cả
                    </button>
                    {tags.map(tag => (
                        <div key={tag.id} className="relative group">
                            <button
                                onClick={() => setActiveTab(tag.id)}
                                className={`pl-3 pr-7 py-1.5 rounded-lg text-xs font-bold whitespace-nowrap transition-all flex items-center gap-1.5 border relative
                                    ${activeTab === tag.id ? 'text-white shadow-md border-transparent' : 'bg-white text-slate-600 hover:bg-slate-50 border-transparent hover:border-slate-200'}
                                `}
                                style={{ 
                                    backgroundColor: activeTab === tag.id ? tag.color : undefined,
                                }}
                            >
                                <span className={`w-1.5 h-1.5 rounded-full ${activeTab === tag.id ? 'bg-white' : ''}`} style={{ backgroundColor: activeTab === tag.id ? undefined : tag.color }} />
                                {tag.name}
                                {tag.isPinned && (
                                     <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-2.5 h-2.5 ml-0.5 opacity-80">
                                        <path fillRule="evenodd" d="M10 2a.75.75 0 0 1 .75.75v1.514l1.815 1.09a3 3 0 0 1 1.026 3.655l-1.09 2.544 2.82 1.408a.75.75 0 0 1 .054 1.32l-1.636.98a.75.75 0 0 1-.88-.106l-2.088-2.09-.771.772v1.928a.75.75 0 0 1-1.5 0v-1.928l-.772-.772-2.089 2.09a.75.75 0 0 1-.879.106l-1.636-.98a.75.75 0 0 1 .053-1.32l2.82-1.409-1.09-2.543a3 3 0 0 1 1.026-3.655l1.814-1.09V2.75A.75.75 0 0 1 10 2Z" clipRule="evenodd" />
                                     </svg>
                                )}
                            </button>

                            {/* Hover Actions: Pin & Delete */}
                            <div className={`absolute -top-2 right-0 flex gap-1 z-10 transition-opacity ${activeTab === tag.id ? 'opacity-0 pointer-events-none' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button 
                                    onClick={(e) => { e.stopPropagation(); toggleTagPin(tag.id); }}
                                    className={`w-5 h-5 rounded-full flex items-center justify-center shadow-sm border border-white hover:scale-110 transition-all ${tag.isPinned ? 'bg-slate-700 text-white' : 'bg-slate-200 text-slate-500 hover:bg-slate-300'}`}
                                    title={tag.isPinned ? "Bỏ ghim" : "Ghim thẻ"}
                                >
                                     <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-2.5 h-2.5">
                                        <path fillRule="evenodd" d="M10 2a.75.75 0 0 1 .75.75v1.514l1.815 1.09a3 3 0 0 1 1.026 3.655l-1.09 2.544 2.82 1.408a.75.75 0 0 1 .054 1.32l-1.636.98a.75.75 0 0 1-.88-.106l-2.088-2.09-.771.772v1.928a.75.75 0 0 1-1.5 0v-1.928l-.772-.772-2.089 2.09a.75.75 0 0 1-.879.106l-1.636-.98a.75.75 0 0 1 .053-1.32l2.82-1.409-1.09-2.543a3 3 0 0 1 1.026-3.655l1.814-1.09V2.75A.75.75 0 0 1 10 2Z" clipRule="evenodd" />
                                     </svg>
                                </button>
                                <button 
                                    onClick={(e) => { e.stopPropagation(); deleteTag(tag.id); }}
                                    className="w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center shadow-sm border border-white hover:scale-110 transition-all"
                                    title="Xóa thẻ"
                                >
                                    &times;
                                </button>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Notes List */}
                <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar bg-slate-50/30">
                    {filteredNotes.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-12 h-12 mb-2">
                                <path strokeLinecap="round" strokeLinejoin="round" d="m16.862 4.487 1.687-1.688a1.875 1.875 0 1 1 2.652 2.652L10.582 16.07a4.5 4.5 0 0 1-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 0 1 1.13-1.897l8.932-8.931Zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0 1 15.75 21H5.25A2.25 2.25 0 0 1 3 18.75V8.25A2.25 2.25 0 0 1 5.25 6H10" />
                            </svg>
                            <span className="text-sm font-medium">Chưa có ghi chú nào</span>
                        </div>
                    ) : (
                        filteredNotes.map(note => {
                            const tag = getTag(note.tagId);
                            const status = statusConfig[note.status];

                            return (
                                <div 
                                    key={note.id} 
                                    className={`
                                        p-3 rounded-2xl shadow-sm border-l-[6px] border group hover:shadow-md transition-all relative overflow-hidden
                                        ${status.borderClass} ${status.containerClass} border-t-white/40 border-r-white/40 border-b-white/40 bg-white
                                    `}
                                >
                                    {/* Tag & Time */}
                                    <div className="flex justify-between items-start mb-2 relative z-10">
                                        <div className="flex items-center gap-2">
                                            {tag && (
                                                <span 
                                                    className="text-[10px] px-2 py-0.5 rounded-md font-bold text-white shadow-sm" 
                                                    style={{ backgroundColor: tag.color }}
                                                >
                                                    {tag.name}
                                                </span>
                                            )}
                                            <span className="text-[10px] text-slate-400 font-semibold bg-white/50 px-1.5 rounded">
                                                {new Date(note.timestamp).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit', day: '2-digit', month: '2-digit'})}
                                            </span>
                                        </div>
                                        <button 
                                            onClick={() => deleteNote(note.id)}
                                            className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 p-1 rounded-full hover:bg-red-50"
                                            title="Xóa ghi chú"
                                        >
                                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4"><path d="M6.28 5.22a.75.75 0 0 0-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 1 0 1.06 1.06L10 11.06l3.72 3.72a.75.75 0 1 0 1.06-1.06L11.06 10l3.72-3.72a.75.75 0 0 0-1.06-1.06L10 8.94 6.28 5.22Z" /></svg>
                                        </button>
                                    </div>

                                    <p className="text-sm text-slate-800 font-medium mb-3 whitespace-pre-wrap leading-relaxed relative z-10">
                                        {note.content}
                                    </p>

                                    {/* Status Actions */}
                                    <div className="flex gap-1 overflow-x-auto no-scrollbar-on-mobile pb-1 relative z-10">
                                        {(Object.keys(statusConfig) as NoteStatus[]).map((s) => (
                                            <button
                                                key={s}
                                                onClick={() => updateNoteStatus(note.id, s)}
                                                className={`
                                                    flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-bold border transition-all whitespace-nowrap
                                                    ${note.status === s 
                                                        ? `${statusConfig[s].badgeClass} border-transparent shadow-sm ring-1 ring-black/5` 
                                                        : 'bg-white/60 border-transparent text-slate-400 hover:bg-white hover:text-slate-600'}
                                                `}
                                            >
                                                {note.status === s ? statusConfig[s].icon : null}
                                                {statusConfig[s].label}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>
            </>
        )}
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useNotes } from '../hooks/useNotes';
import { NoteStatus, NoteTag } from '../types';

export const NotesManager: React.FC = () => {
  const { notes, tags, addNote, updateNoteStatus, deleteNote, addTag, deleteTag, toggleTagPin } = useNotes();
  const [isOpen, setIsOpen] = useState(false);

  // View Mode: 'list' (default), 'add-note', 'add-tag'
  const [viewMode, setViewMode] = useState<'list' | 'add-note' | 'add-tag'>('list');

  const [activeTab, setActiveTab] = useState<string>('all'); 

  // Add Note State
  const [newNoteContent, setNewNoteContent] = useState('');
  const [selectedTagForNewNote, setSelectedTagForNewNote] = useState<string>('');
  const [isTagDropdownOpen, setIsTagDropdownOpen] = useState(false);
  const tagDropdownRef = useRef<HTMLDivElement>(null);

  // Create Tag State
  const [newTagName, setNewTagName] = useState('');
  const [newTagColor, setNewTagColor] = useState('#3b82f6');

  // Handle outside click for Tag Dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (tagDropdownRef.current && !tagDropdownRef.current.contains(event.target as Node)) {
            setIsTagDropdownOpen(false);
        }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filteredNotes = activeTab === 'all' 
    ? notes 
    : notes.filter(n => n.tagId === activeTab);

  const getTag = (id: string | null) => tags.find(t => t.id === id);

  const handleAddNote = () => {
    if (!newNoteContent.trim()) return;
    addNote(newNoteContent, selectedTagForNewNote || null);
    setNewNoteContent('');
    setSelectedTagForNewNote('');
    setViewMode('list');
  };

  const handleCreateTag = () => {
    if (!newTagName.trim()) return;
    addTag(newTagName, newTagColor);
    setNewTagName('');
    setNewTagColor('#3b82f6');
    setViewMode('list');
  };

  // Config màu sắc
  const statusConfig: Record<NoteStatus, { label: string, badgeClass: string, borderClass: string, containerClass: string, icon: React.ReactNode }> = {
    incomplete: { 
      label: 'Chưa xong', 
      badgeClass: 'text-red-600 bg-red-100',
      borderClass: 'border-red-500', 
      containerClass: 'bg-red-50/30',
      icon: <div className="w-2 h-2 rounded-full bg-red-500" />
    },
    attention: { 
      label: 'Chú ý', 
      badgeClass: 'text-amber-600 bg-amber-100',
      borderClass: 'border-amber-500', 
      containerClass: 'bg-amber-50/30',
      icon: <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3 text-amber-500"><path fillRule="evenodd" d="M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Zm-8-5a.75.75 0 0 1 .75.75v4.5a.75.75 0 0 1-1.5 0v-4.5A.75.75 0 0 1 10 5Zm0 10a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z" clipRule="evenodd" /></svg>
    },
    completed: { 
      label: 'Hoàn thành', 
      badgeClass: 'text-emerald-600 bg-emerald-100',
      borderClass: 'border-emerald-500', 
      containerClass: 'bg-emerald-50/30',
      icon: <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3 text-emerald-500"><path fillRule="evenodd" d="M16.704 4.153a.75.75 0 0 1 .143 1.052l-8 10.5a.75.75 0 0 1-1.127.075l-4.5-4.5a.75.75 0 0 1 1.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 0 1 1.05-.143Z" clipRule="evenodd" /></svg>
    },
    skipped: { 
      label: 'Bỏ qua', 
      badgeClass: 'text-slate-500 bg-slate-200',
      borderClass: 'border-slate-400', 
      containerClass: 'bg-slate-100/50 opacity-75',
      icon: <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3 text-slate-500"><path d="M6.28 5.22a.75.75 0 0 0-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 1 0 1.06 1.06L10 11.06l3.72 3.72a.75.75 0 1 0 1.06-1.06L11.06 10l3.72-3.72a.75.75 0 0 0-1.06-1.06L10 8.94 6.28 5.22Z" /></svg>
    },
  };

  const renderHeader = () => (
    <div className="px-5 py-4 border-b border-slate-100 flex items-center justify-between bg-white/80 backdrop-blur-md sticky top-0 z-20 shrink-0 rounded-t-3xl">
        <div className="flex items-center gap-3">
            {viewMode !== 'list' && (
                <button onClick={() => setViewMode('list')} className="p-1 -ml-2 rounded-full hover:bg-slate-100 text-slate-500 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5" />
                    </svg>
                </button>
            )}
            <h3 className="font-extrabold text-slate-800 text-lg flex items-center gap-2">
                {viewMode === 'list' && <>Ghi chú <span className="text-xs font-normal bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full">{notes.length}</span></>}
                {viewMode === 'add-note' && 'Thêm ghi chú'}
                {viewMode === 'add-tag' && 'Thêm thẻ mới'}
            </h3>
        </div>

        <div className="flex items-center gap-2">
            {viewMode === 'list' && (
                <>
                <button 
                    onClick={() => setViewMode('add-tag')}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 rounded-lg transition-colors border border-indigo-100"
                    title="Thêm thẻ phân loại"
                >
                   <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3.5 h-3.5">
                        <path d="M12.232 4.232a2.5 2.5 0 0 1 3.536 3.536l-1.225 1.224a.75.75 0 0 0 1.061 1.06l1.224-1.224a4 4 0 0 0-5.656-5.656l-3 3a4 4 0 0 0 .225 5.865.75.75 0 0 0 .977-1.138 2.5 2.5 0 0 1-.142-3.667l3-3Z" />
                        <path d="M11.603 7.963a.75.75 0 0 0-.977 1.138 2.5 2.5 0 0 1 .142 3.667l-3 3a2.5 2.5 0 0 1-3.536-3.536l1.225-1.224a.75.75 0 0 0-1.061-1.06l-1.224 1.224a4 4 0 1 0 5.656 5.656l3-3a4 4 0 0 0-.225-5.865Z" />
                   </svg>
                   <span className="hidden sm:inline">Thêm thẻ</span>
                </button>
                <button 
                    onClick={() => setViewMode('add-note')}
