                    {viewMode === 'add-tag' && (
                        <div className={`p-5 flex flex-col gap-4 overflow-y-auto custom-scrollbar ${isSubViewClosing ? 'animate-fade-out-down' : 'animate-fade-in-up'}`}>
                            <div className="max-w-3xl mx-auto w-full">
                                <div className="mb-4">
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Tên thẻ mới</label>
                                    <input 
                                        type="text" 
                                        placeholder="Ví dụ: Mua sắm, Deadline..." 
                                        className="w-full text-sm px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:border-indigo-500 bg-slate-50 focus:bg-white transition-all"
                                        value={newTagName}
                                        onChange={(e) => setNewTagName(e.target.value)}
                                        autoFocus
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Chọn màu nhận diện</label>
                                    <div className="flex items-center gap-3">
                                        <input 
                                            type="color" 
                                            className="w-14 h-14 rounded-xl cursor-pointer border-2 border-white shadow-sm"
                                            value={newTagColor}
                                            onChange={(e) => setNewTagColor(e.target.value)}
                                        />
                                        <span className="text-sm font-mono bg-slate-100 px-3 py-1 rounded text-slate-600">{newTagColor}</span>
                                    </div>
                                </div>
                                <div className="mt-6 flex gap-3 pb-2">
                                    <button 
                                        onClick={handleBackToMain}
                                        className="flex-1 py-3.5 bg-slate-100 hover:bg-slate-200 text-slate-600 text-sm font-bold rounded-xl transition-colors"
                                    >
                                        Hủy
                                    </button>
                                    <button 
                                        onClick={handleCreateTag}
                                        className="flex-1 py-3.5 bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold rounded-xl transition-colors shadow-lg shadow-indigo-200"
                                    >
                                        Tạo thẻ
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* --- VIEW: ADD NOTE --- */}
                    {viewMode === 'add-note' && (
                        <div className={`p-5 flex flex-col gap-5 flex-1 h-full overflow-y-auto custom-scrollbar ${isSubViewClosing ? 'animate-fade-out-down' : 'animate-fade-in-up'}`}>
                            <div className="max-w-3xl mx-auto w-full h-full flex flex-col">
                                {/* Flex-col with gap ensures label and textarea don't overlap */}
                                <div className="flex-1 flex flex-col gap-2 min-h-[200px]">
                                    <label className="block text-xs font-bold text-slate-500 uppercase">Nội dung ghi chú</label>
                                    <textarea 
                                        className="w-full flex-1 bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm focus:outline-none focus:border-indigo-500 focus:bg-white transition-all resize-none shadow-inner"
                                        placeholder="Nhập nội dung ghi chú của bạn..."
                                        value={newNoteContent}
                                        onChange={(e) => setNewNoteContent(e.target.value)}
                                        autoFocus
                                    />
                                </div>

                                {/* Custom Tag Dropdown */}
                                <div className="relative shrink-0 mt-4" ref={tagDropdownRef}>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Phân loại thẻ</label>
                                    <button
                                        onClick={() => setIsTagDropdownOpen(!isTagDropdownOpen)}
                                        className={`w-full flex items-center justify-between px-4 py-3 rounded-xl border bg-white transition-all ${isTagDropdownOpen ? 'border-indigo-500 ring-2 ring-indigo-50' : 'border-slate-200 hover:border-slate-300'}`}
                                    >
                                        {selectedTagForNewNote ? (
                                            <div className="flex items-center gap-2">
                                                <span className="w-3 h-3 rounded-full" style={{ backgroundColor: getTag(selectedTagForNewNote)?.color }}></span>
                                                <span className="text-sm font-semibold text-slate-700">{getTag(selectedTagForNewNote)?.name}</span>
                                            </div>
                                        ) : (
                                            <span className="text-sm text-slate-400">Chọn thẻ...</span>
                                        )}
                                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4 text-slate-400">
                                            <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
                                        </svg>
                                    </button>

                                    {isTagDropdownOpen && (
                                        <div className="absolute bottom-full left-0 w-full mb-2 bg-white rounded-xl shadow-xl border border-slate-100 overflow-hidden z-20 animate-fade-in-up">
                                            <div className="max-h-40 overflow-y-auto custom-scrollbar p-1">
                                                <button
                                                    onClick={() => { setSelectedTagForNewNote(''); setIsTagDropdownOpen(false); }}
                                                    className="w-full text-left px-3 py-2 text-sm text-slate-600 hover:bg-slate-50 rounded-lg font-medium"
                                                >
                                                    Mặc định (Không thẻ)
                                                </button>
                                                {tags.map(tag => (
                                                    <button
                                                        key={tag.id}
                                                        onClick={() => { setSelectedTagForNewNote(tag.id); setIsTagDropdownOpen(false); }}
                                                        className="w-full flex items-center gap-2 px-3 py-2 hover:bg-slate-50 rounded-lg transition-colors"
                                                    >
                                                        <span className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: tag.color }}></span>
                                                        <span className="text-sm font-semibold text-slate-700">{tag.name}</span>
                                                    </button>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <div className="flex gap-3 mt-4 shrink-0">
                                    <button 
                                        onClick={handleBackToMain}
                                        className="flex-1 py-3.5 bg-slate-100 hover:bg-slate-200 text-slate-600 text-sm font-bold rounded-xl transition-colors"
                                    >
                                        Hủy
                                    </button>
                                    <button 
                                        onClick={handleAddNote}
                                        disabled={!newNoteContent.trim()}
                                        className={`flex-1 py-3.5 text-white text-sm font-bold rounded-xl transition-colors shadow-lg
                                            ${newNoteContent.trim() ? 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200' : 'bg-slate-300 cursor-not-allowed'}
                                        `}
                                    >
                                        Lưu ghi chú
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* --- VIEW: LIST --- */}
                    {viewMode === 'list' && (
                        <div className="flex flex-col h-full overflow-hidden animate-fade-in-up">
                            {/* Filter Tabs */}
                            <div className="px-5 py-3 flex gap-2 overflow-x-auto custom-scrollbar no-scrollbar-on-mobile border-b border-slate-100/50 bg-slate-50/50 shrink-0">
                                <button
                                    onClick={() => setActiveTab('all')}
                                    className={`px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap transition-all shadow-sm
                                        ${activeTab === 'all' 
                                            ? 'bg-slate-800 text-white shadow-md transform scale-105' 
                                            : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}
                                    `}
                                >
                                    Tất cả
                                </button>
                                {tags.map(tag => (
                                    <div 
                                        key={tag.id} 
                                        className={`
                                            flex items-center rounded-xl border shadow-sm transition-all overflow-hidden relative
                                            ${activeTab === tag.id ? 'border-transparent shadow-md transform scale-105' : 'bg-white border-slate-100 hover:border-slate-200'}
                                        `}
                                        style={{ 
                                            backgroundColor: activeTab === tag.id ? tag.color : 'white',
                                            color: activeTab === tag.id ? 'white' : undefined,
                                        }}
                                    >
                                        <button
                                            onClick={() => setActiveTab(tag.id)}
                                            className={`pl-3 pr-3 py-2 text-xs font-bold whitespace-nowrap flex items-center gap-1.5 h-full ${activeTab !== tag.id ? 'text-slate-600' : ''}`}
                                        >
                                            <span className={`w-1.5 h-1.5 rounded-full ${activeTab === tag.id ? 'bg-white' : ''}`} style={{ backgroundColor: activeTab === tag.id ? undefined : tag.color }} />
                                            {tag.name}
                                        </button>

                                        {/* Actions - Only visible when active */}
                                        {activeTab === tag.id && (
                                            <div className="flex items-center h-full">
                                                <div className="h-4 w-px bg-white/30"></div>
                                                <button 
                                                    onClick={(e) => { e.stopPropagation(); toggleTagPin(tag.id); }}
                                                    className="px-2 py-2 h-full flex items-center justify-center transition-colors hover:bg-black/10"
                                                    title={tag.isPinned ? "Bỏ ghim" : "Ghim thẻ"}
                                                >
                                                    {tag.isPinned ? (
                                                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-3.5 h-3.5">
                                                            <path fillRule="evenodd" d="M11.47 2.47a.75.75 0 0 1 1.06 0l4.5 4.5a.75.75 0 0 1-1.06 1.06l-4.5-4.5a.75.75 0 0 1 0-1.06Zm-5 5a.75.75 0 0 1 1.06 0l4.5 4.5a.75.75 0 0 1-1.06 1.06l-4.5-4.5a.75.75 0 0 1 0-1.06Z" clipRule="evenodd" />
                                                            <path d="M14.75 12.25a.75.75 0 0 0 0 1.5H16v2.25h-2.25a.75.75 0 0 0 0 1.5H16v2.5a.75.75 0 0 0 1.5 0v-2.5h2.25a.75.75 0 0 0 0-1.5H17.5V13.75h2.25a.75.75 0 0 0 0-1.5H14.75Z" opacity="0" /> 
                                                            <path fillRule="evenodd" d="M9.702 3.86a.75.75 0 0 1 .493 1.018l-1.082 3.093 5.925 5.925 3.093-1.082a.75.75 0 0 1 .937.937l-1.383 4.84a.75.75 0 0 1-1.05.474l-3.37-1.444-2.298 2.298a.75.75 0 0 1-1.06 0l-1.061-1.061a.75.75 0 0 1 0-1.061l2.298-2.298-1.444-3.37a.75.75 0 0 1 .474-1.05l4.84-1.383a.75.75 0 0 1 .494-1.018Z" clipRule="evenodd" />
                                                        </svg>
                                                    ) : (
                                                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5 opacity-60">
                                                            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9 3.75h.008v.008H12v-.008Z" /> 
                                                            <path strokeLinecap="round" strokeLinejoin="round" d="m15 11.25-3-3m0 0-3 3m3-3v7.5" />
                                                        </svg>
                                                    )}
                                                </button>

                                                <div className="h-4 w-px bg-white/30"></div>
                                                <button 
                                                    onClick={(e) => { e.stopPropagation(); deleteTag(tag.id); }}
                                                    className="px-2 py-2 h-full flex items-center justify-center hover:bg-black/10 transition-colors"
                                                    title="Xóa thẻ"
                                                >
                                                    <span className="text-white font-bold leading-none text-sm">&times;</span>
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>

                            {/* Notes List with Grid Layout on Desktop */}
                            <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/30 pb-20">
                                {filteredNotes.length === 0 ? (
                                    <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60 min-h-[200px]">
                                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-12 h-12 mb-2">
                                            <path strokeLinecap="round" strokeLinejoin="round" d="m16.862 4.487 1.687-1.688a1.875 1.875 0 1 1 2.652 2.652L10.582 16.07a4.5 4.5 0 0 1-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 0 1 1.13-1.897l8.932-8.931Zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0 1 15.75 21H5.25A2.25 2.25 0 0 1 3 18.75V8.25A2.25 2.25 0 0 1 5.25 6H10" />
                                        </svg>
                                        <span className="text-sm font-medium">Chưa có ghi chú nào</span>
                                        <p className="text-xs text-slate-400 mt-2 text-center px-4">Giữ lì vào ghi chú để chọn nhiều</p>
                                    </div>
                                ) : (
                                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 auto-rows-min">
                                        {filteredNotes.map(note => {
                                            const tag = getTag(note.tagId);
                                            const status = statusConfig[note.status];
                                            const isSelected = selectedIds.has(note.id);
                                            const isAllTab = activeTab === 'all';

                                            return (
                                                <div 
                                                    key={note.id} 
                                                    data-note-id={note.id}
                                                    onPointerDown={(e) => handlePointerDown(e, note.id)}
                                                    onClick={() => {
                                                        if (isSelectionMode) {
                                                            handleCheckboxChange(note.id);
                                                        }
                                                    }}
                                                    className={`
                                                        rounded-2xl shadow-sm border border-l-[6px] group transition-all relative overflow-hidden flex items-stretch touch-manipulation select-none h-full
                                                        ${isSelectionMode 
                                                            ? 'cursor-pointer hover:shadow-md' 
                                                            : 'hover:shadow-md'}
                                                        ${isSelectionMode && isSelected 
                                                            ? 'bg-indigo-50 border-l-indigo-500 border-indigo-200' 
                                                            : `${status.borderClass} ${status.containerClass} bg-white border-t-white/40 border-r-white/40 border-b-white/40`}
                                                    `}
                                                >
                                                    {/* Selection Checkbox Area */}
                                                    {isSelectionMode && (
                                                        <div className="w-12 flex items-center justify-center border-r border-slate-100/50 bg-white/40 shrink-0">
                                                            <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-all ${isSelected ? 'bg-indigo-600 border-indigo-600' : 'bg-white border-slate-300'}`}>
                                                                {isSelected && (
                                                                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3.5 h-3.5 text-white">
                                                                        <path fillRule="evenodd" d="M16.704 4.153a.75.75 0 0 1 .143 1.052l-8 10.5a.75.75 0 0 1-1.127.075l-4.5-4.5a.75.75 0 0 1 1.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 0 1 1.05-.143Z" clipRule="evenodd" />
                                                                    </svg>
                                                                )}
                                                            </div>
                                                        </div>
                                                    )}

                                                    {/* Category Badge for 'All' view */}
                                                    {!isSelectionMode && isAllTab && tag && (
                                                        <div 
                                                            className="absolute top-0 right-0 px-3 py-1.5 rounded-bl-xl rounded-tr-2xl text-[9px] font-bold text-white shadow-sm z-[5] pointer-events-none"
                                                            style={{ backgroundColor: tag.color }}
                                                        >
                                                            {tag.name}
                                                        </div>
                                                    )}

                                                    <div className="flex-1 p-3 flex flex-col h-full">
                                                        {/* Tag & Time */}
                                                        <div className="flex justify-between items-start mb-2 relative z-10">
                                                            <div className="flex items-center gap-2">
                                                                {tag && !isAllTab && (
                                                                    <span 
                                                                        className="text-[10px] px-2 py-0.5 rounded-md font-bold text-white shadow-sm" 
                                                                        style={{ backgroundColor: tag.color }}
                                                                    >
                                                                        {tag.name}
                                                                    </span>
                                                                )}
                                                                <span className="text-[10px] text-slate-400 font-semibold bg-white/50 px-1.5 rounded">
                                                                    {new Date(note.timestamp).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit', day: '2-digit', month: '2-digit'})}
                                                                </span>
                                                            </div>

                                                            {/* Single Delete Button (Only when not in selection mode) */}
                                                            {!isSelectionMode && (
                                                                <button 
                                                                    onClick={(e) => { e.stopPropagation(); handleDeleteClick([note.id]); }}
                                                                    className={`text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 p-1 rounded-full hover:bg-red-50 ${isAllTab ? 'mt-5 mr-1' : ''}`}
                                                                    title="Xóa ghi chú"
                                                                >
                                                                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4"><path d="M6.28 5.22a.75.75 0 0 0-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 1 0 1.06 1.06L10 11.06l3.72 3.72a.75.75 0 1 0 1.06-1.06L11.06 10l3.72-3.72a.75.75 0 0 0-1.06-1.06L10 8.94 6.28 5.22Z" /></svg>
                                                                </button>
                                                            )}
                                                        </div>

                                                        <p className="text-sm text-slate-800 font-medium mb-3 whitespace-pre-wrap leading-relaxed relative z-10 flex-1">
                                                            {note.content}
                                                        </p>

                                                        {/* Status Actions (Disabled in selection mode) */}
                                                        <div className={`flex gap-1 overflow-x-auto no-scrollbar-on-mobile pb-1 relative z-10 mt-auto ${isSelectionMode ? 'pointer-events-none opacity-60' : ''}`}>
                                                            {(Object.keys(statusConfig) as NoteStatus[]).map((s) => (
                                                                <button
                                                                    key={s}
                                                                    onClick={(e) => { e.stopPropagation(); updateNoteStatus(note.id, s); }}
                                                                    className={`
                                                                        flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-bold border transition-all whitespace-nowrap
                                                                        ${note.status === s 
                                                                            ? `${statusConfig[s].badgeClass} border-transparent shadow-sm ring-1 ring-black/5` 
                                                                            : 'bg-white/60 border-transparent text-slate-400 hover:bg-white hover:text-slate-600'}
                                                                    `}
                                                                >
                                                                    {note.status === s ? statusConfig[s].icon : null}
                                                                    {statusConfig[s].label}
                                                                </button>
                                                            ))}
                                                        </div>
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>

                            {/* Floating Bulk Delete Action */}
                            {isSelectionMode && (
                                <div className="absolute bottom-0 left-0 right-0 p-4 bg-white border-t border-slate-200 shadow-lg z-30 animate-fade-in-up">
                                    <button
                                        onClick={() => handleDeleteClick(Array.from(selectedIds))}
                                        disabled={selectedIds.size === 0}
                                        className={`w-full py-3.5 rounded-xl font-bold text-white shadow-lg transition-all flex items-center justify-center gap-2 ${
                                            selectedIds.size > 0 
                                            ? 'bg-red-500 hover:bg-red-600 active:scale-[0.98]' 
                                            : 'bg-slate-300 cursor-not-allowed'
                                        }`}
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                                            <path strokeLinecap="round" strokeLinejoin="round" d="m14.74 9-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 0 1-2.244 2.077H8.084a2.25 2.25 0 0 1-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 0 0-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 0 1 3.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 0 0-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 0 0-7.5 0" />
                                        </svg>
                                        Xóa {selectedIds.size} ghi chú
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>
             </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {confirmDelete.isOpen && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
              <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-[2px]" onClick={() => setConfirmDelete({ ...confirmDelete, isOpen: false })}></div>
              <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm relative z-10 animate-pulse-soft">
                  <div className="text-center mb-6">
                      <div className="w-14 h-14 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-4 text-red-500 ring-4 ring-red-50">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z" />
                        </svg>
                      </div>
                      <h4 className="text-xl font-bold text-slate-800 mb-2">Xác nhận xóa</h4>
                      <p className="text-slate-500">
                          {confirmDelete.ids.length > 1 
                              ? `Bạn có chắc chắn muốn xóa ${confirmDelete.ids.length} ghi chú đã chọn không?`
                              : "Bạn có chắc chắn muốn xóa ghi chú này không?"
                          }
                      </p>
                  </div>
                  <div className="flex gap-3">
                      <button 
                        onClick={() => setConfirmDelete({ ...confirmDelete, isOpen: false })}
                        className="flex-1 py-3 rounded-xl font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors"
                      >
                          Hủy bỏ
                      </button>
                      <button 
                        onClick={performDelete}
                        className="flex-1 py-3 rounded-xl font-bold text-white bg-red-500 hover:bg-red-600 transition-colors shadow-lg shadow-red-200"
                      >
                          Xóa ngay
                      </button>
                  </div>
              </div>
          </div>
      )}
    </>
  );
};

import React from 'react';
import { ThemeColor } from '../types';

interface TabSelectorProps {
  activeTab: 'convert' | 'calculate' | 'revenue';
  onTabChange: (tab: 'convert' | 'calculate' | 'revenue') => void;
  theme: ThemeColor;
}

export const TabSelector: React.FC<TabSelectorProps> = ({ activeTab, onTabChange, theme }) => {
  const getLeftPosition = () => {
    switch (activeTab) {
      case 'convert': return '0.375rem';
      case 'calculate': return 'calc(33.33% + 0.1875rem)';
      case 'revenue': return 'calc(66.66% + 0.1875rem)'; // adjusted for 3 tabs
      default: return '0.375rem';
    }
  };

  return (
    <div className="flex p-1.5 bg-white/50 backdrop-blur-sm rounded-xl mb-6 relative shadow-sm border border-white/40">
      <div 
        className="absolute top-1.5 bottom-1.5 rounded-lg bg-gradient-to-r from-primary-600 to-primary-500 shadow-md shadow-primary-200 transition-all duration-300 ease-in-out"
        style={{
            left: getLeftPosition(),
            width: 'calc(33.33% - 0.5rem)'
        }}
      />
      <button
        onClick={() => onTabChange('convert')}
        className={`flex-1 relative z-10 py-2.5 text-xs sm:text-sm md:text-base font-bold text-center rounded-lg transition-colors duration-300 ${
            activeTab === 'convert' ? 'text-white' : 'text-slate-500 hover:text-slate-800 hover:bg-white/40'
        }`}
      >
        Chuyển đổi
      </button>
      <button
        onClick={() => onTabChange('calculate')}
        className={`flex-1 relative z-10 py-2.5 text-xs sm:text-sm md:text-base font-bold text-center rounded-lg transition-colors duration-300 ${
            activeTab === 'calculate' ? 'text-white' : 'text-slate-500 hover:text-slate-800 hover:bg-white/40'
        }`}
      >
        Tính phí
      </button>
       <button
        onClick={() => onTabChange('revenue')}
        className={`flex-1 relative z-10 py-2.5 text-xs sm:text-sm md:text-base font-bold text-center rounded-lg transition-colors duration-300 ${
            activeTab === 'revenue' ? 'text-white' : 'text-slate-500 hover:text-slate-800 hover:bg-white/40'
        }`}
      >
        Tính doanh thu
      </button>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { DenominationSelector } from './components/DenominationSelector';
import { HistorySection } from './components/HistorySection';
import { ThemeSelector } from './components/ThemeSelector';
import { TabSelector } from './components/TabSelector';
import { NotesManager } from './components/NotesManager';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState, ThemeColor, Currency, ConversionHistoryItem } from './types';
import { THEME_COLORS, DEFAULT_SOURCE_CURRENCY } from './constants';
import { generatePalette, extractDominantColor, compressImage } from './utils/themeUtils';
import { getReadFunction } from './utils/currencyTextFormatter';
import { CopyButton } from './components/CopyButton';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult, addToHistory
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [theme, setTheme] = useState<ThemeColor>('blue');
  const [showHistory, setShowHistory] = useState(false);
  const [isClosingHistory, setIsClosingHistory] = useState(false); // New state for history closing animation

  // Background Image State
  const [backgroundImage, setBackgroundImage] = useState<string | null>(null);

  // States for Calculation & Revenue Mode
  const [activeTab, setActiveTab] = useState<'convert' | 'calculate' | 'revenue'>('convert');
  const [salaryAmount, setSalaryAmount] = useState<string>('');
  const [calcType, setCalcType] = useState<'probation' | 'official'>('official');

  // New State for Revenue Options
  const [revenueShare, setRevenueShare] = useState<'all' | 'cv' | 'job'>('all');
  const [isRevenueDropdownOpen, setIsRevenueDropdownOpen] = useState(false);
  const revenueDropdownRef = useRef<HTMLDivElement>(null);

  const [revenueResult, setRevenueResult] = useState<{
      totalRevenue: number;
      stageRevenue: number;
      netIncome: number;
  } | null>(null);

  const revenueOptions = [
    { value: 'all', label: 'Tất cả (100%)' },
    { value: 'cv', label: 'Có CV (70%)' },
    { value: 'job', label: 'Nắm Job (30%)' }
  ];

  // Filter history based on active tab
  const filteredHistory = useMemo(() => {
    return history.filter(item => item.type === activeTab);
  }, [history, activeTab]);

  const applyTheme = (colorIdOrHex: string) => {
    let hex = colorIdOrHex;
    const preset = THEME_COLORS.find(t => t.id === colorIdOrHex);
    if (preset) hex = preset.hex;

    const palette = generatePalette(hex);
    const root = document.documentElement;
    Object.entries(palette).forEach(([shade, value]) => {
      root.style.setProperty(`--color-primary-${shade}`, value);
    });
  };

  // Initial load of theme and background
  useEffect(() => {
    const savedTheme = localStorage.getItem('app_theme');
    const savedBg = localStorage.getItem('app_bg');

    if (savedBg) {
        setBackgroundImage(savedBg);
    }

    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      applyTheme('blue');
    }
  }, []);

  const handleThemeChange = (newTheme: ThemeColor) => {
    setTheme(newTheme);
    localStorage.setItem('app_theme', newTheme);
    applyTheme(newTheme);
  };

  const handleBackgroundUpload = async (file: File) => {
      if (!file) return;

      try {
          // Compress image to avoid LocalStorage quota limit
          const base64String = await compressImage(file);

          setBackgroundImage(base64String);

          try {
              localStorage.setItem('app_bg', base64String);
          } catch (e) {
              console.error("LocalStorage quota exceeded", e);
              alert("Ảnh nền quá lớn để lưu tự động. Ảnh sẽ chỉ hiển thị trong phiên làm việc hiện tại.");
          }

          // Auto extract color and set theme
          try {
              const dominantColor = await extractDominantColor(base64String);
              setTheme(dominantColor);
              localStorage.setItem('app_theme', dominantColor);
              applyTheme(dominantColor);
          } catch (e) {
              console.error("Could not extract color", e);
          }
      } catch (error) {
          console.error("Error processing background image", error);
          alert("Có lỗi xảy ra khi xử lý ảnh.");
      }
  };

  const handleRemoveBackground = () => {
    setBackgroundImage(null);
    localStorage.removeItem('app_bg');
  };

  // Handle click outside for Revenue Dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (revenueDropdownRef.current && !revenueDropdownRef.current.contains(event.target as Node)) {
            setIsRevenueDropdownOpen(false);
        }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleAmountChange = (val: string) => {
    if (activeTab === 'calculate' || activeTab === 'revenue') {
        setSalaryAmount(val);
    } else {
        setAmount(val);
    }
    resetResult();
    setRevenueResult(null); // Reset revenue result on input change
  };

  const handleFromChange = (currency: Currency) => {
    setFromCurrency(currency);
    resetResult();
  };

  const handleToChange = (currency: Currency) => {
    setToCurrency(currency);
    resetResult();
  };

  const handleDenominationSelect = (newAmount: string) => {
    handleAmountChange(newAmount);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        if (isNaN(val)) return `0 ${currencyCode}`;
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  const handleCloseHistory = () => {
      setIsClosingHistory(true);
      setTimeout(() => {
          setShowHistory(false);
          setIsClosingHistory(false);
      }, 300); // 300ms matches standard CSS transition time
  };

  const handleHistorySelect = (item: ConversionHistoryItem) => {
    selectHistoryItem(item);

    if (item.type === 'calculate' && item.originalSalary) {
        setSalaryAmount(item.originalSalary.toString());
        handleConvert(item.inputAmount.toString(), activeTab, item.originalSalary);
    } 
    else if (item.type === 'revenue' && item.revenueDetails) {
        setSalaryAmount(item.inputAmount.toString());
        setRevenueShare(item.revenueDetails.shareType);
        // Recalculate directly to show result
        setRevenueResult({
            totalRevenue: item.revenueDetails.totalRevenue,
            stageRevenue: item.revenueDetails.stageRevenue,
            netIncome: item.convertedAmount
        });
    }
    else {
        handleConvert(item.inputAmount.toString(), activeTab);
    }

    handleCloseHistory();
  };

  const handleSwapClick = () => {
    handleSwap(activeTab as 'convert' | 'calculate');
  };

  // Main Calculation Logic
  const onCalculateAndConvert = () => {
    if (activeTab === 'revenue') {
        // Revenue Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
             setRevenueResult(null);
             return;
        }

        // 1. Calculate Base Fee (Revenue) from Salary
        const feeMultiplier = calcType === 'probation' ? 0.75 : 0.60;
        const baseRevenue = Math.floor(salary * feeMultiplier);

        // 2. Apply Revenue Share Option
        let shareMultiplier = 1;
        if (revenueShare === 'cv') shareMultiplier = 0.7;
        else if (revenueShare === 'job') shareMultiplier = 0.3;

        const totalRevenue = Math.floor(baseRevenue * shareMultiplier);

        // 3. Calculate Derived Values
        const stageRevenue = Math.floor(totalRevenue / 2);
        const netIncome = Math.floor(totalRevenue * 0.49);

        setRevenueResult({
            totalRevenue,
            stageRevenue,
            netIncome
        });

        // Add to history
        addToHistory(
            salary,
            DEFAULT_SOURCE_CURRENCY, // Assume VND
            DEFAULT_SOURCE_CURRENCY, // Assume VND
            netIncome,
            'revenue',
            undefined,
            {
                shareType: revenueShare,
                stageRevenue: stageRevenue,
                totalRevenue: totalRevenue
            }
        );

    } else if (activeTab === 'calculate') {
        // Calculate Fee Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
            handleConvert('0', activeTab); 
            return;
        }
        const multiplier = calcType === 'probation' ? 0.75 : 0.60;
        const fee = Math.floor(salary * multiplier);
        setAmount(fee.toString()); // Sync state
        handleConvert(fee.toString(), activeTab, salary); // Trigger conversion
    } else {
        // Standard Convert Logic
        handleConvert(amount, activeTab);
    }
  };

  const renderHistoryButton = (
    <button 
        onClick={() => setShowHistory(true)}
        className={`flex items-center gap-1.5 text-xs font-bold hover:text-primary-700 px-2 py-1 rounded-md transition-all 
        ${backgroundImage ? 'text-primary-600 bg-white/90' : 'text-primary-600 bg-primary-50 hover:bg-primary-100'}`}
    >
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5">
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
        </svg>
        Lịch sử
    </button>
  );

  // Calculate Stage Fee Values (only available when result is present)
  const stageFeeData = useMemo(() => {
    if (activeTab !== 'calculate' || !result || !amount) return null;

    const totalFeeSource = parseFloat(amount);
    if (isNaN(totalFeeSource)) return null;

    const stageSource = Math.floor(totalFeeSource / 2);
    // Calculate target using the same rate logic
    const stageTarget = Math.ceil(stageSource * result.exchangeRate);

    const formattedSource = formatCurrency(stageSource, fromCurrency.locale, fromCurrency.code);
    const formattedTarget = formatCurrency(stageTarget, toCurrency.locale, toCurrency.code);

    return {
        source: stageSource,
        target: stageTarget,
        formattedSource,
        formattedTarget,
        textSource: getReadFunction(fromCurrency.code, stageSource),
        textTarget: getReadFunction(toCurrency.code, stageTarget)
    };
  }, [activeTab, result, amount, fromCurrency, toCurrency]);

  const vietNamFlagUrl = "https://flagcdn.com/w80/vn.png";
  const hasBackground = !!backgroundImage;

  return (
    <div 
        className={`min-h-screen font-sans text-slate-800 selection:bg-primary-200 flex flex-col relative transition-all duration-500`}
        style={{
            backgroundColor: backgroundImage ? 'transparent' : '#f1f5f9',
            backgroundImage: backgroundImage ? `url(${backgroundImage})` : 'none',
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            backgroundAttachment: 'fixed',
            backgroundRepeat: 'no-repeat'
        }}
    >

      {/* 1. Global Blurred Background */}
      <div 
        className="fixed inset-0 z-0 transition-all duration-500 bg-slate-100"
        style={{
            backgroundImage: backgroundImage ? `url(${backgroundImage})` : 'none',
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            backgroundAttachment: 'fixed',
            filter: backgroundImage ? 'blur(20px) brightness(0.9)' : 'none',
            transform: 'scale(1.05)'
        }}
      />

      <div className="fixed top-3 right-3 sm:top-5 sm:right-5 z-[100] animate-fade-in-up">
        <ThemeSelector 
            currentTheme={theme} 
            onThemeChange={handleThemeChange} 
            onBackgroundUpload={handleBackgroundUpload}
            onRemoveBackground={handleRemoveBackground}
            currentBackground={backgroundImage}
        />
      </div>

      <div className="flex-1 flex items-center justify-center p-3 sm:p-4 relative z-20">
        {/* 2. Main Card with Optimized Border/Background */}
        <div 
            className={`w-full max-w-5xl rounded-3xl relative flex flex-col my-2 mb-8 transition-all duration-300 shadow-2xl
            ${!hasBackground 
                ? 'bg-white/95 backdrop-blur-sm border border-white/60 shadow-slate-900/10' 
                : 'border border-white/10 ring-1 ring-white/20 shadow-black/20'}`} 
            style={{
                backgroundImage: hasBackground ? `url(${backgroundImage})` : 'none',
                backgroundSize: 'cover',
                backgroundPosition: 'center',
            }}
        >
          {/* Internal overlay */}
          {hasBackground && <div className="absolute inset-0 bg-black/5 z-0 pointer-events-none rounded-3xl"></div>}

          <div className="relative z-10">
            <Header theme={theme} onShowHistory={() => {}} />

            <div className="p-4 sm:p-8 space-y-6 relative flex-1">

                <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                    <TabSelector 
                        activeTab={activeTab} 
                        onTabChange={(tab) => { setActiveTab(tab); resetResult(); setAmount(''); setSalaryAmount(''); setRevenueResult(null); }} 
                        theme={theme} 
                    />
                </div>

                {activeTab === 'convert' && (
                    <div className="animate-fade-in-up" style={{ animationDelay: '150ms' }}>
                    <DenominationSelector 
                        currency={fromCurrency} 
                        onSelect={handleDenominationSelect} 
                        currentAmount={amount}
                        theme={theme}
                    />
                    </div>
                )}

                <div className="flex flex-col md:flex-row items-center md:items-start relative gap-3 md:gap-4">
                {/* 
                    Z-Index Logic Fixed: 
                    If FROM is active OR Revenue Dropdown is open, it gets z-50 to stack above the button.
                    Otherwise, it sits at z-20.
                */}
                <div className={`w-full md:flex-1 transition-all relative ${activeDropdown === 'FROM' || isRevenueDropdownOpen ? 'z-50' : 'z-20'}`}> 
                    <CurrencyRow
                        key={activeTab}
                        label={activeTab === 'convert' ? "Nhập số tiền cần đổi" : "Nhập mức lương"}
                        amount={activeTab === 'convert' ? amount : salaryAmount}
                        currency={fromCurrency}
                        onAmountChange={handleAmountChange}
                        onCurrencyChange={handleFromChange}
                        inputPlacement="left"
                        autoFocus={true}
                        isActive={activeDropdown === 'FROM'}
                        onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                        onCloseDropdown={() => setActiveDropdown(null)}
                        theme={theme}
                        headerAction={renderHistoryButton}
                        error={errorMsg}
                        onEnter={onCalculateAndConvert}
                        hasBackgroundImage={hasBackground}
                    />

                    {(activeTab === 'calculate' || activeTab === 'revenue') && (
                        <div className="mt-3 flex gap-3 animate-fade-in-up">
                            {/* Official Salary */}
                            <label className={`flex-1 flex items-center justify-center gap-2 px-3 rounded-2xl border cursor-pointer transition-all h-[60px] sm:h-[66px]
                                ${calcType === 'official' 
                                    ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' 
                                    : hasBackground ? 'bg-white/80 border-white/40 text-slate-700 hover:bg-white' : 'bg-white/90 border-slate-200 text-slate-600 hover:bg-white'}`}>
                                <input type="radio" name="calcType" value="official" checked={calcType === 'official'} onChange={() => setCalcType('official')} className="hidden" />
                                <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'official' ? 'border-primary-500' : 'border-slate-300'}`}>
                                    {calcType === 'official' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                                </div>
                                <span>Chính thức (60%)</span>
                            </label>

                            {/* Probation Salary */}
                            <label className={`flex-1 flex items-center justify-center gap-2 px-3 rounded-2xl border cursor-pointer transition-all h-[60px] sm:h-[66px]
                                ${calcType === 'probation' 
                                    ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' 
                                    : hasBackground ? 'bg-white/80 border-white/40 text-slate-700 hover:bg-white' : 'bg-white/90 border-slate-200 text-slate-600 hover:bg-white'}`}>
                                <input type="radio" name="calcType" value="probation" checked={calcType === 'probation'} onChange={() => setCalcType('probation')} className="hidden" />
                                <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${calcType === 'probation' ? 'border-primary-500' : 'border-slate-300'}`}>
                                    {calcType === 'probation' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                                </div>
                                <span>Thử việc (75%)</span>
                            </label>
                        </div>
                    )}

                    {activeTab === 'revenue' && (
                        <div className="mt-4 animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                            <div className="flex flex-col gap-1.5 w-full" ref={revenueDropdownRef}>
                                <label className={`text-[10px] sm:text-xs font-bold uppercase tracking-wide ml-1 transition-colors ${hasBackground ? 'text-white/90 drop-shadow-sm' : 'text-slate-500'}`}>
                                    Tùy chọn tỷ lệ
                                </label>
                                <div className="relative group">
                                    <button
                                        onClick={() => setIsRevenueDropdownOpen(!isRevenueDropdownOpen)}
                                        className={`relative w-full border text-slate-800 text-left text-base sm:text-lg font-bold py-4 px-4 pr-12 rounded-2xl transition-all h-[60px] sm:h-[66px] flex items-center backdrop-blur-md
                                        ${isRevenueDropdownOpen 
                                            ? 'border-primary-500 ring-2 ring-primary-100 z-50 bg-white' 
                                            : hasBackground 
                                                ? 'bg-white/80 border-white/40 hover:bg-white' 
                                                : 'bg-white/90 border-slate-200 hover:border-primary-300 hover:bg-white'}`}
                                    >
                                        {revenueOptions.find(o => o.value === revenueShare)?.label}
                                        <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-400">
                                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className={`w-4 h-4 transition-transform ${isRevenueDropdownOpen ? 'rotate-180 text-primary-500' : ''}`}>
                                                <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
                                            </svg>
                                        </div>
                                    </button>

                                    {isRevenueDropdownOpen && (
                                        <div className="absolute top-[calc(100%+8px)] w-full bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden transition-all z-[100] animate-fade-in-up">
                                            <div className="p-1">
                                                {revenueOptions.map((option) => (
                                                    <div 
                                                        key={option.value}
                                                        onClick={() => {
                                                            setRevenueShare(option.value as any);
                                                            setIsRevenueDropdownOpen(false);
                                                        }}
                                                        className={`flex items-center justify-between px-4 py-3 rounded-xl cursor-pointer transition-colors ${revenueShare === option.value ? 'bg-primary-50 text-primary-700' : 'hover:bg-slate-50 text-slate-700'}`}
                                                    >
                                                        <span className="font-bold">{option.label}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {activeTab === 'convert' && (
                    <div className="md:mt-12 z-30 shrink-0 relative">
                        <SwapButton onClick={handleSwapClick} isSwapping={isSwapping} theme={theme} />
                    </div>
                )}

                {activeTab !== 'revenue' && (
                    <div className={`w-full md:flex-1 transition-all relative ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                        <CurrencyRow
                            label={activeTab === 'calculate' ? "Quy đổi phí sang" : "Quy đổi sang"}
                            amount=""
                            currency={toCurrency}
                            onCurrencyChange={handleToChange}
                            inputPlacement="hidden"
                            isActive={activeDropdown === 'TO'}
                            onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                            onCloseDropdown={() => setActiveDropdown(null)}
                            theme={theme}
                            hasBackgroundImage={hasBackground}
                        />
                    </div>
                )}
                </div>

                <button
                    onClick={onCalculateAndConvert}
                    disabled={loadingState === LoadingState.LOADING}
                    className={`w-full py-3.5 sm:py-4 rounded-2xl text-white font-bold text-base sm:text-lg shadow-xl transition-all transform mt-4 relative z-20
                    ${loadingState === LoadingState.LOADING 
                        ? 'bg-slate-400 cursor-not-allowed opacity-80' 
                        : `bg-gradient-to-r from-primary-600 to-primary-800 hover:-translate-y-1 active:scale-[0.98]`
                    }`}
                >
                    <span className="flex items-center justify-center gap-2">
                        {loadingState === LoadingState.LOADING ? (
                        <>
                            <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                            </svg>
                            Đang xử lý...
                        </>
                        ) : (
                            activeTab === 'revenue' ? 'Tính doanh thu' :
                            activeTab === 'calculate' ? 'Tính toán & Quy đổi' : 'Chuyển đổi ngay'
                        )}
                    </span>
                </button>

                {/* Exchange Rate Badge */}
                {activeTab !== 'revenue' && result && loadingState === LoadingState.SUCCESS && (
                    <div className="flex justify-center -mt-2 animate-fade-in-up relative z-10">
                    <div className="text-xs sm:text-sm font-medium px-4 py-1.5 rounded-full border border-white/60 bg-white/95 backdrop-blur-sm text-slate-500 shadow-sm flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                        {formatExchangeRate(result.exchangeRate, fromCurrency.code, toCurrency.code)}
                    </div>
                    </div>
                )}

                {/* --- RESULTS SECTIONS --- */}
                {activeTab !== 'revenue' && result && loadingState === LoadingState.SUCCESS && (
                    <>
                    {activeTab === 'calculate' && (
                            <div className="flex items-center gap-2 animate-fade-in-up mt-2">
                                <div className="h-px bg-slate-200/50 flex-1"></div>
                                <span className={`text-sm font-extrabold uppercase tracking-widest drop-shadow-sm ${hasBackground ? 'text-white drop-shadow-sm' : 'text-slate-500'}`}>Phí dịch vụ tổng</span>
                                <div className="h-px bg-slate-200/50 flex-1"></div>
                            </div>
                    )}
                    <ResultSection 
                        result={result} 
                        fromCurrency={fromCurrency} 
                        toCurrency={toCurrency} 
                        inputAmount={amount}
                        formatCurrency={formatCurrency}
                        theme={theme}
                        hasBackgroundImage={hasBackground}
                    />
                    </>
                )}

                {activeTab === 'calculate' && stageFeeData && loadingState === LoadingState.SUCCESS && (
                    <div className="animate-fade-in-up pt-2">
