                                    <path d="M12 7.5a2.25 2.25 0 1 0 0 4.5 2.25 2.25 0 0 0 0-4.5Z" />
                                    <path fillRule="evenodd" d="M1.5 4.875C1.5 3.839 2.34 3 3.375 3h17.25c1.035 0 1.875.84 1.875 1.875v9.75c0 1.036-.84 1.875-1.875 1.875H3.375A1.875 1.875 0 0 1 1.5 14.625v-9.75ZM8.25 9.75a3.75 3.75 0 1 1 7.5 0 3.75 3.75 0 0 1-7.5 0ZM18.75 9a.75.75 0 0 0-.75.75v.008c0 .414.336.75.75.75h.008a.75.75 0 0 0 .75-.75V9.75a.75.75 0 0 0-.75-.75h-.008ZM4.5 9.75A.75.75 0 0 1 5.25 9h.008a.75.75 0 0 1 .75.75v.008a.75.75 0 0 1-.75.75H5.25a.75.75 0 0 1-.75-.75V9.75Z" clipRule="evenodd" />
                                    <path d="M2.25 18a.75.75 0 0 0 0 1.5c5.4 0 10.63.722 15.6 2.075 1.19.324 2.4-.558 2.4-1.82V18.75a.75.75 0 0 0-.75-.75H2.25Z" />
                                </svg>
                            </div>

                            <div className="relative z-10 flex flex-col items-center text-center">
                                <div className="flex items-center gap-2 mb-2 bg-white/10 px-3 py-1 rounded-full backdrop-blur-sm">
                                    <img src={vietNamFlagUrl} alt="VND" className="w-5 h-3.5 rounded shadow-sm object-cover" />
                                    <span className="text-xs font-bold uppercase text-white/90 tracking-widest">Thu nhập thực nhận (49%)</span>
                                </div>

                                <div className="my-2">
                                    <span className="text-3xl sm:text-4xl md:text-5xl font-extrabold text-white tracking-tight">
                                        {formatCurrency(revenueResult.netIncome, 'vi-VN', 'VND')}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
          </div>
        </div>
      </div>

      {/* 3. Floating Notes Manager */}
      <NotesManager />

      {/* Footer */}
      <footer className="w-full bg-slate-900/80 backdrop-blur text-slate-400 py-6 mt-auto relative z-10">
        <div className="container mx-auto px-4 text-center">
            <p className="font-semibold text-slate-300 mb-1 tracking-wide text-sm">Powered by ZiQi</p>
            <p className="text-xs opacity-60">Lasted update: {new Date().toLocaleDateString('vi-VN')} </p>
        </div>
      </footer>

      {showHistory && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
             <div 
                className={`absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity duration-300 ${isClosingHistory ? 'opacity-0' : 'opacity-100 animate-fade-in-up'}`} 
                onClick={handleCloseHistory}
            />
             <div className={`bg-white rounded-2xl shadow-2xl w-full max-w-4xl relative z-10 overflow-hidden flex flex-col max-h-[85vh] 
                ${isClosingHistory ? 'animate-fade-out-down' : 'animate-fade-in-up'}`}
             >
                <div className="p-0 flex-1 overflow-hidden flex flex-col min-h-0">
                   <HistorySection 
                        history={filteredHistory} 
                        onSelect={handleHistorySelect} 
                        onClear={clearHistory} 
                        onDeleteItems={deleteHistoryItems}
                        formatCurrency={formatCurrency}
                        onClose={handleCloseHistory}
                   />
                </div>
             </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { useNotes } from '../hooks/useNotes';
import { NoteStatus } from '../types';

export const NotesManager: React.FC = () => {
  const { notes, tags, addNote, updateNoteStatus, deleteNote, deleteNotes, addTag, deleteTag, toggleTagPin } = useNotes();
  const [isOpen, setIsOpen] = useState(false);
  const [isClosing, setIsClosing] = useState(false); // Modal closing state

  // View Mode: 'list' (default), 'add-note', 'add-tag'
  const [viewMode, setViewMode] = useState<'list' | 'add-note' | 'add-tag'>('list');
  const [isSubViewClosing, setIsSubViewClosing] = useState(false); // Sub-view closing state
  const [activeTab, setActiveTab] = useState<string>('all'); 

  // Selection & Delete State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [confirmDelete, setConfirmDelete] = useState<{ isOpen: boolean, ids: string[] }>({ isOpen: false, ids: [] });

  // Gesture Selection Refs
  const longPressTimerRef = useRef<number | null>(null);
  const isDragSelectingRef = useRef(false);
  const startPosRef = useRef<{ x: number, y: number } | null>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const selectionSetRef = useRef<Set<string>>(new Set()); // Mirror state for ref access in event handlers

  // Add Note State
  const [newNoteContent, setNewNoteContent] = useState('');
  const [selectedTagForNewNote, setSelectedTagForNewNote] = useState<string>('');
  const [isTagDropdownOpen, setIsTagDropdownOpen] = useState(false);
  const tagDropdownRef = useRef<HTMLDivElement>(null);

  // Create Tag State
  const [newTagName, setNewTagName] = useState('');
  const [newTagColor, setNewTagColor] = useState('#3b82f6');

  // --- DRAGGABLE BUTTON STATE ---
  const [btnPos, setBtnPos] = useState({ x: 20, y: typeof window !== 'undefined' ? window.innerHeight - 150 : 500 });
  const isDraggingBtn = useRef(false);
  const btnDragOffset = useRef({ x: 0, y: 0 });
  const btnDragStartPos = useRef({ x: 0, y: 0 });
  const hasMovedBtn = useRef(false);

  useEffect(() => {
      // Initial position adjustment to avoid server/client mismatch
      setBtnPos({ x: 30, y: window.innerHeight - 120 });
  }, []);

  // Button Drag Handlers
  const handleBtnPointerDown = (e: React.PointerEvent) => {
    isDraggingBtn.current = true;
    hasMovedBtn.current = false;
    btnDragStartPos.current = { x: e.clientX, y: e.clientY };
    btnDragOffset.current = {
        x: e.clientX - btnPos.x,
        y: e.clientY - btnPos.y
    };
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const handleBtnPointerMove = (e: React.PointerEvent) => {
    if (!isDraggingBtn.current) return;

    const newX = e.clientX - btnDragOffset.current.x;
    const newY = e.clientY - btnDragOffset.current.y;

    // Check if moved significantly (> 5px) to consider it a drag
    if (!hasMovedBtn.current) {
        const dist = Math.hypot(e.clientX - btnDragStartPos.current.x, e.clientY - btnDragStartPos.current.y);
        if (dist > 5) hasMovedBtn.current = true;
    }

    setBtnPos({ x: newX, y: newY });
  };

  const handleBtnPointerUp = (e: React.PointerEvent) => {
    isDraggingBtn.current = false;
    e.currentTarget.releasePointerCapture(e.pointerId);

    // Snap to edge logic
    const screenWidth = window.innerWidth;
    const screenHeight = window.innerHeight;
    const buttonWidth = 56; // w-14

    // Clamp Y to stay on screen
    let finalY = Math.max(20, Math.min(screenHeight - 80, btnPos.y));

    // Snap X to nearest side
    let finalX = btnPos.x;
    const midPoint = screenWidth / 2;

    if (btnPos.x + buttonWidth / 2 < midPoint) {
        finalX = 20; // Snap Left
    } else {
        finalX = screenWidth - buttonWidth - 20; // Snap Right
    }

    setBtnPos({ x: finalX, y: finalY });
  };

  // Dedicated Click Handler: Only fires if we haven't dragged the button
  const handleBtnClick = (e: React.MouseEvent) => {
      if (!hasMovedBtn.current) {
          if(isOpen) handleClose();
          else setIsOpen(true);
      }
  };


  // Handle outside click for Tag Dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (tagDropdownRef.current && !tagDropdownRef.current.contains(event.target as Node)) {
            setIsTagDropdownOpen(false);
        }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Sync ref with state
  useEffect(() => {
      selectionSetRef.current = selectedIds;
  }, [selectedIds]);

  const filteredNotes = activeTab === 'all' 
    ? notes 
    : notes.filter(n => n.tagId === activeTab);

  const getTag = (id: string | null) => tags.find(t => t.id === id);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(() => {
        setIsOpen(false);
        setIsClosing(false);
        setIsSelectionMode(false);
        setViewMode('list'); 
    }, 300); // Match animation duration
  };

  const handleBackToMain = () => {
    setIsSubViewClosing(true);
    setTimeout(() => {
        setViewMode('list');
        setIsSubViewClosing(false);
    }, 300);
  };

  const handleAddNote = () => {
    if (!newNoteContent.trim()) return;
    addNote(newNoteContent, selectedTagForNewNote || null);
    setNewNoteContent('');
    setSelectedTagForNewNote('');
    handleBackToMain();
  };

  const handleCreateTag = () => {
    if (!newTagName.trim()) return;
    addTag(newTagName, newTagColor);
    setNewTagName('');
    setNewTagColor('#3b82f6');
    handleBackToMain();
  };

  // Selection Logic
  const toggleSelectionMode = () => {
    setIsSelectionMode(!isSelectionMode);
    setSelectedIds(new Set());
  };

  const handleCheckboxChange = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  // --- GESTURE LOGIC: Long Press & Drag ---
  const handlePointerDown = (e: React.PointerEvent, id: string) => {
      if (viewMode !== 'list' || confirmDelete.isOpen) return;

      // If already in selection mode, let the click handler deal with toggling
      if (isSelectionMode) return;

      startPosRef.current = { x: e.clientX, y: e.clientY };

      longPressTimerRef.current = window.setTimeout(() => {
          // Long press triggered!
          setIsSelectionMode(true);
          setSelectedIds(new Set([id]));
          isDragSelectingRef.current = true;

          if (navigator.vibrate) navigator.vibrate(50);
      }, 500); // 500ms long press
  };

  useEffect(() => {
    const handleGlobalPointerMove = (e: PointerEvent) => {
        // 1. Check if we should cancel long press due to scrolling
        if (longPressTimerRef.current && startPosRef.current && !isDragSelectingRef.current) {
            const moveX = Math.abs(e.clientX - startPosRef.current.x);
            const moveY = Math.abs(e.clientY - startPosRef.current.y);
            if (moveX > 10 || moveY > 10) {
                clearTimeout(longPressTimerRef.current);
                longPressTimerRef.current = null;
                startPosRef.current = null;
            }
        }

        // 2. Handle Drag Selection
        if (isDragSelectingRef.current) {
            e.preventDefault();
            const element = document.elementFromPoint(e.clientX, e.clientY);
            const noteItem = element?.closest('[data-note-id]');

            if (noteItem) {
                const noteId = noteItem.getAttribute('data-note-id');
                if (noteId && !selectionSetRef.current.has(noteId)) {
                    setSelectedIds(prev => new Set(prev).add(noteId));
                    if (navigator.vibrate) navigator.vibrate(10);
                }
            }
        }
    };

    const handleGlobalPointerUp = () => {
        if (longPressTimerRef.current) {
            clearTimeout(longPressTimerRef.current);
            longPressTimerRef.current = null;
        }
        startPosRef.current = null;
        isDragSelectingRef.current = false;
    };

    window.addEventListener('pointermove', handleGlobalPointerMove, { passive: false });
    window.addEventListener('pointerup', handleGlobalPointerUp);
    window.addEventListener('pointercancel', handleGlobalPointerUp);

    return () => {
        window.removeEventListener('pointermove', handleGlobalPointerMove);
        window.removeEventListener('pointerup', handleGlobalPointerUp);
        window.removeEventListener('pointercancel', handleGlobalPointerUp);
    };
  }, []);
  // ------------------------------------------

  const handleDeleteClick = (ids: string[]) => {
      setConfirmDelete({ isOpen: true, ids });
  };

  const performDelete = () => {
      deleteNotes(confirmDelete.ids);
      setConfirmDelete({ isOpen: false, ids: [] });
      if (isSelectionMode) {
          setSelectedIds(new Set());
          if (filteredNotes.length === confirmDelete.ids.length) {
               setIsSelectionMode(false);
          }
      }
  };

  const statusConfig: Record<NoteStatus, { label: string, badgeClass: string, borderClass: string, containerClass: string, icon: React.ReactNode }> = {
    incomplete: { 
      label: 'Chưa xong', 
      badgeClass: 'text-red-600 bg-red-100',
      borderClass: 'border-red-500', 
      containerClass: 'bg-red-50/30',
      icon: <div className="w-2 h-2 rounded-full bg-red-500" />
    },
    attention: { 
      label: 'Chú ý', 
      badgeClass: 'text-amber-600 bg-amber-100',
      borderClass: 'border-amber-500', 
      containerClass: 'bg-amber-50/30',
      icon: <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3 text-amber-500"><path fillRule="evenodd" d="M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Zm-8-5a.75.75 0 0 1 .75.75v4.5a.75.75 0 0 1-1.5 0v-4.5A.75.75 0 0 1 10 5Zm0 10a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z" clipRule="evenodd" /></svg>
    },
    completed: { 
      label: 'Hoàn thành', 
      badgeClass: 'text-emerald-600 bg-emerald-100',
      borderClass: 'border-emerald-500', 
      containerClass: 'bg-emerald-50/30',
      icon: <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3 text-emerald-500"><path fillRule="evenodd" d="M16.704 4.153a.75.75 0 0 1 .143 1.052l-8 10.5a.75.75 0 0 1-1.127.075l-4.5-4.5a.75.75 0 0 1 1.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 0 1 1.05-.143Z" clipRule="evenodd" /></svg>
    },
    skipped: { 
      label: 'Bỏ qua', 
      badgeClass: 'text-slate-500 bg-slate-200',
      borderClass: 'border-slate-400', 
      containerClass: 'bg-slate-100/50 opacity-75',
      icon: <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3 text-slate-500"><path d="M6.28 5.22a.75.75 0 0 0-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 1 0 1.06 1.06L10 11.06l3.72 3.72a.75.75 0 1 0 1.06-1.06L11.06 10l3.72-3.72a.75.75 0 0 0-1.06-1.06L10 8.94 6.28 5.22Z" /></svg>
    },
  };

  const renderHeader = () => (
    <div className="flex items-center justify-between p-5 border-b border-slate-100 bg-white/50 backdrop-blur-md shrink-0">
        <div className="flex items-center gap-3">
            {viewMode !== 'list' && (
                <button 
                    onClick={handleBackToMain}
                    className="p-2 -ml-2 rounded-full hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5" />
                    </svg>
                </button>
            )}
            <h3 className="text-xl font-extrabold text-slate-800 tracking-tight">
                {viewMode === 'list' ? 'Ghi chú của bạn' : 
                 viewMode === 'add-note' ? 'Thêm ghi chú mới' : 'Tạo thẻ phân loại'}
            </h3>
        </div>

        <div className="flex items-center gap-2">
            {viewMode === 'list' && !isSelectionMode && (
                <>
                    <button 
                        onClick={() => setViewMode('add-tag')}
                        className="p-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors flex items-center gap-2"
                        title="Quản lý thẻ"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M9.568 3H5.25A2.25 2.25 0 0 0 3 5.25v4.318c0 .597.237 1.17.659 1.591l9.581 9.581c.699.699 1.78.872 2.607.33a18.095 18.095 0 0 0 5.223-5.223c.542-.827.369-1.908-.33-2.607L11.16 3.66A2.25 2.25 0 0 0 9.568 3Z" />
                            <path strokeLinecap="round" strokeLinejoin="round" d="M6 6h.008v.008H6V6Z" />
                        </svg>
                        <span className="hidden sm:inline text-xs font-bold uppercase">Thẻ</span>
                    </button>
                    <button 
                        onClick={() => setViewMode('add-note')}
                        className="py-2.5 px-4 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg shadow-indigo-200 transition-all active:scale-95 flex items-center gap-2"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
                        </svg>
                        <span className="text-sm font-bold hidden sm:inline">Thêm mới</span>
                    </button>
                </>
            )}
             {isSelectionMode && (
                <button 
                    onClick={toggleSelectionMode}
                    className="px-4 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-600 text-sm font-bold transition-colors"
                >
                    Hủy chọn
                </button>
            )}

            <div className="w-px h-6 bg-slate-200 mx-1"></div>

            <button 
                onClick={handleClose}
                className="p-2 rounded-full hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors"
            >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M6 18 18 6M6 6l12 12" />
                </svg>
            </button>
        </div>
    </div>
  );

