             >
                {renderHeader()}

                <div className="flex-1 overflow-hidden flex flex-col min-h-0 relative" ref={scrollContainerRef}>
                    {/* --- VIEW: ADD TAG --- */}
                    {viewMode === 'add-tag' && (
