import { useState, useEffect } from 'react';
import { Note, NoteTag, NoteStatus } from '../types';
import { useAuth } from './useAuth';
import { db } from '../services/firebase';
import { collection, onSnapshot, setDoc, doc, deleteDoc, query, orderBy } from 'firebase/firestore';

const DEFAULT_TAGS: NoteTag[] = [
  { id: 'personal', name: 'Cá nhân', color: '#3b82f6', isPinned: false }, // Blue
  { id: 'work', name: 'Công việc', color: '#10b981', isPinned: true },   // Emerald (Pinned by default example)
  { id: 'idea', name: 'Ý tưởng', color: '#f59e0b', isPinned: false },     // Amber
];

export const useNotes = () => {
  const { user } = useAuth();
  const [notes, setNotes] = useState<Note[]>([]);
  const [tags, setTags] = useState<NoteTag[]>(DEFAULT_TAGS);
  const [loading, setLoading] = useState(true);

  // Load data (LocalStorage OR Firebase)
  useEffect(() => {
    if (!user) {
        // LocalStorage Mode
        try {
            const savedNotes = localStorage.getItem('app_notes');
            const savedTags = localStorage.getItem('app_note_tags');

            if (savedNotes) setNotes(JSON.parse(savedNotes));
            else setNotes([]);

            if (savedTags) setTags(JSON.parse(savedTags));
            else setTags(DEFAULT_TAGS);
        } catch (e) {
            console.error("Failed to load notes from local", e);
        }
        setLoading(false);
        return;
    }

    if (!db) return;

    // Firebase Mode - Realtime Listeners
    setLoading(true);

    // Notes Listener
    const notesRef = collection(db, 'users', user.uid, 'notes');
    const qNotes = query(notesRef); // Ordering can be done client-side or add orderBy('timestamp', 'desc')

    const unsubNotes = onSnapshot(qNotes, (snapshot) => {
        const fetchedNotes = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Note));
        // Sort by timestamp desc locally
        fetchedNotes.sort((a, b) => b.timestamp - a.timestamp);
        setNotes(fetchedNotes);
    });

    // Tags Listener
    const tagsRef = collection(db, 'users', user.uid, 'tags');
    const unsubTags = onSnapshot(tagsRef, (snapshot) => {
        if (snapshot.empty) {
             // If no tags in DB, keep default (or maybe save defaults to DB? kept simple here)
             setTags(DEFAULT_TAGS); 
        } else {
             const fetchedTags = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as NoteTag));
             setTags(fetchedTags);
        }
        setLoading(false);
    });

    return () => {
        unsubNotes();
        unsubTags();
    };
  }, [user]);

  // Helper to sync to DB if logged in, else LocalStorage
  const saveNoteToStorage = async (note: Note) => {
      if (user && db) {
          await setDoc(doc(db, 'users', user.uid, 'notes', note.id), note);
      } else {
          // Local update handled by state + effect is tricky with mixed modes.
          // Simplest pattern for hybrid: Update State -> Side effect saves to storage
      }
  };

  // PERSISTENCE EFFECT FOR LOCAL STORAGE ONLY
  useEffect(() => {
      if (!user) {
          localStorage.setItem('app_notes', JSON.stringify(notes));
      }
  }, [notes, user]);

  useEffect(() => {
      if (!user) {
          localStorage.setItem('app_note_tags', JSON.stringify(tags));
      }
  }, [tags, user]);


  // Note Actions
  const addNote = async (content: string, tagId: string | null) => {
    const newNote: Note = {
      id: Date.now().toString(),
      content,
      timestamp: Date.now(),
      status: 'incomplete',
      tagId
    };

    if (user && db) {
        await setDoc(doc(db, 'users', user.uid, 'notes', newNote.id), newNote);
    } else {
        setNotes(prev => [newNote, ...prev]);
    }
  };

  const updateNoteStatus = async (id: string, status: NoteStatus) => {
    if (user && db) {
        const note = notes.find(n => n.id === id);
        if (note) {
            await setDoc(doc(db, 'users', user.uid, 'notes', id), { ...note, status });
        }
    } else {
        setNotes(prev => prev.map(n => n.id === id ? { ...n, status } : n));
    }
  };

  const deleteNote = async (id: string) => {
    if (user && db) {
        await deleteDoc(doc(db, 'users', user.uid, 'notes', id));
    } else {
        setNotes(prev => prev.filter(n => n.id !== id));
    }
  };

  const deleteNotes = async (ids: string[]) => {
      if (user && db) {
          // Batch delete not implemented for simplicity, loop delete
          ids.forEach(id => deleteDoc(doc(db, 'users', user.uid, 'notes', id)));
      } else {
          setNotes(prev => prev.filter(n => !ids.includes(n.id)));
      }
  };

  // Tag Actions
  const addTag = async (name: string, color: string) => {
    const newTag: NoteTag = {
      id: Date.now().toString(),
      name,
      color,
      isPinned: false
    };
    if (user && db) {
        await setDoc(doc(db, 'users', user.uid, 'tags', newTag.id), newTag);
    } else {
        setTags(prev => [...prev, newTag]);
    }
  };

  const deleteTag = async (id: string) => {
    if (user && db) {
        await deleteDoc(doc(db, 'users', user.uid, 'tags', id));
    } else {
        setTags(prev => prev.filter(t => t.id !== id));
    }
  };

  const toggleTagPin = async (id: string) => {
    if (user && db) {
        const tag = tags.find(t => t.id === id);
        if (tag) {
             await setDoc(doc(db, 'users', user.uid, 'tags', id), { ...tag, isPinned: !tag.isPinned });
        }
    } else {
        setTags(prev => prev.map(t => t.id === id ? { ...t, isPinned: !t.isPinned } : t));
    }
  };

  // Sort tags: Pinned first
  const sortedTags = [...tags].sort((a, b) => {
      if (a.isPinned && !b.isPinned) return -1;
      if (!a.isPinned && b.isPinned) return 1;
      return 0; 
  });

  return {
    notes,
    tags: sortedTags, 
    addNote,
    updateNoteStatus,
    deleteNote,
    deleteNotes,
    addTag,
    deleteTag,
    toggleTagPin,
    loading
  };
};

import { useState, useCallback, useEffect } from 'react';
import { Currency, ConversionResult, LoadingState, ConversionHistoryItem } from '../types';
import { DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from '../constants';
import { convertCurrencyApi } from '../services/geminiService';
import { useAuth } from './useAuth';
import { db } from '../services/firebase';
import { collection, onSnapshot, setDoc, doc, deleteDoc, writeBatch } from 'firebase/firestore';

export const useCurrencyConverter = () => {
  const { user } = useAuth();
  const [amount, setAmount] = useState<string>('100000');
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');
  const [isSwapping, setIsSwapping] = useState(false);
  const [history, setHistory] = useState<ConversionHistoryItem[]>([]);

  // Load history logic (Firebase vs Local)
  useEffect(() => {
    if (!user) {
        // LocalStorage Mode
        try {
            const savedHistory = localStorage.getItem('conversion_history');
            if (savedHistory) {
                const parsed = JSON.parse(savedHistory);
                const migrated = parsed.map((item: any) => ({
                    ...item,
                    type: item.type || 'convert'
                }));
                setHistory(migrated);
            } else {
                setHistory([]);
            }
        } catch (e) {
            console.error("Failed to load history locally", e);
        }
        return;
    }

    if (!db) return;

    // Firebase Mode
    const historyRef = collection(db, 'users', user.uid, 'history');
    const unsubscribe = onSnapshot(historyRef, (snapshot) => {
        const fetchedHistory = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as ConversionHistoryItem));
        // Sort by timestamp desc
        fetchedHistory.sort((a, b) => b.timestamp - a.timestamp);
        // Limit to 50 items locally for view
        setHistory(fetchedHistory.slice(0, 50));
    });

    return () => unsubscribe();
  }, [user]);

  // Sync to LocalStorage if not logged in
  useEffect(() => {
      if (!user) {
          localStorage.setItem('conversion_history', JSON.stringify(history));
      }
  }, [history, user]);


  const addToHistory = async (
      currentAmount: number, 
      source: Currency, 
      target: Currency, 
      converted: number, 
      type: 'convert' | 'calculate' | 'revenue', 
      originalSalary?: number,
      revenueDetails?: { shareType: 'all' | 'cv' | 'job', stageRevenue: number, totalRevenue: number }
  ) => {
    const newItem: ConversionHistoryItem = {
      id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      inputAmount: currentAmount,
      fromCurrency: source,
      toCurrency: target,
      convertedAmount: converted,
      type: type,
      originalSalary: originalSalary,
      revenueDetails: revenueDetails
    };

    if (user && db) {
        // Firebase Add
        await setDoc(doc(db, 'users', user.uid, 'history', newItem.id), newItem);

        // Optional: Clean up old items in cloud function, but here we just append.
        // Client side limit is handled in the listener.
    } else {
        // LocalStorage Add logic
        const existingIndex = history.findIndex(item => 
            item.inputAmount === newItem.inputAmount && 
            item.fromCurrency.code === newItem.fromCurrency.code && 
            item.toCurrency.code === newItem.toCurrency.code &&
            item.type === newItem.type &&
            item.originalSalary === newItem.originalSalary &&
            item.revenueDetails?.shareType === newItem.revenueDetails?.shareType
        );

        let updatedHistory = [...history];
        if (existingIndex > -1) updatedHistory.splice(existingIndex, 1);
        updatedHistory.unshift(newItem);
        updatedHistory = updatedHistory.slice(0, 50); 
        setHistory(updatedHistory);
    }
  };

  const clearHistory = async () => {
    if (user && db) {
        // Deleting all docs in a collection from client is expensive (one by one), 
        // usually better to delete specific items. For "Clear All", we iterate.
        const batch = writeBatch(db);
        history.forEach(item => {
            const ref = doc(db, 'users', user.uid, 'history', item.id);
            batch.delete(ref);
        });
        await batch.commit();
    } else {
        setHistory([]);
    }
  };

  const deleteHistoryItems = async (ids: string[]) => {
    if (user && db) {
        const batch = writeBatch(db);
        ids.forEach(id => {
            const ref = doc(db, 'users', user.uid, 'history', id);
            batch.delete(ref);
        });
        await batch.commit();
    } else {
        const updatedHistory = history.filter(item => !ids.includes(item.id));
        setHistory(updatedHistory);
    }
  };

  const selectHistoryItem = (item: ConversionHistoryItem) => {
    setAmount(item.inputAmount.toString());
    setFromCurrency(item.fromCurrency);
    setToCurrency(item.toCurrency);
  };

  const resetResult = useCallback(() => {
    setResult(null);
    setErrorMsg('');
    setLoadingState(LoadingState.IDLE);
  }, []);

  const executeConversion = async (currentAmount: number, source: Currency, target: Currency, type: 'convert' | 'calculate', originalSalary?: number) => {
    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');

    try {
      const data = await convertCurrencyApi(currentAmount, source.code, target.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);

      // Add to history on success
      addToHistory(currentAmount, source, target, data.convertedAmount, type, originalSalary);
    } catch (err) {
      setErrorMsg("Có lỗi xảy ra khi lấy tỷ giá. Vui lòng thử lại.");
      setLoadingState(LoadingState.ERROR);
      setResult(null); 
    }
  };

  const handleConvert = useCallback((amountOverride?: string, type: 'convert' | 'calculate' = 'convert', originalSalary?: number) => {
    const valueToCheck = amountOverride !== undefined ? amountOverride : amount;
    const numAmount = parseFloat(valueToCheck);

    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }
    executeConversion(numAmount, fromCurrency, toCurrency, type, originalSalary);
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = (currentType: 'convert' | 'calculate' = 'convert') => {
    setIsSwapping(true);
    setTimeout(() => setIsSwapping(false), 500); 

    const newFrom = toCurrency;
    const newTo = fromCurrency;

    setFromCurrency(newFrom);
    setToCurrency(newTo);

    if (result) {
        const numAmount = parseFloat(amount);
        if (!isNaN(numAmount) && numAmount > 0) {
            executeConversion(numAmount, newFrom, newTo, currentType);
        } else {
            setResult(null);
        }
    } else {
        setResult(null); 
    }
  };

  return {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult, addToHistory
  };
};

