import { useState, useEffect } from 'react';
import { Note, NoteTag, NoteStatus } from '../types';
import { useAuth } from './useAuth';
import { db } from '../services/firebase';
import { collection, onSnapshot, setDoc, doc, deleteDoc, query } from 'firebase/firestore';

const DEFAULT_TAGS: NoteTag[] = [
  { id: 'personal', name: 'Cá nhân', color: '#3b82f6', isPinned: false }, // Blue
  { id: 'work', name: 'Công việc', color: '#10b981', isPinned: true },   // Emerald
  { id: 'idea', name: 'Ý tưởng', color: '#f59e0b', isPinned: false },     // Amber
];

export const useNotes = () => {
  const { user } = useAuth();
  const [notes, setNotes] = useState<Note[]>([]);
  const [tags, setTags] = useState<NoteTag[]>(DEFAULT_TAGS);

  // -- EFFECT: LOAD DATA (Hybrid: LocalStorage or Firestore) --
  useEffect(() => {
    // 1. Nếu chưa đăng nhập: Dùng LocalStorage
    if (!user) {
        try {
            const savedNotes = localStorage.getItem('app_notes');
            const savedTags = localStorage.getItem('app_note_tags');

            if (savedNotes) setNotes(JSON.parse(savedNotes));
            else setNotes([]);

            if (savedTags) setTags(JSON.parse(savedTags));
            else setTags(DEFAULT_TAGS);
        } catch (e) {
            console.error("Failed to load local notes", e);
        }
        return;
    }

    // 2. Nếu đã đăng nhập: Dùng Firebase Firestore
    if (!db) return;

    // Listen to Notes
    const notesRef = collection(db, 'users', user.uid, 'notes');
    const unsubNotes = onSnapshot(notesRef, (snapshot) => {
        const fetchedNotes = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Note));
        // Sort client-side
        fetchedNotes.sort((a, b) => b.timestamp - a.timestamp);
        setNotes(fetchedNotes);
    });

    // Listen to Tags
    const tagsRef = collection(db, 'users', user.uid, 'tags');
    const unsubTags = onSnapshot(tagsRef, (snapshot) => {
        if (snapshot.empty) {
             setTags(DEFAULT_TAGS);
        } else {
             const fetchedTags = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as NoteTag));
             setTags(fetchedTags);
        }
    });

    return () => {
        unsubNotes();
        unsubTags();
    };
  }, [user]);

  // -- LOCAL STORAGE SYNC (Only when logged out) --
  useEffect(() => {
      if (!user) {
          localStorage.setItem('app_notes', JSON.stringify(notes));
      }
  }, [notes, user]);

  useEffect(() => {
      if (!user) {
          localStorage.setItem('app_note_tags', JSON.stringify(tags));
      }
  }, [tags, user]);

  // -- ACTIONS --

  const addNote = async (content: string, tagId: string | null) => {
    const newNote: Note = {
      id: Date.now().toString(),
      content,
      timestamp: Date.now(),
      status: 'incomplete',
      tagId
    };

    if (user && db) {
        await setDoc(doc(db, 'users', user.uid, 'notes', newNote.id), newNote);
    } else {
        setNotes(prev => [newNote, ...prev]);
    }
  };

  const updateNoteStatus = async (id: string, status: NoteStatus) => {
    if (user && db) {
        const noteToUpdate = notes.find(n => n.id === id);
        if (noteToUpdate) {
            await setDoc(doc(db, 'users', user.uid, 'notes', id), { ...noteToUpdate, status });
        }
    } else {
        setNotes(prev => prev.map(n => n.id === id ? { ...n, status } : n));
    }
  };

  const deleteNote = async (id: string) => {
    if (user && db) {
        await deleteDoc(doc(db, 'users', user.uid, 'notes', id));
    } else {
        setNotes(prev => prev.filter(n => n.id !== id));
    }
  };

  const deleteNotes = async (ids: string[]) => {
    if (user && db) {
        ids.forEach(id => deleteDoc(doc(db, 'users', user.uid, 'notes', id)));
    } else {
        setNotes(prev => prev.filter(n => !ids.includes(n.id)));
    }
  };

  const addTag = async (name: string, color: string) => {
    const newTag: NoteTag = {
      id: Date.now().toString(),
      name,
      color,
      isPinned: false
    };
    if (user && db) {
        await setDoc(doc(db, 'users', user.uid, 'tags', newTag.id), newTag);
    } else {
        setTags(prev => [...prev, newTag]);
    }
  };

  const deleteTag = async (id: string) => {
    if (user && db) {
        await deleteDoc(doc(db, 'users', user.uid, 'tags', id));
    } else {
        setTags(prev => prev.filter(t => t.id !== id));
    }
  };

  const toggleTagPin = async (id: string) => {
    if (user && db) {
        const tag = tags.find(t => t.id === id);
        if (tag) {
             await setDoc(doc(db, 'users', user.uid, 'tags', id), { ...tag, isPinned: !tag.isPinned });
        }
    } else {
        setTags(prev => prev.map(t => t.id === id ? { ...t, isPinned: !t.isPinned } : t));
    }
  };

  // Sort tags: Pinned first
  const sortedTags = [...tags].sort((a, b) => {
      if (a.isPinned && !b.isPinned) return -1;
      if (!a.isPinned && b.isPinned) return 1;
      return 0; 
  });

  return {
    notes,
    tags: sortedTags, 
    addNote,
    updateNoteStatus,
    deleteNote,
    deleteNotes,
    addTag,
    deleteTag,
    toggleTagPin
  };
};

import { useState, useCallback, useEffect } from 'react';
import { Currency, ConversionResult, LoadingState, ConversionHistoryItem } from '../types';
import { DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from '../constants';
import { convertCurrencyApi } from '../services/geminiService';
import { useAuth } from './useAuth';
import { db } from '../services/firebase';
import { collection, onSnapshot, setDoc, doc, writeBatch } from 'firebase/firestore';

export const useCurrencyConverter = () => {
  const { user } = useAuth();
  const [amount, setAmount] = useState<string>('100000');
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');
  const [isSwapping, setIsSwapping] = useState(false);
  const [history, setHistory] = useState<ConversionHistoryItem[]>([]);

  // -- EFFECT: LOAD HISTORY --
  useEffect(() => {
    // 1. Local Storage Mode
    if (!user) {
        try {
            const savedHistory = localStorage.getItem('conversion_history');
            if (savedHistory) {
                const parsed = JSON.parse(savedHistory);
                const migrated = parsed.map((item: any) => ({
                    ...item,
                    type: item.type || 'convert'
                }));
                setHistory(migrated);
            } else {
                setHistory([]);
            }
        } catch (e) {
            console.error("Failed to load local history", e);
        }
        return;
    }

    // 2. Firebase Mode
    if (!db) return;

    const historyRef = collection(db, 'users', user.uid, 'history');
    const unsubscribe = onSnapshot(historyRef, (snapshot) => {
        const fetchedHistory = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as ConversionHistoryItem));
        fetchedHistory.sort((a, b) => b.timestamp - a.timestamp);
        // Limit local view to 50 items
        setHistory(fetchedHistory.slice(0, 50));
    });

    return () => unsubscribe();
  }, [user]);

  // Sync to LocalStorage if NOT logged in
  useEffect(() => {
      if (!user) {
          localStorage.setItem('conversion_history', JSON.stringify(history));
      }
  }, [history, user]);

  const addToHistory = async (
      currentAmount: number, 
      source: Currency, 
      target: Currency, 
      converted: number, 
      type: 'convert' | 'calculate' | 'revenue', 
      originalSalary?: number,
      revenueDetails?: { shareType: 'all' | 'cv' | 'job', stageRevenue: number, totalRevenue: number }
  ) => {
    const newItem: ConversionHistoryItem = {
      id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      inputAmount: currentAmount,
      fromCurrency: source,
      toCurrency: target,
      convertedAmount: converted,
      type: type,
      originalSalary: originalSalary,
      revenueDetails: revenueDetails
    };

    if (user && db) {
        // Cloud Save
        await setDoc(doc(db, 'users', user.uid, 'history', newItem.id), newItem);
    } else {
        // Local Save logic (dedupe, unshift, limit)
        const existingIndex = history.findIndex(item => 
            item.inputAmount === newItem.inputAmount && 
            item.fromCurrency.code === newItem.fromCurrency.code && 
            item.toCurrency.code === newItem.toCurrency.code &&
            item.type === newItem.type &&
            item.originalSalary === newItem.originalSalary
        );

        let updatedHistory = [...history];
        if (existingIndex > -1) updatedHistory.splice(existingIndex, 1);
        updatedHistory.unshift(newItem);
        updatedHistory = updatedHistory.slice(0, 50); 
        setHistory(updatedHistory);
    }
  };

  const clearHistory = async () => {
    if (user && db) {
        const batch = writeBatch(db);
        history.forEach(item => {
            batch.delete(doc(db, 'users', user.uid, 'history', item.id));
        });
        await batch.commit();
    } else {
        setHistory([]);
    }
  };

  const deleteHistoryItems = async (ids: string[]) => {
    if (user && db) {
        const batch = writeBatch(db);
        ids.forEach(id => {
            batch.delete(doc(db, 'users', user.uid, 'history', id));
        });
        await batch.commit();
    } else {
        const updatedHistory = history.filter(item => !ids.includes(item.id));
        setHistory(updatedHistory);
    }
  };

  const selectHistoryItem = (item: ConversionHistoryItem) => {
    setAmount(item.inputAmount.toString());
    setFromCurrency(item.fromCurrency);
    setToCurrency(item.toCurrency);
  };

  const resetResult = useCallback(() => {
    setResult(null);
    setErrorMsg('');
    setLoadingState(LoadingState.IDLE);
  }, []);

  const executeConversion = async (currentAmount: number, source: Currency, target: Currency, type: 'convert' | 'calculate', originalSalary?: number) => {
    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');

    try {
      const data = await convertCurrencyApi(currentAmount, source.code, target.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);

      addToHistory(currentAmount, source, target, data.convertedAmount, type, originalSalary);
    } catch (err) {
      setErrorMsg("Có lỗi xảy ra khi lấy tỷ giá. Vui lòng thử lại.");
      setLoadingState(LoadingState.ERROR);
      setResult(null); 
    }
  };

  const handleConvert = useCallback((amountOverride?: string, type: 'convert' | 'calculate' = 'convert', originalSalary?: number) => {
    const valueToCheck = amountOverride !== undefined ? amountOverride : amount;
    const numAmount = parseFloat(valueToCheck);

    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }
    executeConversion(numAmount, fromCurrency, toCurrency, type, originalSalary);
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = (currentType: 'convert' | 'calculate' = 'convert') => {
    setIsSwapping(true);
    setTimeout(() => setIsSwapping(false), 500); 

    const newFrom = toCurrency;
    const newTo = fromCurrency;

    setFromCurrency(newFrom);
    setToCurrency(newTo);

    if (result) {
        const numAmount = parseFloat(amount);
        if (!isNaN(numAmount) && numAmount > 0) {
            executeConversion(numAmount, newFrom, newTo, currentType);
        } else {
            setResult(null);
        }
    } else {
        setResult(null); 
    }
  };

  return {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult, addToHistory
  };
};

import React, { useState, useRef, useEffect } from 'react';
import { useNotes } from '../hooks/useNotes';
import { NoteStatus } from '../types';

export const NotesManager: React.FC = () => {
  const { notes, tags, addNote, updateNoteStatus, deleteNote, deleteNotes, addTag, deleteTag, toggleTagPin } = useNotes();
  const [isOpen, setIsOpen] = useState(false);
  const [isClosing, setIsClosing] = useState(false);

  // View Mode: 'list' (default), 'add-note', 'add-tag'
  const [viewMode, setViewMode] = useState<'list' | 'add-note' | 'add-tag'>('list');
  const [isSubViewClosing, setIsSubViewClosing] = useState(false);
  const [activeTab, setActiveTab] = useState<string>('all'); 

  // Selection States
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [confirmDelete, setConfirmDelete] = useState<{ isOpen: boolean, ids: string[] }>({ isOpen: false, ids: [] });
  const [tagToDelete, setTagToDelete] = useState<string | null>(null);

  // Gesture Refs
  const longPressTimerRef = useRef<number | null>(null);
  const isDragSelectingRef = useRef(false);
  const startPosRef = useRef<{ x: number, y: number } | null>(null);
  const selectionSetRef = useRef<Set<string>>(new Set());

  // Form State
  const [newNoteContent, setNewNoteContent] = useState('');
  const [selectedTagForNewNote, setSelectedTagForNewNote] = useState<string>('');
  const [isTagDropdownOpen, setIsTagDropdownOpen] = useState(false);
  const tagDropdownRef = useRef<HTMLDivElement>(null);
  const [newTagName, setNewTagName] = useState('');
  const [newTagColor, setNewTagColor] = useState('#3b82f6');

  // Draggable Button State
  const [btnPos, setBtnPos] = useState({ x: 20, y: typeof window !== 'undefined' ? window.innerHeight - 120 : 500 });
  const isDraggingBtn = useRef(false);
  const btnDragOffset = useRef({ x: 0, y: 0 });
  const btnDragStartPos = useRef({ x: 0, y: 0 });
  const hasMovedBtn = useRef(false);

  useEffect(() => {
      setBtnPos({ x: 30, y: window.innerHeight - 120 });
  }, []);

  // Button Logic
  const handleBtnPointerDown = (e: React.PointerEvent) => {
    isDraggingBtn.current = true;
    hasMovedBtn.current = false;
    btnDragStartPos.current = { x: e.clientX, y: e.clientY };
    btnDragOffset.current = { x: e.clientX - btnPos.x, y: e.clientY - btnPos.y };
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const handleBtnPointerMove = (e: React.PointerEvent) => {
    if (!isDraggingBtn.current) return;
    e.preventDefault();
    const newX = e.clientX - btnDragOffset.current.x;
    const newY = e.clientY - btnDragOffset.current.y;
    if (!hasMovedBtn.current) {
        const dist = Math.hypot(e.clientX - btnDragStartPos.current.x, e.clientY - btnDragStartPos.current.y);
        if (dist > 6) hasMovedBtn.current = true;
    }
    if (hasMovedBtn.current) setBtnPos({ x: newX, y: newY });
  };

  const handleBtnPointerUp = (e: React.PointerEvent) => {
    if (!isDraggingBtn.current) return;
    isDraggingBtn.current = false;
    e.currentTarget.releasePointerCapture(e.pointerId);
    if (hasMovedBtn.current) {
        const screenWidth = window.innerWidth;
        const screenHeight = window.innerHeight;
        let finalY = Math.max(20, Math.min(screenHeight - 80, btnPos.y));
        let finalX = btnPos.x + 28 < screenWidth / 2 ? 20 : screenWidth - 76;
        setBtnPos({ x: finalX, y: finalY });
    }
  };

  const handleBtnClick = (e: React.MouseEvent) => {
      e.stopPropagation();
      if (hasMovedBtn.current) return;
      if (isOpen) handleClose();
      else setIsOpen(true);
  };

  // Sync ref
  useEffect(() => { selectionSetRef.current = selectedIds; }, [selectedIds]);

  const filteredNotes = activeTab === 'all' ? notes : notes.filter(n => n.tagId === activeTab);
  const getTag = (id: string | null) => tags.find(t => t.id === id);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(() => {
        setIsOpen(false);
        setIsClosing(false);
        setIsSelectionMode(false);
        setViewMode('list'); 
    }, 300);
  };

  const handleBackToMain = () => {
    setIsSubViewClosing(true);
    setTimeout(() => {
        setViewMode('list');
        setIsSubViewClosing(false);
    }, 300);
  };

  const handleAddNote = () => {
    if (!newNoteContent.trim()) return;
    addNote(newNoteContent, selectedTagForNewNote || null);
    setNewNoteContent('');
    setSelectedTagForNewNote('');
    handleBackToMain();
  };

  const handleCreateTag = () => {
    if (!newTagName.trim()) return;
    addTag(newTagName, newTagColor);
    setNewTagName('');
    setNewTagColor('#3b82f6');
  };

  // Selection & Gestures
  const toggleSelectionMode = () => {
    setIsSelectionMode(!isSelectionMode);
    setSelectedIds(new Set());
  };

  const handleCheckboxChange = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) newSelected.delete(id); else newSelected.add(id);
    setSelectedIds(newSelected);
  };

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
      if (viewMode !== 'list' || confirmDelete.isOpen || isSelectionMode) return;
      startPosRef.current = { x: e.clientX, y: e.clientY };
      longPressTimerRef.current = window.setTimeout(() => {
          setIsSelectionMode(true);
          setSelectedIds(new Set([id]));
          isDragSelectingRef.current = true;
          if (navigator.vibrate) navigator.vibrate(50);
      }, 500);
  };

  useEffect(() => {
    const handleGlobalPointerMove = (e: PointerEvent) => {
        if (longPressTimerRef.current && startPosRef.current && !isDragSelectingRef.current) {
            if (Math.abs(e.clientX - startPosRef.current.x) > 10 || Math.abs(e.clientY - startPosRef.current.y) > 10) {
                clearTimeout(longPressTimerRef.current);
                longPressTimerRef.current = null;
            }
        }
        if (isDragSelectingRef.current) {
            e.preventDefault();
            const element = document.elementFromPoint(e.clientX, e.clientY);
            const noteItem = element?.closest('[data-note-id]');
            if (noteItem) {
                const noteId = noteItem.getAttribute('data-note-id');
                if (noteId && !selectionSetRef.current.has(noteId)) {
                    setSelectedIds(prev => new Set(prev).add(noteId));
                    if (navigator.vibrate) navigator.vibrate(10);
                }
            }
        }
    };
    const handleGlobalPointerUp = () => {
        if (longPressTimerRef.current) clearTimeout(longPressTimerRef.current);
        startPosRef.current = null;
        isDragSelectingRef.current = false;
    };
    window.addEventListener('pointermove', handleGlobalPointerMove, { passive: false });
    window.addEventListener('pointerup', handleGlobalPointerUp);
    window.addEventListener('pointercancel', handleGlobalPointerUp);
    return () => {
        window.removeEventListener('pointermove', handleGlobalPointerMove);
        window.removeEventListener('pointerup', handleGlobalPointerUp);
        window.removeEventListener('pointercancel', handleGlobalPointerUp);
    };
  }, []);

  const performDelete = () => {
      deleteNotes(confirmDelete.ids);
      setConfirmDelete({ isOpen: false, ids: [] });
      if (isSelectionMode && filteredNotes.length === confirmDelete.ids.length) setIsSelectionMode(false);
      else if (isSelectionMode) setSelectedIds(new Set());
  };

  const statusConfig: Record<NoteStatus, { label: string, badgeClass: string, icon: React.ReactNode }> = {
    incomplete: { label: 'Chưa xong', badgeClass: 'text-red-600 bg-red-100', icon: <div className="w-2 h-2 rounded-full bg-red-500" /> },
    attention: { label: 'Chú ý', badgeClass: 'text-amber-600 bg-amber-100', icon: <div className="w-2 h-2 rounded-full bg-amber-500" /> },
    completed: { label: 'Hoàn thành', badgeClass: 'text-emerald-600 bg-emerald-100', icon: <div className="w-2 h-2 rounded-full bg-emerald-500" /> },
    skipped: { label: 'Bỏ qua', badgeClass: 'text-slate-500 bg-slate-200', icon: <div className="w-2 h-2 rounded-full bg-slate-500" /> },
  };

  const renderHeader = () => (
    <div className="flex items-center justify-between px-5 py-4 border-b border-slate-100 bg-white/50 backdrop-blur-md shrink-0">
        <div className="flex items-center gap-3">
            {viewMode !== 'list' && (
                <button onClick={handleBackToMain} className="p-2 -ml-2 rounded-full hover:bg-slate-100 text-slate-500">
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5" /></svg>
                </button>
            )}
            <h3 className="text-xl font-extrabold text-slate-800 tracking-tight">
                {viewMode === 'list' ? 'Ghi chú' : viewMode === 'add-note' ? 'Thêm mới' : 'Thẻ phân loại'}
            </h3>
        </div>
        <div className="flex items-center gap-2">
            {viewMode === 'list' && !isSelectionMode && (
                <>
                    <button onClick={() => setViewMode('add-tag')} className="p-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-600">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M9.568 3H5.25A2.25 2.25 0 0 0 3 5.25v4.318c0 .597.237 1.17.659 1.591l9.581 9.581c.699.699 1.78.872 2.607.33a18.095 18.095 0 0 0 5.223-5.223c.542-.827.369-1.908-.33-2.607L11.16 3.66A2.25 2.25 0 0 0 9.568 3Z" /><path strokeLinecap="round" strokeLinejoin="round" d="M6 6h.008v.008H6V6Z" /></svg>
                    </button>
                    <button onClick={() => setViewMode('add-note')} className="py-2.5 px-4 rounded-xl bg-indigo-600 text-white font-bold text-sm shadow-lg shadow-indigo-200 flex items-center gap-2">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg>
                        <span className="hidden sm:inline">Viết ghi chú</span>
                    </button>
                </>
            )}
             {isSelectionMode && <button onClick={toggleSelectionMode} className="px-4 py-2 rounded-xl bg-slate-100 font-bold text-sm text-slate-600">Hủy</button>}
            <button onClick={handleClose} className="p-2 rounded-full hover:bg-slate-100 text-slate-400"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18 18 6M6 6l12 12" /></svg></button>
        </div>
    </div>
  );

  return (
    <>
      {/* Draggable Button */}
      <div 
        className="fixed z-[60] touch-none select-none cursor-pointer"
        style={{ left: btnPos.x, top: btnPos.y, transition: isDraggingBtn.current ? 'none' : 'all 0.4s cubic-bezier(0.18, 0.89, 0.32, 1.28)' }}
        onClick={handleBtnClick} onPointerDown={handleBtnPointerDown} onPointerMove={handleBtnPointerMove} onPointerUp={handleBtnPointerUp}
      >
        <button className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-transform active:scale-95 border-2 border-white/50 backdrop-blur-md pointer-events-none ${isOpen ? 'bg-slate-800 text-white rotate-90 scale-90' : 'bg-gradient-to-br from-indigo-500 to-purple-600 text-white'}`}>
          {isOpen ? <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18 18 6M6 6l12 12" /></svg> : <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7"><path strokeLinecap="round" strokeLinejoin="round" d="m16.862 4.487 1.687-1.688a1.875 1.875 0 1 1 2.652 2.652L10.582 16.07a4.5 4.5 0 0 1-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 0 1 1.13-1.897l8.932-8.931Zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0 1 15.75 21H5.25A2.25 2.25 0 0 1 3 18.75V8.25A2.25 2.25 0 0 1 5.25 6H10" /></svg>}
        </button>
      </div>

      {/* Modal / Full Screen Container */}
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center md:p-4">
             <div className={`absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity duration-300 ${isClosing ? 'opacity-0' : 'opacity-100'}`} onClick={handleClose}/>

             <div className={`
                bg-white/95 backdrop-blur-xl w-full md:max-w-5xl md:rounded-3xl shadow-2xl flex flex-col relative z-10 border border-white/60
                h-[92dvh] md:h-[85vh] rounded-t-3xl md:rounded-3xl transition-transform duration-300
                ${isClosing ? 'translate-y-full md:translate-y-10 md:opacity-0' : 'translate-y-0 animate-fade-in-up'}
             `}>
                {renderHeader()}

                <div className="flex-1 overflow-hidden flex flex-col min-h-0 relative bg-slate-50/50">
                    {/* ADD TAG VIEW */}
                    {viewMode === 'add-tag' && (
                        <div className={`p-5 flex flex-col gap-6 overflow-y-auto custom-scrollbar ${isSubViewClosing ? 'opacity-0' : 'opacity-100'}`}>
                            <div className="max-w-3xl mx-auto w-full">
                                <h4 className="text-sm font-extrabold text-slate-800 uppercase tracking-wide mb-4">Tạo thẻ mới</h4>
                                <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
                                    <div className="mb-4">
                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Tên thẻ</label>
                                        <input type="text" placeholder="Ví dụ: Quan trọng..." className="w-full text-sm px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:border-indigo-500 bg-slate-50" value={newTagName} onChange={(e) => setNewTagName(e.target.value)} autoFocus />
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <input type="color" className="w-12 h-12 rounded-xl cursor-pointer border-2 border-white shadow-sm" value={newTagColor} onChange={(e) => setNewTagColor(e.target.value)} />
                                        <button onClick={handleCreateTag} className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-200">Tạo ngay</button>
                                    </div>
                                </div>
                            </div>
                            <div className="max-w-3xl mx-auto w-full pb-6">
                                <h4 className="text-sm font-extrabold text-slate-800 uppercase tracking-wide mb-4">Danh sách ({tags.length})</h4>
                                <div className="space-y-2">
                                    {tags.map(tag => (
