                                        }`}
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                                            <path strokeLinecap="round" strokeLinejoin="round" d="m14.74 9-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 0 1-2.244 2.077H8.084a2.25 2.25 0 0 1-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 0 0-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 0 1 3.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 0 0-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 0 0-7.5 0" />
                                        </svg>
                                        Xóa {selectedIds.size} ghi chú
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>
             </div>
        </div>
      )}

      {/* Delete Confirmation Modal (NOTES) */}
      {confirmDelete.isOpen && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
              <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-[2px]" onClick={() => setConfirmDelete({ ...confirmDelete, isOpen: false })}></div>
              <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm relative z-10 animate-pulse-soft">
                  <div className="text-center mb-6">
                      <div className="w-14 h-14 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-4 text-red-500 ring-4 ring-red-50">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z" />
                        </svg>
                      </div>
                      <h4 className="text-xl font-bold text-slate-800 mb-2">Xác nhận xóa</h4>
                      <p className="text-slate-500">
                          {confirmDelete.ids.length > 1 
                              ? `Bạn có chắc chắn muốn xóa ${confirmDelete.ids.length} ghi chú đã chọn không?`
                              : "Bạn có chắc chắn muốn xóa ghi chú này không?"
                          }
                      </p>
                  </div>
                  <div className="flex gap-3">
                      <button 
                        onClick={() => setConfirmDelete({ ...confirmDelete, isOpen: false })}
                        className="flex-1 py-3 rounded-xl font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors"
                      >
                          Hủy bỏ
                      </button>
                      <button 
                        onClick={performDelete}
                        className="flex-1 py-3 rounded-xl font-bold text-white bg-red-500 hover:bg-red-600 transition-colors shadow-lg shadow-red-200"
                      >
                          Xóa ngay
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Delete Confirmation Modal (TAGS) */}
      {tagToDelete && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center p-4">
              <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-[2px]" onClick={() => setTagToDelete(null)}></div>
              <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm relative z-10 animate-pulse-soft">
                  <div className="text-center mb-6">
                      <div className="w-14 h-14 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-4 text-amber-500 ring-4 ring-amber-50">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9 3.75h.008v.008H12v-.008Z" /> 
                            <path strokeLinecap="round" strokeLinejoin="round" d="m15 11.25-3-3m0 0-3 3m3-3v7.5" />
                        </svg>
                      </div>
                      <h4 className="text-xl font-bold text-slate-800 mb-2">Xóa thẻ phân loại?</h4>
                      <p className="text-slate-500 text-sm">
                          Thẻ <strong>"{getTag(tagToDelete)?.name}"</strong> sẽ bị xóa vĩnh viễn. Các ghi chú thuộc thẻ này sẽ không bị xóa nhưng sẽ mất phân loại.
                      </p>
                  </div>
                  <div className="flex gap-3">
                      <button 
                        onClick={() => setTagToDelete(null)}
                        className="flex-1 py-3 rounded-xl font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors"
                      >
                          Hủy bỏ
                      </button>
                      <button 
                        onClick={confirmTagDeletion}
                        className="flex-1 py-3 rounded-xl font-bold text-white bg-red-500 hover:bg-red-600 transition-colors shadow-lg shadow-red-200"
                      >
                          Xóa thẻ
                      </button>
                  </div>
              </div>
          </div>
      )}
    </>
  );
};

import { useState, useCallback, useEffect } from 'react';
import { Currency, ConversionResult, LoadingState, ConversionHistoryItem } from '../types';
import { DEFAULT_SOURCE_CURRENCY, DEFAULT_TARGET_CURRENCY } from '../constants';
import { convertCurrencyApi } from '../services/geminiService';

export const useCurrencyConverter = () => {
  const [amount, setAmount] = useState<string>('100000');
  const [fromCurrency, setFromCurrency] = useState<Currency>(DEFAULT_SOURCE_CURRENCY);
  const [toCurrency, setToCurrency] = useState<Currency>(DEFAULT_TARGET_CURRENCY);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string>('');
  const [isSwapping, setIsSwapping] = useState(false);
  const [history, setHistory] = useState<ConversionHistoryItem[]>([]);

  // Load history from local storage on mount
  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('conversion_history');
      if (savedHistory) {
        const parsed = JSON.parse(savedHistory);
        // Migration support for old data without 'type'
        const migrated = parsed.map((item: any) => ({
            ...item,
            type: item.type || 'convert'
        }));
        setHistory(migrated);
      }
    } catch (e) {
      console.error("Failed to load history", e);
    }
  }, []);

  const saveHistory = (newHistory: ConversionHistoryItem[]) => {
    setHistory(newHistory);
    localStorage.setItem('conversion_history', JSON.stringify(newHistory));
  };

  const addToHistory = (
      currentAmount: number, 
      source: Currency, 
      target: Currency, 
      converted: number, 
      type: 'convert' | 'calculate' | 'revenue', 
      originalSalary?: number,
      revenueDetails?: { shareType: 'all' | 'cv' | 'job', stageRevenue: number, totalRevenue: number }
  ) => {
    const newItem: ConversionHistoryItem = {
      id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      inputAmount: currentAmount,
      fromCurrency: source,
      toCurrency: target,
      convertedAmount: converted,
      type: type,
      originalSalary: originalSalary,
      revenueDetails: revenueDetails
    };

    // Check if an identical conversion exists
    const existingIndex = history.findIndex(item => 
        item.inputAmount === newItem.inputAmount && 
        item.fromCurrency.code === newItem.fromCurrency.code && 
        item.toCurrency.code === newItem.toCurrency.code &&
        item.type === newItem.type &&
        item.originalSalary === newItem.originalSalary &&
        item.revenueDetails?.shareType === newItem.revenueDetails?.shareType
    );

    let updatedHistory = [...history];

    if (existingIndex > -1) {
        // Remove the existing item so the new one can go to the top
        updatedHistory.splice(existingIndex, 1);
    }

    // Add new item to the beginning
    updatedHistory.unshift(newItem);

    // Limit to 50 items total
    updatedHistory = updatedHistory.slice(0, 50); 

    saveHistory(updatedHistory);
  };

  const clearHistory = () => {
    saveHistory([]);
  };

  const deleteHistoryItems = (ids: string[]) => {
    const updatedHistory = history.filter(item => !ids.includes(item.id));
    saveHistory(updatedHistory);
  };

  const selectHistoryItem = (item: ConversionHistoryItem) => {
    setAmount(item.inputAmount.toString());
    setFromCurrency(item.fromCurrency);
    setToCurrency(item.toCurrency);
  };

  const resetResult = useCallback(() => {
    setResult(null);
    setErrorMsg('');
    setLoadingState(LoadingState.IDLE);
  }, []);

  const executeConversion = async (currentAmount: number, source: Currency, target: Currency, type: 'convert' | 'calculate' | 'revenue', originalSalary?: number) => {
    setLoadingState(LoadingState.LOADING);
    setErrorMsg('');

    try {
      const data = await convertCurrencyApi(currentAmount, source.code, target.code);
      setResult(data);
      setLoadingState(LoadingState.SUCCESS);

      // Add to history on success
      addToHistory(currentAmount, source, target, data.convertedAmount, type, originalSalary);
    } catch (err) {
      setErrorMsg("Có lỗi xảy ra khi lấy tỷ giá. Vui lòng thử lại.");
      setLoadingState(LoadingState.ERROR);
      setResult(null); 
    }
  };

  const handleConvert = useCallback((amountOverride?: string, type: 'convert' | 'calculate' | 'revenue' = 'convert', originalSalary?: number) => {
    const valueToCheck = amountOverride !== undefined ? amountOverride : amount;
    const numAmount = parseFloat(valueToCheck);

    if (isNaN(numAmount) || numAmount <= 0) {
      setErrorMsg("Vui lòng nhập số tiền hợp lệ");
      return;
    }
    executeConversion(numAmount, fromCurrency, toCurrency, type, originalSalary);
  }, [amount, fromCurrency, toCurrency]);

  const handleSwap = (currentType: 'convert' | 'calculate' | 'revenue' = 'convert') => {
    setIsSwapping(true);
    setTimeout(() => setIsSwapping(false), 500); 

    const newFrom = toCurrency;
    const newTo = fromCurrency;

    setFromCurrency(newFrom);
    setToCurrency(newTo);

    if (result) {
        const numAmount = parseFloat(amount);
        if (!isNaN(numAmount) && numAmount > 0) {
            executeConversion(numAmount, newFrom, newTo, currentType);
        } else {
            setResult(null);
        }
    } else {
        setResult(null); 
    }
  };

  return {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult, addToHistory
  };
};

import React, { useRef, useEffect, useState, useMemo, ReactNode } from 'react';
import { POPULAR_CURRENCIES as CURRENCY_LIST } from '../constants';
import { Currency, ThemeColor } from '../types';

interface CurrencyRowProps {
  label: string;
  amount: number | string;
  currency: Currency;
  onAmountChange?: (value: string) => void;
  onCurrencyChange: (currency: Currency) => void;
  readOnly?: boolean;
  isActive?: boolean;
  onToggleDropdown?: () => void;
  onCloseDropdown?: () => void;
  inputPlacement?: 'left' | 'right' | 'hidden';
  autoFocus?: boolean;
  theme: ThemeColor;
  headerAction?: ReactNode;
  error?: string; // Prop for error message
  onEnter?: () => void; // New prop for handling Enter key
  hasBackgroundImage?: boolean;
}

export const CurrencyRow: React.FC<CurrencyRowProps> = ({
  label, amount, currency, onAmountChange, onCurrencyChange,
  readOnly = false, isActive = false, onToggleDropdown, onCloseDropdown,
  inputPlacement = 'left', autoFocus = false, headerAction, error, onEnter, hasBackgroundImage
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const amountInputRef = useRef<HTMLInputElement>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    if (autoFocus && amountInputRef.current) {
      amountInputRef.current.focus();
    }
  }, [autoFocus]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        if (isActive && onCloseDropdown) onCloseDropdown();
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [isActive, onCloseDropdown]);

  useEffect(() => {
    if (isActive) {
      const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) || window.innerWidth < 768;

      if (!isMobile) {
        setTimeout(() => searchInputRef.current?.focus(), 50);
      }
    } else {
      setSearchQuery('');
    }
  }, [isActive]);

  const displayCurrencies = useMemo(() => {
    let list = [...CURRENCY_LIST];
    const currentIndex = list.findIndex(c => c.code === currency.code);
    if (currentIndex > -1) {
      const [selected] = list.splice(currentIndex, 1);
      list.unshift(selected);
    }
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      return list.filter((c) => 
        c.code.toLowerCase().includes(query) || 
        c.name.toLowerCase().includes(query)
      );
    }
    return list;
  }, [currency.code, searchQuery]);

  const { groupSeparator, decimalSeparator } = useMemo(() => {
    try {
      const parts = new Intl.NumberFormat(currency.locale).formatToParts(1000.1);
      return {
        groupSeparator: parts.find(p => p.type === 'group')?.value || ',',
        decimalSeparator: parts.find(p => p.type === 'decimal')?.value || '.'
      };
    } catch (e) { return { groupSeparator: ',', decimalSeparator: '.' }; }
  }, [currency.locale]);

  const displayValue = useMemo(() => {
    if (amount === '' || amount === undefined || amount === null) return '';
    const parts = amount.toString().split('.');
    const integerFormatted = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, groupSeparator);
    return parts.length > 1 ? `${integerFormatted}${decimalSeparator}${parts[1]}` : integerFormatted;
  }, [amount, groupSeparator, decimalSeparator]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!onAmountChange) return;
    let value = e.target.value;
    if (value === '') { onAmountChange(''); return; }
    if (decimalSeparator === ',' && value.endsWith('.')) value = value.slice(0, -1) + ',';
    const groupSepRegex = new RegExp(groupSeparator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
    let cleanValue = value.replace(groupSepRegex, '').replace(new RegExp(decimalSeparator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'), '.').replace(/[^0-9.]/g, '');
    const parts = cleanValue.split('.');
    if (parts.length > 2) cleanValue = parts[0] + '.' + parts.slice(1).join('');
    onAmountChange(cleanValue);
  };

  const renderSelectorButton = () => (
    <button
      onClick={(e) => { e.stopPropagation(); if (onToggleDropdown) onToggleDropdown(); }}
      className={`flex items-center gap-2 px-2 py-3 sm:px-3 sm:py-4 hover:bg-white/40 transition-colors group outline-none shrink-0
        ${inputPlacement === 'hidden' ? 'w-full justify-between rounded-2xl' : ''}
        ${inputPlacement === 'left' ? 'rounded-r-2xl border-l border-slate-100/50' : ''}
        ${inputPlacement === 'right' ? 'rounded-l-2xl border-r border-slate-100/50' : ''}
      `}
    >
      <div className="flex items-center gap-2">
        <img src={currency.flag} alt={currency.code} className="w-6 h-4 sm:w-7 sm:h-5 object-cover rounded shadow-sm border border-slate-100" />
        <span className="text-base sm:text-lg font-bold text-slate-700 leading-none">{currency.code}</span>
      </div>
      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className={`w-3 h-3 sm:w-3.5 sm:h-3.5 text-slate-400 transition-transform ${isActive ? `rotate-180 text-primary-500` : ''}`}><path strokeLinecap="round" strokeLinejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" /></svg>
    </button>
  );

  const renderInput = () => (
    <div className="flex-1 p-2 w-full h-full relative flex items-center">
      <input
        ref={amountInputRef}
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={handleInputChange}
        onFocus={(e) => e.target.select()}
        onKeyDown={(e) => {
            if (e.key === 'Enter' && onEnter) {
                e.currentTarget.blur(); // Blur to hide keyboard on mobile
                onEnter();
            }
        }}
        readOnly={readOnly}
        className={`w-full h-full px-2 bg-transparent border-none outline-none text-xl sm:text-2xl font-bold placeholder-slate-300 transition-colors 
            ${error ? 'text-red-600 placeholder-red-300' : 'text-slate-800'}`}
        placeholder="0"
        autoComplete="off"
      />

      {/* Warning Icon Inside Input */}
      {error && (
        <div className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-red-500 animate-pulse">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-6 h-6">
                <path fillRule="evenodd" d="M2.25 12c0-5.385 4.365-9.75 9.75-9.75s9.75 4.365 9.75 9.75-4.365 9.75-9.75 9.75S2.25 17.385 2.25 12ZM12 8.25a.75.75 0 0 1 .75.75v3.75a.75.75 0 0 1-1.5 0V9a.75.75 0 0 1 .75-.75Zm0 8.25a.75.75 0 1 0 0-1.5.75.75 0 0 0 0 1.5Z" clipRule="evenodd" />
            </svg>
        </div>
      )}
    </div>
  );

  return (
    <div className="flex flex-col gap-0 w-full" ref={containerRef}>
      {/* Fixed height (h-8 = 32px) ensures alignment regardless of button presence */}
      <div className="flex items-center justify-between ml-1 h-8">
        <label className={`text-[10px] sm:text-xs font-bold uppercase tracking-wide transition-colors ${error ? 'text-red-500' : 'text-slate-500'}`}>
            {label}
        </label>
        {headerAction && <div>{headerAction}</div>}
      </div>

      <div onClick={() => !readOnly && !isActive && amountInputRef.current?.focus()}
        className={`
            relative flex items-center border rounded-2xl transition-all h-[60px] sm:h-[66px] cursor-text bg-white/70 backdrop-blur-sm
            ${isActive 
                ? `border-primary-500 ring-2 ring-primary-100 z-50 bg-white` 
                : error 
                    ? 'border-red-500 ring-4 ring-red-50 bg-red-50/10 z-20' 
                    : 'border-slate-200 hover:border-primary-300 hover:bg-white'}
        `}>

        {inputPlacement === 'left' && <>{renderInput()}{renderSelectorButton()}</>}
        {inputPlacement === 'right' && <>{renderSelectorButton()}{renderInput()}</>}
        {inputPlacement === 'hidden' && renderSelectorButton()}

        <div className={`absolute top-[calc(100%+8px)] w-full sm:w-72 bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden transition-all z-[100] 
            ${inputPlacement === 'right' ? 'left-0 origin-top-left' : 'right-0 origin-top-right'}
            ${isActive ? 'opacity-100 scale-100 visible' : 'opacity-0 scale-95 invisible'}`}>
            <div className="p-3 border-b border-slate-100"><input ref={searchInputRef} type="text" className={`w-full px-3 py-2 border rounded-lg bg-slate-50 text-sm outline-none focus:border-primary-500`} placeholder="Tìm kiếm..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onClick={(e) => e.stopPropagation()} /></div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {displayCurrencies.map((c) => (
                <div key={c.code} onClick={(e) => { e.stopPropagation(); onCurrencyChange(c); onCloseDropdown?.(); }} className={`flex items-center gap-3 px-3 py-2.5 rounded-lg cursor-pointer ${c.code === currency.code ? `bg-primary-50 text-primary-700` : 'hover:bg-slate-50'}`}>
                  <img src={c.flag} className="w-6 h-4 object-cover rounded" /><div className="flex flex-col"><span className="text-sm font-bold">{c.code}</span><span className="text-xs opacity-70 truncate max-w-[150px]">{c.name}</span></div>
                  {c.code === currency.code && <div className="ml-auto"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="m4.5 12.75 6 6 9-13.5" /></svg></div>}
                </div>
              ))}
              {displayCurrencies.length === 0 && <div className="p-4 text-center text-sm text-slate-400 italic">Không tìm thấy kết quả</div>}
            </div>
        </div>
      </div>

      {/* Error Message Below Input */}
      {error && (
        <div className="flex items-center gap-1.5 mt-1.5 ml-1 animate-fade-in-up">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3.5 h-3.5 text-red-500">
                <path fillRule="evenodd" d="M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Zm-8-5a.75.75 0 0 1 .75.75v4.5a.75.75 0 0 1-1.5 0v-4.5A.75.75 0 0 1 10 5Zm0 10a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z" clipRule="evenodd" />
            </svg>
            <span className="text-[11px] sm:text-xs font-semibold text-red-500">{error}</span>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { ConversionResult, Currency, ThemeColor } from '../types';
import { CopyButton } from './CopyButton';

interface ResultSectionProps {
  result: ConversionResult;
  fromCurrency: Currency;
  toCurrency: Currency;
  inputAmount: string;
  formatCurrency: (val: number, locale: string, currencyCode: string) => string;
  theme: ThemeColor;
  hasBackgroundImage?: boolean;
}

export const ResultSection: React.FC<ResultSectionProps> = ({ result, fromCurrency, toCurrency, inputAmount, formatCurrency, hasBackgroundImage }) => {
  // Safe parsing to avoid NaN display
  const safeInputAmount = React.useMemo(() => {
    const parsed = parseFloat(inputAmount);
    return isNaN(parsed) ? 0 : parsed;
  }, [inputAmount]);

  const formattedSource = formatCurrency(safeInputAmount, fromCurrency.locale, fromCurrency.code);
  const formattedTarget = formatCurrency(result.convertedAmount, toCurrency.locale, toCurrency.code);

  return (
    <div className="animate-fade-in-up space-y-4 pt-2">
      <div className="grid md:grid-cols-2 gap-4">
        {/* Source Currency Card */}
        <div className="p-4 sm:p-5 rounded-2xl border border-white/50 bg-white/60 backdrop-blur-sm flex flex-col justify-between h-full group/card">
            <div>
              <div className="flex items-center gap-2 mb-2 opacity-70">
                  <img src={fromCurrency.flag} alt={fromCurrency.code} className="w-6 h-4 sm:w-8 sm:h-6 rounded shadow-sm object-cover" />
                  <span className="text-xs sm:text-sm font-bold uppercase text-slate-500">Nguồn tiền</span>
              </div>
              <div className="flex items-start justify-between gap-3">
                <div className="text-xl sm:text-2xl md:text-3xl font-bold break-words mb-1 text-slate-700 leading-tight">
                    {formattedSource}
                </div>
                <CopyButton text={formattedSource} />
              </div>
            </div>
            <div className="mt-4 pt-4 border-t border-slate-200/50">
                 <div className="flex items-center justify-between mb-2">
                    <p className="text-[10px] sm:text-xs font-semibold text-slate-400 uppercase">Bằng chữ</p>
                    <CopyButton 
                        text={result.textSource} 
                        className="bg-white/80 border-slate-200 text-slate-400 hover:text-slate-600 hover:border-slate-300"
                    />
                 </div>
                 <p className="text-sm italic font-medium text-slate-600 leading-relaxed min-h-[1.5rem]">{result.textSource}</p>
            </div>
        </div>

        {/* Target Currency Card */}
        <div className={`p-4 sm:p-5 rounded-2xl border border-primary-100/50 bg-gradient-to-br from-primary-50/70 to-white/70 backdrop-blur-sm shadow-sm flex flex-col justify-between h-full relative overflow-hidden group/card`}>
            <div className={`absolute -right-4 -top-4 opacity-10 text-primary-900 pointer-events-none`}>
                <svg xmlns="http://www.w3.org/2000/svg" fill="currentColor" viewBox="0 0 24 24" className="w-24 h-24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm.31-8.86c-1.77-.45-2.34-.94-2.34-1.67 0-.84.79-1.43 2.1-1.43 1.38 0 1.9.66 1.94 1.64h1.71c-.05-1.34-.87-2.57-2.49-2.95V5h-2.93v2.63c-1.71.47-2.77 1.64-2.77 2.81 0 1.7 1.3 2.53 3.53 3.03 1.91.42 2.31.97 2.31 1.72 0 .86-.81 1.5-2.2 1.5-1.54 0-2.17-.79-2.26-1.8H6.6c.11 1.63 1.05 2.72 2.65 3.08V20h2.93v-2.72c1.76-.43 3-1.6 3-2.92 0-1.86-1.5-2.68-3.87-3.22z"/></svg>
            </div>
            <div className="relative z-10">
              <div className="flex items-center gap-2 mb-2">
                  <img src={toCurrency.flag} alt={toCurrency.code} className="w-6 h-4 sm:w-8 sm:h-6 rounded shadow-sm object-cover" />
                  <span className={`text-xs sm:text-sm font-bold text-primary-500 uppercase`}>Quy đổi được</span>
              </div>
              <div className="flex items-start justify-between gap-3">
                <div className={`text-2xl sm:text-3xl md:text-4xl font-extrabold text-primary-700 break-words mb-1 tracking-tight leading-tight`}>
                    {formattedTarget}
                </div>
                <CopyButton 
                  text={formattedTarget} 
                  className="bg-white/80 border-primary-200 text-primary-500 hover:text-primary-700 hover:border-primary-300"
                />
              </div>
            </div>
            <div className={`mt-4 pt-4 border-t border-primary-200/50 relative z-10`}>
                 <div className="flex items-center justify-between mb-2">
                    <p className={`text-[10px] sm:text-xs font-semibold text-primary-400 uppercase`}>Bằng chữ</p>
                    <CopyButton 
                      text={result.textTarget}
                      className="bg-white/80 border-primary-100 text-primary-400 hover:text-primary-600 hover:border-primary-200"
                    />
                 </div>
                 <p className={`text-base italic font-bold text-primary-800 leading-relaxed min-h-[1.5rem]`}>{result.textTarget}</p>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { CurrencyRow } from './components/CurrencyRow';
import { Header } from './components/Header';
import { SwapButton } from './components/SwapButton';
import { ResultSection } from './components/ResultSection';
import { DenominationSelector } from './components/DenominationSelector';
import { HistorySection } from './components/HistorySection';
import { ThemeSelector } from './components/ThemeSelector';
import { TabSelector } from './components/TabSelector';
import { NotesManager } from './components/NotesManager';
import { useCurrencyConverter } from './hooks/useCurrencyConverter';
import { LoadingState, ThemeColor, Currency, ConversionHistoryItem } from './types';
import { THEME_COLORS, DEFAULT_SOURCE_CURRENCY } from './constants';
import { generatePalette, extractDominantColor, compressImage } from './utils/themeUtils';
import { getReadFunction } from './utils/currencyTextFormatter';
import { CopyButton } from './components/CopyButton';

const App: React.FC = () => {
  const {
    amount, setAmount, fromCurrency, setFromCurrency, toCurrency, setToCurrency,
    loadingState, result, errorMsg, isSwapping, handleConvert, handleSwap,
    history, clearHistory, deleteHistoryItems, selectHistoryItem, resetResult, addToHistory
  } = useCurrencyConverter();

  const [activeDropdown, setActiveDropdown] = useState<'FROM' | 'TO' | null>(null);
  const [theme, setTheme] = useState<ThemeColor>('blue');
  const [showHistory, setShowHistory] = useState(false);
  const [isClosingHistory, setIsClosingHistory] = useState(false); // New state for history closing animation

  // Background Image State
  const [backgroundImage, setBackgroundImage] = useState<string | null>(null);

  // States for Calculation & Revenue Mode
  const [activeTab, setActiveTab] = useState<'convert' | 'calculate' | 'revenue'>('convert');
  const [salaryAmount, setSalaryAmount] = useState<string>('');
  const [calcType, setCalcType] = useState<'probation' | 'official'>('official');

  // New State for Revenue Options
  const [revenueShare, setRevenueShare] = useState<'all' | 'cv' | 'job'>('all');
  const [isRevenueDropdownOpen, setIsRevenueDropdownOpen] = useState(false);
  const revenueDropdownRef = useRef<HTMLDivElement>(null);

  const [revenueResult, setRevenueResult] = useState<{
      totalRevenue: number;
      stageRevenue: number;
      netIncome: number;
  } | null>(null);

  const revenueOptions = [
    { value: 'all', label: 'Tất cả (100%)' },
    { value: 'cv', label: 'Có CV (70%)' },
    { value: 'job', label: 'Nắm Job (30%)' }
  ];

  // Filter history based on active tab
  const filteredHistory = useMemo(() => {
    return history.filter(item => item.type === activeTab);
  }, [history, activeTab]);

  const applyTheme = (colorIdOrHex: string) => {
    let hex = colorIdOrHex;
    const preset = THEME_COLORS.find(t => t.id === colorIdOrHex);
    if (preset) hex = preset.hex;

    const palette = generatePalette(hex);
    const root = document.documentElement;
    Object.entries(palette).forEach(([shade, value]) => {
      root.style.setProperty(`--color-primary-${shade}`, value);
    });
  };

  // Initial load of theme and background
  useEffect(() => {
    const savedTheme = localStorage.getItem('app_theme');
    const savedBg = localStorage.getItem('app_bg');

    if (savedBg) {
        setBackgroundImage(savedBg);
    }

    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      applyTheme('blue');
    }
  }, []);

  const handleThemeChange = (newTheme: ThemeColor) => {
    setTheme(newTheme);
    localStorage.setItem('app_theme', newTheme);
    applyTheme(newTheme);
  };

  const handleBackgroundUpload = async (file: File) => {
      if (!file) return;

      try {
          // Compress image to avoid LocalStorage quota limit
          const base64String = await compressImage(file);

          setBackgroundImage(base64String);

          try {
              localStorage.setItem('app_bg', base64String);
          } catch (e) {
              console.error("LocalStorage quota exceeded", e);
              alert("Ảnh nền quá lớn để lưu tự động. Ảnh sẽ chỉ hiển thị trong phiên làm việc hiện tại.");
          }

          // Auto extract color and set theme
          try {
              const dominantColor = await extractDominantColor(base64String);
              setTheme(dominantColor);
              localStorage.setItem('app_theme', dominantColor);
              applyTheme(dominantColor);
          } catch (e) {
              console.error("Could not extract color", e);
          }
      } catch (error) {
          console.error("Error processing background image", error);
          alert("Có lỗi xảy ra khi xử lý ảnh.");
      }
  };

  const handleRemoveBackground = () => {
    setBackgroundImage(null);
    localStorage.removeItem('app_bg');
  };

  // Handle click outside for Revenue Dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (revenueDropdownRef.current && !revenueDropdownRef.current.contains(event.target as Node)) {
            setIsRevenueDropdownOpen(false);
        }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleAmountChange = (val: string) => {
    if (activeTab === 'calculate' || activeTab === 'revenue') {
        setSalaryAmount(val);
    } else {
        setAmount(val);
    }
    resetResult();
    setRevenueResult(null); // Reset revenue result on input change
  };

  const handleFromChange = (currency: Currency) => {
    setFromCurrency(currency);
    resetResult();
  };

  const handleToChange = (currency: Currency) => {
    setToCurrency(currency);
    resetResult();
  };

  const handleDenominationSelect = (newAmount: string) => {
    handleAmountChange(newAmount);
  };

  const formatCurrency = (val: number, locale: string, currencyCode: string) => {
    try {
        if (isNaN(val)) return `0 ${currencyCode}`;
        return new Intl.NumberFormat(locale, {
          style: 'currency',
          currency: currencyCode,
          maximumFractionDigits: 0,
          minimumFractionDigits: 0
        }).format(val);
    } catch (e) { return `${val} ${currencyCode}`; }
  };

  const formatExchangeRate = (rate: number, from: string, to: string) => {
     const precision = rate < 0.01 ? 6 : 4;
     const formattedRate = new Intl.NumberFormat('en-US', { maximumFractionDigits: precision }).format(rate);
     return `1 ${from} ≈ ${formattedRate} ${to}`;
  };

  const handleCloseHistory = () => {
      setIsClosingHistory(true);
      setTimeout(() => {
          setShowHistory(false);
          setIsClosingHistory(false);
      }, 300); // 300ms matches standard CSS transition time
  };

  const handleHistorySelect = (item: ConversionHistoryItem) => {
    selectHistoryItem(item);

    if (item.type === 'calculate' && item.originalSalary) {
        setSalaryAmount(item.originalSalary.toString());
        handleConvert(item.inputAmount.toString(), activeTab, item.originalSalary);
    } 
    else if (item.type === 'revenue' && item.revenueDetails) {
        setSalaryAmount(item.inputAmount.toString());
        setRevenueShare(item.revenueDetails.shareType);
        // Recalculate directly to show result
        setRevenueResult({
            totalRevenue: item.revenueDetails.totalRevenue,
            stageRevenue: item.revenueDetails.stageRevenue,
            netIncome: item.convertedAmount
        });
    }
    else {
        handleConvert(item.inputAmount.toString(), activeTab);
    }

    handleCloseHistory();
  };

  const handleSwapClick = () => {
    handleSwap(activeTab);
  };

  // Main Calculation Logic
  const onCalculateAndConvert = () => {
    if (activeTab === 'revenue') {
        // Revenue Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
             setRevenueResult(null);
             return;
        }

        // 1. Calculate Base Fee (Revenue) from Salary
        const feeMultiplier = calcType === 'probation' ? 0.75 : 0.60;
        const baseRevenue = Math.floor(salary * feeMultiplier);

        // 2. Apply Revenue Share Option
        let shareMultiplier = 1;
        if (revenueShare === 'cv') shareMultiplier = 0.7;
        else if (revenueShare === 'job') shareMultiplier = 0.3;

        const totalRevenue = Math.floor(baseRevenue * shareMultiplier);

        // 3. Calculate Derived Values
        const stageRevenue = Math.floor(totalRevenue / 2);
        const netIncome = Math.floor(totalRevenue * 0.49);

        setRevenueResult({
            totalRevenue,
            stageRevenue,
            netIncome
        });

        // Add to history
        addToHistory(
            salary,
            DEFAULT_SOURCE_CURRENCY, // Assume VND
            DEFAULT_SOURCE_CURRENCY, // Assume VND
            netIncome,
            'revenue',
            undefined,
            {
                shareType: revenueShare,
                stageRevenue: stageRevenue,
                totalRevenue: totalRevenue
            }
        );

    } else if (activeTab === 'calculate') {
        // Calculate Fee Logic
        const salary = parseFloat(salaryAmount.replace(/,/g, ''));
        if (isNaN(salary) || salary <= 0) {
            handleConvert('0', activeTab); 
            return;
        }
        const multiplier = calcType === 'probation' ? 0.75 : 0.60;
        const fee = Math.floor(salary * multiplier);
        setAmount(fee.toString()); // Sync state
        handleConvert(fee.toString(), activeTab, salary); // Trigger conversion
    } else {
        // Standard Convert Logic
        handleConvert(amount, activeTab);
    }
  };

  const renderHistoryButton = (
    <button 
        onClick={() => setShowHistory(true)}
        className={`flex items-center gap-1.5 text-xs font-bold hover:text-primary-700 px-2 py-1 rounded-md transition-all 
        ${backgroundImage ? 'text-primary-600 bg-white/90' : 'text-primary-600 bg-primary-50 hover:bg-primary-100'}`}
    >
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3.5 h-3.5">
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
        </svg>
        Lịch sử
    </button>
  );

  // Calculate Stage Fee Values (only available when result is present)
  const stageFeeData = useMemo(() => {
    if (activeTab !== 'calculate' || !result || !amount) return null;

    const totalFeeSource = parseFloat(amount);
    if (isNaN(totalFeeSource)) return null;

    const stageSource = Math.floor(totalFeeSource / 2);
    // Calculate target using the same rate logic
    const stageTarget = Math.ceil(stageSource * result.exchangeRate);

    const formattedSource = formatCurrency(stageSource, fromCurrency.locale, fromCurrency.code);
    const formattedTarget = formatCurrency(stageTarget, toCurrency.locale, toCurrency.code);

    return {
        source: stageSource,
        target: stageTarget,
        formattedSource,
        formattedTarget,
        textSource: getReadFunction(fromCurrency.code, stageSource),
        textTarget: getReadFunction(toCurrency.code, stageTarget)
    };
  }, [activeTab, result, amount, fromCurrency, toCurrency]);

  const vietNamFlagUrl = "https://flagcdn.com/w80/vn.png";
  const hasBackground = !!backgroundImage;

  return (
    <div 
        className={`min-h-screen font-sans text-slate-800 selection:bg-primary-200 flex flex-col relative transition-all duration-500`}
        style={{
            backgroundColor: backgroundImage ? 'transparent' : '#f1f5f9',
            backgroundImage: backgroundImage ? `url(${backgroundImage})` : 'none',
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            backgroundAttachment: 'fixed',
            backgroundRepeat: 'no-repeat'
        }}
    >

      {/* 1. Global Blurred Background */}
      <div 
        className="fixed inset-0 z-0 transition-all duration-500 bg-slate-100"
        style={{
            backgroundImage: backgroundImage ? `url(${backgroundImage})` : 'none',
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            backgroundAttachment: 'fixed',
            filter: backgroundImage ? 'blur(20px) brightness(0.9)' : 'none',
            transform: 'scale(1.05)'
        }}
      />

      <div className="fixed top-3 right-3 sm:top-5 sm:right-5 z-[100] animate-fade-in-up">
        <ThemeSelector 
            currentTheme={theme} 
            onThemeChange={handleThemeChange} 
            onBackgroundUpload={handleBackgroundUpload}
            onRemoveBackground={handleRemoveBackground}
            currentBackground={backgroundImage}
        />
      </div>

      <div className="flex-1 flex items-center justify-center p-3 sm:p-4 relative z-20">
        {/* 2. Main Card with Optimized Border/Background */}
        <div 
            className={`w-full max-w-5xl rounded-3xl relative flex flex-col my-2 mb-8 transition-all duration-300 shadow-2xl
            ${!hasBackground 
                ? 'bg-white/95 backdrop-blur-sm border border-white/60 shadow-slate-900/10' 
                : 'border border-white/10 ring-1 ring-white/20 shadow-black/20'}`} 
            style={{
                backgroundImage: hasBackground ? `url(${backgroundImage})` : 'none',
                backgroundSize: 'cover',
                backgroundPosition: 'center',
            }}
        >
          {/* Internal overlay */}
          {hasBackground && <div className="absolute inset-0 bg-black/5 z-0 pointer-events-none rounded-3xl"></div>}

          <div className="relative z-10">
            <Header theme={theme} onShowHistory={() => {}} />

            <div className="p-4 sm:p-8 space-y-6 relative flex-1">

                <div className="animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                    <TabSelector 
                        activeTab={activeTab} 
                        onTabChange={(tab) => { setActiveTab(tab); resetResult(); setAmount(''); setSalaryAmount(''); setRevenueResult(null); }} 
                        theme={theme} 
                    />
                </div>

                {activeTab === 'convert' && (
                    <div className="animate-fade-in-up" style={{ animationDelay: '150ms' }}>
                    <DenominationSelector 
                        currency={fromCurrency} 
                        onSelect={handleDenominationSelect} 
                        currentAmount={amount}
                        theme={theme}
                    />
                    </div>
                )}

                <div className="flex flex-col md:flex-row items-center md:items-start relative gap-3 md:gap-4">
                {/* 
                    Z-Index Logic Fixed: 
                    If FROM is active OR Revenue Dropdown is open, it gets z-50 to stack above the button.
                    Otherwise, it sits at z-20.
                */}
                <div className={`w-full md:flex-1 transition-all relative ${activeDropdown === 'FROM' || isRevenueDropdownOpen ? 'z-50' : 'z-20'}`}> 
                    <CurrencyRow
                        key={activeTab}
                        label={activeTab === 'convert' ? "Nhập số tiền cần đổi" : "Nhập mức lương"}
                        amount={activeTab === 'convert' ? amount : salaryAmount}
                        currency={fromCurrency}
                        onAmountChange={handleAmountChange}
                        onCurrencyChange={handleFromChange}
                        inputPlacement="left"
                        autoFocus={true}
                        isActive={activeDropdown === 'FROM'}
                        onToggleDropdown={() => setActiveDropdown(activeDropdown === 'FROM' ? null : 'FROM')}
                        onCloseDropdown={() => setActiveDropdown(null)}
                        theme={theme}
                        headerAction={renderHistoryButton}
                        error={errorMsg}
                        onEnter={onCalculateAndConvert}
                        hasBackgroundImage={hasBackground}
                    />

                    {(activeTab === 'calculate' || activeTab === 'revenue') && (
                        <div className="mt-3 flex gap-3 animate-fade-in-up">
                            {/* Official Salary */}
                            <label className={`flex-1 flex items-center justify-center gap-2 px-3 rounded-2xl border cursor-pointer transition-all h-[60px] sm:h-[66px]
                                ${calcType === 'official' 
                                    ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' 
                                    : hasBackground ? 'bg-white/80 border-white/40 text-slate-700 hover:bg-white' : 'bg-white/90 border-slate-200 text-slate-600 hover:bg-white'}`}>
                                <input type="radio" name="calcType" value="official" checked={calcType === 'official'} onChange={() => setCalcType('official')} className="hidden" />
                                <div className={`w-4 h-4 rounded-full border flex items-center justify-center shrink-0 ${calcType === 'official' ? 'border-primary-500' : 'border-slate-300'}`}>
                                    {calcType === 'official' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                                </div>
                                <div className="flex flex-col sm:flex-row items-center gap-0.5 sm:gap-2 leading-tight">
                                    <span className="text-sm">Chính thức</span>
                                    <span className="text-[10px] sm:text-xs opacity-70 font-normal">(60%)</span>
                                </div>
                            </label>

                            {/* Probation Salary */}
                            <label className={`flex-1 flex items-center justify-center gap-2 px-3 rounded-2xl border cursor-pointer transition-all h-[60px] sm:h-[66px]
                                ${calcType === 'probation' 
                                    ? 'bg-primary-50 border-primary-500 text-primary-700 font-bold' 
                                    : hasBackground ? 'bg-white/80 border-white/40 text-slate-700 hover:bg-white' : 'bg-white/90 border-slate-200 text-slate-600 hover:bg-white'}`}>
                                <input type="radio" name="calcType" value="probation" checked={calcType === 'probation'} onChange={() => setCalcType('probation')} className="hidden" />
                                <div className={`w-4 h-4 rounded-full border flex items-center justify-center shrink-0 ${calcType === 'probation' ? 'border-primary-500' : 'border-slate-300'}`}>
                                    {calcType === 'probation' && <div className="w-2 h-2 rounded-full bg-primary-500" />}
                                </div>
                                <div className="flex flex-col sm:flex-row items-center gap-0.5 sm:gap-2 leading-tight">
                                    <span className="text-sm">Thử việc</span>
                                    <span className="text-[10px] sm:text-xs opacity-70 font-normal">(75%)</span>
                                </div>
                            </label>
                        </div>
                    )}

                    {activeTab === 'revenue' && (
                        <div className="mt-4 animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                            <div className="flex flex-col gap-1.5 w-full" ref={revenueDropdownRef}>
                                <label className={`text-[10px] sm:text-xs font-bold uppercase tracking-wide ml-1 transition-colors ${hasBackground ? 'text-white/90 drop-shadow-sm' : 'text-slate-500'}`}>
                                    Tùy chọn tỷ lệ
                                </label>
                                <div className="relative group">
                                    <button
                                        onClick={() => setIsRevenueDropdownOpen(!isRevenueDropdownOpen)}
                                        className={`relative w-full border text-slate-800 text-left text-base sm:text-lg font-bold py-4 px-4 pr-12 rounded-2xl transition-all h-[60px] sm:h-[66px] flex items-center backdrop-blur-md
                                        ${isRevenueDropdownOpen 
                                            ? 'border-primary-500 ring-2 ring-primary-100 z-50 bg-white' 
                                            : hasBackground 
                                                ? 'bg-white/80 border-white/40 hover:bg-white' 
                                                : 'bg-white/90 border-slate-200 hover:border-primary-300 hover:bg-white'}`}
                                    >
                                        {revenueOptions.find(o => o.value === revenueShare)?.label}
                                        <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-400">
                                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className={`w-4 h-4 transition-transform ${isRevenueDropdownOpen ? 'rotate-180 text-primary-500' : ''}`}>
                                                <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
                                            </svg>
                                        </div>
                                    </button>

                                    {isRevenueDropdownOpen && (
                                        <div className="absolute top-[calc(100%+8px)] w-full bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden transition-all z-[100] animate-fade-in-up">
                                            <div className="p-1">
                                                {revenueOptions.map((option) => (
                                                    <div 
                                                        key={option.value}
                                                        onClick={() => {
                                                            setRevenueShare(option.value as any);
                                                            setIsRevenueDropdownOpen(false);
                                                        }}
                                                        className={`flex items-center justify-between px-4 py-3 rounded-xl cursor-pointer transition-colors ${revenueShare === option.value ? 'bg-primary-50 text-primary-700' : 'hover:bg-slate-50 text-slate-700'}`}
                                                    >
                                                        <span className="font-bold">{option.label}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {activeTab === 'convert' && (
                    <div className="md:mt-12 z-30 shrink-0 relative">
                        <SwapButton onClick={handleSwapClick} isSwapping={isSwapping} theme={theme} />
                    </div>
                )}

                {activeTab !== 'revenue' && (
                    <div className={`w-full md:flex-1 transition-all relative ${activeDropdown === 'TO' ? 'z-50' : 'z-20'}`}>
                        <CurrencyRow
                            label={activeTab === 'calculate' ? "Quy đổi phí sang" : "Quy đổi sang"}
                            amount=""
                            currency={toCurrency}
                            onCurrencyChange={handleToChange}
                            inputPlacement="hidden"
                            isActive={activeDropdown === 'TO'}
                            onToggleDropdown={() => setActiveDropdown(activeDropdown === 'TO' ? null : 'TO')}
                            onCloseDropdown={() => setActiveDropdown(null)}
                            theme={theme}
                            hasBackgroundImage={hasBackground}
                        />
                    </div>
                )}
                </div>

                <button
                    onClick={onCalculateAndConvert}
                    disabled={loadingState === LoadingState.LOADING}
                    className={`w-full py-3.5 sm:py-4 rounded-2xl text-white font-bold text-base sm:text-lg shadow-xl transition-all transform mt-4 relative z-20
                    ${loadingState === LoadingState.LOADING 
                        ? 'bg-slate-400 cursor-not-allowed opacity-80' 
