                                                            {note.content}
                                                        </p>

                                                        {/* Status Actions (Disabled in selection mode) */}
                                                        <div className={`flex gap-1 overflow-x-auto no-scrollbar-on-mobile pb-1 relative z-10 mt-auto ${isSelectionMode ? 'pointer-events-none opacity-60' : ''}`}>
