                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-3">Màu nhận diện</label>
                                        <div className="flex flex-col gap-4">
                                            {/* Preset Colors Grid */}
                                            <div className="grid grid-cols-6 sm:grid-cols-8 gap-3">
                                                {PRESET_COLORS.map(color => (
                                                    <button 
                                                        key={color}
