                                </div>
                                <div className="flex flex-col sm:flex-row items-center gap-0.5 sm:gap-2 leading-tight">
                                    <span className="text-sm">Thử việc</span>
                                    <span className="text-[10px] sm:text-xs opacity-70 font-normal">(75%)</span>
                                </div>
                            </label>
                        </div>
