                    <input 
                        type="color" 
                        className="absolute inset-0 w-[200%] h-[200%] opacity-0 cursor-pointer top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 p-0 m-0"
                        value={isPreset ? '#2563eb' : currentTheme}
