               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" 
                className={`w-5 h-5 transition-transform group-hover:rotate-45 duration-500 ${currentBackground ? 'text-white' : ''}`}
