                                </div>

                                {/* 2. STATUS FILTER (Secondary) */}
                                <div className="px-4 overflow-x-auto custom-scrollbar no-scrollbar-on-mobile flex items-center gap-2 snap-x snap-mandatory scroll-pl-4">
