);

export const NotesManager: React.FC = () => {
  const { notes, tags, isLoading, addNote, updateNoteStatus, deleteNote, deleteNotes, addTag, deleteTag, toggleTagPin } = useNotes();
  const [isOpen, setIsOpen] = useState(false);
