import React, { useState, useRef, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { Tooltip } from './Tooltip';
import { ThemeColor } from '../types';

interface UserMenuProps {
  hasBackgroundImage?: boolean;
  theme?: ThemeColor;
}

