import React, { createContext, useContext, useEffect, useState } from 'react';
import { 
  onAuthStateChanged, 
  signInWithPopup, 
  signOut, 
  User,
  AuthError
} from 'firebase/auth';
import { auth, googleProvider } from '../firebase';

interface NotificationState {
  message: string;
  type: 'success' | 'error' | 'info';
}

interface AuthContextType {
  user: User | null;
  loading: boolean;
  loginGoogle: () => Promise<void>;
  logout: () => Promise<void>;
  notification: NotificationState | null;
  closeNotification: () => void;
  showNotification: (message: string, type: 'success' | 'error' | 'info') => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [notification, setNotification] = useState<NotificationState | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  const showNotification = (message: string, type: 'success' | 'error' | 'info') => {
    setNotification({ message, type });
    // Tự động tắt sau 4 giây
    setTimeout(() => {
      setNotification(null);
    }, 4000);
  };

  const closeNotification = () => setNotification(null);

  const handleAuthError = (error: AuthError, providerName: string) => {
    console.error(`${providerName} Login Error:`, error.code, error.message);

    let message = `Đăng nhập ${providerName} thất bại.`;

    switch (error.code) {
      case 'auth/popup-closed-by-user':
        message = 'Bạn đã đóng cửa sổ đăng nhập.';
        break;
      case 'auth/cancelled-popup-request':
        message = 'Yêu cầu đăng nhập bị hủy do có cửa sổ khác đang mở.';
        break;
      case 'auth/account-exists-with-different-credential':
        message = 'Email này đã được liên kết với một phương thức đăng nhập khác.';
        break;
      case 'auth/unauthorized-domain':
        message = 'Tên miền hiện tại chưa được ủy quyền trong Firebase Console. Vui lòng thêm tên miền này vào Authentication > Settings > Authorized Domains.';
        break;
      case 'auth/operation-not-allowed':
        message = `Đăng nhập bằng ${providerName} chưa được kích hoạt trong Firebase Console.`;
        break;
      case 'auth/popup-blocked':
        message = 'Trình duyệt đã chặn cửa sổ bật lên (popup). Vui lòng cho phép popup để đăng nhập.';
        break;
      case 'auth/network-request-failed':
        message = 'Lỗi kết nối mạng. Vui lòng kiểm tra lại đường truyền.';
        break;
      default:
        break;
    }

    showNotification(message, 'error');
  };

  const loginGoogle = async () => {
    try {
      await signInWithPopup(auth, googleProvider);
      showNotification('Đăng nhập Google thành công!', 'success');
    } catch (error: any) {
      handleAuthError(error, 'Google');
    }
  };

  const logout = async () => {
    try {
      await signOut(auth);
      showNotification('Đã đăng xuất thành công.', 'info');
    } catch (error: any) {
      console.error("Logout Error:", error);
      showNotification('Đăng xuất thất bại.', 'error');
    }
  };

  return (
    <AuthContext.Provider value={{ user, loading, loginGoogle, logout, notification, closeNotification, showNotification }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error("useAuth must be used within an AuthProvider");
  return context;
};

import { useState, useEffect } from 'react';
import { RevenueRecord } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { db } from '../firebase';
import { doc, getDoc, setDoc } from 'firebase/firestore';

export const useRevenueTracker = () => {
  const [records, setRecords] = useState<RevenueRecord[]>([]);
  const { user } = useAuth();

  // Load Data
  useEffect(() => {
    const loadData = async () => {
      if (user) {
        try {
          const docRef = doc(db, "users", user.uid);
          const docSnap = await getDoc(docRef);
          if (docSnap.exists()) {
             const data = docSnap.data();
             if (data.revenueRecords) setRecords(data.revenueRecords);
          }
        } catch (e) {
          console.error("Failed to load revenue records from Firestore", e);
        }
      } else {
        try {
          const savedRecords = localStorage.getItem('app_revenue_records');
          if (savedRecords) setRecords(JSON.parse(savedRecords));
        } catch (e) {
          console.error("Failed to load revenue records from LocalStorage", e);
        }
      }
    };
    loadData();
  }, [user]);

  // Persist Data
  const persistData = async (newRecords: RevenueRecord[]) => {
    if (user) {
      try {
        const docRef = doc(db, "users", user.uid);
        await setDoc(docRef, { revenueRecords: newRecords }, { merge: true });
      } catch (e) {
        console.error("Failed to save revenue records to Firestore", e);
      }
    } else {
      localStorage.setItem('app_revenue_records', JSON.stringify(newRecords));
    }
  };

  const addRecord = (
    inputSalary: number, 
    shareType: 'all' | 'cv' | 'job', 
    totalRevenue: number, 
    netIncome: number
  ) => {
    const newRecord: RevenueRecord = {
      id: Date.now().toString() + Math.random().toString(36).substr(2, 5),
      timestamp: Date.now(),
      inputSalary,
      shareType,
      totalRevenue,
      netIncome
    };
    const updated = [newRecord, ...records];
    setRecords(updated);
    persistData(updated);
  };

  const deleteRecord = (id: string) => {
    const updated = records.filter(r => r.id !== id);
    setRecords(updated);
    persistData(updated);
  };

  return {
    records,
    addRecord,
    deleteRecord
  };
};

