import React, { useState, useMemo } from 'react';
import { RevenueRecord, ThemeColor } from '../types';

interface RevenueStatsSectionProps {
  records: RevenueRecord[];
  onDeleteRecord: (id: string) => void;
  formatCurrency: (val: number, locale: string, currencyCode: string) => string;
  theme: ThemeColor;
}

export const RevenueStatsSection: React.FC<RevenueStatsSectionProps> = ({ 
  records, 
  onDeleteRecord, 
  formatCurrency, 
  theme 
}) => {
  // Determine available months from records
  const availableMonths = useMemo(() => {
    const months = new Set<string>();
    records.forEach(r => {
      const date = new Date(r.timestamp);
      months.add(`${date.getMonth() + 1}/${date.getFullYear()}`);
    });
    return Array.from(months).sort((a, b) => {
       const [m1, y1] = a.split('/').map(Number);
       const [m2, y2] = b.split('/').map(Number);
       return y2 - y1 || m2 - m1; // Sort descending
    });
  }, [records]);

  // Default to current month if available, else first available, else current date
  const [selectedMonth, setSelectedMonth] = useState<string>(() => {
     const now = new Date();
     const current = `${now.getMonth() + 1}/${now.getFullYear()}`;
     if (availableMonths.includes(current)) return current;
     return availableMonths[0] || current;
  });

  // Filter records by selected month
  const filteredRecords = useMemo(() => {
      return records.filter(r => {
          const date = new Date(r.timestamp);
          return `${date.getMonth() + 1}/${date.getFullYear()}` === selectedMonth;
      }).sort((a, b) => b.timestamp - a.timestamp);
  }, [records, selectedMonth]);

  // Calculations
  const totalRevenue = filteredRecords.reduce((sum, r) => sum + r.totalRevenue, 0);
  const totalNetIncome = filteredRecords.reduce((sum, r) => sum + r.netIncome, 0);

  const handlePrevMonth = () => {
     const [m, y] = selectedMonth.split('/').map(Number);
     let newM = m - 1;
     let newY = y;
     if (newM < 1) { newM = 12; newY -= 1; }
     setSelectedMonth(`${newM}/${newY}`);
  };

  const handleNextMonth = () => {
     const [m, y] = selectedMonth.split('/').map(Number);
     let newM = m + 1;
     let newY = y;
     if (newM > 12) { newM = 1; newY += 1; }
     setSelectedMonth(`${newM}/${newY}`);
  };

  const getShareLabel = (type: string) => {
     if (type === 'cv') return 'CV (70%)';
     if (type === 'job') return 'Job (30%)';
     return '100%';
  };

  return (
    <div className="animate-fade-in-up space-y-6">
       {/* Month Selector */}
       <div className="flex items-center justify-between bg-white/60 backdrop-blur-sm p-2 rounded-2xl border border-white/50 shadow-sm">
            <button onClick={handlePrevMonth} className="p-2 hover:bg-white rounded-xl text-slate-500 transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5" />
                </svg>
            </button>
            <div className="flex flex-col items-center">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Tháng</span>
                <span className="text-xl font-extrabold text-slate-800">{selectedMonth}</span>
            </div>
            <button onClick={handleNextMonth} className="p-2 hover:bg-white rounded-xl text-slate-500 transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                    <path strokeLinecap="round" strokeLinejoin="round" d="m8.25 4.5 7.5 7.5-7.5 7.5" />
                </svg>
            </button>
       </div>

       {/* Summary Cards */}
       <div className="grid grid-cols-2 gap-4">
            <div className="p-4 rounded-2xl bg-emerald-50 border border-emerald-100 shadow-sm">
                <span className="text-xs font-bold text-emerald-600 uppercase tracking-wide block mb-1">Tổng doanh thu</span>
                <span className="text-lg sm:text-xl font-extrabold text-emerald-700 block truncate">
                    {formatCurrency(totalRevenue, 'vi-VN', 'VND')}
                </span>
            </div>
            <div className="p-4 rounded-2xl bg-blue-50 border border-blue-100 shadow-sm">
                <span className="text-xs font-bold text-blue-600 uppercase tracking-wide block mb-1">Thực nhận (49%)</span>
                <span className="text-lg sm:text-xl font-extrabold text-blue-700 block truncate">
                    {formatCurrency(totalNetIncome, 'vi-VN', 'VND')}
                </span>
            </div>
       </div>

       {/* Detail List */}
       <div className="bg-white/70 backdrop-blur-md rounded-3xl border border-white/50 shadow-lg overflow-hidden">
            <div className="p-4 border-b border-slate-100/50 flex justify-between items-center">
                <h3 className="font-bold text-slate-700">Chi tiết ({filteredRecords.length})</h3>
            </div>

            <div className="max-h-[400px] overflow-y-auto custom-scrollbar">
                {filteredRecords.length === 0 ? (
                    <div className="p-8 text-center text-slate-400">
                        Chưa có dữ liệu cho tháng này
                    </div>
                ) : (
                    <div className="divide-y divide-slate-100">
                        {filteredRecords.map((record) => (
                            <div key={record.id} className="p-4 hover:bg-white/80 transition-colors flex items-center justify-between group">
                                <div className="flex flex-col gap-1">
                                    <span className="text-[10px] font-bold text-slate-400 uppercase">
                                        {new Date(record.timestamp).toLocaleString('vi-VN', { 
                                            day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' 
                                        })}
                                    </span>
                                    <div className="flex items-center gap-2">
                                        <span className="font-bold text-slate-700">
                                            {formatCurrency(record.netIncome, 'vi-VN', 'VND')}
                                        </span>
                                        <span className={`text-[10px] px-1.5 py-0.5 rounded font-bold uppercase
                                            ${record.shareType === 'all' ? 'bg-slate-100 text-slate-500' : 
                                              record.shareType === 'cv' ? 'bg-purple-100 text-purple-600' : 
                                              'bg-orange-100 text-orange-600'}
                                        `}>
                                            {getShareLabel(record.shareType)}
                                        </span>
                                    </div>
                                    <span className="text-xs text-slate-500">
                                        Doanh thu: {formatCurrency(record.totalRevenue, 'vi-VN', 'VND')}
                                    </span>
                                </div>
                                <button 
                                    onClick={() => onDeleteRecord(record.id)}
                                    className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-full transition-all opacity-0 group-hover:opacity-100"
                                    title="Xóa"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                                        <path strokeLinecap="round" strokeLinejoin="round" d="m14.74 9-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 0 1-2.244 2.077H8.084a2.25 2.25 0 0 1-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 0 0-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 0 1 3.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 0 0-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 0 0-7.5 0" />
                                    </svg>
                                </button>
                            </div>
                        ))}
                    </div>
                )}
            </div>
       </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
