                <button 
                    onClick={toggleSelectionMode}
                    className="px-4 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-600 text-sm font-bold transition-colors"
                >
                    Hủy chọn
                </button>
            )}

            <div className="w-px h-6 bg-slate-200 mx-1"></div>

            <button 
                onClick={handleClose}
