                                                    <input type="color" className="absolute inset-0 w-[200%] h-[200%] opacity-0 cursor-pointer -top-1/2 -left-1/2 p-0 m-0" value={newTagColor} onChange={(e) => setNewTagColor(e.target.value)} />
